INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OrderlyNetwork/dex-creator/translate-locales', 'community', 'OrderlyNetwork', 'dex-creator', 'OrderlyNetwork/dex-creator', 'translate-locales', 6, 22, 57, '2026-03-04T09:51:55Z', '2026-03-06T06:53:43.604Z', 'ede1d253d0e3ee6aa16de47782cc036e7f49a5b4cde85e65dde9e78b111b0f8d', '{"id":"OrderlyNetwork/dex-creator/translate-locales","name":"translate-locales","description":{"en":"The translate-locales skill regenerates the English locale from i18n modules and translates new or changed content into four locales for the DApp, benefiting developers working on multilingual applications.","zh":"translate-locales 技术允许开发者使用 AIエージェント 实现批量翻译和多语言支持，支持 zh、ja、ko 等语言","ja":"translate-locales は、AIエージェントを使用して多言語対応を実現する技術です。React、Python、CLI などの技術と組み合わせて使用できます","ko":"translate-locales 는 AI 에이전트를 사용하여 다국어 지원을 구현하는 기술입니다. Python, CLI 등의 기술과 함께 사용할 수 있습니다","es":"translate-locales es una habilidad que regenera el locale inglés y traduce contenido nuevo o modificado a cuatro locales para tu DApp.","fr":"translate-locales est une compétence qui régénère le locale anglais et traduit le contenu nouveau ou modifié en quatre locales pour votre DApp.","de":"translate-locales ist eine Fähigkeit, die das Englisch-locale regeneriert und neuen oder geänderten Inhalt in vier Sprachen für Ihre DApp übersetzt.","pt":"O translate-locales é um skill que regenera o locale inglês a partir de módulos i18n e detecta novo ou alterado conteúdo para traduzir em quatro locais","ru":"Translate-locales - это навык, который регенерирует английский локаль из модулей i18n и обнаруживает новый или измененный контент для перевода на четыре локали","ar":"translate-locales هو مهارة تقوم بإعادة generar الlocale الإنجليزية من الوحدات i18n واكتشاف المحتوى الجديد أو المعدل لترجمته إلى أربعة مواقع"},"seo":{"title":{"en":"translate-locales: Automated Localization Setup Guide | A...","zh":"translate-locales 技术指南：AIエージェント批量翻译","ja":"translate-locales セットアップガイド：AIエージェントを使用した多言語対応","ko":"translate-locales 설정 가이드: AI 에이전트를 활용한 다국어 지원","es":"Guía de Configuración de translate-locales para Agentes d...","fr":"Guide de Configuration de translate-locales pour Outils d''IA","de":"Einrichtungsleitfaden für translate-locales bei KI-Tools","pt":"Guia de Configuração do translate-locales para Ferramenta...","ru":"Настройка translate-locales для ИИ Агентов","ar":"دليل إعداد translate-locales لآلات اللغة الإصطناعية"},"description":{"en":"Streamline your DApp''s localization process with translate-locales. Learn how to invoke this skill and regenerate English locales from i18n modules. Get star...","zh":"了解 translate-locales 技术的详细指南，使用 AIエージェント 实现批量翻译和多语言支持","ja":"translate-locales の設定方法とベストプラクティスを紹介。AIエージェントを使用して多言語対応を実現する","ko":"translate-locales 설정과 구현에 대한 전문가 가이드. AI 에이전트를 사용하여 다국어 지원을 구현하세요","es":"Aprende a configurar translate-locales para regenerar el locale inglés y traducir contenido nuevo o modificado a cuatro locales para tu DApp con Agentes de IA.","fr":"Découvrez comment configurer translate-locales pour régénérer le locale anglais et traduire le contenu nouveau ou modifié en quatre locales pour votre DApp a...","de":"Erfahren Sie, wie Sie translate-locales konfigurieren, um das Englisch-locale zu regenerieren und neuen oder geänderten Inhalt in vier Sprachen für Ihre DApp...","pt":"Aprenda a configurar o translate-locales para Ferramentas de IA e melhore a experiência do usuário com traduções precisas","ru":"Узнайте, как настроить translate-locales для ИИ Агентов и улучшить пользовательский опыт с точными переводами","ar":"تعلم كيفية إعداد translate-locales لآلات اللغة الإصطناعية وتحسين تجربة المستخدم بالترجمات الدقيقة"},"definition":{"en":"translate-locales is a skill that automates the localization process by regenerating English locales and translating content into zh, tc, ko, and other languages.","zh":"translate-locales 是一种使用 AIエージェント 实现批量翻译和多语言支持的技术","ja":"translate-locales は、AIエージェントを使用して多言語対応を実現する技術です","ko":"translate-locales 는 AI 에이전트를 사용하여 다국어 지원을 구현하는 기술입니다","es":"translate-locales es una habilidad de Agentes de IA que traduce contenido nuevo o modificado a múltiples locales.","fr":"translate-locales est une compétence d''Outils d''IA qui traduit le contenu nouveau ou modifié en plusieurs locales.","de":"translate-locales ist eine Fähigkeit von KI-Tools, die neuen oder geänderten Inhalt in mehrere Sprachen übersetzt.","pt":"O translate-locales é um skill de Ferramentas de IA que traduz conteúdo para vários locais","ru":"Translate-locales - это навык ИИ Агентов, который переводит контент на несколько локалей","ar":"translate-locales هو مهارة آلات اللغة الإصطناعية التي تترجم المحتوى إلى عدة مواقع"},"features":{"en":["Regenerates English locale from i18n modules using the `@translate-locales` command","Detects new or changed content in `app/app/i18n/locales/en.json`","Translates content into four locales: zh, tc, ko","Supports batch workflow for exporting and translating locale files","Works with JSON file format for locale data","Invoked explicitly using the `@translate-locales` command"],"zh":["支持批量翻译和多语言支持","使用 AIエージェント 实现自动翻译","支持 zh、ja、ko 等语言","与 React、Python、CLI 等技术兼容","实现新或改变的内容检测和翻译"],"ja":["バッチ翻訳と多言語対応をサポート","AIエージェントを使用して自動翻訳を実現","zh、ja、ko などの言語をサポート","React、Python、CLI などの技術と組み合わせて使用可能","新しいまたは変更されたコンテンツの検出と翻訳を実現"],"ko":["다국어 지원과 배치 번역을 지원","AI 에이전트를 사용하여 자동 번역을 구현","zh, ja, ko 등 언어를 지원","Python, CLI 등의 기술과 함께 사용할 수 있습니다","새로 추가되거나 변경된 내용을 감지하고 번역을 구현"],"es":["Regeneración del locale inglés desde módulos i18n","Detección de contenido nuevo o modificado","Traducción a cuatro locales (zh, tc, ko, etc.)","Integración con flujos de trabajo por lotes","Compatibilidad con módulos i18n de la aplicación","Soporte para múltiples idiomas"],"fr":["Régénération du locale anglais à partir de modules i18n","Détection de contenu nouveau ou modifié","Traduction en quatre locales (zh, tc, ko, etc.)","Intégration avec des flux de travail par lots","Compatibilité avec des modules i18n de l''application","Prise en charge de plusieurs langues"],"de":["Regenerierung des Englisch-locales aus i18n-Modulen","Erkennung von neuem oder geändertem Inhalt","Übersetzung in vier Sprachen (zh, tc, ko usw.)","Integration in Batch-Workflows","Kompatibilität mit i18n-Modulen der Anwendung","Unterstützung für mehrere Sprachen"],"pt":["Regeneração do locale inglês a partir de módulos i18n","Detecção de novo ou alterado conteúdo","Tradução para quatro locais: zh, tc, ko e mais","Integração com workflows em lote","Suporte a módulos i18n","CLI para execução de comandos"],"ru":["Регенерация английского локали из модулей i18n","Обнаружение нового или измененного контента","Перевод на четыре локали: zh, tc, ko и более","Интеграция с пакетными рабочими процессами","Поддержка модулей i18n","CLI для выполнения команд"],"ar":["إعادة generar الlocale الإنجليزية من الوحدات i18n","اكتشاف المحتوى الجديد أو المعدل","ترجمة إلى أربعة مواقع: zh, tc, ko و أكثر","التكامل مع سير عمل الدفع","دعم الوحدات i18n","CLI لتنفيذ الأوامر"]},"keywords":{"en":["how to use translate-locales","what is translate-locales","translate-locales alternative","translate-locales setup guide","translate-locales install","DApp localization","i18n module integration","automated translation workflow"],"zh":["translate-locales","AIエージェント","批量翻译","多语言支持","React","Python","CLI","zh语言支持","ja语言支持","ko语言支持"],"ja":["translate-locales","AIエージェント","バッチ翻訳","多言語対応","React","Python","CLI","zh言語対応","ja言語対応","ko言語対応"],"ko":["translate-locales","AI 에이전트","다국어 지원","배치 번역","Python","CLI","zh 언어 지원","ja 언어 지원","ko 언어 지원"],"es":["Agentes de IA","translate-locales","i18n","traducción automática","desarrollo de DApp","locale inglés","traducción de contenido","módulos i18n","flujos de trabajo por lotes"],"fr":["Outils d''IA","translate-locales","i18n","traduction automatique","développement de DApp","locale anglais","traduction de contenu","modules i18n","flux de travail par lots"],"de":["KI-Tools","translate-locales","i18n","automatische Übersetzung","DApp-Entwicklung","Englisch-locale","Inhaltsübersetzung","i18n-Module","Batch-Workflows"],"pt":["translate-locales","Ferramentas de IA","i18n","tradução automática","locale","workflow em lote","CLI","módulos i18n","desenvolvimento de software"],"ru":["translate-locales","ИИ Агенты","i18n","автоматический перевод","локаль","пакетный рабочий процесс","CLI","модули i18n","разработка программного обеспечения"],"ar":["translate-locales","آلات اللغة الإصطناعية","i18n","ترجمة آلية","الموقع","سير عمل الدفع","CLI","وحدات i18n","تطوير البرمجيات"]}},"owner":"OrderlyNetwork","repo":"dex-creator","repoPath":"OrderlyNetwork/dex-creator","stars":6,"forks":22,"updatedAt":"2026-03-04T09:51:55Z","topics":[],"category":"community","skillMd":{"name":"translate-locales","description":"7-step workflow to export en.json from app i18n modules (or use user-provided JSON), detect new/changed keys via git diff when applicable, translate into zh/tc/ko/es using TRANSLATION_PROMPT.md, and merge into app locale JSON files.","bodyPreview":"## Translate Locales\n\nWhen the user explicitly invokes this skill (e.g. `@translate-locales`), follow this 7-step workflow to regenerate the English locale from i18n modules, detect new or changed content, and translate it into four locales for the DApp.\n\n### Usage\n\n- This skill is designed **only** for the batch workflow of exporting `app/app/i18n/locales/en.json` from the app i18n modules and translating **new or changed** keys (vs. the staged version of `en.json`) into `zh`, `tc`, `ko`, and `","body":"## Translate Locales\n\nWhen the user explicitly invokes this skill (e.g. `@translate-locales`), follow this 7-step workflow to regenerate the English locale from i18n modules, detect new or changed content, and translate it into four locales for the DApp.\n\n### Usage\n\n- This skill is designed **only** for the batch workflow of exporting `app/app/i18n/locales/en.json` from the app i18n modules and translating **new or changed** keys (vs. the staged version of `en.json`) into `zh`, `tc`, `ko`, and `es` under `app/app/i18n/locales/`.\n- If the user provides a specific JSON file or object to translate (e.g. a custom en subset or another locale to use as source), use it as the translation source and skip regenerating en.json and computing git diff (Step 2 and Step 3).\n- Use this skill **only** when the user explicitly asks to generate and translate i18n keys for the DApp (e.g. `@translate-locales` or by name).\n- Do **not** use this skill for general translation requests, ad-hoc string translation, or refactoring existing i18n keys.\n\n## Workflow\n\nAll shell commands below assume you start from the repo root. Step 1–2 run from the `app` directory; diff and merge steps refer to paths relative to the repo root.\n\n**Entry condition:**\n\n- **If the user has manually provided JSON**: The user has explicitly given a JSON file path (e.g. `app/app/i18n/locales/xxx.json`) or pasted/provided JSON object content, and has indicated that this JSON should be used as the translation source. In this case **skip Step 2 and Step 3**; use that JSON as the \"English i18n JSON to translate\" and go directly to Step 4 (check size and batch if needed), then Step 5 (translate), Step 6 (merge), and Step 7 (sync-locales).\n- **If the user has not provided JSON**: Run the full sequence Step 1 → Step 2 → Step 3 → Step 4 → Step 5 → Step 6 → Step 7.\n\n### Step 1 – Navigate to app\n\n- From the repo root, if the current directory is not `app`, run `cd app`. If already in `app`, skip.\n- When the user has provided JSON and you skip Step 2 and Step 3, still ensure you are in (or will be in) the `app` directory before running Step 6 and Step 7.\n\n### Step 2 – Regenerate en.json\n\n_When the user has not manually provided a JSON file/object, run this step; otherwise skip and use the provided JSON as the input to Step 4._\n\n- In `app`, run: `yarn export-en-json`\n- This re-exports the `en` object from the i18n modules (see `app/scripts/export-en-json.ts`) into `app/app/i18n/locales/en.json`.\n\n### Step 3 – Detect new or changed content\n\n_When the user has not manually provided a JSON file/object, run this step to build the minimal diff JSON; otherwise skip and use the user-provided JSON as the input to Step 4._\n\n- Ensure that the version of `app/app/i18n/locales/en.json` in the git index (staging area) represents the **last confirmed canonical English locale** (for example, staged after the previous successful translation run or commit). If not, stage that confirmed version first before proceeding.\n- From the repo root (or from `app` with path `app/app/i18n/locales/en.json`), compare the current working copy of `app/app/i18n/locales/en.json` with the **staged** version in the index, e.g. run: `git diff -- app/app/i18n/locales/en.json` (no `HEAD`: diff is working tree vs staging area, not vs last commit). Git interprets this path relative to the repo root, so the command works even when run from `app`.\n- Identify keys whose values are **added or modified** compared to the staged version of `en.json` (the last confirmed canonical version).\n- Build a **minimal JSON object** containing only these new/changed key paths and values, preserving the same nested structure as in `en.json`.\n- If there are no new or changed keys (diff JSON is empty), stop and inform the user that no translation is needed.\n\n### Step 4 – Check size and batch (if needed)\n\nYou have **the JSON to translate** (from Step 3’s minimal diff, or from the user when Step 2 and Step 3 were skipped). Check its size:\n\n- **If the JSON is empty or has no keys**: Stop and inform the user that no translation is needed.\n- **If the JSON is large** (e.g. **more than 200 keys** or **more than 40,000 characters**): Use batch translation to avoid exceeding the model’s token limit. From the user’s perspective this remains a single `@translate-locales` run; batching is handled internally.\n  - **Split**: Split the JSON to translate into smaller batches of keys (e.g. **80–150 keys per batch**), preserving the same nested key structure. You may split by key order or by top-level namespace.\n  - **Per batch**: For each batch, use that batch’s JSON as the \"English i18n JSON file\" input to `TRANSLATION_PROMPT.md` and ask the model to produce the four JSON objects for `zh`, `tc`, `ko`, and `es` (same strict rules as in Step 5). Shallow-merge each batch’s four outputs into four accumulator objects (later batches overwrite same keys).\n  - **After all batches**: Write the four accumulated locale objects to `app/app/i18n/locales/diff-zh.json`, `diff-tc.json`, `diff-ko.json`, and `diff-es.json`, then proceed to Step 6.\n- **If the JSON is small** (within the thresholds above): Proceed to Step 5 and use the single-shot process there.\n\n### Step 5 – Translate new content with TRANSLATION_PROMPT\n\n**When the JSON to translate is small** (within the threshold in Step 4), use this single-shot process:\n\n- The \"English i18n JSON file\" input is either: (1) the minimal diff JSON from Step 3 (when Step 2/3 were not skipped), or (2) the user-provided JSON file/object (when the user skipped Step 2 and Step 3). Use that JSON as the content in the prompt defined in `TRANSLATION_PROMPT.md` (in this skill directory).\n- Ask the current AI to produce four JSON objects for `zh`, `tc`, `ko`, and `es`, following the strict rules in the prompt (keys unchanged, placeholders/tags/newlines and token symbols preserved, etc.).\n- Write the outputs to four **per-locale** diff files under `app/app/i18n/locales/`:\n  - `diff-zh.json`\n  - `diff-tc.json`\n  - `diff-ko.json`\n  - `diff-es.json`\n- Each file must contain only the keys and values for that locale (no wrapper object like `{ \"zh\": { ... } }`), preserving the same key structure as in `en.json` (for example):\n  ```json\n  {\n    \"common.confirm\": \"Confirm\"\n  }\n  ```\n\n### Step 6 – Merge translations into locale files\n\n- Use the built-in merge script at `app/scripts/merge-translations.mjs`. From the `app` directory, run:\n  ```bash\n  node scripts/merge-translations.mjs\n  ```\n- The script looks for per-locale diff files `diff-zh.json`, `diff-tc.json`, `diff-ko.json`, and `diff-es.json` in `app/app/i18n/locales/` and merges their keys into `zh.json`, `tc.json`, `ko.json`, and `es.json` respectively.\n- These per-locale diff files are treated as temporary input; after the merge completes the script will attempt to delete each `diff-*.json` file, so they are not processed again by `sync-locales` or future merge runs.\n\n### Step 7 – Normalize locale files with sync-locales\n\n- After Steps 1–6 are complete, ensure you are in the `app` directory.\n- Run: `yarn sync-locales`.\n- This command treats `app/app/i18n/locales/en.json` as the canonical key set and ordering, and for each other locale JSON file under `app/app/i18n/locales/` it keeps only keys present in `en.json` and rewrites them in the same key order. If the user provided a custom JSON that is not a subset of the current `en.json`, keys that do not exist in `en.json` will be dropped from the locale files during this step.\n\n## Checklist\n\n**When the user has not manually provided JSON** (full flow):\n\n- [ ] In repo root, then `cd app`; `yarn export-en-json` run; `app/app/i18n/locales/en.json` updated as the latest canonical English locale\n- [ ] Git diff inspected: `git diff -- app/app/i18n/locales/en.json` (working tree vs staging area, using the staged `en.json` as the last confirmed canonical version); diff JSON (new/changed keys only) prepared\n- [ ] Step 4: If the diff JSON is large, use the batch flow (split, translate per batch, accumulate, then write once); otherwise go to Step 5 for single-shot; outputs written to `app/app/i18n/locales/diff-zh.json`, `diff-tc.json`, `diff-ko.json`, `diff-es.json`\n- [ ] `node scripts/merge-translations.mjs` run from `app` (Step 6); per-locale `diff-*.json` files removed after merge\n- [ ] In `app`, `yarn sync-locales` run (Step 7); non-English locale JSON files aligned to the key set and ordering of `en.json`, with any extra keys dropped\n- [ ] Spot-check several languages to ensure placeholders, HTML tags, newlines, and token symbols are preserved and that key sets match the English source\n\n**When the user has manually provided JSON** (skip Step 2 and Step 3):\n\n- [ ] Ensure in `app` (or run Step 1) before merge/sync; user-provided JSON used as the translation source\n- [ ] Step 4: If JSON is empty, stop; if it exceeds the thresholds, apply the batch flow; otherwise Step 5 single-shot; outputs written to `app/app/i18n/locales/diff-zh.json`, `diff-tc.json`, `diff-ko.json`, `diff-es.json`\n- [ ] Step 6: `node scripts/merge-translations.mjs` run from `app`; then Step 7: `yarn sync-locales` in `app`\n- [ ] Spot-check several languages to ensure placeholders, HTML tags, newlines, and token symbols are preserved and that key sets match the source\n\n## Built-in script\n\nThe merge script `app/scripts/merge-translations.mjs` is a permanent part of the repo. It runs in **per-locale diff mode**: when called from the `app` directory, it reads `diff-zh.json`, `diff-tc.json`, `diff-ko.json`, and `diff-es.json` from `app/app/i18n/locales/` and merges their keys into `zh.json`, `tc.json`, `ko.json`, and `es.json` respectively.\n\nDo not recreate this script; use the existing one.\n\n## Error handling\n\n- If `yarn export-en-json` fails: verify the script and i18n module paths exist, run `yarn install` if needed, and check `app/app/i18n/module/index.ts` exports correctly.\n- If the user-provided JSON is missing, invalid, or empty: ask for a valid JSON file path or object, or stop and explain that no translation is needed.\n- If translation output is invalid JSON: validate the AI output (no trailing commas, no comments, proper escaping), and re-run translation if needed.\n- If a locale file is missing: the merge script creates an empty object `{}` before merging.\n- If `merge-translations.mjs` fails, ensure `diff-zh.json`, `diff-tc.json`, `diff-ko.json`, and `diff-es.json` exist under `app/app/i18n/locales/` (or that missing locales are intentionally omitted), and that you are running the script from the `app` directory.\n- If a single translation request fails due to token limits, switch to the batch strategy in Step 4 (split the JSON into smaller batches, e.g. 50–80 keys per batch, translate each batch, accumulate, then write the four diff files and run the merge script once).\n\n## When NOT to use this skill\n\n- The user only wants to translate a small number of ad-hoc strings or UI copy.\n- The user is refactoring or renaming existing i18n keys rather than translating new/changed keys.\n- The task is general content translation unrelated to the DApp i18n JSON files.\n"},"lastSynced":"2026-03-06T06:53:43.604Z","agentAnalysis":{"suitability":{"en":"Ideal for Multilingual AI Agents like Claude Code and AutoGPT needing automated translation capabilities for i18n modules","zh":"适合于像 Claude Code 和 AutoGPT 这样的多语言 AI 代理，需要为 i18n 模块提供自动化翻译能力","ja":"Claude Code や AutoGPT などの多言語 AI エージェントに適しており、i18n モジュールの自動翻訳機能が必要","ko":"Claude Code와 AutoGPT 같은 멀티언어 AI 에이전트에 적합하며, i18n 모듈을 위한 자동 번역 기능이 필요","es":"Ideal para Agentes de Inteligencia Artificial Multilingües como Claude Code y AutoGPT que necesitan capacidades de traducción automatizada para módulos i18n","fr":"Idéal pour les Agents d''Intelligence Artificielle Multilingues comme Claude Code et AutoGPT nécessitant des capacités de traduction automatisées pour les modules i18n","de":"Ideal für mehrsprachige KI-Agents wie Claude Code und AutoGPT, die automatisierte Übersetzungsfunktionen für i18n-Module benötigen","pt":"Ideal para Agentes de IA Multilíngues como Claude Code e AutoGPT que necessitam de capacidades de tradução automatizada para módulos i18n","ru":"Идеален для мультиязычных агентов ИИ, таких как Claude Code и AutoGPT, требующих автоматических возможностей перевода для модулей i18n","ar":"مثالي لوكلاء الذكاء الاصطناعي المتعددة اللغات مثل Claude Code و AutoGPT الذين يحتاجون إلى قدرات ترجمة آلية لمكونات i18n"},"recommendation":{"en":"Empowers agents to regenerate the English locale from i18n modules, detect new or changed content, and translate it into multiple locales such as zh, tc, and ko using JSON files like en.json, leveraging batch workflow and export capabilities","zh":"使代理能够从 i18n 模块重新生成英文区域设置，检测新的或更改的内容，并使用 JSON 文件（如 en.json）将其翻译成多个区域设置（如 zh, tc 和 ko），利用批处理工作流和导出功能","ja":"エージェントが i18n モジュールから英語ロケールを再生成し、新しいまたは変更されたコンテンツを検出して、JSON ファイル（たとえば en.json）を使用してこれを複数のロケール（たとえば zh, tc, ko）に翻訳することを可能にし、バッチ ワークフローとエクスポート機能を利用","ko":"에이전트가 i18n 모듈로부터 영어 로케일을 재생성하고 새로운 혹은 변경된 콘텐츠를 감지하여 JSON 파일(예: en.json)을 사용하여 이를 여러 로케일(zh, tc, ko 등)로 번역할 수 있도록 하며, 배치 작업 흐름과 내보내기 기능을 활용","es":"Habilita a los agentes a regenerar la configuración regional en inglés desde módulos i18n, detectar contenido nuevo o cambiado y traducirlo a múltiples configuraciones regionales como zh, tc y ko utilizando archivos JSON como en.json, aprovechando capacidades de flujo de trabajo por lotes y exportación","fr":"Permet aux agents de régénérer la configuration régionale anglaise à partir de modules i18n, de détecter le contenu nouveau ou modifié et de le traduire dans plusieurs configurations régionales telles que zh, tc et ko en utilisant des fichiers JSON comme en.json, en exploitant les capacités de workflow par lot et d''exportation","de":"Ermöglicht es Agents, die englische Spracheinstellung aus i18n-Modulen zu regenerieren, neues oder geändertes Inhalte zu erkennen und diese in mehrere Spracheinstellungen wie zh, tc und ko zu übersetzen, indem JSON-Dateien wie en.json verwendet werden, wobei die Batch-Arbeitsablauf- und Exportfunktionen genutzt werden","pt":"Habilita os agentes a regenerar o local inglês a partir de módulos i18n, detectar novo ou conteúdo alterado e traduzi-lo para vários locais, como zh, tc e ko, usando arquivos JSON como en.json, aproveitando recursos de fluxo de trabalho em lote e exportação","ru":"Наделяет агентов возможностью регенерировать английский локаль из модулей i18n, обнаруживать новый или измененный контент и переводить его на несколько локалей, таких как zh, tc и ko, используя файлы JSON, такие как en.json, используя возможности пакетного рабочего процесса и экспорта","ar":"يسمح للوكلاء بإعادة إنشاء الموقع الإنجليزي من مكونات i18n، وكشف المحتوى الجديد أو المتغير، وترجمته إلى عدة مواقع إقليمية مثل zh و tc و ko، باستخدام ملفات JSON مثل en.json، واستغلال إمكانيات سير العمل الدفعية وتصديرها"},"useCases":{"en":["Automating translation of new or changed content into four locales for DApps","Regenerating the English locale from i18n modules for multilingual applications","Detecting and translating new keys in en.json files"],"zh":["为 DApps 自动翻译新的或更改的内容到四个区域设置","为多语言应用程序重新生成 i18n 模块的英文区域设置","检测并翻译 en.json 文件中的新键"],"ja":["DApps の新しいまたは変更されたコンテンツを 4 つのロケールに自動翻訳する","多言語アプリケーションの i18n モジュールの英語ロケールを再生成する","en.json ファイルの新しいキーを検出して翻訳する"],"ko":["DApps의 새로운 혹은 변경된 콘텐츠를 네 개의 로케일로 자동 번역하기","멀티언어 애플리케이션을 위한 i18n 모듈의 영어 로케일을 재생성하기","en.json 파일의 새로운 키를 감지하고 번역하기"],"es":["Automatizar la traducción de contenido nuevo o cambiado a cuatro configuraciones regionales para DApps","Regenerar la configuración regional en inglés desde módulos i18n para aplicaciones multilingües","Detectar y traducir nuevas claves en archivos en.json"],"fr":["Automatiser la traduction de contenu nouveau ou modifié dans quatre configurations régionales pour les DApps","Régénérer la configuration régionale anglaise à partir de modules i18n pour les applications multilingues","Détecter et traduire de nouvelles clés dans les fichiers en.json"],"de":["Automatisieren der Übersetzung von neuem oder geändertem Inhalt in vier Spracheinstellungen für DApps","Regenerieren der englischen Spracheinstellung aus i18n-Modulen für mehrsprachige Anwendungen","Erkennen und Übersetzen neuer Schlüssel in en.json-Dateien"],"pt":["Automatizar a tradução de novo ou conteúdo alterado para quatro locais para DApps","Regenerar o local inglês a partir de módulos i18n para aplicações multilíngues","Detectar e traduzir novas chaves em arquivos en.json"],"ru":["Автоматизировать перевод нового или измененного контента на четыре локали для DApps","Регенерировать английский локаль из модулей i18n для мультиязычных приложений","Обнаруживать и переводить новые ключи в файлах en.json"],"ar":["تأتمة ترجمة المحتوى الجديد أو المتغير إلى أربعة مواقع إقليمية ل تطبيقات DApps","إعادة إنشاء الموقع الإنجليزي من مكونات i18n لتطبيقات متعددة اللغات","كشف المفاتيح الجديدة وترجمتها في ملفات en.json"]},"limitations":{"en":["Designed only for batch workflow","Limited to translating into four specific locales: zh, tc, ko, and one other unspecified locale"],"zh":["仅适用于批处理工作流","仅限翻译到四个特定区域设置：zh, tc, ko 和另一个未指定的区域设置"],"ja":["バッチ ワークフローにのみ対応","特定の 4 つのロケール (zh, tc, ko、および別の未指定のロケール) への翻訳のみ対応"],"ko":["배치 작업 흐름만을 지원","네 개의 특정 로케일(zh, tc, ko 및 또 다른 미지정 로케일)로 번역하는 것만을 지원"],"es":["Diseñado solo para flujos de trabajo por lotes","Limitado a la traducción a cuatro configuraciones regionales específicas: zh, tc, ko y otra configuración regional no especificada"],"fr":["Conçu uniquement pour les workflows par lot","Limité à la traduction dans quatre configurations régionales spécifiques : zh, tc, ko et une autre configuration régionale non spécifiée"],"de":["Nur für Batch-Arbeitsabläufe konzipiert","Begrenzt auf die Übersetzung in vier bestimmte Spracheinstellungen: zh, tc, ko und eine weitere nicht spezifizierte Spracheinstellung"],"pt":["Concebido apenas para fluxo de trabalho em lote","Limitado à tradução para quatro locais específicos: zh, tc, ko e outro local não especificado"],"ru":["Разработан только для пакетного рабочего процесса","Ограничен переводом на четыре конкретные локали: zh, tc, ko и одну другую неуказанную локаль"],"ar":["صمّم فقط لسير العمل الدفعي","محدود بالترجمة إلى أربعة مواقع إقليمية محددة: zh و tc و ko وموقع إقليمي آخر غير محدد"]},"version":4},"contentHash":"ede1d253d0e3ee6aa16de47782cc036e7f49a5b4cde85e65dde9e78b111b0f8d","qualityScore":57}');
