INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('OrderlyNetwork/dex-creator/translate-locales', 'translate-locales', 'OrderlyNetwork', 'dex-creator', 'community', 'translate-locales OrderlyNetwork dex-creator community The translate-locales skill regenerates the English locale from i18n modules and translates new or changed content into four locales for the DApp, benefiting developers working on multilingual applications. translate-locales 技术允许开发者使用 AIエージェント 实现批量翻译和多语言支持，支持 zh、ja、ko 等语言 translate-locales は、AIエージェントを使用して多言語対応を実現する技術です。React、Python、CLI などの技術と組み合わせて使用できます translate-locales 는 AI 에이전트를 사용하여 다국어 지원을 구현하는 기술입니다. Python, CLI 등의 기술과 함께 사용할 수 있습니다 translate-locales es una habilidad que regenera el locale inglés y traduce contenido nuevo o modificado a cuatro locales para tu DApp. translate-locales est une compétence qui régénère le locale anglais et traduit le contenu nouveau ou modifié en quatre locales pour votre DApp. translate-locales ist eine Fähigkeit, die das Englisch-locale regeneriert und neuen oder geänderten Inhalt in vier Sprachen für Ihre DApp übersetzt. O translate-locales é um skill que regenera o locale inglês a partir de módulos i18n e detecta novo ou alterado conteúdo para traduzir em quatro locais Translate-locales - это навык, который регенерирует английский локаль из модулей i18n и обнаруживает новый или измененный контент для перевода на четыре локали translate-locales هو مهارة تقوم بإعادة generar الlocale الإنجليزية من الوحدات i18n واكتشاف المحتوى الجديد أو المعدل لترجمته إلى أربعة مواقع how to use translate-locales what is translate-locales translate-locales alternative translate-locales setup guide translate-locales install DApp localization i18n module integration automated translation workflow translate-locales AIエージェント 批量翻译 多语言支持 React Python CLI zh语言支持 ja语言支持 ko语言支持 Regenerates English locale from i18n modules using the `@translate-locales` command Detects new or changed content in `app/app/i18n/locales/en.json` Translates content into four locales: zh, tc, ko Supports batch workflow for exporting and translating locale files Works with JSON file format for locale data Invoked explicitly using the `@translate-locales` command translate-locales is a skill that automates the localization process by regenerating English locales and translating content into zh, tc, ko, and other languages.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yusukebe/ai-with-hono/hono', 'community', 'yusukebe', 'ai-with-hono', 'yusukebe/ai-with-hono', 'hono', 5, 0, 57, '2026-01-28T07:09:06Z', '2026-03-06T06:54:19.086Z', '7654632ebcf81803855d3c64b08f26ac01c1915bf1cec2cb52e811a5d5423cf3', '{"id":"yusukebe/ai-with-hono/hono","name":"hono","description":{"en":"Hono is a skill that enables developers to efficiently develop Hono applications using Hono CLI. It benefits developers by providing a streamlined development process.","zh":"Hono是一种使用Hono CLI（@hono/cli）开发AI应用的效率工具","ja":"Honoは、Hono CLI（@hono/cli）を使用してAIエージェントを開発するための効率化ツール","ko":"Hono는 Hono CLI（@hono/cli）를 사용하여 AI 도구를 개발하는 효율성 도구","es":"Hono es una herramienta de desarrollo que permite crear aplicaciones de manera eficiente con Hono CLI. Ofrece comandos para buscar y visualizar documentación.","fr":"Hono est un outil de développement qui permet de créer des applications de manière efficace avec Hono CLI. Il propose des commandes pour rechercher et afficher la documentation.","de":"Hono ist ein Entwicklungstool, das es ermöglicht, Anwendungen effizient mit Hono CLI zu erstellen. Es bietet Befehle zum Suchen und Anzeigen von Dokumentationen.","pt":"O Hono CLI permite desenvolver aplicativos Hono de forma eficiente. Utilize comandos para busca e visualização de documentação.","ru":"Hono CLI позволяет эффективно разрабатывать приложения Hono. Используйте команды для поиска и просмотра документации.","ar":"Hono CLI يسمح بتطوير التطبيقات Hono بفعالية. استخدم أوامر البحث وعرض الوثائق."},"seo":{"title":{"en":"Hono Skill: Efficient Development Setup Guide | AI Agent","zh":"Hono Setup Guide: 优化您的AI开发体验","ja":"Honoのセットアップガイド: AIエージェント開発のベストプラクティス","ko":"Hono 설정 가이드: AI 도구 개발 효율화","es":"Guía de configuración de Hono: Desarrollo de aplicaciones...","fr":"Guide de configuration de Hono: Développement d''applicati...","de