INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('promobase/openpromo/ux-research', 'ux-research', 'promobase', 'openpromo', 'community', 'ux-research promobase openpromo community ux-research is a skill for AI agents that identifies friction in user flows and provides actionable improvements. It benefits developers and UX researchers in social media and ads management. ux-research 是一种 AI 工具，帮助优化用户体验，减少用户流中的摩擦。它提供了对用户行为的深入分析和改进建议 ux-research は、ユーザー体験を最適化し、ユーザーフロー中的のフリクションを減らす AI エージェントです。ユーザー行動に対する深い分析と改善提案を提供します ux-research는 사용자 경험을 최적화하고 사용자 흐름中的 마찰을 줄이는 AI 에이전트입니다. 사용자 행동에 대한 심층 분석과 개선 제안을 제공합니다 ux-research es una habilidad que ayuda a identificar la fricción en los flujos de usuario y proporciona mejoras acciónables ux-research est une compétence qui aide à identifier les frictions dans les flux d''utilisateurs et fournit des améliorations actionnables ux-research ist eine Fähigkeit, die dabei hilft, Reibungspunkte in Benutzerflüssen zu identifizieren und handhabbare Verbesserungen bereitzustellen A UX research é uma técnica para identificar atritos no fluxo de usuário e fornecer melhorias Исследование пользовательского опыта - это техника для выявления проблем в потоке пользователя и предоставления улучшений بحث تجربة المستخدم هو تقنية لتحديد العوائق في تدفق المستخدم وتقديم تحسينات how to use ux-research ux-research setup guide ux-research vs user testing what is ux-research ux-research install for AI agents ux-research best practices for social media ux-research AI 工具 用户体验优化 用户流分析 转化率提高 产品开发 用户行为分析 AI 技术 Identifies friction in user flows using a 15+ year industry-leading expertise Provides battle-tested, actionable improvements for UX optimization Simulates first-time user behavior with limited patience and unclear mental models Audits user flows to detect confusion or friction points Delivers expertise from companies like Apple, Stripe, and Airbnb ux-research is a specialized skill for identifying and improving user experience friction points in digital products and services.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mufengbufeng/opence/prompt-sync-workflow', 'community', 'mufengbufeng', 'opence', 'mufengbufeng/opence', 'prompt-sync-workflow', 3, 0, 57, '2026-02-08T11:34:15Z', '2026-03-06T07:00:49.730Z', '13897ad8fab9b1d50e564e8e59224cefd565e509c1e1648eb15e0d40f5b8ad64', '{"id":"mufengbufeng/opence/prompt-sync-workflow","name":"prompt-sync-workflow","description":{"en":"The prompt-sync-workflow skill coordinates prompt and skill updates for AI agents, ensuring consistent OpenCE workflow guidance. It benefits developers working with native skills and CLI commands.","zh":"prompt-sync-workflow是一种用于协调prompt和技能更新的工作流，适用于修改OpenCe工作流指导的场景。它可以帮助开发者优化AIエージェント的行为和CLI命令","ja":"prompt-sync-workflowは、OpenCeワークフローガイダンスを変更するシナリオ向けにプロンプトとスキルの更新を調整するワークフローです。AIエージェントの動作とCLIコマンドを最適化するのに役立ちます","ko":"prompt-sync-workflow는 OpenCe 작업 흐름 가이드를 변경하는 시나리오에 적합한 프롬프트 및 스킬 업데이트를 조정하는 워크 플로우입니다. AI 에이전트의 동작 및 CLI 명령을 최적화하는 데 도움이 됩니다","es":"El flujo de trabajo prompt-sync-workflow coordina actualizaciones de habilidades y prompts para una implementación eficiente de flujos de trabajo","fr":"Le workflow prompt-sync-workflow coordonne les mises à jour de compétences et de prompts pour une mise en œuvre efficace des flux de travail","de":"Der Workflow prompt-sync-workflow koordiniert Updates von Fähigkeiten und Prompts für eine effiziente Implementierung von Workflows","pt":"O prompt-sync-workflow é uma ferramenta para coordenar atualizações de prompt e habilidades em Ferramentas de IA, garantindo uma integração perfeita.","ru":"ИИ Агенты: prompt-sync-workflow - инструмент для координации обновлений запросов и навыков.","ar":"أداة الـAI: سير عمل prompt-sync-workflow لتنسيق تحديثات البرومبت والمهارات"},"seo":{"title":{"en":"prompt-sync-workflow: Coordinate AI Agent Updates | AI Ag...","zh":"AIエージェント开发指南：prompt-sync-workflow Setup","ja":"AIエージェント開発ガイド：prompt-sync-workflow ベストプラクティス","ko":"AI 에이전트 개발 가이드: prompt-sync-workflow 설정","es":"Configuración de prompt-sync-workflow para Herramientas d...","fr":"Guide d''installation de prompt-sync-workflow pour Outils ...","de":"Einrichtung von prompt-sync-workflow für KI-Tools und -As...","pt":"Guia de Configuração do prompt-sync-workflow para Ferrame...","ru":"Настройка Работы с ИИ Агентами при помощи prompt-sync-wor...","ar":"دليل إعداد أداة الـAI باستخدام سير عمل prompt-sync-workflow"},"description":{"en":"Streamline AI agent development with prompt-sync-workflow. Learn how to coordinate prompt and skill updates for seamless OpenCE workflow guidance. Get starte...","zh":"了解prompt-sync-workflow的技术细节和应用场景，优化AIエージェント的开发流程","ja":"prompt-sync-workflowのテクニカルな詳細と適用シナリオを学び、AIエージェントの開発プロセスを最適化する","ko":"prompt-sync-workflow의 기술 세부 사항과 응용 시나리오를 이해하고 AI 에이전트의 개발 프로세스를 최적화하십시오","es":"Aprende a coordinar actualizaciones de habilidades y prompts con prompt-sync-workflow para una implementación eficiente de flujos de trabajo","fr":"Découvrez comment coordonner les mises à jour de compétences et de prompts avec prompt-sync-workflow pour une mise en œuvre efficace des flux de travail","de":"Erfahren Sie, wie Sie Updates von Fähigkeiten und Prompts mit prompt-sync-workflow für eine effiziente Implementierung von Workflows koordinieren","pt":"Aprenda a coordenar atualizações de prompt e habilidades com o workflow de sincronização para Ferramentas de IA","ru":"Координируйте обновления запросов и навыков с помощью потока работы prompt-sync-workflow для ИИ Агентов","ar":"تعرف على كيفية تنسيق تحديثات البرومبت والمهارات باستخدام سير عمل prompt-sync-workflow لأدوات الـAI"},"definition":{"en":"prompt-sync-workflow is a skill that coordinates prompt and skill updates when implementing changes that affect OpenCE workflow guidance, ensuring AI assistants behave correctly during each phase.","zh":"prompt-sync-workflow是一种AIエージェント开发工作流，用于协调prompt和技能更新","ja":"prompt-sync-workflowは、プロンプトとスキルの更新を調整するAIエージェント開発ワークフローです","ko":"prompt-sync-workflow는 프롬프트 및 스킬 업데이트를 조정하는 AI 에이전트 개발 워크 플로우입니다","es":"Prompt-sync-workflow es un flujo de trabajo que coordina actualizaciones de habilidades y prompts para implementaciones de flujos de trabajo","fr":"Prompt-sync-workflow est un workflow qui coordonne les mises à jour de compétences et de prompts pour les mises en œuvre de flux de travail","de":"Prompt-sync-workflow ist ein Workflow, der Updates von Fähigkeiten und Prompts für die Implementierung von Workflows koordiniert","pt":"O que é prompt-sync-workflow? É uma ferramenta para coordenar atualizações de prompt e habilidades em Ferramentas de IA.","ru":"Что такое prompt-sync-workflow? Это инструмент для координации обновлений запросов и навыков для ИИ Агентов.","ar":"ما هو سير عمل prompt-sync-workflow? هو أداة لتنسيق تحديثات البرومبت والمهارات لأدوات الـAI"},"features":{"en":["Triggers updates when creating or modifying files in src/core/templates/","Supports adding new native skills, such as plan, work, review, compound, and skill-creator","Modifies workflow stages and their responsibilities","Changes AI assistant behavior during phases","Adds new CLI commands referenced in prompts"],"zh":["支持添加新本地技能（plan、work、review、compound、skill-creator）","支持修改工作流阶段或其职责","支持更改AIエージェント在阶段中的行为","支持添加新CLI命令"],"ja":["新しいネイティブスキル（plan、work、review、compound、skill-creator）の追加をサポート","ワークフローステージまたはその責任の変更をサポート","AIエージェントのフェーズ中の動作の変更をサポート","新しいCLIコマンドの追加をサポート"],"ko":["새로운 네이티브 스킬（plan、work、review、compound、skill-creator）的 추가를 지원합니다","작업 흐름 단계 또는 해당 책임의 변경을 지원합니다","AI 에이전트의 단계 중 동작의 변경을 지원합니다","새로운 CLI 명령의 추가를 지원합니다"],"es":["Coordinación de actualizaciones de habilidades y prompts","Implementación de flujos de trabajo personalizados","Compatibilidad con comandos de CLI","Actualizaciones de fases de flujo de trabajo","Soporte para habilidades nativas"],"fr":["Coordination des mises à jour de compétences et de prompts","Mise en œuvre de flux de travail personnalisés","Compatibilité avec les commandes CLI","Mises à jour des phases de flux de travail","Prise en charge des compétences natives"],"de":["Koordinierung von Updates von Fähigkeiten und Prompts","Implementierung von benutzerdefinierten Workflows","Unterstützung von CLI-Befehlen","Aktualisierungen von Workflow-Phasen","Unterstützung von nativen Fähigkeiten"],"pt":["Coordenação de atualizações de prompt e habilidades","Integração com CLI para referenciar comandos","Modificação de estágios de workflow e responsabilidades","Adição de novas habilidades nativas","Modificação do comportamento de assistentes de IA"],"ru":["Координация обновлений запросов и навыков","Интеграция с CLI для ссылок на команды","Модификация стадий рабочего процесса и ответственностей","Добавление новых родных навыков","Модификация поведения ИИ-помощников"],"ar":["تنسيق تحديثات البرومبت والمهارات","التكامل مع CLI للاشارة إلى أوامر","تعديل مراحل سير العمل والمسؤوليات","إضافة مهارات جديدة أصلية","تعديل سلوك مساعدي الـAI"]},"keywords":{"en":["how to use prompt-sync-workflow","prompt-sync-workflow setup guide","what is prompt-sync-workflow","prompt-sync-workflow alternative","prompt-sync-workflow vs OpenCE","prompt-sync-workflow install","coordinate AI agent updates","OpenCE workflow guidance","native skills development"],"zh":["AIエージェント开发","prompt-sync-workflow","OpenCe工作流指导","CLI命令","技能更新","工作流优化"],"ja":["AIエージェント開発","prompt-sync-workflow","OpenCeワークフローガイダンス","CLIコマンド","スキル更新","ワークフロー最適化"],"ko":["AI 에이전트 개발","prompt-sync-workflow","OpenCe 작업 흐름 가이드","CLI 명령","스킬 업데이트","작업 흐름 최적화"],"es":["prompt-sync-workflow","herramientas de inteligencia artificial","flujos de trabajo personalizados","comandos de CLI","actualizaciones de habilidades","implementación de flujos de trabajo","integración de AI"],"fr":["prompt-sync-workflow","outils d''intelligence artificielle","flux de travail personnalisés","commandes CLI","mises à jour de compétences","mise en œuvre de flux de travail","intégration d''IA"],"de":["prompt-sync-workflow","KI-Tools","benutzerdefinierte Workflows","CLI-Befehle","Updates von Fähigkeiten","Implementierung von Workflows","KI-Integration"],"pt":["Ferramentas de IA","prompt-sync-workflow","coordenar atualizações","CLI","habilidades nativas","modificação de workflow"],"ru":["ИИ Агенты","prompt-sync-workflow","координация обновлений","CLI","родные навыки","модификация рабочего процесса"],"ar":["أدوات الـAI","سير عمل prompt-sync-workflow","تنسيق تحديثات","CLI","المهارات الأصلية","تعديل سير العمل"]}},"owner":"mufengbufeng","repo":"opence","repoPath":"mufengbufeng/opence","stars":3,"forks":0,"updatedAt":"2026-02-08T11:34:15Z","topics":[],"category":"community","skillMd":{"name":"prompt-sync-workflow","description":"Coordinate prompt and skill updates across related changes","bodyPreview":"# prompt-sync-workflow\n\nCoordinate prompt and skill updates when implementing changes that affect opence workflow guidance.\n\n## When to Use\n\nUse this workflow when your change:\n- Adds new native skills (plan, work, review, compound, skill-creator)\n- Modifies workflow stages or their responsibilities\n- Changes how AI assistants should behave during a phase\n- Adds new CLI commands that should be referenced in prompts\n\n**Triggering signals**:\n- Creating or modifying files in `src/core/templates/`\n-","body":"# prompt-sync-workflow\n\nCoordinate prompt and skill updates when implementing changes that affect opence workflow guidance.\n\n## When to Use\n\nUse this workflow when your change:\n- Adds new native skills (plan, work, review, compound, skill-creator)\n- Modifies workflow stages or their responsibilities\n- Changes how AI assistants should behave during a phase\n- Adds new CLI commands that should be referenced in prompts\n\n**Triggering signals**:\n- Creating or modifying files in `src/core/templates/`\n- Adding entries to `OPENCE_SKILL_IDS`\n- Updating how `opence init` or `opence update` works\n\n## Workflow Steps\n\n### 1. Update Source Templates First\n\nEdit the canonical source in `src/core/templates/slash-command-templates.ts`:\n\n```typescript\n// Update the relevant step constants (planSteps, workSteps, etc.)\nconst compoundSteps = `**Steps**\n1. ...\n2. ...\n3. New or modified step\n4. ...`;\n```\n\nThis is the single source of truth that generates all downstream files.\n\n### 2. Update Matching Prompt Files\n\nIf you modify templates, also update the corresponding `.github/prompts/` files:\n\n```bash\n# These files are used by GitHub Copilot\n.github/prompts/opence-plan.prompt.md\n.github/prompts/opence-work.prompt.md\n.github/prompts/opence-review.prompt.md\n.github/prompts/opence-compound.prompt.md\n```\n\nKeep them in sync with `slash-command-templates.ts` content.\n\n### 3. Build and Run Update\n\n```bash\n# Rebuild to compile template changes\nnpm run build\n\n# Propagate to all tool directories\nopence update\n```\n\nThis will update:\n- `.claude/commands/opence/*.md` (Claude slash commands)\n- `.codex/prompts/opence-*.md` (Codex prompts)  \n- `.github/prompts/opence-*.prompt.md` (GitHub Copilot prompts)\n- `.claude/skills/opence-*/SKILL.md` (Claude skills)\n- `.codex/skills/opence-*/SKILL.md` (Codex skills)\n\n### 4. Verify Synchronization\n\nCheck that updates propagated correctly:\n\n```bash\n# Verify specific prompt updated\nSelect-String -Path .claude/skills/opence-compound/SKILL.md -Pattern \"your-new-text\"\n\n# Or check all locations\nrg \"your-new-text\" .claude/ .codex/ .github/prompts/\n```\n\n### 5. Test End-to-End\n\nFor new skills or commands:\n\n```bash\n# Test skill appears\nopence skill list\n\n# Test skill content\nopence skill show opence-your-skill\n\n# Test skill files exist\nls .claude/skills/opence-your-skill/\nls .codex/skills/opence-your-skill/\n```\n\n## Common Patterns\n\n### Adding a New Native Skill\n\n1. Add to `OpenceSkillId` type\n2. Add to `OPENCE_SKILL_IDS` array\n3. Add entry to `SKILLS` object\n4. Implement content generation function\n5. Update init.ts and update.ts if special handling needed\n6. Build, run `opence update`, verify\n\n### Modifying Existing Workflow Stage\n\n1. Update source in `slash-command-templates.ts`\n2. Update matching `.github/prompts/` file\n3. Build and run `opence update`\n4. Verify with `grep` or `Select-String`\n\n### Adding CLI Command Reference\n\n1. Document command in relevant skill (usually compound)\n2. Update source template with command usage\n3. Update `.github/prompts/` file\n4. Build and update\n5. Test command works as documented\n\n## Pitfalls to Avoid\n\n❌ **Don''t edit generated files directly**\n- Files in `.claude/`, `.codex/` are generated\n- Edit source templates instead\n\n❌ **Don''t forget `npm run build`**\n- Template changes need compilation\n- Update won''t pick up changes without build\n\n❌ **Don''t update only one tool**\n- If you update Claude prompts, update Codex too\n- Inconsistency confuses users with multiple tools\n\n❌ **Don''t skip verification**\n- Always check at least one generated file\n- Template typos propagate everywhere\n\n## Verification Checklist\n\nAfter changes:\n- [ ] Source template updated\n- [ ] `.github/prompts/` file updated\n- [ ] `npm run build` successful\n- [ ] `opence update` run\n- [ ] Spot-check 2+ generated files\n- [ ] New skills appear in `opence skill list`\n- [ ] Content matches expectations\n- [ ] Tests pass\n\n## See Also\n\n- `opence-skill-creator` - For creating project skills\n- docs/solutions/skill-creator-native-skill.md - Example of this workflow\n- docs/solutions/skill-management-commands.md - Another example\n\n\n### When to use this skill\n\n- [Scenario 1]\n- [Scenario 2]\n- [Scenario 3]\n\n### How to use this skill\n\n1. [Step 1]\n2. [Step 2]\n3. [Step 3]\n\n### Examples\n\n[Add examples of using this skill]\n\n### Guidelines\n\n- [Guideline 1]\n- [Guideline 2]\n\n### References\n\nSee the `references/` directory for additional documentation and context.\n\n### Scripts\n\nSee the `scripts/` directory for reusable code and utilities.\n"},"lastSynced":"2026-03-06T07:00:49.730Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code that require synchronized workflow guidance for native skills and CLI commands.","zh":"适用于像 Cursor、Windsurf 和 Claude Code 这样的 AI 代理，它们需要对原生技能和 CLI 命令进行同步的工作流指导。","ja":"Cursor、Windsurf、Claude Code などの AI エージェントに適しています。これらは、ネイティブ スキルと CLI コマンドの同期されたワークフロー ガイダンスを必要とします。","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에 적합합니다. 이들은 네이티브 스킬 및 CLI 명령에 대한同步된 워크플로우 가이드를 필요로합니다.","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que requieren orientación de flujo de trabajo sincronizado para habilidades nativas y comandos CLI.","fr":"Idéal pour les agents IA comme Cursor, Windsurf et Claude Code qui nécessitent une orientation de workflow synchronisée pour les compétences natives et les commandes CLI.","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die eine synchronisierte Workflow-Anleitung für native Fähigkeiten und CLI-Befehle benötigen.","pt":"Ideal para Agentes de IA como Cursor, Windsurf e Claude Code que exigem orientação de fluxo de trabalho sincronizado para habilidades nativas e comandos CLI.","ru":"Идеально для агентов ИИ, таких как Cursor, Windsurf и Claude Code, которые требуют синхронизированного руководства по рабочему процессу для родных навыков и команд CLI.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Cursor و Windsurf و Claude Code الذي يتطلب إرشادات سير عمل متزامنة لمهارات محلية وأوامر CLI."},"recommendation":{"en":"Empowers agents to coordinate prompt and skill updates seamlessly, ensuring consistent OpenCE workflow guidance through modifications to workflow stages, native skills, and CLI commands in files like `src/core/templates/`.","zh":"赋予代理人无缝地协调提示和技能更新的能力，确保通过对工作流阶段、原生技能和 CLI 命令的修改来实现一致的 OpenCE 工作流指导，例如在文件 `src/core/templates/` 中。","ja":"エージェントがプロンプトとスキルの更新をシームレスに調整できるようにし、ファイル `src/core/templates/` などのワークフロー ステージ、ネイティブ スキル、CLI コマンドの変更を通じて一貫した OpenCE ワークフロー ガイダンスを確保します。","ko":"에이전트가 프롬프트 및 스킬 업데이트를無침으로 조정할 수 있도록하여 `src/core/templates/`などの 파일에서 워크플로우 단계, 네이티브 스킬, CLI 명령의 수정을 통해 일관된 OpenCE 워크플로우 가이드를 보장합니다.","es":"Permite a los agentes coordinar actualizaciones de solicitudes y habilidades de forma fluida, garantizando una orientación de flujo de trabajo de OpenCE coherente a través de modificaciones en las etapas del flujo de trabajo, habilidades nativas y comandos CLI en archivos como `src/core/templates/`.","fr":"Permet aux agents de coordonner les mises à jour des invites et des compétences de manière transparente, assurant une orientation de workflow OpenCE cohérente à travers les modifications des étapes de workflow, des compétences natives et des commandes CLI dans des fichiers comme `src/core/templates/`.","de":"Ermöglicht es Agents, Anfragen- und Fähigkeitsaktualisierungen nahtlos zu koordinieren, wodurch eine konsistente OpenCE-Workflow-Anleitung durch Änderungen an den Workflow-Stufen, nativen Fähigkeiten und CLI-Befehlen in Dateien wie `src/core/templates/` sichergestellt wird.","pt":"Habilita os agentes a coordenar atualizações de prompts e habilidades de forma transparente, garantindo orientação de fluxo de trabalho consistente do OpenCE por meio de modificações em estágios de fluxo de trabalho, habilidades nativas e comandos CLI em arquivos como `src/core/templates/`.","ru":"Наделяет агентов возможностью координировать обновления подсказок и навыков бесшовно, обеспечивая последовательное руководство рабочим процессом OpenCE посредством изменений на стадиях рабочего процесса, родных навыках и командах CLI в файлах, таких как `src/core/templates/`.","ar":"تمكين الوكيل من تنسيق تحديثات الإشارات و المهارات بسلاسة، مما يضمن توجيه سير عمل متسق من OpenCE من خلال التعديلات على مراحل سير العمل و المهارات المحلية و أوامر CLI في الملفات مثل `src/core/templates/`."},"useCases":{"en":["Updating native skills like plan, work, review, compound, or skill-creator to reflect changes in workflow stages","Modifying workflow stages or their responsibilities to adapt to new AI assistant behaviors","Adding new CLI commands that should be referenced in prompts for enhanced user interaction"],"zh":["更新原生技能，如计划、工作、审查、复合或技能创建者，以反映工作流阶段的变化","修改工作流阶段或其职责，以适应新的 AI 助手行为","添加新的 CLI 命令，这些命令应该在提示中引用，以增强用户交互"],"ja":["プラン、作業、レビュー、複合、またはスキル作成者などのネイティブ スキルを更新して、ワークフロー ステージの変更を反映する","ワークフロー ステージまたはその責任を変更して、新しい AI アシスタントの動作に適応する","プロンプトで参照される新しい CLI コマンドを追加して、ユーザーの相互作用を強化する"],"ko":["계획, 작업, 검토, 합성 또는 스킬 생성자와 같은 네이티브 스킬을 업데이트하여 워크플로우 단계의 변경을 반영","새로운 AI 어시스트의 동작에 적응하기위한 워크플로우 단계 또는 해당 책임을 수정","사용자 상호 작용을 강화하기위한 프롬프트에서 참조할 새로운 CLI 명령을 추가"],"es":["Actualizar habilidades nativas como plan, trabajo, revisión, compuesto o skill-creator para reflejar cambios en las etapas del flujo de trabajo","Modificar las etapas del flujo de trabajo o sus responsabilidades para adaptarse a nuevos comportamientos de asistentes de IA","Agregar nuevos comandos CLI que deberían estar referenciados en solicitudes para una mejor interacción del usuario"],"fr":["Mettre à jour des compétences natives comme plan, travail, révision, composé ou skill-creator pour refléter les changements dans les étapes de workflow","Modifier les étapes de workflow ou leurs responsabilités pour s''adapter à de nouveaux comportements d''assistants IA","Ajouter de nouvelles commandes CLI qui devraient être référencées dans les invites pour une interaction utilisateur améliorée"],"de":["Aktualisieren von nativen Fähigkeiten wie Plan, Arbeit, Überprüfung, Zusammengesetzt oder Fähigkeits-Ersteller, um Änderungen an den Workflow-Stufen widerzuspiegeln","Ändern der Workflow-Stufen oder ihrer Verantwortlichkeiten, um sich an neue Verhaltensweisen von KI-Assistenten anzupassen","Hinzufügen neuer CLI-Befehle, die in Anfragen referenziert werden sollten, um eine verbesserte Benutzerinteraktion zu ermöglichen"],"pt":["Atualizar habilidades nativas como plano, trabalho, revisão, composto ou criador de habilidades para refletir alterações em estágios de fluxo de trabalho","Modificar estágios de fluxo de trabalho ou suas responsabilidades para se adaptar a novos comportamentos de assistentes de IA","Adicionar novos comandos CLI que devem ser referenciados em prompts para interação do usuário aprimorada"],"ru":["Обновление родных навыков, таких как план, работа, обзор, составной или создатель навыков, чтобы отразить изменения на стадиях рабочего процесса","Модификация стадий рабочего процесса или их ответственности для адаптации к новым поведениям помощников ИИ","Добавление новых команд CLI, которые должны быть ссылками в подсказках для улучшения взаимодействия пользователя"],"ar":["تحديث المهارات المحلية مثل الخطة و العمل و المراجعة و المركب أو مخترع المهارات لت phảnع تعديلات في مراحل سير العمل","تعديل مراحل سير العمل أو مسؤولياتها لتكيف مع سلوكيات جديدة لمساعدي الذكاء الاصطناعي","إضافة أوامر CLI جديدة التي يجب أن يتم الإشارة إليها في الإشارات لتعزيز تفاعل المستخدم"]},"limitations":{"en":["Requires updates to files in `src/core/templates/` to trigger synchronization","Limited to OpenCE workflow guidance"],"zh":["需要更新 `src/core/templates/` 中的文件以触发同步","仅限 OpenCE 工作流指导"],"ja":["同期をトリガーするために `src/core/templates/` 内のファイルを更新する必要がある","OpenCE ワークフロー ガイダンスのみに限定される"],"ko":["동기화 트리거를 위해 `src/core/templates/` 내의 파일을 업데이트해야함","OpenCE 워크플로우 가이드에만 제한됨"],"es":["Requiere actualizaciones de archivos en `src/core/templates/` para desencadenar la sincronización","Limitado a la orientación de flujo de trabajo de OpenCE"],"fr":["Nécessite des mises à jour de fichiers dans `src/core/templates/` pour déclencher la synchronisation","Limité à l''orientation de workflow OpenCE"],"de":["Benötigt Aktualisierungen von Dateien in `src/core/templates/`, um die Synchronisierung auszulösen","Begrenzt auf die OpenCE-Workflow-Anleitung"],"pt":["Exige atualizações em arquivos em `src/core/templates/` para disparar sincronização","Limitado à orientação de fluxo de trabalho do OpenCE"],"ru":["Требует обновлений файлов в `src/core/templates/`, чтобы запустить синхронизацию","Ограничен руководством рабочим процессом OpenCE"],"ar":["يتطلب تحديثات في الملفات في `src/core/templates/` لتسريع التزامن","محدود بتوجيه سير عمل OpenCE"]},"version":4},"contentHash":"13897ad8fab9b1d50e564e8e59224cefd565e509c1e1648eb15e0d40f5b8ad64","qualityScore":57}');
