INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mufengbufeng/opence/prompt-sync-workflow', 'prompt-sync-workflow', 'mufengbufeng', 'opence', 'community', 'prompt-sync-workflow mufengbufeng opence community The prompt-sync-workflow skill coordinates prompt and skill updates for AI agents, ensuring consistent OpenCE workflow guidance. It benefits developers working with native skills and CLI commands. prompt-sync-workflow是一种用于协调prompt和技能更新的工作流，适用于修改OpenCe工作流指导的场景。它可以帮助开发者优化AIエージェント的行为和CLI命令 prompt-sync-workflowは、OpenCeワークフローガイダンスを変更するシナリオ向けにプロンプトとスキルの更新を調整するワークフローです。AIエージェントの動作とCLIコマンドを最適化するのに役立ちます prompt-sync-workflow는 OpenCe 작업 흐름 가이드를 변경하는 시나리오에 적합한 프롬프트 및 스킬 업데이트를 조정하는 워크 플로우입니다. AI 에이전트의 동작 및 CLI 명령을 최적화하는 데 도움이 됩니다 El flujo de trabajo prompt-sync-workflow coordina actualizaciones de habilidades y prompts para una implementación eficiente de flujos de trabajo Le workflow prompt-sync-workflow coordonne les mises à jour de compétences et de prompts pour une mise en œuvre efficace des flux de travail Der Workflow prompt-sync-workflow koordiniert Updates von Fähigkeiten und Prompts für eine effiziente Implementierung von Workflows O prompt-sync-workflow é uma ferramenta para coordenar atualizações de prompt e habilidades em Ferramentas de IA, garantindo uma integração perfeita. ИИ Агенты: prompt-sync-workflow - инструмент для координации обновлений запросов и навыков. أداة الـAI: سير عمل prompt-sync-workflow لتنسيق تحديثات البرومبت والمهارات how to use prompt-sync-workflow prompt-sync-workflow setup guide what is prompt-sync-workflow prompt-sync-workflow alternative prompt-sync-workflow vs OpenCE prompt-sync-workflow install coordinate AI agent updates OpenCE workflow guidance native skills development AIエージェント开发 prompt-sync-workflow OpenCe工作流指导 CLI命令 技能更新 工作流优化 Triggers updates when creating or modifying files in src/core/templates/ Supports adding new native skills, such as plan, work, review, compound, and skill-creator Modifies workflow stages and their responsibilities Changes AI assistant behavior during phases Adds new CLI commands referenced in prompts prompt-sync-workflow is a skill that coordinates prompt and skill updates when implementing changes that affect OpenCE workflow guidance, ensuring AI assistants behave correctly during each phase.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tdhopper/dotfiles2.0/reviewing-code', 'community', 'tdhopper', 'dotfiles2.0', 'tdhopper/dotfiles2.0', 'reviewing-code', 3, 3, 57, '2026-02-26T16:55:23Z', '2026-03-06T07:01:11.106Z', 'f0db778840a3515f9653eab595025668b86ee4d82038f53a57ca2c52bfb1e275', '{"id":"tdhopper/dotfiles2.0/reviewing-code","name":"reviewing-code","description":{"en":"The reviewing-code skill helps developers manage code review with yadm, focusing on substantive issues like bugs and performance. It benefits developers by streamlining code review processes","zh":"代码审查工具用于优化代码质量和性能，支持Codex和Gemini等外部审查工具","ja":"コードレビューツールは、コードの品質とパフォーマンスを最適化するために使用され、CodexやGeminiなどの外部レビューツールをサポートします","ko":"코드 리뷰 도구는 코드 품질과 성능을 최적화 하는데 사용되며, Codex와 Gemini 등의 외부 리뷰 도구를 지원합니다","es":"Revisión de código con yadm y AI Agent para mejorar la calidad del código","fr":"Révision de code avec yadm et outil IA pour améliorer la qualité du code","de":"Code-Überprüfung mit yadm und KI-Tool für eine bessere Code-Qualität","pt":"Revisão de código com yadm e ferramentas de IA para melhorar a qualidade do código","ru":"Проверка кода с yadm и ИИ Агентами для повышения качества кода","ar":"مراجعة الشفرة باستخدام yadm وأدوات الإيضاح الإلكترونية لتحسين جودة الشفرة"},"seo":{"title":{"en":"Reviewing-Code: Setup Guide for AI Agents","zh":"代码审查工具：设置指南","ja":"コードレビューツール：セットアップガイド - AIエージェント","ko":"코드 리뷰 도구: 설정 가이드 - AI 에이전트","es":"Guía de Configuración para Revisión de Código con yadm y ...","fr":"Guide de Configuration pour la Révision de Code avec yadm...","de":"Konfigurationsleitfaden für Code-Review mit yadm und KI-Tool","pt":"Guia de Configuração para Revisão de Código com yadm e Fe...","ru":"Настройка ИИ Агентов для Проверки Кодa с yadm","ar":"دليل إعداد المراجعة الشفرة باستخدام yadm وأدوات الإيضاح ا..."},"description":{"en":"Discover how to optimize code review with yadm and AI tools like Codex and Gemini. Learn to prioritize substantive issues and streamline your workflow","zh":"了解代码审查工具的设置和最佳实践，优化代码质量和性能","ja":"コードレビューツールのセットアップとベストプラクティスを学び、コードの品質とパフォーマンスを最適化する - AIエージェント","ko":"코드 리뷰 도구의 설정과 최선의 방법을 배우고 코드 품질과 성능을 최적화하세요 - AI 에이전트","es":"Aprende a configurar yadm para la revisión de código y optimiza tu flujo de trabajo con AI Agent","fr":"Découvrez comment configurer yadm pour la révision de code et optimisez votre flux de travail avec l''outil IA","de":"Erfahren Sie, wie Sie yadm für die Code-Überprüfung konfigurieren und Ihren Arbeitsablauf mit dem KI-Tool optimieren","pt":"Aprenda a configurar yadm e integrar ferramentas de revisão de código para melhorar a qualidade do seu código","ru":"Узнайте, как настроить yadm и интегрировать инструменты проверки кода для повышения качества вашего кода с помощью ИИ Агентов","ar":"تعلم كيفية إعداد yadm وتكامل أدوات مراجعة الشفرة لتحسين جودة شفرتك باستخدام أدوات الإيضاح الإلكترونية"},"definition":{"en":"reviewing-code is a skill that utilizes yadm for managing dotfiles and prioritizes code review on substantive issues","zh":"代码审查工具是一种用于优化代码质量和性能的工具","ja":"コードレビューツールは、コードの品質とパフォーマンスを最適化するためのツールです","ko":"코드 리뷰 도구는 코드 품질과 성능을 최적화 하는ための 도구입니다","es":"Revisión de código es el proceso de examinar el código para detectar errores y mejorar su calidad","fr":"La révision de code est le processus d''examen du code pour détecter les erreurs et améliorer sa qualité","de":"Code-Überprüfung ist der Prozess der Überprüfung von Code, um Fehler zu erkennen und die Qualität zu verbessern","pt":"Revisão de código é o processo de análise de código para identificar problemas e melhorar a qualidade","ru":"Проверка кода - это процесс анализа кода для выявления проблем и повышения качества","ar":"مراجعة الشفرة هي عملية تحليل الشفرة لتحديد المشاكل وتحسين الجودة"},"features":{"en":["Utilizes yadm for dotfiles management","Prioritizes substantive code review issues like bugs and performance","Supports external review with Codex and Gemini","Checks for Codex availability with bash commands","Runs local branch with codex --config model_re command"],"zh":["支持Codex和Gemini等外部审查工具","优化代码质量和性能","支持本地分支审查","使用CLI命令进行审查"],"ja":["CodexやGeminiなどの外部レビューツールをサポート","コードの品質とパフォーマンスを最適化","ローカルブランチのレビューをサポート","CLIコマンドを使用してレビューを行う"],"ko":["Codex와 Gemini 등의 외부 리뷰 도구를 지원","코드 품질과 성능을 최적화","로컬 브ラン치 리뷰를 지원","CLI 명령어를 사용하여 리뷰를 수행"],"es":["Uso de yadm para la gestión de dotfiles","Integración con AI Agent para la revisión de código","Detección de problemas de código como errores y complejidad","Soporte para revisión externa con Codex y Gemini","Priorización de revisores con Codex y Gemini","Uso de comandos bash para la configuración y ejecución"],"fr":["Utilisation de yadm pour la gestion des dotfiles","Intégration avec l''outil IA pour la révision de code","Détection de problèmes de code tels que les erreurs et la complexité","Prise en charge de la révision externe avec Codex et Gemini","Priorisation des réviseurs avec Codex et Gemini","Utilisation de commandes bash pour la configuration et l''exécution"],"de":["Verwendung von yadm für die Verwaltung von dotfiles","Integration mit dem KI-Tool für die Code-Überprüfung","Erkennung von Codeproblemen wie Fehlern und Komplexität","Unterstützung für externe Überprüfung mit Codex und Gemini","Priorisierung von Überprüfern mit Codex und Gemini","Verwendung von Bash-Befehlen für die Konfiguration und Ausführung"],"pt":["Integração com yadm para gerenciamento de dotfiles","Suporte a revisão de código com ferramentas de IA","Priorização de revisores externos com Codex e Gemini","Execução de comandos bash para verificar disponibilidade de ferramentas"],"ru":["Интеграция с yadm для управления dotfiles","Поддержка проверки кода с помощью ИИ Агентов","Приоритизация внешних рецензентов с Codex и Gemini","Выполнение команд bash для проверки доступности инструментов"],"ar":["التكامل مع yadm لإدارة dotfiles","دعم مراجعة الشفرة باستخدام أدوات الإيضاح الإلكترونية","التأهيل الأولوية للمراجعين الخارجيين مع Codex وGemini","تشغيل أوامر bash للتحقق من توفر الأدوات"]},"keywords":{"en":["how to use reviewing-code","reviewing-code setup guide","yadm dotfiles management","codex vs gemini","reviewing-code install","code review best practices with AI tools"],"zh":["代码审查工具","代码质量优化","性能优化","Codex","Gemini","CLI命令","本地分支审查"],"ja":["コードレビューツール","コード品質最適化","パフォーマンス最適化","Codex","Gemini","CLIコマンド","ローカルブランチレビュー"],"ko":["코드 리뷰 도구","코드 품질 최적화","성능 최적화","Codex","Gemini","CLI 명령어","로컬 브ラン치 리뷰"],"es":["revisión de código","yadm","AI Agent","dotfiles","Codex","Gemini","revisión de código con AI","mejora de la calidad del código","detección de errores","integración con herramientas de desarrollo"],"fr":["révision de code","yadm","outil IA","dotfiles","Codex","Gemini","révision de code avec IA","amélioration de la qualité du code","détection d''erreurs","intégration avec les outils de développement"],"de":["Code-Überprüfung","yadm","KI-Tool","dotfiles","Codex","Gemini","Code-Überprüfung mit KI","Verbesserung der Code-Qualität","Fehlererkennung","Integration mit Entwicklungstools"],"pt":["revisão de código","yadm","ferramentas de IA","qualidade de código","desenvolvimento de software","gerenciamento de dotfiles","revisores externos","Codex","Gemini"],"ru":["проверка кода","yadm","ИИ Агенты","качество кода","разработка программного обеспечения","управление dotfiles","внешние рецензенты","Codex","Gemini"],"ar":["مراجعة الشفرة","yadm","أدوات الإيضاح الإلكترونية","جودة الشفرة","تطوير البرمجيات","إدارة dotfiles","مراجعين خارجيين","Codex","Gemini"]}},"owner":"tdhopper","repo":"dotfiles2.0","repoPath":"tdhopper/dotfiles2.0","stars":3,"forks":3,"updatedAt":"2026-02-26T16:55:23Z","topics":[],"category":"community","skillMd":{"name":"reviewing-code","description":"Review pull requests, branch changes, or code diffs. Triggers on review this PR, review my changes, code review, review branch, or GitHub PR URLs. Focuses on bugs, tests, complexity, and performance - not linting.","bodyPreview":"# Code Review\n\nFocus on substantive issues: bugs, missing tests, complexity, performance, duplication, incomplete implementations. Skip linting concerns (formatting, imports, naming style).\n\n## External Review (Optional)\n\nCheck for external reviewers and use if available. **Priority: Codex > Gemini**\n\n```bash\ncommand -v codex >/dev/null 2>&1 && echo \"Codex available\"\ncommand -v gemini >/dev/null 2>&1 && echo \"Gemini available\"\n```\n\n**If Codex available:**\n- Local branch: `codex --config model_re","body":"# Code Review\n\nFocus on substantive issues: bugs, missing tests, complexity, performance, duplication, incomplete implementations. Skip linting concerns (formatting, imports, naming style).\n\n## External Review (Optional)\n\nCheck for external reviewers and use if available. **Priority: Codex > Gemini**\n\n```bash\ncommand -v codex >/dev/null 2>&1 && echo \"Codex available\"\ncommand -v gemini >/dev/null 2>&1 && echo \"Gemini available\"\n```\n\n**If Codex available:**\n- Local branch: `codex --config model_reasoning_effort=\"high\" review --base BASE_BRANCH`\n- Remote PR: `gh pr diff NUMBER | codex review --config model_reasoning_effort=\"high\" -`\n\n**If only Gemini:** Pipe diff to gemini with review prompt.\n\n## Workflow\n\n1. **Get the diff**\n   - PR: `gh pr view NUMBER --json title,body,files` then `gh pr diff NUMBER`\n   - Branch: `git diff origin/master...HEAD`\n   - Uncommitted: `git diff`\n\n2. **Gather context** - Read PR description, commit messages, project CLAUDE.md\n\n3. **Review each file** for:\n   - **Completeness**: All code paths handled? Stubs left behind?\n   - **Tests**: Added? Meaningful? Edge cases covered?\n   - **Complexity**: Justified abstractions? Simpler alternatives?\n   - **Performance**: Hot path regressions? Unbatched I/O?\n   - **Duplication**: Similar code already exists? (`rg \"pattern\"`)\n\n4. **Synthesize** external review (if used) with your findings. Consensus issues = high confidence.\n\n## Output Format\n\n```markdown\n## Summary\n[1-2 sentences]\n\n## External Reviewer\n[If used: Codex or Gemini]\n\n## Key Findings\n\n### Must Address\n1. **[Issue]** (`file:line`) [Models]\n   - Details\n   - **Risk**: Why it matters\n\n### Should Consider\n2. **[Issue]** (`file:line`)\n   - Details\n\n### Minor Notes\n- Observations\n\n## Tests\n[Coverage and quality assessment]\n\n## Complexity\n[Net impact on codebase complexity]\n```\n\n**Numbering**: Single sequence across all sections. Model attribution: `[Codex + Claude]`, `[Claude]`, etc.\n\n## Scope\n\n**In scope**: Logic errors, missing error handling, test gaps, performance regressions, unnecessary complexity, duplication, incomplete implementations, project guideline violations.\n\n**Out of scope** (linters handle): Formatting, import order, naming style, type annotations, docstring format.\n"},"lastSynced":"2026-03-06T07:01:11.106Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced bug detection and performance optimization capabilities.","zh":"适合需要高级bug检测和性能优化能力的代码审查代理。","ja":"コードレビュー代理が高度なバグ検出とパフォーマンス最適化機能を必要とする場合に最適です。","ko":"고급 버그 감지 및 성능 최적화 기능이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan capacidades de detección de errores y optimización de rendimiento avanzadas.","fr":"Parfait pour les agents de révision de code nécessitant des capacités de détection de bogues et d''optimisation de performances avancées.","de":"Perfekt für Code-Review-Agents, die erweiterte Fähigkeiten zur Fehlererkennung und Leistungsoptimierung benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de detecção avançada de bugs e capacidades de otimização de desempenho.","ru":"Идеально подходит для агентов код-ревью, которым необходимы продвинутые возможности обнаружения ошибок и оптимизации производительности.","ar":"مثالي للوكلاء المراجعة اللغوية الذين يحتاجون إلى كشف الأخطاء المتقدمة وقدرات تحسين الأداء."},"recommendation":{"en":"Empowers agents to streamline code review processes, focusing on substantive issues like bugs, performance, and complexity, while utilizing tools like Codex and Gemini for external review, and skipping linting concerns using yadm.","zh":"赋予代理简化代码审查过程的能力，关注实质性问题，如bug、性能和复杂性，同时利用Codex和Gemini等工具进行外部审查，并使用yadm跳过代码风格检查问题。","ja":"エージェントにコードレビューのプロセスをストリームライン化する能力を与え、バグ、パフォーマンス、複雑性などの実質的な問題に焦点を当て、CodexやGeminiなどのツールを使用して外部のレビューを行い、yadmを使用してlintの問題をスキップします。","ko":"에이전트가 코드 리뷰 프로세스를 간소화할 수 있도록하며, 버그, 성능 및 복잡성과 같은 실질적인 문제에 중점을 두고 Codex 및 Gemini와 같은 도구를 사용하여 외부 리뷰를 수행하며 yadm을 사용하여 lint 문제를 건너뜁니다.","es":"Permite a los agentes simplificar los procesos de revisión de código, centrándose en problemas sustantivos como errores, rendimiento y complejidad, mientras utiliza herramientas como Codex y Gemini para la revisión externa, y omitiendo las preocupaciones de linting con yadm.","fr":"Permet aux agents de simplifier les processus de révision de code, en se concentrant sur des problèmes substantiels tels que les bogues, les performances et la complexité, tout en utilisant des outils comme Codex et Gemini pour la révision externe, et en ignorant les préoccupations de linting avec yadm.","de":"Ermöglich es den Agenten, Code-Review-Prozesse zu rationalisieren, indem sie sich auf wesentliche Probleme wie Fehler, Leistung und Komplexität konzentrieren, während sie Tools wie Codex und Gemini für die externe Überprüfung nutzen und Linting-Bedenken mit yadm umgehen.","pt":"Habilita os agentes a simplificar os processos de revisão de código, focando em questões substantivas como bugs, desempenho e complexidade, utilizando ferramentas como Codex e Gemini para revisão externa, e ignorando preocupações de linting usando yadm.","ru":"Наделяет агентов возможностью упростить процессы код-ревью, фокусируясь на существенных вопросах, таких как ошибки, производительность и сложность, используя инструменты, такие как Codex и Gemini для внешней проверки, и пропуская проблемы linting с помощью yadm.","ar":"يمكّن الوكلاء من تبسيط عمليات مراجعة الشفرة، مع التركيز على القضايا المهمة مثل الأخطاء والأداء والتعقيد، باستخدام أدوات مثل Codex وGemini لمراجعة خارجية، وتجاوز مشاكل linting باستخدام yadm."},"useCases":{"en":["Automating code reviews for bug detection","Optimizing code performance with external reviewers","Streamlining code review processes with yadm"],"zh":["自动化代码审查以检测bug","使用外部审查者优化代码性能","使用yadm简化代码审查过程"],"ja":["バグ検出のためのコードレビューの自動化","外部レビューアーを使用したコードパフォーマンスの最適化","yadmを使用したコードレビューのプロセスのストリームライン化"],"ko":["버그 감지를 위한 코드 리뷰 자동화","외부 리뷰어를 사용한 코드 성능 최적화","yadm을 사용한 코드 리뷰 프로세스 간소화"],"es":["Automatización de revisiones de código para la detección de errores","Optimización del rendimiento del código con revisores externos","Racionalización de los procesos de revisión de código con yadm"],"fr":["Automatisation des révisions de code pour la détection de bogues","Optimisation des performances du code avec des réviseurs externes","Rationalisation des processus de révision de code avec yadm"],"de":["Automatisierung von Code-Reviews zur Fehlertektion","Optimierung der Codeleistung mit externen Überprüfern","Rationalisierung von Code-Review-Prozessen mit yadm"],"pt":["Automatizar revisões de código para detecção de bugs","Otimizar desempenho de código com revisores externos","Simplificar processos de revisão de código com yadm"],"ru":["Автоматизация код-ревью для обнаружения ошибок","Оптимизация производительности кода с помощью внешних проверяющих","Упрощение процессов код-ревью с помощью yadm"],"ar":["تأتميم مراجعة الشفرة للكشف عن الأخطاء","تحسين أداء الشفرة مع المراجعين الخارجيين","تبسيط عمليات مراجعة الشفرة مع yadm"]},"limitations":{"en":["Requires yadm for code management","Codex or Gemini availability for external review","Limited to substantive issues, excluding linting concerns"],"zh":["需要yadm进行代码管理","需要Codex或Gemini进行外部审查","仅限于实质性问题，不包括代码风格检查问题"],"ja":["コード管理のためにyadmが必要","外部レビューのためにCodexまたはGeminiが必要","実質的な問題のみに限定され、lintの問題は除外される"],"ko":["코드 관리를 위해 yadm이 필요","외부 리뷰를 위해 Codex 또는 Gemini가 필요","실질적인 문제만 해당되며, lint 문제는 제외"],"es":["Requiere yadm para la gestión de código","Disponibilidad de Codex o Gemini para la revisión externa","Limitado a problemas sustantivos, excluyendo preocupaciones de linting"],"fr":["Nécessite yadm pour la gestion de code","Disponibilité de Codex ou Gemini pour la révision externe","Limité à des problèmes substantiels, excluant les préoccupations de linting"],"de":["Benötigt yadm für die Codeverwaltung","Verfügbarkeit von Codex oder Gemini für die externe Überprüfung","Begrenzt auf wesentliche Probleme, Linting-Bedenken ausgeschlossen"],"pt":["Requer yadm para gerenciamento de código","Disponibilidade de Codex ou Gemini para revisão externa","Limitado a questões substantivas, excluindo preocupações de linting"],"ru":["Требуется yadm для управления кодом","Доступность Codex или Gemini для внешней проверки","Ограничен существенными вопросами, исключая проблемы linting"],"ar":["يتطلب yadm لإدارة الشفرة","متوفرة Codex أو Gemini لمراجعة خارجية","محدود بالمسائل المهمة، باستثناء مشاكل linting"]},"version":4},"contentHash":"f0db778840a3515f9653eab595025668b86ee4d82038f53a57ca2c52bfb1e275","qualityScore":57}');
