INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tdhopper/dotfiles2.0/reviewing-code', 'reviewing-code', 'tdhopper', 'dotfiles2.0', 'community', 'reviewing-code tdhopper dotfiles2.0 community The reviewing-code skill helps developers manage code review with yadm, focusing on substantive issues like bugs and performance. It benefits developers by streamlining code review processes 代码审查工具用于优化代码质量和性能，支持Codex和Gemini等外部审查工具 コードレビューツールは、コードの品質とパフォーマンスを最適化するために使用され、CodexやGeminiなどの外部レビューツールをサポートします 코드 리뷰 도구는 코드 품질과 성능을 최적화 하는데 사용되며, Codex와 Gemini 등의 외부 리뷰 도구를 지원합니다 Revisión de código con yadm y AI Agent para mejorar la calidad del código Révision de code avec yadm et outil IA pour améliorer la qualité du code Code-Überprüfung mit yadm und KI-Tool für eine bessere Code-Qualität Revisão de código com yadm e ferramentas de IA para melhorar a qualidade do código Проверка кода с yadm и ИИ Агентами для повышения качества кода مراجعة الشفرة باستخدام yadm وأدوات الإيضاح الإلكترونية لتحسين جودة الشفرة how to use reviewing-code reviewing-code setup guide yadm dotfiles management codex vs gemini reviewing-code install code review best practices with AI tools 代码审查工具 代码质量优化 性能优化 Codex Gemini CLI命令 本地分支审查 Utilizes yadm for dotfiles management Prioritizes substantive code review issues like bugs and performance Supports external review with Codex and Gemini Checks for Codex availability with bash commands Runs local branch with codex --config model_re command reviewing-code is a skill that utilizes yadm for managing dotfiles and prioritizes code review on substantive issues');
