INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('StirlingMarketingGroup/cool-mysql/cool-mysql', 'cool-mysql', 'StirlingMarketingGroup', 'cool-mysql', 'community', 'cool-mysql StirlingMarketingGroup cool-mysql community cool-mysql is a MySQL helper library for Go that simplifies database operations. It benefits developers by reducing boilerplate code and providing advanced features. cool-mysql 是一个为 Go 而生的 MySQL 辅助库，提供缓存、自动重试和双读写连接池等高级功能 cool-mysql は、Go 用の MySQL ヘルパーライブラリで、キャッシュ、自動リトライ、デュアルリード/ライト接続プールなどの高度な機能を提供します cool-mysql은 Go용 MySQL 헬퍼 라이브러리로서 캐싱, 자동 재시도, 듀얼 리드/라이트 연결 풀 등을 제공합니다 Cool-mysql es una biblioteca de ayuda para MySQL en Go que reduce el código de boilerplate para operaciones de base de datos comunes y ofrece características avanzadas como caché y conexiones de lectura/escritura duales Cool-mysql est une bibliothèque d''aide pour MySQL en Go qui réduit le code de boilerplate pour les opérations de base de données courantes et offre des fonctionnalités avancées comme le cache et les connexions de lecture/écriture doubles Cool-mysql ist eine MySQL-Hilfsbibliothek für Go, die den Boilerplate-Code für gängige Datenbankoperationen reduziert und erweiterte Funktionen wie Caching und duale Lese-/Schreibverbindungen bietet A biblioteca cool-mysql é uma ferramenta de helper MySQL para Go que fornece conveniências para operações de banco de dados comuns Библиотека cool-mysql является библиотекой-хелпером для MySQL на основе ИИ Агентов, предоставляющей удобства для общих операций с базой данных مكتبة cool-mysql هي أداة مساعدة MySQL للغة Go التي توفر وسائل راحة لعمليات قاعدة البيانات الشائعة how to use cool-mysql cool-mysql alternative cool-mysql install what is cool-mysql cool-mysql vs go-sql-driver cool-mysql setup guide cool-mysql go library mysql helper library for go cool-mysql documentation cool-mysql MySQL 辅助库 Go MySQL 缓存 自动重试 双读写连接池 AIエージェント Wraps database/sql with MySQL-specific conveniences Reduces boilerplate code for common database operations Provides caching for improved performance Supports automatic retries for reliable connections Offers dual read/write connection pools for efficient data management cool-mysql is a MySQL helper library for Go that wraps database/sql with MySQL-specific conveniences.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fullstacktard/claude-workflow/surrealist-prompting', 'community', 'fullstacktard', 'claude-workflow', 'fullstacktard/claude-workflow', 'surrealist-prompting', 3, 0, 57, '2026-03-06T12:18:55Z', '2026-03-06T13:07:03.533Z', 'dd44a1e137eb18488019448f2fc0851ef255d544fe3861c70ba2f356230f60d6', '{"id":"fullstacktard/claude-workflow/surrealist-prompting","name":"surrealist-prompting","description":{"en":"The surrealist-prompting skill provides expert guidance for creating surrealist video content using AI video generation models, benefiting developers and content creators.","zh":"Surrealist Prompting技能提供Automated Claude Code配置设置，用于创建梦幻、超现实和迷幻内容","ja":"Surrealist Promptingスキルは、夢のような、超現実的、サイケデリックなコンテンツを作成するためのAutomated Claude Code構成設定を提供します","ko":"Surrealist Prompting 기술은夢幻、초현실적이고サイケデリック한 콘텐츠를 생성하기 위한Automated Claude Code 구성 설정을 제공합니다","es":"Surrealist Prompting es una habilidad que proporciona plantillas y consejos para generar contenido surrealista y psicodélico con modelos de generación de video AI","fr":"Surrealist Prompting est une compétence qui fournit des modèles et des conseils pour générer du contenu surréaliste et psychédélique avec des modèles de génération de vidéo IA","de":"Surrealist Prompting ist eine Fähigkeit, die Vorlagen und Tipps zur Erstellung von surrealistischem und psychedelischem Inhalt mit AI-Video-Generationsmodellen bietet","pt":"O Surrealist-Prompting é uma habilidade que fornece configuração automática de Claude Code para projetos existentes, permitindo a criação de conteúdo de vídeo surrealista e sonhador","ru":"Surrealist-Prompting - это умение, которое обеспечивает автоматическую настройку Claude Code для существующих проектов, позволяя создавать сурреалистическое и мечтательное видеоконтент","ar":"Surrealist-Prompting هي مهارة توفر إعدادًا تلقائيًا لمرمّز Claude للمشاريع الحالية، مما يسمح بإنشاء محتوى فيديو مستوحى من الحلم والخيال"},"seo":{"title":{"en":"Surrealist-Prompting: Automated Claude Code Setup Guide |...","zh":"Surrealist Prompting Setup Guide - AIエージェント配置","ja":"Surrealist Prompting ベストプラクティス - AIエージェント","ko":"Surrealist Prompting 설정 가이드 - AI 에이전트","es":"Configuración de Surrealist Prompting: Guía de Setup para...","fr":"Mise en place de Surrealist Prompting : Guide d''installat...","de":"Surrealist Prompting-Konfiguration: Einrichtungsanleitung...","pt":"Guia de Configuração do Surrealist-Prompting para Projeto...","ru":"Настройка Surrealist-Prompting: ИИ Агенты для видеоконтента","ar":"دليل إعداد Surrealist-Prompting لإنشاء محتوى فيديو مستوحى..."},"description":{"en":"Unlock surreal video generation with expert guidance on Claude Code configuration. Learn how to create dreamlike content with actionable templates and tips.","zh":"使用Surrealist Prompting技能创建梦幻、超现实和迷幻内容，了解如何配置AI视频生成模型","ja":"Surrealist Promptingスキルを使用して夢のような、超現実的、サイケデリックなコンテンツを作成する方法","ko":"Surrealist Prompting 기술을 사용하여梦幻、초현실적이고サイケデリック한 콘텐츠를 생성하는 방법","es":"Descubre cómo configurar Surrealist Prompting para generar contenido surrealista y psicodélico con modelos de generación de video AI","fr":"Découvrez comment configurer Surrealist Prompting pour générer du contenu surréaliste et psychédélique avec des modèles de génération de vidéo IA","de":"Erfahren Sie, wie Sie Surrealist Prompting konfigurieren, um surrealistisches und psychedelisches Inhalte mit AI-Video-Generationsmodellen zu erstellen","pt":"Aprenda a configurar o Surrealist-Prompting para criar conteúdo de vídeo surrealista e sonhador com modelos de geração de vídeo AI","ru":"Откройте для себя возможности Surrealist-Prompting: экспертные советы и шаблоны для создания сурреалистического видеоконтента с ИИ Агентами","ar":"اكتشف كيفية إعداد Surrealist-Prompting لإنشاء محتوى فيديو خيالي و梦ي باستخدام نماذج جيل الفيديو الإصطناعي"},"definition":{"en":"Surrealist-prompting is a skill that enables automated Claude Code configuration setup for existing projects to generate surrealist, dreamlike, and psychedelic video content.","zh":"Surrealist Prompting是一种AI技能，用于创建梦幻、超现实和迷幻内容","ja":"Surrealist Promptingは、夢のような、超現実的、サイケデリックなコンテンツを作成するためのAIスキルです","ko":"Surrealist Prompting은夢幻、초현실적이고サイケデリック한 콘텐츠를生成하기 위한AI 기술입니다","es":"Surrealist Prompting es una técnica de configuración de AI que permite generar contenido surrealista y psicodélico","fr":"Surrealist Prompting est une technique de configuration de l''IA qui permet de générer du contenu surréaliste et psychédélique","de":"Surrealist Prompting ist eine AI-Konfigurationstechnik, die die Erstellung von surrealistischem und psychedelischem Inhalt ermöglicht","pt":"O que é Surrealist-Prompting? É uma habilidade que permite a criação de conteúdo de vídeo surrealista e sonhador usando modelos de geração de vídeo AI","ru":"Что такое Surrealist-Prompting? Это умение, которое позволяет создавать сурреалистическое и мечтательное видеоконтент с помощью моделей генерации видео ИИ","ar":"ما هي Surrealist-Prompting؟ هي مهارة تمكن من إنشاء محتوى فيديو خيالي و梦ي باستخدام نماذج جيل الفيديو الإصطناعي"},"features":{"en":["Provides actionable templates for surrealist video generation","Offers provider-specific tips for consistent, high-quality output","Supports creation of dreamlike or surreal video content","Enables application of impossible physics effects, such as floating, melting, and morphing","Generates psychedelic or trippy visuals using AI video generation models","Includes curated examples for reference and inspiration"],"zh":["Automated Claude Code配置设置","梦幻、超现实和迷幻内容生成","支持不可思议的物理效果（浮动、熔解、变形）","提供特定 provider 的提示和示例"],"ja":["Automated Claude Code構成設定","夢のような、超現実的、サイケデリックなコンテンツ生成","不可思議な物理効果（浮動、溶解、変形）をサポート","特定のプロバイダーのヒントと例を提供"],"ko":["Automated Claude Code 구성 설정","夢幻、초현실적이고サイケデリック한 콘텐츠 생성","불가능한 물리 효과（부유、용해、변형）을 지원","특정 프로바이더의 힌트와 예제를 제공"],"es":["Configuración automática de Claude Code","Plantillas para generar contenido surrealista y psicodélico","Consejos para aplicar efectos de física imposibles","Generación de visuales psicodélicas y trippy","Referencia a ejemplos específicos de contenido surrealista"],"fr":["Configuration automatique de Claude Code","Modèles pour générer du contenu surréaliste et psychédélique","Conseils pour appliquer des effets de physique impossibles","Génération de visuels psychédéliques et trippy","Référence à des exemples spécifiques de contenu surréaliste"],"de":["Automatische Konfiguration von Claude Code","Vorlagen für die Erstellung von surrealistischem und psychedelischem Inhalt","Tipps für die Anwendung von unmöglichen Physikeffekten","Erstellung von psychedelischen und trippy Visuals","Verweis auf spezifische Beispiele für surrealistischen Inhalt"],"pt":["Configuração automática de Claude Code para projetos existentes","Criação de conteúdo de vídeo surrealista e sonhador com modelos de geração de vídeo AI","Aplicação de efeitos de física impossíveis, como flutuação, derretimento e metamorfose","Geração de visuais psicodélicos e alucinógenos","Referência a estilos e temas específicos"],"ru":["Автоматическая настройка Claude Code для существующих проектов","Создание сурреалистического и мечтательного видеоконтента с помощью моделей генерации видео ИИ","Применение невозможных физических эффектов, таких как плавание, расплавление и метаморфоза","Генерация психоделических и трип-видео","Ссылка на конкретные стили и темы"],"ar":["إعداد تلقائي لمرمّز Claude للمشاريع الحالية","إنشاء محتوى فيديو خيالي و梦ي باستخدام نماذج جيل الفيديو الإصطناعي","تطبيق تأثيرات فيزيائية مستحيلة، مثل الطفو والذوبان والتحول","إنشاء صور ومشاهد خيالية ومثيرة","المرجع إلى أساليب ومواضيع محددة"]},"keywords":{"en":["how to use surrealist-prompting","what is surrealist-prompting","surrealist-prompting alternative","surrealist-prompting vs deep dream generator","surrealist-prompting install","surrealist-prompting setup guide","AI video generation models","Claude Code configuration","surrealist video content creation"],"zh":["Surrealist Prompting","AIエージェント","Automated Claude Code","梦幻内容生成","超现实内容生成","迷幻内容生成","AI视频生成模型"],"ja":["Surrealist Prompting","AIエージェント","Automated Claude Code","夢のようなコンテンツ生成","超現実的コンテンツ生成","サイケデリックなコンテンツ生成","AIビデオ生成モデル"],"ko":["Surrealist Prompting","AI 에이전트","Automated Claude Code","夢幻콘텐츠 생성","초현실적콘텐츠 생성","サイケデリック한콘텐츠 생성","AI 비디오 생성 모델"],"es":["Surrealist Prompting","AI Agents","Herramientas de IA","Generación de video AI","Contenido surrealista","Efectos de física imposibles","Visuales psicodélicas","Configuración de Claude Code"],"fr":["Surrealist Prompting","Agents IA","Outils d''IA","Génération de vidéo IA","Contenu surréaliste","Effets de physique impossibles","Visuels psychédéliques","Configuration de Claude Code"],"de":["Surrealist Prompting","AI-Tools","KI-Agenten","AI-Video-Generierung","Surrealistischer Inhalt","Unmögliche Physikeffekte","Psychedelische Visuals","Claude-Code-Konfiguration"],"pt":["Surrealist-Prompting","configuração de Claude Code","modelos de geração de vídeo AI","conteúdo de vídeo surrealista","efeitos de física impossíveis","visuais psicodélicos","referência a estilos e temas"],"ru":["Surrealist-Prompting","настройка Claude Code","модели генерации видео ИИ","сурреалистическое видеоконтент","невозможные физические эффекты","психоделические видео","ссылка на стили и темы"],"ar":["Surrealist-Prompting","إعداد مرمّز Claude","نماذج جيل الفيديو الإصطناعي","محتوى فيديو خيالي","تأثيرات فيزيائية مستحيلة","صور ومشاهد خيالية","المرجع إلى أساليب ومواضيع"]}},"owner":"fullstacktard","repo":"claude-workflow","repoPath":"fullstacktard/claude-workflow","stars":3,"forks":0,"updatedAt":"2026-03-06T12:18:55Z","topics":[],"category":"community","skillMd":{"name":"surrealist-prompting","description":"Expert guidance for creating surrealist, dreamlike, and psychedelic content using AI video generation. Use when crafting prompts for artistic video content, applying impossible physics, or achieving specific surrealist aesthetics.","bodyPreview":"# Surrealist Prompting Skill\n\nExpert guidance for creating surrealist, dreamlike, and psychedelic content using AI video generation models. This skill provides actionable templates, provider-specific tips, and curated examples to ensure consistent, high-quality surrealist video generation.\n\n## When to Use This Skill\n\n- Creating dreamlike or surreal video content\n- Applying impossible physics effects (floating, melting, morphing)\n- Generating psychedelic or trippy visuals\n- Referencing specific a","body":"# Surrealist Prompting Skill\n\nExpert guidance for creating surrealist, dreamlike, and psychedelic content using AI video generation models. This skill provides actionable templates, provider-specific tips, and curated examples to ensure consistent, high-quality surrealist video generation.\n\n## When to Use This Skill\n\n- Creating dreamlike or surreal video content\n- Applying impossible physics effects (floating, melting, morphing)\n- Generating psychedelic or trippy visuals\n- Referencing specific art movements (Dali, Magritte, HR Giger)\n- Combining unexpected elements in artistic ways\n- Creating liminal or uncanny atmospheres\n- Animating logos or artwork with surreal motion\n- Producing music videos with abstract visuals\n\n## Common Queries\n\nThese are examples of questions that activate this skill:\n\n1. \"Create a surreal video with melting clocks and floating objects\"\n2. \"Generate a psychedelic music video with fractal visuals\"\n3. \"Make a dreamlike animation in the style of Salvador Dali\"\n4. \"Create a trippy video with impossible geometry\"\n5. \"Generate cosmic horror visuals with Lovecraftian themes\"\n6. \"Animate my logo with surreal, organic movement\"\n7. \"Create a liminal space video with uncanny atmosphere\"\n8. \"Make an ethereal video with hypnagogic imagery\"\n9. \"Generate Magritte-style surrealist content\"\n10. \"Create a fever dream sequence with morphing forms\"\n\n## Core Principles\n\n### Principle 1: Use \"Surreal\" or \"Dreamlike\" as Primary Modifier\n\nAI models are trained on surrealist art and respond exceptionally well to these tokens. Including them triggers creative, illogical outputs that capture the essence of surrealism.\n\n**Effective modifiers:**\n- \"surreal\", \"surrealist\", \"surrealism\"\n- \"dreamlike\", \"dream logic\", \"dream state\"\n- \"otherworldly\", \"ethereal\", \"mystical\"\n- \"uncanny\", \"liminal\", \"hypnagogic\"\n\n**Example prompt demonstrating this principle:**\n```\nA surreal garden where flowers have human faces and trees grow upside down,\ndreamlike atmosphere, soft ethereal glow, otherworldly color palette\n--chaos 25 --stylize 700\n```\n\n### Principle 2: Describe Impossible Physics\n\nSurrealism thrives on defying natural laws. Explicitly describe physical impossibilities to guide the AI toward genuinely surreal outputs.\n\n**Impossible physics keywords:**\n- \"defying gravity\", \"floating\", \"levitating\"\n- \"melting\", \"dripping\", \"liquid architecture\"\n- \"fractal dimensions\", \"impossible geometry\", \"non-Euclidean\"\n- \"morphing\", \"transforming\", \"metamorphosis\"\n- \"infinite recursion\", \"endless loops\", \"paradoxical spaces\"\n\n**Example prompt demonstrating this principle:**\n```\nStaircases that loop infinitely into themselves, defying gravity and logic,\nliquid architecture slowly melting upward, fractal dimensions visible through\nimpossible doorways, M.C. Escher inspired geometry --chaos 35 --stylize 750\n```\n\n### Principle 3: Juxtapose Unrelated Elements\n\nClassic surrealist technique: combine unexpected, unrelated elements in the same scene. The more surprising the combination, the more surreal the result.\n\n**Juxtaposition strategies:**\n- Natural + mechanical: \"forest made of gears\", \"organic machinery\"\n- Scale distortion: \"giant butterflies on tiny skyscrapers\"\n- Material substitution: \"clouds made of fabric\", \"ocean of glass\"\n- Temporal mixing: \"ancient ruins with holographic displays\"\n\n**Example prompt demonstrating this principle:**\n```\nA clock melting over a desert made of human eyes, grandfather clocks growing\nfrom the sand like cacti, hourglasses filled with liquid starlight,\nSalvador Dali inspired, hyperrealistic detail --chaos 30 --stylize 700\n```\n\n### Principle 4: Specify Art Movements and Artists\n\nReference specific surrealist artists or movements to guide the AI toward established aesthetic styles.\n\n**Key artist references:**\n- **Salvador Dali**: Melting forms, elongated figures, desert landscapes, symbolic imagery\n- **Rene Magritte**: Everyday objects in impossible contexts, bowler hats, clouded skies\n- **HR Giger**: Biomechanical nightmares, organic-metal fusion, alien aesthetics\n- **Yayoi Kusama**: Infinite polka dots, mirror rooms, pumpkins, cosmic patterns\n- **Hieronymus Bosch**: Medieval nightmare gardens, fantastical creatures, moral allegories\n- **Max Ernst**: Frottage textures, forest imagery, bird motifs\n- **Zdzislaw Beksinski**: Dark fantasy, skeletal forms, decaying architecture\n\n**Example prompt demonstrating this principle:**\n```\nA biomechanical cathedral interior, HR Giger aesthetic, organic ribbed walls\nmerging with Gothic architecture, bioluminescent membranes filtering light,\nalien machinery pulsing with life, dark atmospheric lighting\n--chaos 35 --stylize 800 --weird 500\n```\n\n### Principle 5: Include Emotional and Atmospheric Keywords\n\nSurrealist art evokes specific emotional responses. Include atmospheric and emotional descriptors to set the tone.\n\n**Atmospheric keywords:**\n- \"ethereal\", \"haunting\", \"melancholic\"\n- \"fever dream\", \"hypnagogic state\", \"lucid dream\"\n- \"cosmic horror\", \"existential dread\", \"sublime terror\"\n- \"nostalgic\", \"wistful\", \"bittersweet\"\n- \"mysterious\", \"enigmatic\", \"uncanny valley\"\n\n**Example prompt demonstrating this principle:**\n```\nA liminal hallway stretching into infinity, uncanny valley atmosphere,\nnostalgic melancholy permeating the space, hypnagogic state between\nwaking and sleeping, soft fluorescent buzz, faded wallpaper patterns\nshifting subtly --chaos 20 --ar 3:4 --stylize 600\n```\n\n## AI Video Model Capabilities & Limits\n\nUnderstanding what video models can and cannot do is critical for crafting prompts that produce usable output. These constraints apply to the models available via Replicate and the Runway Direct API.\n\n### What Video Models Do Well (Lean Into These)\n\n| Strength | Description | Example |\n|----------|-------------|---------|\n| **Single subject, simple motion** | One entity doing one thing is the sweet spot | A skull floating in a void, slowly rotating |\n| **Atmospheric environments** | Fog, rain, fire, mist, sunrise/sunset | Volumetric fog drifting through a dark cathedral |\n| **Lighting and mood** | Dramatic backlighting, neon, golden hour, volumetric rays | Crimson light pulsing through cracks in obsidian |\n| **Abstract/surreal content** | Impossible geometry, dreamlike transitions, floating objects -- models EXCEL here because they aren''t constrained by real-world physics | Staircases folding into themselves in non-Euclidean space |\n| **Slow camera movements** | Dolly, drift, orbit, slow zoom -- one movement at a time | Slow camera drift toward a glowing orb |\n| **Surface transformations** | Cracking, melting, morphing, dissolving | Stone surface fracturing to reveal molten light beneath |\n| **Environmental effects** | Fog, particles, glow, embers, dust (as mood, not precise trajectories) | Glowing embers rising from dark fissures |\n| **Dark scenes with accent lighting** | Single strong light source in darkness | A lone red light pulsing in infinite blackness |\n\n### Hard Failures (NEVER Include in Video Prompts)\n\nThese fail across ALL models available to us (Ray 2, Gen-4 Turbo, Kling v2.6, Hailuo 2.3, Veo 3.1, etc.):\n\n| Failure | Why It Fails | What to Do Instead |\n|---------|-------------|-------------------|\n| **Readable text, code, numbers** | Models generate gibberish glyphs. No current Replicate model renders readable text. | Add ALL text via Remotion post-production (text overlays, captions, titles) |\n| **Hands performing actions** | Extra fingers, fused digits, impossible joints. Hands are the #1 artifact in AI video. | Remove hands from frame, use wide shots, or replace hand actions with environmental effects |\n| **Specific detailed objects** | Playing cards (garbled faces), dice (wrong pips), instruments (wrong fingering), watches (unreadable) | Use abstract equivalents: \"glowing geometric shapes\" instead of \"playing cards\" |\n| **Multi-step action sequences** | \"Walk to table, pick up cup, drink\" -- models handle 1 action, not chains | One motion per clip. Split sequences across multiple clips. |\n| **Multiple interacting subjects** | Identity blending, face-swapping, clothing transfer between characters | Limit to 1-2 subjects max. Avoid physical interaction between them. |\n| **Complex physics** | Cloth draping, hair in wind, liquid pouring, collision chains | Describe mood and atmosphere, not precise physics. Let the model interpret. |\n| **Precise particle trajectories** | \"Particles spiral inward then explode outward\" -- too specific | Describe particle mood: \"embers drift upward\" not \"embers follow a helix path\" |\n\n### Risky (May Work -- Plan for Failure)\n\n| Element | Risk Level | Mitigation |\n|---------|-----------|------------|\n| Self-healing/sealing effects | Medium | Describe as \"energy flowing into cracks\" not \"hand seals the breach\" |\n| Multiple copies of same object | Medium | Models produce inconsistent copies -- avoid \"infinite network of skulls\" |\n| Very dark scenes with no light source | Medium | Models tend to auto-brighten. Always include at least one accent light. |\n| Fast motion in dark scenes | Medium-High | Increased motion blur artifacts. Prefer slow motion in dark environments. |\n| Two subjects in frame | Low-Medium | Works on newer models if subjects don''t physically interact |\n\n### The Golden Rule\n\n**AI generates VISUALS** (atmosphere, light, motion, transformation).\n**Remotion handles INFORMATION** (text, branding, labels, data, captions).\n\nNever ask the video model to communicate information. It creates moods and imagery.\n\n---\n\n## Prompt Feasibility Checklist\n\n**Run this check before submitting ANY video prompt:**\n\n- [ ] **Single subject focus** -- 1 main element (2 max if no interaction between them)\n- [ ] **One continuous motion** -- one primary motion per clip, not a sequence of actions\n- [ ] **No text, numbers, code, or readable symbols** -- all information goes in Remotion post\n- [ ] **No hands performing specific actions** -- no gripping, pointing, sealing, catching\n- [ ] **No objects requiring fine detail** -- no playing cards, dice, instruments, watches, written text\n- [ ] **Simple camera movement** -- one movement type (dolly OR drift OR orbit OR zoom)\n- [ ] **Duration within provider limits** -- Luma 5-9s (prefer 9s), Kling/Hailuo 5-10s, Veo 4-8s, Sora 4-12s, Wan 5-15s\n- [ ] **At least one light source** -- even in dark scenes, include accent lighting to prevent auto-brightening\n- [ ] **Mood descriptors included** -- atmospheric and emotional keywords guide the model\n\nIf a prompt fails any check, revise it before submitting.\n\n---\n\n## Translating Concepts to Feasible Visuals\n\nWhen a creative brief uses abstract concepts, translate them into visual metaphors that models handle well. The FEELING matters, not literal representation.\n\n### Security / Protection\n```\nBAD:  \"A glowing shield deflects incoming threat particles that disintegrate on contact\"\nGOOD: \"A vast dark cathedral with rivers of red energy flowing through stone channels, a single pulsing orb suspended at the center\"\nWHY:  Architecture + lighting = reliable. Shield physics + particle interactions = unreliable.\n```\n\n### Breach / Vulnerability\n```\nBAD:  \"A skeletal hand reaches through a fracture and seals it with red lightning\"\nGOOD: \"An obsidian surface cracking apart in slow motion, molten red light erupting from deep fissures, dark fragments suspended mid-air\"\nWHY:  Surface fracturing = single transformation. Hands + lightning + sealing = 3 sequential actions with worst-case elements.\n```\n\n### Data / Code / Digital\n```\nBAD:  \"Floating terminal text and hexadecimal streams flowing through a digital fortress\"\nGOOD: \"Glowing geometric patterns flowing through dark channels like rivers of light, pulsing with rhythmic energy\"\nWHY:  Models can''t generate readable text. Abstract light patterns convey \"digital\" without requiring legible characters.\n```\n\n### Power / Dominance\n```\nBAD:  \"A figure raises their hand and lightning erupts from their palm, text appears saying POWER\"\nGOOD: \"A colossal skull floating in an infinite void, crimson beams radiating from hollow eye sockets, orbiting particles forming a planetary ring\"\nWHY:  Single object + light effects = reliable. Hands + lightning + text = triple hard-fail.\n```\n\n### Speed / Transformation\n```\nBAD:  \"A clock''s hands spin rapidly then the clock explodes into a flock of birds\"\nGOOD: \"A clock face slowly melting and dripping into calm water below, its form dissolving into rippling reflections\"\nWHY:  Slow continuous transformation = achievable. Rapid motion + explosion + animal generation = unreliable.\n```\n\n---\n\n## Provider-Specific Tips\n\n### Reference Image Generation (Midjourney)\n\nWhen using image-to-video workflows, Midjourney is excellent for generating surrealist reference images that feed into video models. These parameters optimize surreal image output:\n\n```\n--chaos 20-50    # Higher chaos = more unexpected, surreal results\n                 # Start at 25 for controlled surrealism, 40+ for wild psychedelia\n\n--stylize 500-750  # Balance between prompt adherence and artistic interpretation\n                   # Higher values = more artistic freedom\n\n--style raw      # More literal interpretation for precise surrealism\n                 # Use when you want specific elements rendered accurately\n\n--ar 9:16 or 3:4  # Vertical formats work exceptionally well for dreamlike content\n                  # Suggest depth and portal-like imagery\n\n--weird 250-1000  # Increases unconventional aesthetics\n                  # 250-500 for subtle weird, 750+ for extreme surrealism\n```\n\n**Template for reference images:**\n```\n[Subject] in a [setting], [surreal element], [art movement] inspired,\n[atmosphere] atmosphere, [lighting], [quality modifiers]\n--chaos [20-45] --stylize [600-800] --ar [aspect ratio]\n```\n\nThen animate the generated image using `video_image_to_video` with Luma or Runway.\n\n### Video Provider Tips\n\n#### Luma (Ray 2) -- Best for Atmospheric Surrealism\n- Excels at dreamlike quality, coherent single-subject scenes\n- 5-9s duration (prefer 9s for richer scenes)\n- Strong at: transformations, environmental effects, abstract motion\n- Weak at: fast motion, multiple characters, long sequences\n- Supports image-to-video with start frame\n\n```\nA vintage telephone with flowers growing from the receiver, floating in a vast\ndesert landscape at golden hour, dreamy atmosphere, soft warm lighting,\nDali-inspired surrealism, smooth camera drift\n```\n\n#### Kling (v2.6) -- Best for Fast Iteration + Audio\n- 5-10s duration, quick generation turnaround\n- **Native audio generation enabled** -- include ambient sound cues in prompts\n- Good at: character motion, iterative prompt refinement\n- Weak at: fine detail, text rendering\n\n```\nSlow dreamy camera drift through impossible architecture, objects float past\ndefying gravity, surfaces ripple like water, perspective shifts impossibly,\nambient hum of energy, dreamlike pace\n```\n\n#### Hailuo/MiniMax (2.3) -- Best for Character Motion\n- 6-10s duration, best motion fluidity of all providers\n- Strong at: dynamic movement, vibrant colors, character motion\n- Weak at: static scenes (wastes its strength)\n- Use explicit camera direction language\n\n```\nDirector: slow dolly through crystalline cavern, camera tilts to reveal\ngravity-defying waterfalls flowing upward, vibrant iridescent colors\nshimmer across surfaces, physics-bending reflections in every crystal face\n```\n\n#### Veo (3.1) -- Best Overall Quality-to-Cost\n- 4-8s duration, Google-quality output\n- **Native audio generation enabled** -- include sound descriptors\n- Fast variant available for cheaper iteration\n- Strong at: visual quality, atmospheric scenes, coherent motion\n\n#### Runway (Gen-4 Turbo) -- Premium Quality\n- Via Replicate: image-to-video, 5-10s\n- Via Direct API (with RUNWAY_API_KEY): text-to-video 4-8s, **audio enabled**, best camera control\n- Strong at: highest visual fidelity, precise camera parameters\n- Use for: final deliverables where quality matters most\n\n#### Wan (2.6) -- Longest Duration\n- 5-15s -- the longest text-to-video option available\n- Good baseline quality, budget-friendly\n- Use when you need clips longer than 10 seconds\n\n#### Sora (2 Pro) -- Extended Duration + Quality\n- 4-12s duration, OpenAI quality\n- Strong narrative coherence over longer clips\n- Good for: extended surreal sequences that need temporal consistency\n\n## Style Templates\n\nUse this universal template structure for any surrealist prompt:\n\n```\n[Subject] + [Surreal element] + [Style/Art movement] + [Atmosphere] + [Technical parameters]\n```\n\n### Style 1: Surrealist (Dali/Magritte)\n\nClassic surrealism with symbolic imagery and dreamlike logic.\n\n```\n[subject] in a Dali-esque landscape, melting clocks scattered across\nimpossible horizons, elongated shadows stretching toward infinity,\nimpossible architecture defying perspective, dreamlike atmosphere,\nhyperrealistic detail, golden hour lighting\n--chaos 25 --stylize 700\n```\n\n**Key elements:** Melting forms, symbolic objects, desert landscapes, elongated figures, impossible perspectives.\n\n### Style 2: Psychedelic/Trippy\n\nIntense visual experiences with fractal patterns and consciousness-expanding imagery.\n\n```\nInfinite fractal corridors of liquid chrome reflecting nebulae,\npsychedelic journey through consciousness, kaleidoscopic patterns\nmorphing between organic and geometric forms, DMT vision aesthetic,\nelectric neon colors pulsing with cosmic energy\n--chaos 40 --stylize 750\n```\n\n**Key elements:** Fractals, kaleidoscopic patterns, chromatic effects, consciousness themes, intense colors.\n\n### Style 3: Dreamlike/Ethereal\n\nSoft, nostalgic atmospheres with hypnagogic imagery.\n\n```\n[subject] in a liminal space, soft ethereal glow, muted pastel colors,\nfog drifting through impossible doorways, nostalgic melancholy,\nhypnagogic state between waking and dreaming, film photography grain,\nquiet contemplative atmosphere\n--chaos 20 --ar 3:4 --stylize 650\n```\n\n**Key elements:** Soft lighting, muted colors, fog, liminal spaces, nostalgic tone.\n\n### Style 4: Cosmic Horror\n\nVast, incomprehensible scales with Lovecraftian undertones.\n\n```\n[subject] encountering vast incomprehensible geometry, Lovecraftian scale,\nbioluminescent void creatures drifting through non-Euclidean space,\nreality fracturing at the edges, overwhelming sense of insignificance,\nHR Giger organic machinery, cosmic dread atmosphere\n--chaos 35 --stylize 800 --weird 500\n```\n\n**Key elements:** Massive scale, alien geometry, organic machinery, existential dread, void creatures.\n\n### Style 5: Liminal/Uncanny\n\nEmpty transitional spaces with unsettling familiarity.\n\n```\n[subject] in an endless backroom, yellow-tinted fluorescent lighting,\nidentical corridors repeating infinitely, faded corporate carpet patterns,\nuncanny valley atmosphere, something is wrong but indescribable,\nnostalgic 90s aesthetic, analog horror undertones\n--chaos 25 --stylize 550 --ar 16:9\n```\n\n**Key elements:** Repetitive spaces, harsh lighting, nostalgic decay, subtle wrongness, empty corridors.\n\n### Style 6: Organic/Mechanical Fusion\n\nBiomechanical aesthetics blending living and machine.\n\n```\n[subject] made of living machinery, organic circuits pulsing with\nbioluminescent fluid, mechanical bones wrapped in synthetic muscle,\ncybernetic flora growing from metal soil, HR Giger meets botanical garden,\ndark industrial atmosphere with organic warmth\n--chaos 30 --stylize 750 --weird 350\n```\n\n**Key elements:** Biomechanical, bioluminescence, industrial organic, synthetic life.\n\n## Example Prompts\n\nBelow are curated prompts organized by use case. Each is tagged for its intended medium.\n\n### Reference Image Prompts (Midjourney → image-to-video)\n\nThese use Midjourney parameters. Generate the image first, then animate with `video_image_to_video`.\n\n#### 1. Abstract/Psychedelic `[IMAGE]`\n```\nInfinite fractal corridors of liquid chrome reflecting nebulae,\npsychedelic journey through consciousness, kaleidoscopic patterns\nmorphing between organic and geometric forms, DMT vision aesthetic,\nsaturated electric colors --chaos 40 --stylize 750\n```\n\n#### 2. Dali-Inspired `[IMAGE]`\n```\nFloating islands of crystalline forms reaching toward a melting clock sun,\nelephants on impossibly thin legs walking across the sky, Salvador Dali\ninspired, ethereal light, desert of the subconscious, symbolic imagery\n--chaos 30 --stylize 750\n```\n\n#### 3. Practical Product Surrealism `[IMAGE]`\n```\nSurreal car made of pink balloons, covered by pink balloons, photography,\nhyperrealistic, blue sky with clean white clouds, commercial surrealism,\nplayful impossible physics --chaos 20 --ar 3:4 --style raw\n```\n\n#### 4. Magritte-Style Conceptual `[IMAGE]`\n```\nA figure in a bowler hat standing in a room where the walls are made\nof blue sky and clouds, a green apple hovering in mid-air,\nRene Magritte inspired, clean painterly style, conceptual surrealism,\neveryday objects in impossible context --chaos 20 --stylize 650\n```\n\n#### 5. Organic/Mechanical Fusion `[IMAGE]`\n```\nA cathedral where every surface is living tissue wrapped around steel bones,\nribbed vaults that breathe, stained glass windows made of stretched membrane,\nHR Giger aesthetic, sacred biomechanical space, bioluminescent altar light\n--chaos 30 --stylize 750 --weird 400\n```\n\n### Video Prompts (direct text-to-video)\n\nThese are optimized for video generation models. Each follows the feasibility checklist.\n\n#### 6. Logo Animation `[VIDEO]` -- Luma, Kling, or Hailuo\n```\nGentle camera push in, subtle particle effects emanating from the design,\nethereal glow intensifies, dreamlike breathing motion where forms slightly\nmorph and pulse, surreal organic movement, hypnotic rhythm\n```\n\n#### 7. Liminal Space `[VIDEO]` -- Luma or Veo\n```\nAn endless empty corridor with faded wallpaper, fluorescent lights\nflickering overhead, the hallway stretching impossibly into the distance,\nslow camera drift forward, liminal atmosphere, nostalgic uncanny mood,\nvaporwave color palette, analog horror undertones\n```\n\n#### 8. Cosmic Scale `[VIDEO]` -- Luma or Runway\n```\nA vast incomprehensible structure stretching across a void, impossibly\nlarge alien geometry, a single point of light dwarfed by the architecture,\ncosmic horror scale, slow camera pull back revealing immensity,\nexistential sublime, cinematic lighting\n```\n\n#### 9. Memory/Nostalgia `[VIDEO]` -- Luma or Wan (longer duration)\n```\nFragments of a room floating in void, objects drifting apart in slow motion,\nwarm sepia tones bleeding into cool blue, light particles dissolving\nfrom surfaces, nostalgic melancholy atmosphere, gentle camera orbit,\ndreamlike decay\n```\n\n#### 10. Nature Impossibilities `[VIDEO]` -- Veo or Luma\n```\nA forest where trees grow downward from the sky into clouds below,\nroots reaching toward distant stars, leaves shimmering with liquid\nmirror reflections, gravity reversed, serene impossibility,\nslow camera tilt upward, magical realism\n```\n\n#### 11. Kusama Infinite Patterns `[VIDEO]` -- Hailuo or Kling\n```\nAn infinite room of mirrors reflecting red polka dots into eternity,\npumpkins floating in void, obsessive repetition fading into darkness,\nhypnotic depth, slow camera rotation, psychedelic calm,\nYayoi Kusama aesthetic\n```\n\n#### 12. Dark Atmospheric (with audio cues) `[VIDEO]` -- Kling or Veo\n```\nA colossal skull carved from dark stone slowly emerging from total darkness,\ndeep red light pulsing through cracks and fissures, crimson glow from\nhollow eye sockets, slow camera drift forward, ominous dark atmosphere,\nvolumetric fog, deep ambient hum resonating through the void\n```\n\n## Prompt Structure Formula\n\nFor consistent results, follow this structure:\n\n```\n[SUBJECT] + [SURREAL MODIFICATION] + [ARTIST/STYLE REFERENCE] + [ATMOSPHERE] + [LIGHTING] + [TECHNICAL PARAMS]\n```\n\n**Components explained:**\n\n1. **Subject**: What is the main focus? (person, object, landscape, abstract concept)\n2. **Surreal Modification**: How is it made surreal? (melting, floating, impossible scale, juxtaposition)\n3. **Artist/Style Reference**: Which aesthetic? (Dali, Magritte, Giger, psychedelic, liminal)\n4. **Atmosphere**: What feeling? (dreamlike, uncanny, ethereal, cosmic horror)\n5. **Lighting**: How is it lit? (golden hour, neon, bioluminescent, harsh fluorescent)\n6. **Technical Params**: Generation settings (chaos, stylize, aspect ratio, weird)\n\n**Example applying formula:**\n```\n[A grandmother] + [made of clockwork with visible gears for organs] +\n[steampunk surrealist, Max Ernst influence] + [nostalgic melancholy atmosphere] +\n[warm golden afternoon light streaming through dusty windows] +\n--chaos 25 --stylize 700 --ar 3:4\n```\n\n## Workflow Recommendations\n\n### Professional Surrealist Short Video (Best Quality)\n\n**Pipeline:** Midjourney → Runway (Gen-4 Turbo) → Remotion compositor\n\n1. Generate surreal keyframes in Midjourney with consistent --sref codes\n2. Animate with `video_image_to_video` via Runway for premium quality\n3. Compose in Remotion with text overlays, transitions, branding, and audio\n\n### Quick Surrealist Clips (Fast Iteration)\n\n**Pipeline:** Text prompt → Kling (v2.6) or Luma (Ray 2)\n\n1. Craft prompt following feasibility checklist\n2. Generate with `video_text_to_video` -- Kling for fast turnaround, Luma for dreamlike quality\n3. Iterate 2-3 times with seed variation or prompt refinement\n\n### Multi-Clip Branded Video (Full Pipeline)\n\n**Pipeline:** surreal-clip-generator → surreal-clip-compositor\n\n1. Generate 3-5 individual clips across providers\n2. Hand off to compositor for branding, transitions, text overlays, audio\n3. Render final MP4 via Remotion\n\n### Extended Narrative (Longer Duration)\n\n**Pipeline:** Text prompt → Wan (2.6) or Sora (2 Pro)\n\n1. Write scene-by-scene script\n2. Generate individual clips (Wan up to 15s, Sora up to 12s per clip)\n3. Compose in Remotion with transitions between clips\n\n### Logo Animation\n\n**Pipeline:** Logo image → Luma (Ray 2) image-to-video\n\n1. Upload logo/artwork as reference image\n2. Use gentle motion prompt (breathing, pulsing, particle effects)\n3. Single 9s clip, minimal post-processing needed\n\n## Quick Reference Card\n\n### Video Generation (via Replicate / Runway Direct)\n\n| Goal | Provider | Duration | Notes |\n|------|----------|----------|-------|\n| Atmospheric surreal scenes | `luma` (Ray 2) | 5-9s | Dreamlike quality, single-subject |\n| Premium final deliverables | `runway` (Gen-4 Turbo) | 5-10s | Highest fidelity, best camera control |\n| Fast iteration / audio | `kling` (v2.6) | 5-10s | Quick turnaround, native audio |\n| Character-focused motion | `minimax` (Hailuo 2.3) | 6-10s | Best fluidity and dynamic movement |\n| Best quality-to-cost | `veo` (3.1) | 4-8s | Google quality, native audio |\n| Extended clips | `wan` (2.6) | 5-15s | Longest duration available |\n| Longer narrative | `sora` (2 Pro) | 4-12s | Good temporal coherence |\n| Budget / experimentation | `hunyuan` | 5s | Baseline quality |\n\n### Reference Image Generation (Midjourney → image-to-video)\n\n| Style | Key Parameters |\n|-------|----------------|\n| Dali-style surrealism | --chaos 25-35, --stylize 700+ |\n| Psychedelic/trippy | --chaos 40+, --weird 500+ |\n| Dreamlike narrative | --chaos 20-30, vertical AR |\n| Cosmic horror | --weird 500+, --chaos 35+ |\n| Liminal spaces | --chaos 20-25, 16:9 AR |\n| Biomechanical | --weird 350-500, --stylize 750+ |\n\n## Common Mistakes to Avoid\n\n### Prompt Engineering Mistakes\n\n**Mistake 1: Over-specifying realism**\n- Bad: \"photorealistic, 8k, ultra detailed, sharp focus\" with surreal elements\n- Better: Balance hyperrealistic with dreamlike modifiers\n\n**Mistake 2: Contradictory style references**\n- Bad: \"Dali meets minimalist modern design\"\n- Better: Stick to compatible aesthetic families\n\n**Mistake 3: Insufficient surreal elements**\n- Bad: \"A cat sitting on a chair, surreal\"\n- Better: \"A cat made of liquid glass sitting on a chair that melts into the floor, surreal\"\n\n**Mistake 4: Chaos too high for coherent output (reference images)**\n- Bad: --chaos 100 (produces incoherent results)\n- Better: 20-45 for controlled surrealism\n\n**Mistake 5: Ignoring aspect ratio for content type**\n- Bad: Square format for liminal corridor (loses depth)\n- Better: 16:9 or 3:4 vertical to emphasize depth and perspective\n\n### Video-Specific Mistakes\n\n**Mistake 6: Including text or readable symbols in video prompts**\n- Bad: \"Floating terminal text and hexadecimal streams\"\n- Better: \"Glowing geometric patterns flowing like rivers of light\"\n- Rule: ALL text, branding, and labels go in Remotion post-production\n\n**Mistake 7: Asking for hand actions**\n- Bad: \"A skeletal hand reaches through and seals the crack\"\n- Better: \"Red energy flows into the cracks, sealing them from within\"\n- Rule: Avoid hands in frame, especially performing specific actions\n\n**Mistake 8: Cramming multiple actions into one clip**\n- Bad: \"The surface cracks, shatters, a hand reaches through, then seals it with lightning\"\n- Better: \"The obsidian surface cracks apart in slow motion, molten light erupting from fissures\"\n- Rule: One primary motion per clip. Split sequences across clips.\n\n**Mistake 9: Requesting specific detailed objects**\n- Bad: \"Giant playing cards and dice made of glass shatter in slow motion\"\n- Better: \"Geometric crystalline forms fracture and scatter in slow motion\"\n- Rule: Use abstract equivalents for objects requiring fine detail\n\n**Mistake 10: Exceeding provider duration limits**\n- Bad: Requesting 15s from Luma (max 9s) or 20s from Kling (max 10s)\n- Better: Check provider limits -- Luma 5-9s, Kling/Hailuo 5-10s, Wan goes to 15s, Sora to 12s\n- Rule: Match clip duration to provider capabilities\n\n**Mistake 11: Dark scenes with no light source**\n- Bad: \"A scene of pure darkness with subtle movement\"\n- Better: \"Deep darkness with a single crimson light pulsing at the center\"\n- Rule: Models auto-brighten totally dark scenes. Always include at least one accent light.\n\n## Integration with Other Skills\n\n**Combine with demo-recording:**\nUse this skill to craft surrealist prompts, then use demo-recording for capture and post-production.\n\n**Combine with replicate-models:**\nGenerate surrealist images via Replicate SDXL or Flux models using prompts from this skill.\n\n**Combine with demo-video-audio:**\nAdd atmospheric soundscapes to surrealist videos for enhanced immersion.\n\n**Combine with demo-video-lottie:**\nOverlay animated elements on surrealist footage for additional visual interest.\n\n## Audio Cues in Video Prompts\n\nSome providers generate synchronized audio alongside video. When using these providers, include audio descriptors in your prompt for richer output:\n\n**Audio-enabled providers:** Kling v2.6, Veo 3.1, Runway Direct API\n\n**How to include audio cues:**\n```\n# Without audio cues (visual only):\n\"A colossal skull emerging from darkness, red light pulsing through cracks\"\n\n# With audio cues (for Kling/Veo):\n\"A colossal skull emerging from darkness, red light pulsing through cracks,\ndeep resonant hum vibrating through the void, distant thunder echoing\"\n```\n\n**Effective audio descriptors:**\n- Ambient: \"deep hum\", \"distant echoes\", \"wind howling through caverns\"\n- Impact: \"deep bass rumble\", \"resonant boom\", \"cracking stone\"\n- Atmospheric: \"ethereal choir\", \"metallic resonance\", \"dripping water in vast space\"\n- Tension: \"rising drone\", \"heartbeat pulse\", \"subsonic vibration\"\n\nAudio cues are ignored by providers that don''t support audio generation, so including them is safe for all providers.\n\n---\n\n## Success Metrics\n\nEffective surrealist prompts produce:\n- Genuinely impossible or illogical visual elements\n- Emotional resonance (wonder, unease, nostalgia, awe)\n- Visual coherence despite surreal content\n- Recognizable artistic style references when specified\n- Appropriate atmosphere matching the intended mood\n- **Pass the feasibility checklist** -- no text, hands, multi-step sequences, or fine-detail objects\n- **Appropriate duration for chosen provider** -- within the provider''s supported range\n- **Clear single subject** -- one focal element, not competing subjects\n"},"lastSynced":"2026-03-06T13:07:03.533Z","agentAnalysis":{"suitability":{"en":"Perfect for Creative Agents needing advanced surrealist video content generation capabilities using AI models.","zh":"非常适合需要使用AI模型生成高级超现实主义视频内容的创意代理。","ja":"クリエイティブエージェントがAIモデルを使用して高度なシュルレアリスム動画コンテンツを生成する必要がある場合に最適です。","ko":"AI 모델을 사용하여 고급 초현실주의 비디오 콘텐츠를 생성해야 하는 창의적 에이전트에 적합합니다.","es":"Perfecto para Agentes Creativos que necesitan capacidades avanzadas de generación de contenido de video surrealista utilizando modelos de inteligencia artificial.","fr":"Parfait pour les agents créatifs ayant besoin de capacités avancées de génération de contenu vidéo surréaliste à l''aide de modèles d''intelligence artificielle.","de":"Perfekt für kreative Agenten, die erweiterte Möglichkeiten zur Erstellung von surrealistischem Video-Inhalt mit KI-Modellen benötigen.","pt":"Perfeito para Agentes Criativos que necessitam de capacidades avançadas de geração de conteúdo de vídeo surrealista usando modelos de IA.","ru":"Идеально для Креативных Агентов, которым необходимы продвинутые возможности генерации сюрреалистического видеоконтента с помощью моделей ИИ.","ar":"مثالي لワكلاء الإبداع الذين يحتاجون إلى قدرات متقدمة لإنشاء محتوى فيديو سريالي باستخدام نماذج الذكاء الاصطناعي."},"recommendation":{"en":"Empowers agents to generate high-quality, dreamlike video content using AI video generation models, applying impossible physics effects like floating, melting, and morphing, and creating psychedelic or trippy visuals with provider-specific tips and curated examples in formats like MP4.","zh":"赋予代理生成高质量的梦幻般的视频内容的能力，使用AI视频生成模型，应用如浮动、熔解和变形等不可能的物理效果，并使用提供商特定的提示和策划的示例以MP4等格式创建迷幻或令人着迷的视觉效果。","ja":"エージェントに、高品質の夢のような動画コンテンツを生成する能力を与え、AIビデオ生成モデルを使用し、浮遊、溶解、変形などの不可能な物理効果を適用し、提供者の特定のヒントやキュレーションされた例を使用して、MP4などの形式でサイケデリックまたはトリッピーな視覚効果を生成します。","ko":"에이전트가 고품질의 몽환적인 비디오 콘텐츠를 생성할 수 있는 능력을 부여하여 AI 비디오 생성 모델을 사용하고, 부유, 용해, 변형 등의 불가능한 물리적 효과를 적용하며, 제공업체 특有的 팁과 커레이션된 예제를 사용하여 MP4 등의 형식으로 사이키델릭 또는 트리피한 시각적 효과를 생성합니다.","es":"Habilita a los agentes a generar contenido de video de alta calidad y onírico utilizando modelos de generación de video de inteligencia artificial, aplicando efectos de física imposible como flotar, derretir y cambiar de forma, y creando visuales psicodélicas o alucinantes con consejos y ejemplos curados específicos del proveedor en formatos como MP4.","fr":"Permet aux agents de générer du contenu vidéo de haute qualité et onirique en utilisant des modèles de génération de vidéo d''intelligence artificielle, en appliquant des effets de physique impossibles tels que le flottement, la fonte et la métamorphose, et en créant des visuels psychédéliques ou hallucinogènes avec des conseils et des exemples spécifiques au fournisseur et soigneusement sélectionnés au format MP4.","de":"Ermächtigt Agenten, hochwertige, traumhafte Videoinhalte mit KI-Video-Generationsmodellen zu erstellen, unmögliche Physikeffekte wie Schweben, Schmelzen und Verformen anzuwenden und psychedelische oder halluzinogene Visuelle mit anbieterspezifischen Tipps und kuratierten Beispielen in Formaten wie MP4 zu erstellen.","pt":"Habilita agentes a gerar conteúdo de vídeo de alta qualidade, semelhante a sonhos, usando modelos de geração de vídeo de IA, aplicando efeitos de física impossíveis como flutuação, derretimento e morfismo, e criando visuais psicodélicos ou alucinógenos com dicas e exemplos específicos do provedor em formatos como MP4.","ru":"Наделяет агентов возможностью генерировать высококачественный, похожий на сон видеоконтент с помощью моделей генерации видео ИИ, применяя эффекты невозможной физики, такие как плавание, плавление и морфинг, и создающие психоделические или триppy визуальные эффекты с помощью советов и примеров, специфичных для провайдера, в форматах, таких как MP4.","ar":"يمنح الوكلاء القدرة على إنشاء محتوى فيديو عالي الجودة يشبه الحلم باستخدام نماذج генерация الفيديو الاصطناعي، وتطبيق تأثيرات فيزيائية مستحيلة مثل الطفو والانصهار والتغيير الشكلي، وإنشاء تصورات مخدرة أو مثيرة للذهول مع نصائح وأمثلة محددة للمزود في صيغ مثل MP4."},"useCases":{"en":["Generating surrealist video content for social media","Creating psychedelic visuals for music videos","Applying impossible physics effects for advertising campaigns"],"zh":["为社交媒体生成超现实主义视频内容","为音乐视频创建迷幻视觉","将不可能的物理效果应用于广告活动"],"ja":["ソーシャルメディア用のシュルレアリスム動画コンテンツを生成する","ミュージックビデオ用のサイケデリックな視覚効果を生成する","広告キャンペーンに不可能な物理効果を適用する"],"ko":["소셜 미디어를 위한 초현실주의 비디오 콘텐츠 생성","음악 비디오를 위한 사이키델릭한 시각적 효과 생성","광고 캠페인에 불가능한 물리적 효과를 적용"],"es":["Generar contenido de video surrealista para redes sociales","Crear visuales psicodélicas para videos musicales","Aplicar efectos de física imposible para campañas publicitarias"],"fr":["Générer du contenu vidéo surréaliste pour les réseaux sociaux","Créer des visuels psychédéliques pour les vidéos musicales","Appliquer des effets de physique impossible pour les campagnes publicitaires"],"de":["Surrealistischen Video-Inhalt für soziale Medien erstellen","Psychedelische Visuelle für Musikvideos erstellen","Unmögliche Physikeffekte für Werbekampagnen anwenden"],"pt":["Geração de conteúdo de vídeo surrealista para mídias sociais","Criação de visuais psicodélicos para vídeos musicais","Aplicação de efeitos de física impossíveis para campanhas publicitárias"],"ru":["Генерация сюрреалистического видеоконтента для социальных сетей","Создание психоделических визуальных эффектов для музыкальных видео","Применение эффектов невозможной физики для рекламных кампаний"],"ar":["إنشاء محتوى فيديو سريالي لوسائل الإعلام الاجتماعية","خلق تصورات مخدرة لفيديوهات الموسيقى","تطبيق تأثيرات فيزيائية مستحيلة لحملات الإعلان"]},"limitations":{"en":["Requires access to AI video generation models","Specific provider expertise needed for optimal results"],"zh":["需要访问AI视频生成模型","需要特定提供商的专业知识以获得最佳结果"],"ja":["AIビデオ生成モデルへのアクセスが必要","最適な結果を得るために提供者の特定の専門知識が必要"],"ko":["AI 비디오 생성 모델에 대한 액세스가 필요","최적의 결과를 얻으려면 제공업체 특有的 전문 지식이 필요"],"es":["Requiere acceso a modelos de generación de video de inteligencia artificial","Se necesita experiencia específica del proveedor para obtener resultados óptimos"],"fr":["Nécessite l''accès à des modèles de génération de vidéo d''intelligence artificielle","Une expertise spécifique du fournisseur est nécessaire pour obtenir des résultats optimaux"],"de":["Erfordert den Zugriff auf KI-Video-Generationsmodelle","Spezifische Anbieterkenntnisse sind erforderlich, um optimale Ergebnisse zu erzielen"],"pt":["Requer acesso a modelos de geração de vídeo de IA","É necessário conhecimento específico do provedor para obter resultados ótimos"],"ru":["Требуется доступ к моделям генерации видео ИИ","Необходимо специфическое знание провайдера для достижения оптимальных результатов"],"ar":["يتطلب الوصول إلى نماذج генерация الفيديو الاصطناعي","يحتاج إلى معرفة محددة للمزود للحصول على نتائج مثالية"]},"version":4},"contentHash":"dd44a1e137eb18488019448f2fc0851ef255d544fe3861c70ba2f356230f60d6","qualityScore":57}');
