INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fullstacktard/claude-workflow/surrealist-prompting', 'surrealist-prompting', 'fullstacktard', 'claude-workflow', 'community', 'surrealist-prompting fullstacktard claude-workflow community The surrealist-prompting skill provides expert guidance for creating surrealist video content using AI video generation models, benefiting developers and content creators. Surrealist Prompting技能提供Automated Claude Code配置设置，用于创建梦幻、超现实和迷幻内容 Surrealist Promptingスキルは、夢のような、超現実的、サイケデリックなコンテンツを作成するためのAutomated Claude Code構成設定を提供します Surrealist Prompting 기술은夢幻、초현실적이고サイケデリック한 콘텐츠를 생성하기 위한Automated Claude Code 구성 설정을 제공합니다 Surrealist Prompting es una habilidad que proporciona plantillas y consejos para generar contenido surrealista y psicodélico con modelos de generación de video AI Surrealist Prompting est une compétence qui fournit des modèles et des conseils pour générer du contenu surréaliste et psychédélique avec des modèles de génération de vidéo IA Surrealist Prompting ist eine Fähigkeit, die Vorlagen und Tipps zur Erstellung von surrealistischem und psychedelischem Inhalt mit AI-Video-Generationsmodellen bietet O Surrealist-Prompting é uma habilidade que fornece configuração automática de Claude Code para projetos existentes, permitindo a criação de conteúdo de vídeo surrealista e sonhador Surrealist-Prompting - это умение, которое обеспечивает автоматическую настройку Claude Code для существующих проектов, позволяя создавать сурреалистическое и мечтательное видеоконтент Surrealist-Prompting هي مهارة توفر إعدادًا تلقائيًا لمرمّز Claude للمشاريع الحالية، مما يسمح بإنشاء محتوى فيديو مستوحى من الحلم والخيال how to use surrealist-prompting what is surrealist-prompting surrealist-prompting alternative surrealist-prompting vs deep dream generator surrealist-prompting install surrealist-prompting setup guide AI video generation models Claude Code configuration surrealist video content creation Surrealist Prompting AIエージェント Automated Claude Code 梦幻内容生成 超现实内容生成 迷幻内容生成 AI视频生成模型 Provides actionable templates for surrealist video generation Offers provider-specific tips for consistent, high-quality output Supports creation of dreamlike or surreal video content Enables application of impossible physics effects, such as floating, melting, and morphing Generates psychedelic or trippy visuals using AI video generation models Includes curated examples for reference and inspiration Surrealist-prompting is a skill that enables automated Claude Code configuration setup for existing projects to generate surrealist, dreamlike, and psychedelic video content.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('thisguymartin/ai-native-dev/qa', 'community', 'thisguymartin', 'ai-native-dev', 'thisguymartin/ai-native-dev', 'qa', 3, 0, 57, '2026-03-06T18:19:09Z', '2026-03-07T12:49:14.175Z', '1dfd84c83ab0e7a3d9cb7e5408476e563b416ecbc35fb94edd2d66eb8c11b619', '{"id":"thisguymartin/ai-native-dev/qa","name":"qa","description":{"en":"The qa skill is designed for Senior QA Automation Architects to automate testing and break code in a controlled environment. It replaces the GUI with autonomous agents and keyboard-centric tools.","zh":"qa AI 에이전트是一种自动化测试工具，帮助开发人员确保代码质量。通过设置指南和最佳实践，实现自动化测试和质量保证","ja":"qa AIエージェントは、開発者がコードの品質を確保するための自動テストツールです。セットアップガイドとベストプラクティスを使用して、自動テストと品質保証を実現します","ko":"qa AI 에이전트는 개발자가 코드 품질을 보증하는 자동화 테스트 도구입니다. 설정 가이드와 모범 사례를 사용하여 자동화 테스트와 품질 보증을 실현합니다","es":"El entorno de trabajo de terminal de QA reemplaza la interfaz gráfica de usuario con agentes autónomos y herramientas de línea de comandos para automatizar pruebas","fr":"L''espace de travail de terminal de QA remplace l''interface graphique utilisateur par des agents autonomes et des outils de ligne de commande pour automatiser les tests","de":"Die QA-Terminal-Arbeitsumgebung ersetzt die grafische Benutzeroberfläche durch autarke Agenten und Kommandozeilen-Tools zur Automatisierung von Tests","pt":"O qa é uma ferramenta de automação de testes que utiliza ferramentas de linha de comando para testar código de forma eficiente","ru":"ИИ Агенты для QA - это инструмент для автоматизации тестирования, который использует командную строку для тестирования кода","ar":"qa هو أداة آلية للاختبار التي تستخدم أدوات سطر الأوامر لاختبار الشفرة بفعالية"},"seo":{"title":{"en":"qa: Automated Testing Setup Guide | AI Agent Skill","zh":"AIエージェント qa 设置指南：自动化测试和质量保证","ja":"AIエージェント qa セットアップガイド：自動テストと品質保証","ko":"AI 에이전트 qa 설정 가이드: 자동화 테스트 및 품질 보증","es":"Guía de configuración de QA: Automatización de pruebas co...","fr":"Guide de configuration QA : Automatisation des tests avec...","de":"QA-Setup-Leitfaden: Automatisierung von Tests mit Kommand...","pt":"Guia de Configuração do QA: Automação de Testes com Ferra...","ru":"Настройка ИИ Агентов для QA: Руководство по Автоматизации...","ar":"دليل إعداد qa: автоматизация الاختبار مع أدوات سطر الأوامر"},"description":{"en":"Discover how to break code in a controlled environment with qa. Learn to write tests and automate your workflow with our expert guide.","zh":"了解如何使用 qa AI 에이전트实现自动化测试和质量保证。设置指南和最佳实践","ja":"qa AIエージェントを使用して自動テストと品質保証を実現する方法を学びます。セットアップガイドとベストプラクティス","ko":"qa AI 에이전트를 사용하여 자동화 테스트와 품질 보증을 실현하는 방법을 배우세요. 설정 가이드와 모범 사례","es":"Aprende a configurar un entorno de trabajo de terminal de QA autónomo con agentes y herramientas de línea de comandos","fr":"Découvrez comment configurer un espace de travail de terminal de QA autonome avec des agents et des outils de ligne de commande","de":"Erfahren Sie, wie Sie eine autarke QA-Terminal-Arbeitsumgebung mit Agenten und Kommandozeilen-Tools einrichten","pt":"Aprenda a configurar o qa para automação de testes com ferramentas de linha de comando e melhore a eficiência do seu processo de teste","ru":"Узнайте, как настроить ИИ Агенты для QA, чтобы автоматизировать тестирование и повысить эффективность процесса тестирования","ar":"تعلم كيفية إعداد qa لآلية الاختبار مع أدوات سطر الأوامر وتحسين كفاءة عملية الاختبار"},"definition":{"en":"qa is an AI-native terminal workspace that automates testing and quality assurance processes.","zh":"qa AI 에이전트是一种自动化测试工具，用于确保代码质量和可靠性","ja":"qa AIエージェントは、コードの品質と信頼性を確保するための自動テストツールです","ko":"qa AI 에이전트는 코드 품질과 신뢰성을 보증하는 자동화 테스트 도구입니다","es":"Un entorno de trabajo de terminal de QA es un espacio de trabajo autónomo que utiliza agentes y herramientas de línea de comandos para automatizar pruebas de software","fr":"Un espace de travail de terminal de QA est un espace de travail autonome qui utilise des agents et des outils de ligne de commande pour automatiser les tests de logiciels","de":"Eine QA-Terminal-Arbeitsumgebung ist eine autarke Arbeitsumgebung, die Agenten und Kommandozeilen-Tools verwendet, um Software-Tests zu automatisieren","pt":"O qa é uma ferramenta de automação de testes que utiliza ferramentas de linha de comando para testar código","ru":"ИИ Агенты для QA - это инструмент для автоматизации тестирования кода","ar":"qa هو أداة آلية للاختبار التي تستخدم أدوات سطر الأوامر"},"features":{"en":["Asks clarification questions to determine scope and type of tests","Supports unit tests with isolated and mocked dependencies","Enables integration tests with real dependencies","Follows a mandatory clarification protocol before writing tests","Tests specific functions, classes, files, or entire modules and directories"],"zh":["自动化测试","代码质量保证","集成测试","单元测试","模拟依赖","Clarification Protocol"],"ja":["自動テスト","コード品質保証","統合テスト","ユニットテスト","モック依存","Clarification Protocol"],"ko":["자동화 테스트","코드 품질 보증","통합 테스트","유닛 테스트","모의 의존","Clarification Protocol"],"es":["Automatización de pruebas unitarias y de integración","Uso de herramientas de línea de comandos para pruebas","Reemplazo de la interfaz gráfica de usuario por agentes autónomos","Soporte para pruebas de software en entornos controlados","Uso de protocolos de clarificación para definir el alcance de las pruebas"],"fr":["Automatisation des tests unitaires et d''intégration","Utilisation d''outils de ligne de commande pour les tests","Remplacement de l''interface graphique utilisateur par des agents autonomes","Support pour les tests de logiciels dans des environnements contrôlés","Utilisation de protocoles de clarification pour définir la portée des tests"],"de":["Automatisierung von Einheitstests und Integrations-tests","Verwendung von Kommandozeilen-Tools für Tests","Ersetzung der grafischen Benutzeroberfläche durch autarke Agenten","Unterstützung für Software-Tests in kontrollierten Umgebungen","Verwendung von Klärungsprotokollen zur Definition des Testumfangs"],"pt":["Automação de testes unitários e de integração","Utilização de ferramentas de linha de comando para testar código","Suporte a testes de isolamento e mock de dependências","Testes de código em um ambiente controlado"],"ru":["Автоматизация юнит-тестов и интеграционных тестов","Использование командной строки для тестирования кода","Поддержка изолированных тестов и(mock) зависимостей","Тестирование кода в контролируемой среде"],"ar":["آلية الاختبار الوحدات والاختبار التكاملي","استخدام أدوات سطر الأوامر لاختبار الشفرة","دعم الاختبارات المعزولة وتجسيد الاعتماد","اختبار الشفرة في بيئة خاضعة للرقابة"]},"keywords":{"en":["how to use qa for automated testing","qa alternative to manual testing","qa vs selenium","qa install guide","qa setup for CI/CD pipelines","what is qa in software development"],"zh":["qa AI 에이전트","自动化测试","代码质量保证","集成测试","单元测试","AI 测试工具","代码测试","自动化质量保证"],"ja":["qa AIエージェント","自動テスト","コード品質保証","統合テスト","ユニットテスト","AI テストツール","コードテスト","自動化品質保証"],"ko":["qa AI 에이전트","자동화 테스트","코드 품질 보증","통합 테스트","유닛 테스트","AI 테스트 도구","코드 테스트","자동화 품질 보증"],"es":["QA automatizado","herramientas de línea de comandos para pruebas","agentes autónomos para pruebas","automatización de pruebas unitarias","automatización de pruebas de integración","protocolos de clarificación para pruebas"],"fr":["QA automatisé","outils de ligne de commande pour les tests","agents autonomes pour les tests","automatisation des tests unitaires","automatisation des tests d''intégration","protocoles de clarification pour les tests"],"de":["Automatisierte QA","Kommandozeilen-Tools für Tests","Autarke Agenten für Tests","Automatisierung von Einheitstests","Automatisierung von Integrations-tests","Klärungsprotokolle für Tests"],"pt":["automação de testes","ferramentas de linha de comando","testes unitários","testes de integração","qa","desenvolvimento de software","testes de software"],"ru":["автоматизация тестирования","ИИ Агенты","командная строка","юнит-тесты","интеграционные тесты","QA","разработка программного обеспечения","тестирование программного обеспечения"],"ar":["آلية الاختبار","أدوات سطر الأوامر","اختبارات الوحدات","اختبارات التكامل","qa","تطوير البرمجيات","اختبار البرمجيات"]}},"owner":"thisguymartin","repo":"ai-native-dev","repoPath":"thisguymartin/ai-native-dev","stars":3,"forks":0,"updatedAt":"2026-03-06T18:19:09Z","topics":[],"category":"community","skillMd":{"name":"qa","description":"QA automation architect - test generation, execution, and coverage analysis","bodyPreview":"You are a **Senior QA Automation Architect**. You do not trust code until you see it pass a test suite. Your goal is to break the code in a controlled environment.\n\n**User request:** $ARGUMENTS\n\n---\n\n## Clarification Protocol (MANDATORY)\n\n**Before writing tests, ALWAYS ask:**\n\n1. **Scope:** What should I test?\n   - Specific function/class\n   - Specific file\n   - Entire module/directory\n2. **Type:** What kind of tests?\n   - Unit tests (isolated, mocked dependencies)\n   - Integration tests (real d","body":"You are a **Senior QA Automation Architect**. You do not trust code until you see it pass a test suite. Your goal is to break the code in a controlled environment.\n\n**User request:** $ARGUMENTS\n\n---\n\n## Clarification Protocol (MANDATORY)\n\n**Before writing tests, ALWAYS ask:**\n\n1. **Scope:** What should I test?\n   - Specific function/class\n   - Specific file\n   - Entire module/directory\n2. **Type:** What kind of tests?\n   - Unit tests (isolated, mocked dependencies)\n   - Integration tests (real dependencies, test boundaries)\n   - E2E tests (full flow)\n3. **Coverage:** What level of coverage?\n   - Happy path only (quick validation)\n   - Happy + sad path (standard coverage)\n   - Comprehensive (edge cases, property testing)\n4. **Existing Tests:** Are there existing test patterns to follow?\n5. **Priority:** Any specific scenarios to focus on?\n\n---\n\n## Framework Detection (Auto-detect by language)\n\n### TypeScript/JavaScript\n**Check:** `package.json`\n| Framework | Detection | Default |\n|-----------|-----------|---------|\n| Jest | `\"jest\"` in dependencies | Yes |\n| Vitest | `\"vitest\"` in dependencies | |\n| Mocha | `\"mocha\"` in dependencies | |\n\n### Python\n**Check:** `pyproject.toml`, `requirements.txt`, `setup.py`\n| Framework | Detection | Default |\n|-----------|-----------|---------|\n| Pytest | `pytest` in dependencies | Yes |\n| Unittest | Built-in | Fallback |\n\n### Go\n**Check:** `go.mod` exists\n| Framework | Detection | Default |\n|-----------|-----------|---------|\n| go test | Built-in | Yes |\n| testify | `testify` in imports | Enhancement |\n\n### .NET\n**Check:** `*.csproj` files\n| Framework | Detection | Default |\n|-----------|-----------|---------|\n| xUnit | `xunit` in PackageReference | Yes |\n| NUnit | `NUnit` in PackageReference | |\n| MSTest | `MSTest` in PackageReference | |\n\n**If no framework detected:** Ask the user which to use.\n\n---\n\n## Test Standards\n\n### 1. Isolation & Mocking (CRITICAL)\n- **NEVER** allow unit tests to hit real APIs, Databases, or File System\n- **MANDATORY:** External calls MUST be mocked\n- Verify mocks are in place before running tests\n\n**Mocking by Language:**\n| Language | Mocking Library |\n|----------|-----------------|\n| TypeScript/JS | `jest.mock()`, `sinon`, `vitest mock` |\n| Python | `unittest.mock`, `pytest-mock` |\n| Go | `gomock`, interfaces + test doubles |\n| .NET | `Moq`, `NSubstitute` |\n\n### 2. Test Coverage Levels\n\n**Happy Path:**\n- Normal input -> expected output\n- Valid user flows\n\n**Sad Path:**\n- Invalid inputs (null, empty, negative)\n- Error responses (404, 500, timeouts)\n- Boundary conditions (0, max int, empty arrays)\n- Malformed data (invalid JSON, wrong types)\n\n**Property Testing (for complex logic):**\n- `encode(decode(x)) == x` for any x\n- Sorting is idempotent: `sort(sort(x)) == sort(x)`\n- Mathematical properties hold\n\n### 3. Test Quality\n\n**Naming Convention:**\n```\ntest_{function}_{scenario}_{expected_result}\n```\nExamples:\n- `test_calculateTotal_emptyCart_returnsZero`\n- `test_login_invalidPassword_throwsAuthError`\n- `test_parseDate_malformedString_returnsNull`\n\n**Structure (AAA Pattern):**\n```\n// Arrange - set up test data and mocks\n// Act - call the function under test\n// Assert - verify the result\n```\n\n---\n\n## Test File Conventions\n\n| Language | Location | Naming |\n|----------|----------|--------|\n| TypeScript | `__tests__/` or `*.test.ts` | `{name}.test.ts` |\n| JavaScript | `__tests__/` or `*.test.js` | `{name}.test.js` |\n| Python | `tests/` | `test_{name}.py` |\n| Go | Same package | `{name}_test.go` |\n| .NET | `{Project}.Tests/` | `{Name}Tests.cs` |\n\n---\n\n## Workflow\n\n1. **Clarify** - Ask scope, type, coverage questions\n2. **Detect** - Use Glob to find project config files, identify test framework\n3. **Plan** - List edge cases to cover\n4. **Code** - Generate test file using Write tool, following project conventions\n5. **Execute** - Run the tests using Bash\n6. **Report** - Summarize results\n\n---\n\n## Output Format\n\n### Test Plan (before coding)\n```\n## Test Plan: {function/module}\n\n**Framework:** {detected framework}\n**Coverage Level:** {happy/sad/comprehensive}\n\n### Scenarios to Test\n1. [Scenario] -> Expected: [result]\n2. [Scenario] -> Expected: [result]\n3. [Scenario] -> Expected: [error/exception]\n\n### Mocks Required\n- {dependency} -> mock {behavior}\n```\n\n### Test Results (after execution)\n```\n## QA Report: {function/module}\n\n**Status:** GREEN / RED\n**Tests:** X passed, Y failed\n**Coverage:** {if available}\n\n### Results\n| Test | Status | Notes |\n|------|--------|-------|\n| test_name | PASS | |\n| test_name | FAIL | {reason} |\n\n### Defects Found (if RED)\n- **{test_name}:** {description of bug in code}\n  - Expected: {expected}\n  - Actual: {actual}\n  - Likely cause: {analysis}\n\n### Recommendations\n- [Suggestions for additional tests or fixes]\n```\n\n---\n\n## Constraints\n\n- **NEVER** modify source code - only write/fix test code\n- **ALWAYS** mock external dependencies in unit tests\n- **ALWAYS** follow existing project test patterns if they exist\n- If tests fail due to bug in YOUR test: fix the test immediately\n- If tests fail due to bug in source code: report as defect, do not fix\n- Use descriptive test names - no `test1`, `testFunc`\n"},"lastSynced":"2026-03-07T12:49:14.175Z","agentAnalysis":{"suitability":{"en":"Perfect for Testing Agents needing comprehensive test suite automation and code validation.","zh":"非常适合需要全面测试套件自动化和代码验证的测试代理。","ja":"包括テストスイートの自動化やコードの検証が必要なテストエージェントに最適です。","ko":"포괄적인 테스트 스위트 자동화 및 코드 유효성 검증이 필요한 테스트 에이전트에게 적합합니다.","es":"Perfecto para agentes de prueba que necesitan una automatización de conjunto de pruebas integral y validación de código.","fr":"Parfait pour les agents de test nécessitant une automatisation complète du jeu de tests et une validation de code.","de":"Perfekt für Testagenten, die eine umfassende Automatisierung von Test-Suiten und Code-Validierung benötigen.","pt":"Perfeito para agentes de teste que necessitam de automação de suíte de teste abrangente e validação de código.","ru":"Идеально подходит для агентов тестирования, которым требуется комплексная автоматизация набора тестов и проверка кода.","ar":"مثالي للوكلاء الذين يحتاجون إلى إتمام اختبارات شاملة وتأكيد صحة الكود."},"recommendation":{"en":"Empowers agents to automate testing and break code in a controlled environment, utilizing autonomous agents and keyboard-centric tools, with a focus on unit tests, integration tests, and test suite validation using protocols like Clarification Protocol.","zh":"赋予代理自动化测试和在受控环境中破坏代码的能力，利用自主代理和键盘为中心的工具，并关注使用诸如Clarification Protocol之类的协议的单元测试、集成测试和测试套件验证。","ja":"エージェントは、自律エージェントやキーボード中心のツールを利用して、制御された環境でテストの自動化やコードの破壊を行うことができ、Clarification Protocolなどのプロトコルを使用したユニットテスト、統合テスト、テストスイートの検証に焦点を当てています。","ko":"에이전트가 자동 테스트를 수행하고 제어 환경에서 코드를 손상시키는 기능을 제공하며, 독립적인 에이전트와 키보드 중심 도구를 사용하여 Clarification Protocol과 같은 프로토콜을 사용한 유닛 테스트, 통합 테스트 및 테스트 스위트 유효성 검증에 중점을 둡니다.","es":"Habilita a los agentes a automatizar las pruebas y romper el código en un entorno controlado, utilizando agentes autónomos y herramientas centradas en el teclado, con un enfoque en pruebas unitarias, pruebas de integración y validación de conjunto de pruebas utilizando protocolos como Clarification Protocol.","fr":"Permet aux agents d''automatiser les tests et de casser le code dans un environnement contrôlé, en utilisant des agents autonomes et des outils centrés sur le clavier, avec un focus sur les tests unitaires, les tests d''intégration et la validation du jeu de tests en utilisant des protocoles comme Clarification Protocol.","de":"Ermächtigt die Agenten, Tests zu automatisieren und Code in einer kontrollierten Umgebung zu brechen, indem sie autonome Agenten und keyboardzentrierte Tools verwenden, mit einem Fokus auf Einheitstests, IntegrationsTests und Test-Suite-Validierung unter Verwendung von Protokollen wie Clarification Protocol.","pt":"Habilita os agentes a automatizar testes e quebrar código em um ambiente controlado, utilizando agentes autônomos e ferramentas centradas no teclado, com foco em testes unitários, testes de integração e validação de suíte de teste usando protocolos como o Clarification Protocol.","ru":"Предоставляет агентам возможность автоматизировать тестирование и разрушать код в контролируемой среде, используя автономные агенты и инструменты, ориентированные на клавиатуру, с фокусом на модульных тестах, тестах интеграции и проверке набора тестов с помощью протоколов, таких как Clarification Protocol.","ar":"تمكّن الوكلاء من تطبيق الاختبارات وتكسير الكود في بيئة خاضعة للرقابة، وتتيح لهم استخدام وكلاء آليين وأدوات مركزية على لوحة المفاتيح، مع التركيز على الاختبارات الجزئية واختبارات التكامل وتأكيد صحة مجموعة الاختبارات باستخدام بروتوكولات مثل بروتوكول التوضيح."},"useCases":{"en":["Automating test suite generation for specific functions or classes","Debugging code in a controlled environment using integration tests","Validating test scope and type using Clarification Protocol"],"zh":["为特定函数或类生成测试套件的自动化","使用集成测试在受控环境中调试代码","使用Clarification Protocol验证测试范围和类型"],"ja":["特定の関数またはクラス用のテストスイートの自動生成","統合テストを使用して制御された環境でコードをデバッグする","Clarification Protocolを使用してテストの範囲とタイプを検証する"],"ko":["특정 함수 또는 클래스를 위한 테스트 스위트 생성 자동화","통합 테스트를 사용하여 제어 환경에서 코드를 디버깅하는 것","Clarification Protocol을 사용하여 테스트 범위 및 유형을 검증하는 것"],"es":["Automatizar la generación de conjunto de pruebas para funciones o clases específicas","Depurar código en un entorno controlado utilizando pruebas de integración","Validar el alcance y tipo de prueba utilizando Clarification Protocol"],"fr":["Automatiser la génération de jeu de tests pour des fonctions ou des classes spécifiques","Déboguer le code dans un environnement contrôlé en utilisant des tests d''intégration","Valider la portée et le type de test en utilisant Clarification Protocol"],"de":["Automatisieren der Erstellung von Test-Suiten für bestimmte Funktionen oder Klassen","Fehlerbehebung von Code in einer kontrollierten Umgebung unter Verwendung von IntegrationsTests","Validieren des Testumfangs und -typs unter Verwendung von Clarification Protocol"],"pt":["Automatizar a geração de suíte de teste para funções ou classes específicas","Depurar código em um ambiente controlado usando testes de integração","Validar o escopo e o tipo de teste usando o Clarification Protocol"],"ru":["Автоматизировать генерацию набора тестов для конкретных функций или классов","Отлаживать код в контролируемой среде с помощью тестов интеграции","Проверять объем и тип тестирования с помощью Clarification Protocol"],"ar":["تطبيق تلقائي لاختبار مجموعة اختبارات لمجموعة وظائف أو فئات محددة","تصحيح أخطاء الكود في بيئة خاضعة للرقابة باستخدام اختبارات التكامل","تأكيد نطاق الاختبار ونوعه باستخدام بروتوكول التوضيح"]},"limitations":{"en":["Requires clear test scope and type definition","Limited to controlled environment testing"],"zh":["需要明确的测试范围和类型定义","仅限于受控环境测试"],"ja":["明確なテストの範囲とタイプの定義が必要","制御された環境でのみテスト可能"],"ko":["명확한 테스트 범위 및 유형 정의가 필요","제어 환경에서만 테스트 가능"],"es":["Requiere una definición clara del alcance y tipo de prueba","Limitado a pruebas en un entorno controlado"],"fr":["Nécessite une définition claire de la portée et du type de test","Limité aux tests dans un environnement contrôlé"],"de":["Benötigt eine klare Definition des Testumfangs und -typs","Begrenzt auf Tests in einer kontrollierten Umgebung"],"pt":["Exige definição clara do escopo e do tipo de teste","Limitado a testes em ambiente controlado"],"ru":["Требует четкого определения объема и типа тестирования","Ограничен тестированием в контролируемой среде"],"ar":["يتطلب تعريفًا واضحًا لنطاق الاختبار ونوعه","محدود بالاختبارات في بيئة خاضعة للرقابة"]},"version":4},"contentHash":"1dfd84c83ab0e7a3d9cb7e5408476e563b416ecbc35fb94edd2d66eb8c11b619","qualityScore":57}');
