INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('thisguymartin/ai-native-dev/qa', 'qa', 'thisguymartin', 'ai-native-dev', 'community', 'qa thisguymartin ai-native-dev community The qa skill is designed for Senior QA Automation Architects to automate testing and break code in a controlled environment. It replaces the GUI with autonomous agents and keyboard-centric tools. qa AI 에이전트是一种自动化测试工具，帮助开发人员确保代码质量。通过设置指南和最佳实践，实现自动化测试和质量保证 qa AIエージェントは、開発者がコードの品質を確保するための自動テストツールです。セットアップガイドとベストプラクティスを使用して、自動テストと品質保証を実現します qa AI 에이전트는 개발자가 코드 품질을 보증하는 자동화 테스트 도구입니다. 설정 가이드와 모범 사례를 사용하여 자동화 테스트와 품질 보증을 실현합니다 El entorno de trabajo de terminal de QA reemplaza la interfaz gráfica de usuario con agentes autónomos y herramientas de línea de comandos para automatizar pruebas L''espace de travail de terminal de QA remplace l''interface graphique utilisateur par des agents autonomes et des outils de ligne de commande pour automatiser les tests Die QA-Terminal-Arbeitsumgebung ersetzt die grafische Benutzeroberfläche durch autarke Agenten und Kommandozeilen-Tools zur Automatisierung von Tests O qa é uma ferramenta de automação de testes que utiliza ferramentas de linha de comando para testar código de forma eficiente ИИ Агенты для QA - это инструмент для автоматизации тестирования, который использует командную строку для тестирования кода qa هو أداة آلية للاختبار التي تستخدم أدوات سطر الأوامر لاختبار الشفرة بفعالية how to use qa for automated testing qa alternative to manual testing qa vs selenium qa install guide qa setup for CI/CD pipelines what is qa in software development qa AI 에이전트 自动化测试 代码质量保证 集成测试 单元测试 AI 测试工具 代码测试 自动化质量保证 Asks clarification questions to determine scope and type of tests Supports unit tests with isolated and mocked dependencies Enables integration tests with real dependencies Follows a mandatory clarification protocol before writing tests Tests specific functions, classes, files, or entire modules and directories qa is an AI-native terminal workspace that automates testing and quality assurance processes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hardness1020/VibeFlow/manage-work', 'community', 'hardness1020', 'VibeFlow', 'hardness1020/VibeFlow', 'manage-work', 2, 0, 57, '2026-02-26T21:25:47Z', '2026-03-06T07:06:26.370Z', '6bf825b1c96958750d143ed657d93a2b1fe39960c6117b6481f9ce7cbad7dfea', '{"id":"hardness1020/VibeFlow/manage-work","name":"manage-work","description":{"en":"The manage-work skill enforces docs-before-code discipline in AI-assisted development, providing a full workflow with checkpoint gates and branch-locked enforcement. It benefits developers working with VibeFlow and Claude Code skills.","zh":"VibeFlow 的 manage-work 技能提供了文档优先的开发工作流程，通过 Claude Code 实现自动化和 checkpoint gates","ja":"VibeFlow の manage-work スキルは、ドキュメント優先の開発ワークフローを提供し、Claude Code で自動化とチェックポイントゲートを実現します","ko":"VibeFlow의 manage-work 기능은 문서 우선 개발 워크플로우를 제공하며 Claude Code를 통해 자동화 및 체크포인트 게이트를 구현합니다","es":"manage-work es una habilidad que aplica la disciplina de documentación antes de código en el desarrollo asistido por AI, utilizando Claude Code y VibeFlow para un flujo de trabajo completo","fr":"manage-work est une compétence qui applique la discipline de documentation avant code dans le développement assisté par IA, en utilisant Claude Code et VibeFlow pour un flux de travail complet","de":"manage-work ist eine Fähigkeit, die die Disziplin der Dokumentation vor dem Code in der AI-gestützten Entwicklung anwendet, indem sie Claude Code und VibeFlow für einen kompletten Workflow nutzt","pt":"O manage-work é uma habilidade que impõe a disciplina de docs-antes-código em projetos de desenvolvimento assistidos por IA com VibeFlow e Claude Code, permitindo o registro de itens de trabalho e o acompanhamento de estágios","ru":"Manage-work - это навык, обеспечивающий дисциплину документации перед кодированием в проектах разработки с помощью ИИ с VibeFlow и Claude Code, позволяющий регистрировать рабочие элементы и отслеживать стадии","ar":"manage-work هي مهارة تطبق الانضباط في التوثيق قبل الكود في مشاريع التطوير المدعومة بالذكاء الاصطناعي مع VibeFlow و Claude Code، مما يسمح بتسجيل عناصر العمل وتتبع المراحل"},"seo":{"title":{"en":"manage-work: Streamline AI-Assisted Development Workflow ...","zh":"VibeFlow 工作管理设置指南 - Claude Code  AIエージェント","ja":"VibeFlow ワークフロー管理ベストプラクティス - Claude Code AIエージェント","ko":"VibeFlow 작업 관리 가이드 - Claude Code AI 도구","es":"Guía de Configuración de manage-work: Disciplina de Docum...","fr":"Guide de Configuration de manage-work: Discipline de Docu...","de":"Konfigurationsleitfaden für manage-work: Disziplin für Do...","pt":"Guia de Configuração do manage-work: Disciplina de Docs-a...","ru":"Настройка ИИ Агента manage-work: Управление Работой с Cla...","ar":"دليل إعداد manage-work: الانضباط في التوثيق قبل الكود"},"description":{"en":"Discover how manage-work enforces docs-before-code discipline in AI-assisted development. Learn how to set up and use this skill to boost your workflow effic...","zh":"了解如何使用 VibeFlow 的 manage-work 技能来实施文档优先的开发工作流程，并通过 Claude Code 实现自动化","ja":"VibeFlow の manage-work スキルを使用してドキュメント優先の開発ワークフローを実施し、Claude Code で自動化する方法を学びます","ko":"VibeFlow의 manage-work 기능을 사용하여 문서 우선 개발 워크플ロー 구현 및 Claude Code를 통한 자동화 방법을 알아보세요","es":"Aprenda a implementar la disciplina de documentación antes de código en su flujo de trabajo de desarrollo asistido por AI con manage-work","fr":"Découvrez comment mettre en œuvre la discipline de documentation avant code dans votre flux de travail de développement assisté par IA avec manage-work","de":"Erfahren Sie, wie Sie die Disziplin der Dokumentation vor dem Code in Ihrem Workflow für die AI-gestützte Entwicklung mit manage-work umsetzen","pt":"Aprenda a configurar o manage-work para impor a disciplina de docs-antes-código em projetos de desenvolvimento assistidos por IA com VibeFlow e Claude Code","ru":"Узнайте, как настроить manage-work для обеспечения дисциплины документации перед кодированием в проектах разработки с помощью ИИ с VibeFlow и Claude Code","ar":"تعرف على كيفية إعداد manage-work لتطبيق الانضباط في التوثيق قبل الكود في مشاريع التطوير المدعومة بالذكاء الاصطناعي مع VibeFlow و Claude Code"},"definition":{"en":"manage-work is a skill that tracks multiple work items through the VibeFlow workflow, registering work items, creating feature branches, and advancing stages independently.","zh":"manage-work 是 VibeFlow 的一个技能，用于实施文档优先的开发工作流程","ja":"manage-work は、VibeFlow のスキルで、ドキュメント優先の開発ワークフローを実施するために使用されます","ko":"manage-work는 VibeFlow의 기능으로 문서 우선 개발 워크플로우를 구현하는 데 사용됩니다","es":"manage-work es una habilidad de AI que gestiona elementos de trabajo en un flujo de desarrollo de documentación primero","fr":"manage-work est une compétence IA qui gère des éléments de travail dans un flux de développement de documentation première","de":"manage-work ist eine AI-Fähigkeit, die Arbeitselemente in einem Dokumentations-Entwicklungs-Workflow verwaltet","pt":"O manage-work é uma habilidade de IA que gerencia itens de trabalho em projetos de desenvolvimento assistidos por IA","ru":"Manage-work - это навык ИИ, управляющий рабочими элементами в проектах разработки с помощью ИИ","ar":"manage-work هي مهارة ذكاء اصطناعي تدير عناصر العمل في مشاريع التطوير المدعومة بالذكاء الاصطناعي"},"features":{"en":["Registers work items with their workflow track and creates feat/<slug> branches","Tracks each work item''s current stage independently","Advances work items through stages and routes to the appropriate skill","Closes work items as DONE after checkpoint","Enforces docs-before-code discipline using Claude Code skills and VibeFlow","Provides checkpoint gates and branch-locked enforcement for a full workflow"],"zh":["注册工作项并创建特性分支","跟踪工作项的当前阶段","自动化工作项的阶段转换","使用 Claude Code 实现自动化","提供 checkpoint gates 和分支锁定功能"],"ja":["ワークアイテムの登録と特性ブランチの作成","ワークアイテムの現在の段階の追跡","ワークアイテムの段階の自動化","Claude Code を使用した自動化","チェックポイントゲートとブランチロックの提供"],"ko":["작업 항목 등록 및 특성 분기 생성","작업 항목의 현재 단계 추적","작업 항목의 단계 자동화","Claude Code를 통한 자동화","체크포인트 게이트 및 분기 잠금 기능 제공"],"es":["Registro de elementos de trabajo con su seguimiento de flujo de trabajo","Creación de ramas de características con nombres de características","Seguimiento independiente de cada elemento de trabajo en su etapa actual","Avance de los elementos de trabajo a través de las etapas","Cierre de los elementos de trabajo como FINALIZADO después de un punto de control"],"fr":["Enregistrement des éléments de travail avec leur suivi de flux de travail","Création de branches de fonctionnalités avec des noms de fonctionnalités","Suivi indépendant de chaque élément de travail à son étape actuelle","Avancement des éléments de travail à travers les étapes","Fermeture des éléments de travail comme TERMINÉ après un point de contrôle"],"de":["Registrierung von Arbeitselementen mit ihrer Workflow-Verfolgung","Erstellung von Feature-Branches mit Feature-Namen","Unabhängige Verfolgung jedes Arbeitselements in seiner aktuellen Phase","Vorankommen der Arbeitselemente durch die Phasen","Schließen der Arbeitselemente als ERLEDIGT nach einem Kontrollpunkt"],"pt":["Registro de itens de trabalho com rastreamento de workflow","Criação de branches de recurso com nomeação de slug","Acompanhamento de estágios de itens de trabalho","Avanço de itens de trabalho através de estágios","Encerramento de itens de trabalho como CONCLUÍDO após checkpoint"],"ru":["Регистрация рабочих элементов с отслеживанием рабочего процесса","Создание фич-branch с именованием слага","Отслеживание стадий рабочих элементов","Перемещение рабочих элементов через стадии","Завершение рабочих элементов как ГОТОВО после контрольной точки"],"ar":["تسجيل عناصر العمل مع تتبع سير العمل","إنشاء فروع الميزات مع تسمية Slug","تتبع مراحل عناصر العمل","التقدم في عناصر العمل عبر المراحل","إغلاق عناصر العمل كمنتهي بعد نقطة التحقق"]},"keywords":{"en":["how to use manage-work","manage-work setup guide","what is manage-work","manage-work alternative","manage-work vs VibeFlow","Claude Code skills integration","AI-assisted development workflow","docs-before-code discipline","VibeFlow workflow management"],"zh":["VibeFlow","manage-work","Claude Code","AIエージェント","文档优先开发","自动化工作流程","checkpoint gates","分支锁定"],"ja":["VibeFlow","manage-work","Claude Code","AIエージェント","ドキュメント優先開発","自動化ワークフロー","チェックポイントゲート","ブランチロック"],"ko":["VibeFlow","manage-work","Claude Code","AI 도구","문서 우선 개발","자동화 워크플로우","체크포인트 게이트","분기 잠금"],"es":["AI Agents","Herramientas de desarrollo asistido por AI","Disciplina de documentación antes de código","Claude Code","VibeFlow","Flujo de trabajo de desarrollo de documentación primero","Gestión de elementos de trabajo","Desarrollo de software asistido por IA"],"fr":["Agents IA","Outils de développement assisté par IA","Discipline de documentation avant code","Claude Code","VibeFlow","Flux de travail de développement de documentation première","Gestion des éléments de travail","Développement de logiciels assisté par IA"],"de":["AI-Agents","Tools für die AI-gestützte Entwicklung","Disziplin der Dokumentation vor dem Code","Claude Code","VibeFlow","Dokumentations-Entwicklungs-Workflow","Arbeitselement-Verwaltung","AI-gestützte Software-Entwicklung"],"pt":["manage-work","VibeFlow","Claude Code","desenvolvimento assistido por IA","disciplina de docs-antes-código","gerenciamento de itens de trabalho","rastreamento de workflow","criação de branches de recurso"],"ru":["manage-work","VibeFlow","Claude Code","разработка с помощью ИИ","дисциплина документации перед кодированием","управление рабочими элементами","отслеживание рабочего процесса","создание фич-branch"],"ar":["manage-work","VibeFlow","Claude Code","التطوير المدعوم بالذكاء الاصطناعي","الانضباط في التوثيق قبل الكود","إدارة عناصر العمل","تتبع سير العمل","إنشاء فروع الميزات"]}},"owner":"hardness1020","repo":"VibeFlow","repoPath":"hardness1020/VibeFlow","stars":2,"forks":0,"updatedAt":"2026-02-26T21:25:47Z","topics":["agent","claude-code","claude-skills","guardrails","vibe-coding"],"category":"community","skillMd":{"name":"manage-work","description":"Register work items, create feature branches, track and advance stages, close work items in the VibeFlow docs-first development workflow","bodyPreview":"# manage-work\n\nRegister work items, create feature branches, track and advance stages, close work items in the VibeFlow docs-first development workflow.\n\n## Purpose\n\nThis skill tracks multiple work items through the VibeFlow workflow by:\n- Registering work items with their workflow track and creating `feat/<slug>` branches\n- Tracking each work item''s current stage independently\n- Advancing work items through stages and routing to the appropriate skill\n- Closing work items as DONE after Checkpoin","body":"# manage-work\n\nRegister work items, create feature branches, track and advance stages, close work items in the VibeFlow docs-first development workflow.\n\n## Purpose\n\nThis skill tracks multiple work items through the VibeFlow workflow by:\n- Registering work items with their workflow track and creating `feat/<slug>` branches\n- Tracking each work item''s current stage independently\n- Advancing work items through stages and routing to the appropriate skill\n- Closing work items as DONE after Checkpoint #4 (release is optional)\n- Providing a dashboard view of all in-flight work items\n\n## Workflow\n\n```\nRegister Work Item\n    │\n    ├── Assign ID, generate slug from description, and assign track\n    ├── Create entry in docs/workflow-state.yaml (with branch field)\n    ├── Create git branch: feat/<slug>\n    └── Determine starting stage from track\n    │\n    ▼\nTrack Progress\n    │\n    ├── Show status dashboard (all work items)\n    ├── Show detailed status (single work item)\n    └── Cross-check manifest against artifacts\n    │\n    ▼\nAdvance & Route\n    │\n    ├── Mark work item as advancing to next stage\n    ├── Recommend the appropriate skill command\n    └── Update manifest with new stage\n    │\n    ▼\nClose Work Item (after Checkpoint #4)\n    │\n    ├── Mark stage as DONE (terminal state)\n    ├── Branch ready for merge to main\n    └── Alternative: advance to Stage I for release track\n```\n\n## Usage\n\n### Register a New Work Item\n\n```\n/manage-work register \"<description>\" <ID> <track>\n```\n\nRegisters a work item in `docs/workflow-state.yaml`, determines the starting stage, and creates a git branch `feat/<slug>`.\n\nSteps:\n1. Generate kebab-case slug from description\n2. Add entry to manifest with `branch: feat/<slug>`\n3. Create and checkout git branch: `git checkout -b feat/<slug>`\n\nExample:\n```\n/manage-work register \"Add anti-hallucination guardrails\" 030 medium\n# Creates branch: feat/add-anti-hallucination-guardrails\n\n/manage-work register \"Export data to CSV\" 031 small\n# Creates branch: feat/export-data-to-csv\n```\n\n### Status Dashboard\n\n```\n/manage-work status\n```\n\nShows all registered work items with their current stage, track, and last checkpoint.\n\nExample output:\n```\nWork Item                          Track    Stage  Checkpoint  Started\nadd-anti-hallucination-guardrails  Medium   G      3           2025-02-20\nexport-data-to-csv                 Small    E      2           2025-02-22\n```\n\n### Detailed Work Item Status\n\n```\n/manage-work status <ID>\n```\n\nShows detailed status for one work item including:\n- Current stage and description\n- Completed and remaining stages for its track\n- Last checkpoint passed\n- Artifact verification (cross-check with `detect_track.py --workitem <ID>`)\n\n### Advance a Work Item\n\n```\n/manage-work advance <ID>\n```\n\nMarks a work item as advancing to the next stage in its track:\n- Validates checkpoint if at a checkpoint boundary (blocks if failed)\n- Updates `stage` in `docs/workflow-state.yaml`\n- Updates `checkpoint` if a checkpoint boundary was crossed\n- Updates `docs` paths with any documents produced at the completed stage\n- Shows what the next stage requires\n- **After Checkpoint #4 (Stage H):** Offers two paths:\n  - `advance` → proceed to Stage I (release track)\n  - `close` → mark as DONE (see Close command below)\n\n### Close a Work Item\n\n```\n/manage-work close <ID>\n```\n\nMarks a work item as DONE after passing Checkpoint #4 (Implementation Complete):\n- Validates Checkpoint #4 if not yet passed (runs `validate_checkpoint.py 4 --json --project-root <root>`)\n- Requires work item to be at stage H or later with checkpoint >= 4\n- Sets `stage: DONE` in `docs/workflow-state.yaml`\n- Branch `feat/<slug>` is ready for merge to main\n- Blocked if Checkpoint #4 validation fails\n\nExample:\n```\n/manage-work close 030\n# Sets stage: DONE, branch feat/add-anti-hallucination-guardrails ready for merge\n```\n\n### Next Steps for a Work Item\n\n```\n/manage-work next <ID>\n```\n\nShows the recommended next action for a work item:\n- What the current stage requires\n- Which skill command to run\n- Whether a checkpoint validation is needed first\n\n## Workflow Tracks\n\n| Track | Scope | Stages | Release | Example |\n|-------|-------|--------|---------|---------|\n| **Micro** | Bug fix, typo, small refactor | F → G → DONE | No | Fix typo, update config |\n| **Small** | Single feature, no contracts | E → F → G → H → DONE | Optional (I-L) | Add form field, UI polish |\n| **Medium** | Multi-component, no new services | B → C → D → E → F → G → H → DONE | Optional (I-L) | New API endpoint |\n| **Large** | System change, new contracts/services | A → B → C → D → E → F → G → H → DONE | Optional (I-L) | New LLM integration |\n\n## Stage Overview\n\n### Planning Stages (A-D)\n- **A — Initiate**: Create/update PRD\n- **B — Discovery**: Analyze codebase (Medium/Large)\n- **C — Specify**: Create/update Tech Specs\n- **D — Decide**: Create ADRs for decisions\n\n**Checkpoint #1: Planning Complete**\n\n### Design Stage (E)\n- **E — Plan**: Create Feature Spec with API Design\n\n**Checkpoint #2: Design Complete**\n\n### Implementation Stages (F-H)\n- **F — RED**: Write failing unit tests + stubs\n- **G — GREEN**: Implement to pass tests\n- **H — REFACTOR**: Integration tests + quality validation\n\n**Checkpoint #3: Tests Complete** (after F)\n**Checkpoint #4: Implementation Complete** (after H)\n\n### Release Stages (I-L)\n- **I — Reconcile**: Update specs if implementation deviated\n- **J — Prepare**: Write OP-NOTE\n- **K — Deploy**: Follow OP-NOTE, verify\n- **L — Close**: Update indices, tag release\n\n**Checkpoint #5: Release Ready** (after J)\n**Checkpoint #6: Deployed** (after L)\n\n## Manifest Format\n\nThe manifest file `docs/workflow-state.yaml` is the single source of truth for work item lifecycle state:\n\n```yaml\nworkitems:\n  add-anti-hallucination-guardrails:\n    id: 030\n    description: \"Add anti-hallucination guardrails\"\n    track: medium        # micro | small | medium | large\n    stage: G             # current stage letter (A-L) or DONE\n    branch: feat/add-anti-hallucination-guardrails  # git branch\n    started: 2025-02-20  # date work item was registered\n    checkpoint: 3        # last checkpoint passed (1-6)\n    docs:\n      prd: docs/prds/prd.md\n      discovery: docs/discovery/disco-030.md\n      specs:\n        - docs/specs/spec-llm.md\n      adrs:\n        - docs/adrs/adr-030-prompt-strategy.md\n      feature: docs/features/ft-030-anti-hallucination.md\n      opnote: null\n  export-data-to-csv:\n    id: 031\n    description: \"Export data to CSV\"\n    track: small\n    stage: E\n    branch: feat/export-data-to-csv  # git branch\n    started: 2025-02-22\n    checkpoint: 2\n    docs:\n      prd: null\n      discovery: null\n      specs: []\n      adrs: []\n      feature: docs/features/ft-031-export-csv.md\n      opnote: null\n```\n\nWhen registering a new work item:\n1. Create `docs/workflow-state.yaml` if it doesn''t exist (use `assets/workflow-state-template.yaml`)\n2. Generate a kebab-case slug from the description (e.g., \"Add anti-hallucination guardrails\" → `add-anti-hallucination-guardrails`)\n3. Add the work item entry with `id`, `description`, `track`, `stage` (first stage for the track), `branch` (`feat/<slug>`), `started` (today), `checkpoint: 0`, and empty `docs` hierarchy\n4. Create and checkout git branch: `git checkout -b feat/<slug>`\n\nWhen advancing a work item:\n1. Read `docs/workflow-state.yaml`\n2. Check if current stage is a checkpoint boundary (D→E=CP#1, E→F=CP#2, F→G=CP#3, H→I=CP#4, J→K=CP#5, L→done=CP#6)\n3. If checkpoint boundary: run `python3 .claude/skills/validate-checkpoint/scripts/validate_checkpoint.py <N> --json --project-root <root>`\n   - If exit code 1 (failed): STOP. Report errors. Do NOT update manifest.\n   - If exit code 0 or 2 (passed/warnings): proceed\n4. Update `stage` field to the next stage in the track\n5. Update `checkpoint` if a checkpoint boundary was crossed\n6. Update `docs` with any document paths produced at the completed stage\n\n## Skill Routing\n\nEach stage maps to a specific skill. After determining the current stage for a work item, recommend the appropriate command:\n\n| Stage | Skill | Recommended Command |\n|-------|-------|--------------------|\n| A | define-prd | `/define-prd` |\n| B | analyze-codebase | `/analyze-codebase <ID>` |\n| C | define-tech-spec | `/define-tech-spec <name>` |\n| D | record-decision | `/record-decision <ID> <slug>` |\n| E | create-feature-spec | `/create-feature-spec <ID> <slug>` |\n| F | run-tdd | `/run-tdd red` |\n| G | run-tdd | `/run-tdd green` |\n| H | run-tdd | `/run-tdd refactor` |\n| I | prepare-release | `/prepare-release reconcile <ID>` |\n| J | prepare-release | `/prepare-release opnote <slug>` |\n| K | prepare-release | `/prepare-release check` |\n| L | prepare-release | `/prepare-release check` |\n\n**Checkpoint boundaries** — recommend `/validate-checkpoint <N>` before advancing past:\n- Stage D → E (Checkpoint #1)\n- Stage E → F (Checkpoint #2)\n- Stage F → G (Checkpoint #3)\n- Stage H → I (Checkpoint #4)\n- Stage J → K (Checkpoint #5)\n- Stage L → done (Checkpoint #6)\n\n## Artifact Verification\n\nUse `detect_track.py` to cross-check the manifest against actual artifacts:\n\n```bash\n# Verify a specific work item''s artifacts match its manifest stage\npython scripts/detect_track.py --workitem <ID> --verify\n\n# Detect artifacts for a specific work item\npython scripts/detect_track.py --workitem <ID>\n\n# Detect artifacts for all registered work items\npython scripts/detect_track.py --all-workitems\n```\n\nThis catches drift between the manifest and actual project state.\n\n## References\n\nSee `references/workflow-summary.md` for a condensed workflow overview.\n"},"lastSynced":"2026-03-06T07:06:26.370Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring structured workflow management in VibeFlow and Claude Code environments.","zh":"适合需要在VibeFlow和Claude Code环境中进行结构化工作流管理的开发代理。","ja":"VibeFlowとClaude Code環境での構造化されたワークフロー管理を必要とする開発エージェントに適しています。","ko":"VibeFlow와 Claude Code 환경에서 구조화된 워크플ロー 관리가 필요한 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren una gestión de flujo de trabajo estructurada en VibeFlow y entornos de Claude Code.","fr":"Idéal pour les agents de développement nécessitant une gestion de workflow structurée dans VibeFlow et les environnements Claude Code.","de":"Ideal für Entwicklungsmittel, die eine strukturierte Workflow-Verwaltung in VibeFlow und Claude Code-Umgebungen erfordern.","pt":"Ideal para Agentes de Desenvolvimento que requerem gestão de fluxo de trabalho estruturada em VibeFlow e ambientes Claude Code.","ru":"Идеально для агентов разработки, требующих структурированного управления рабочим процессом в VibeFlow и средах Claude Code.","ar":"مثالي لوكلاء التطوير الذين يحتاجون إلى إدارة تدفق عمل مهيكلة في VibeFlow وبيئات Claude Code."},"recommendation":{"en":"Empowers agents to enforce docs-before-code discipline, track work items through stages, and manage feature branches with checkpoint gates and branch-locked enforcement, leveraging VibeFlow''s docs-first development workflow and integrating with Claude Code skills.","zh":"赋予代理人执行文档优先于代码的纪律，通过阶段跟踪工作项，并使用检查点门和分支锁定执行管理特性分支，利用VibeFlow的文档优先开发工作流，并与Claude Code技能集成。","ja":"エージェントに、ドキュメントをコードよりも優先する規律を実施し、ステージを介して作業項目を追跡し、チェックポイントゲートとブランチロック実行を使用して機能ブランチを管理することを可能にし、VibeFlowのドキュメント優先の開発ワークフローを利用し、Claude Codeスキルと統合します。","ko":"에이전트가 문서를 코드보다 우선하는 규율을 시행하고 단계를 통해 작업 항목을 추적하며 체크포인트 게이트와 분기 잠금 실행을 사용하여 기능 분기를 관리할 수 있도록 하며 VibeFlow의 문서 우선 개발 워크플로를 활용하고 Claude Code 스킬과 통합합니다.","es":"Habilita a los agentes a aplicar la disciplina de documentación antes de código, realizar un seguimiento de los elementos de trabajo a través de las etapas y gestionar ramas de características con puertas de control y aplicación de bloqueo de ramas, aprovechando el flujo de trabajo de desarrollo docs-first de VibeFlow e integrándose con habilidades de Claude Code.","fr":"Permet aux agents d''appliquer la discipline de documentation avant code, de suivre les éléments de travail à travers les étapes et de gérer les branches de fonctionnalités avec des portes de contrôle et une application de verrouillage de branche, en exploitant le flux de travail de développement docs-first de VibeFlow et en s''intégrant aux compétences de Claude Code.","de":"Ermächtigt die Agenten, die Disziplin der Dokumentation vor dem Code durchzusetzen, Arbeitselemente über verschiedene Stadien hinweg zu verfolgen und Funktionszweige mit Kontrollpunkten und Sperren zu verwalten, indem es den docs-first-Entwicklungsworkflow von VibeFlow nutzt und sich in die Fähigkeiten von Claude Code integriert.","pt":"Habilita os agentes a impor a disciplina de docs-before-code, rastrear itens de trabalho por meio de estágios e gerenciar branches de recursos com portões de controle e aplicação de bloqueio de branch, aproveitando o fluxo de trabalho de desenvolvimento docs-first do VibeFlow e integrando com habilidades do Claude Code.","ru":"Наделяет агентов возможностью обеспечить соблюдение дисциплины docs-before-code, отслеживать рабочие элементы на различных стадиях и управлять ветвями функций с помощью контрольных точек и блокировки ветвей, используя рабочий процесс разработки docs-first в VibeFlow и интегрируясь с навыками Claude Code.","ar":"تمكّن الوكلاء من فرض الانضباط المتمثّل في وثائق قبل الكود، وتعقيب عناصر العمل خلال المراحل، وإدارة فروع الميزات بمحابس التحقق والتنفيذ القاصر للفرع، مستفيداً من تدفق عمل تطوير الوثائق أولاً في VibeFlow والتفاعل مع مهارات Claude Code."},"useCases":{"en":["Registering work items with custom workflow tracks","Automating stage advancements for multiple work items","Closing work items as DONE after checkpoint validation"],"zh":["注册带有自定义工作流跟踪的工作项","自动为多个工作项推进阶段","在检查点验证后将工作项关闭为DONE"],"ja":["カスタムワークフロートラックを使用した作業項目の登録","複数の作業項目のステージ自動進捗","チェックポイント検証後、作業項目をDONEとして閉じる"],"ko":["사용자 정의 워크플ロー 트랙을 사용한 작업 항목 등록","다중 작업 항목에 대한 단계 자동 진행","체크포인트 검증 후 작업 항목을 DONE으로 닫기"],"es":["Registrar elementos de trabajo con pistas de flujo de trabajo personalizadas","Automatizar el progreso de etapas para varios elementos de trabajo","Cerrar elementos de trabajo como HECHO después de la validación del punto de control"],"fr":["Enregistrer des éléments de travail avec des pistes de workflow personnalisées","Automatiser la progression des étapes pour plusieurs éléments de travail","Fermer des éléments de travail comme TERMINÉ après validation du point de contrôle"],"de":["Arbeitselemente mit benutzerdefinierten Workflow-Tracks registrieren","Automatisieren des Stadienfortschritts für mehrere Arbeitselemente","Arbeitselemente als ERLEDIGT schließen, nachdem der Kontrollpunkt überprüft wurde"],"pt":["Registrar itens de trabalho com faixas de fluxo de trabalho personalizadas","Automatizar avanços de estágio para vários itens de trabalho","Fechar itens de trabalho como CONCLUÍDO após validação do ponto de controle"],"ru":["Регистрация рабочих элементов с помощью пользовательских рабочих потоков","Автоматизация продвижения по стадиям для нескольких рабочих элементов","Завершение рабочих элементов как ГОТОВЫХ после проверки контрольной точки"],"ar":["تسجيل عناصر العمل مع مسارات تدفق العمل المخصصة","تأتمتة تحرك المراحل للعديد من عناصر العمل","إغلاق عناصر العمل كمنتهية بعد التحقق من نقطة التحقق"]},"limitations":{"en":["Requires VibeFlow and Claude Code skills integration","Limited to docs-first development workflow","Needs branch-locked enforcement for effective management"],"zh":["需要VibeFlow和Claude Code技能集成","仅限于文档优先开发工作流","需要分支锁定执行以有效管理"],"ja":["VibeFlowとClaude Codeスキルの統合が必要","ドキュメント優先の開発ワークフローに限定","有効な管理のためにブランチロック実行が必要"],"ko":["VibeFlow와 Claude Code 스킬의 통합이 필요","문서 우선 개발 워크플로에만 제한","유효한 관리를 위해 분기 잠금 실행이 필요"],"es":["Requiere la integración de habilidades de VibeFlow y Claude Code","Limitado al flujo de trabajo de desarrollo docs-first","Necesita una aplicación de bloqueo de ramas para una gestión eficaz"],"fr":["Nécessite l''intégration des compétences de VibeFlow et de Claude Code","Limité au flux de travail de développement docs-first","Nécessite une application de verrouillage de branche pour une gestion efficace"],"de":["Erfordert die Integration von VibeFlow- und Claude Code-Fähigkeiten","Begrenzt auf den docs-first-Entwicklungsworkflow","Benötigt eine Sperrenanwendung für Zweige für eine effektive Verwaltung"],"pt":["Exige integração de habilidades do VibeFlow e Claude Code","Limitado ao fluxo de trabalho de desenvolvimento docs-first","Necessita de aplicação de bloqueio de branch para gestão eficaz"],"ru":["Требует интеграции навыков VibeFlow и Claude Code","Ограничен рабочим процессом разработки docs-first","Требует блокировки ветвей для эффективного управления"],"ar":["يتطلب تكامل مهارات VibeFlow و Claude Code","محدود بتدفق عمل تطوير الوثائق أولا","يحتاج إلى تنفيذ قاصر للفرع من أجل الإدارة الفعّالة"]},"version":4},"contentHash":"6bf825b1c96958750d143ed657d93a2b1fe39960c6117b6481f9ce7cbad7dfea","qualityScore":57}');
