INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hardness1020/VibeFlow/manage-work', 'manage-work', 'hardness1020', 'VibeFlow', 'community', 'manage-work hardness1020 VibeFlow community agent claude-code claude-skills guardrails vibe-coding The manage-work skill enforces docs-before-code discipline in AI-assisted development, providing a full workflow with checkpoint gates and branch-locked enforcement. It benefits developers working with VibeFlow and Claude Code skills. VibeFlow 的 manage-work 技能提供了文档优先的开发工作流程，通过 Claude Code 实现自动化和 checkpoint gates VibeFlow の manage-work スキルは、ドキュメント優先の開発ワークフローを提供し、Claude Code で自動化とチェックポイントゲートを実現します VibeFlow의 manage-work 기능은 문서 우선 개발 워크플로우를 제공하며 Claude Code를 통해 자동화 및 체크포인트 게이트를 구현합니다 manage-work es una habilidad que aplica la disciplina de documentación antes de código en el desarrollo asistido por AI, utilizando Claude Code y VibeFlow para un flujo de trabajo completo manage-work est une compétence qui applique la discipline de documentation avant code dans le développement assisté par IA, en utilisant Claude Code et VibeFlow pour un flux de travail complet manage-work ist eine Fähigkeit, die die Disziplin der Dokumentation vor dem Code in der AI-gestützten Entwicklung anwendet, indem sie Claude Code und VibeFlow für einen kompletten Workflow nutzt O manage-work é uma habilidade que impõe a disciplina de docs-antes-código em projetos de desenvolvimento assistidos por IA com VibeFlow e Claude Code, permitindo o registro de itens de trabalho e o acompanhamento de estágios Manage-work - это навык, обеспечивающий дисциплину документации перед кодированием в проектах разработки с помощью ИИ с VibeFlow и Claude Code, позволяющий регистрировать рабочие элементы и отслеживать стадии manage-work هي مهارة تطبق الانضباط في التوثيق قبل الكود في مشاريع التطوير المدعومة بالذكاء الاصطناعي مع VibeFlow و Claude Code، مما يسمح بتسجيل عناصر العمل وتتبع المراحل how to use manage-work manage-work setup guide what is manage-work manage-work alternative manage-work vs VibeFlow Claude Code skills integration AI-assisted development workflow docs-before-code discipline VibeFlow workflow management VibeFlow manage-work Claude Code AIエージェント 文档优先开发 自动化工作流程 checkpoint gates 分支锁定 Registers work items with their workflow track and creates feat/<slug> branches Tracks each work item''s current stage independently Advances work items through stages and routes to the appropriate skill Closes work items as DONE after checkpoint Enforces docs-before-code discipline using Claude Code skills and VibeFlow Provides checkpoint gates and branch-locked enforcement for a full workflow manage-work is a skill that tracks multiple work items through the VibeFlow workflow, registering work items, creating feature branches, and advancing stages independently.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('leeovery/tick/workflow-bridge', 'community', 'leeovery', 'tick', 'leeovery/tick', 'workflow-bridge', 2, 0, 57, '2026-02-28T10:43:01Z', '2026-03-06T07:07:32.870Z', '5fd9f97d0e6e0353e0ba1bfb1b3773db89633be95b12c535ac0cba356c0a065a', '{"id":"leeovery/tick/workflow-bridge","name":"workflow-bridge","description":{"en":"workflow-bridge is a lightweight task management CLI designed for AI coding agents, prioritizing determinism and simplicity. It benefits AI developers by streamlining pipeline phases.","zh":"workflow-bridge 是一个轻量级的任务管理 CLI，专为 AI 代码代理设计，实现任务管理的自动化和高效化","ja":"workflow-bridge は、AIエージェント用の軽量タスク管理 CLI で、タスク管理の自動化と効率化を実現します","ko":"workflow-bridge는 AI 에이전트를 위한 가벼운 태스크 관리 CLI로 태스크 관리의 자동화와 효율화를 실현합니다","es":"workflow-bridge es una herramienta de gestión de tareas ligera diseñada para Agentes de IA, que prioriza la determinismo y la simplicidad con integración de Git sin fricciones","fr":"workflow-bridge est un outil de gestion de tâches léger conçu pour les Outils d''IA, qui privilégie la déterminisme et la simplicité avec une intégration Git sans friction","de":"workflow-bridge ist ein leichtes Task-Management-Tool, das für KI-Agenten entwickelt wurde, mit Priorität auf Determinismus und Einfachheit sowie einer reibungslosen Git-Integration","pt":"O workflow-bridge é uma habilidade que permite a gestão de tarefas determinísticas e simples, com integração perfeita ao Git. Utiliza o Tick, uma CLI leve para gerenciamento de tarefas.","ru":"Workflow-bridge — это навык, который позволяет управлять задачами детерминированным и простым способом, с идеальной интеграцией с Git. Использует Tick, легкий CLI для управления задачами.","ar":"جسر_Workflow هو مهارة تمكنك من إدارة المهام بطريقة محددة و بسيطة، مع التكامل المثالي مع Git. يستخدم Tick، واجهة سطر أوامر خفيفة لإدارة المهام."},"seo":{"title":{"en":"workflow-bridge: CLI Task Management for AI Agents | AI A...","zh":"workflow-bridge 设置指南：AI 代码代理任务管理","ja":"workflow-bridge 初心者ガイド：AIエージェントのタスク管理","ko":"workflow-bridge 사용자 가이드: AI 에이전트를 위한 태스크 관리","es":"Guía de configuración de workflow-bridge para Agentes de IA","fr":"Configurer workflow-bridge pour les Outils d''IA avec succès","de":"Einrichtungsleitfaden für workflow-bridge in KI-Agenten","pt":"Guia de Configuração do Workflow-Bridge para Ferramentas ...","ru":"Настройка Workflow-Bridge для ИИ Агентов: Руководство","ar":"دليل إعداد جسر_Workflow لعمليات الذكاء الاصطناعي"},"description":{"en":"Discover how workflow-bridge simplifies AI coding with deterministic task management and zero-friction git integration - get started now!","zh":"了解 workflow-bridge 的功能和优点，实现 AI 代码代理任务管理的自动化和高效化","ja":"workflow-bridge を使用して AIエージェントのタスク管理を自動化し、開発効率を向上させます","ko":"workflow-bridge를 사용하여 AI 에이전트의 태스크 관리를 자동화하고 개발 효율을 높여보세요","es":"Aprende a implementar workflow-bridge en tus proyectos de Agentes de IA para mejorar la gestión de tareas y la integración con Git","fr":"Découvrez comment configurer workflow-bridge pour améliorer la gestion des tâches et l''intégration Git dans vos projets d''Outils d''IA","de":"Erfahren Sie, wie Sie workflow-bridge in Ihren KI-Agenten-Projekten einrichten, um die Aufgabenverwaltung und Git-Integration zu optimieren","pt":"Aprenda a configurar o workflow-bridge para Ferramentas de Inteligência Artificial e melhore a gestão de tarefas com o Tick, uma CLI leve e integrada ao Git","ru":"Узнайте, как настроить workflow-bridge для ИИ Агентов и улучшить управление задачами с помощью Tick, легкого и интегрированного в Git CLI","ar":"تعلم كيفية إعداد جسر_Workflow لعمليات الذكاء الاصطناعي وتحسين إدارة المهام باستخدام Tick، واجهة سطر أوامر خفيفة ومندمجة مع Git"},"definition":{"en":"workflow-bridge is a lightweight CLI task management tool designed for AI coding agents, prioritizing determinism, simplicity, and zero-friction git integration.","zh":"workflow-bridge 是一个用于 AI 代码代理的任务管理工具","ja":"workflow-bridge は、AIエージェント用のタスク管理ツールです","ko":"workflow-bridge는 AI 에이전트를 위한 태스크 관리 도구입니다","es":"workflow-bridge es un puente de flujo de trabajo que permite la gestión de tareas y la integración con Git de manera determinista y sencilla","fr":"workflow-bridge est un pont de workflow qui permet la gestion des tâches et l''intégration Git de manière déterministe et simple","de":"workflow-bridge ist eine Workflow-Brücke, die die Aufgabenverwaltung und Git-Integration deterministisch und einfach ermöglicht","pt":"O que é workflow-bridge? É uma habilidade que habilita a gestão de tarefas determinísticas e integração ao Git para Ferramentas de Inteligência Artificial.","ru":"Что такое workflow-bridge? Это навык, который позволяет управлять задачами детерминированным способом и интегрироваться с Git для ИИ Агентов.","ar":"ما هو جسر_Workflow؟ هو مهارة تمكنك من إدارة المهام بطريقة محددة والتكامل مع Git لعمليات الذكاء الاصطناعي."},"features":{"en":["Enters plan mode with deterministic continuation instructions","Discovers next pipeline phase and creates plan mode handoff","Survives context compaction for seamless workflow","Invoked by processing skills like technical-discussion and technical-specification","Adheres to zero output rule for efficient processing"],"zh":["轻量级任务管理 CLI","支持确定性续行指令","零输出规则，提高开发效率","与 Git 集成，实现版本控制","支持计划模式和上下文压缩"],"ja":["軽量タスク管理 CLI","決定性継続指令のサポート","ゼロ出力規則、開発効率の向上","Gitとの統合、バージョン管理の実現","計画モードとコンテキスト圧縮のサポート"],"ko":["가벼운 태스크 관리 CLI","결정적续行 지침 지원","제로 출력 규칙, 개발 효율성 향상","Git와의 통합, 버전 관리 구현","계획 모드와 컨텍스트 압축 지원"],"es":["Planificación de tareas determinista","Integración de Git sin fricciones","Compatibilidad con CLI","Continuación de instrucciones deterministas","Creación de planes de mano para fases de pipeline"],"fr":["Planification de tâches déterministe","Intégration Git sans friction","Compatibilité avec CLI","Continuation d''instructions déterministes","Création de plans de main pour les phases de pipeline"],"de":["Deterministische Aufgabenplanung","Reibungslose Git-Integration","Kompatibilität mit CLI","Fortsetzung deterministischer Anweisungen","Erstellung von Handoff-Plänen für Pipeline-Phasen"],"pt":["Gestão de tarefas determinísticas com o Tick","Integração perfeita ao Git","Modo de plano com instruções de continuação determinísticas","Criação de plano de mão para a próxima fase","Suporte a context compaction"],"ru":["Управление задачами детерминированным способом с помощью Tick","Идеальная интеграция с Git","Режим плана с инструкциями детерминированного продолжения","Создание плана передачи для следующей фазы","Поддержка сжатия контекста"],"ar":["إدارة المهام بطريقة محددة باستخدام Tick","التكامل المثالي مع Git","وضع التخطيط مع تعليمات الاستمرار المحددة","إنشاء خطة التسليم للطور التالي","دعم ضغط السياق"]},"keywords":{"en":["how to use workflow-bridge","workflow-bridge alternative","workflow-bridge setup guide","what is workflow-bridge","workflow-bridge vs other CI tools","install workflow-bridge","workflow-bridge for AI coding agents","git integration with workflow-bridge","deterministic task management with workflow-bridge"],"zh":["AI 代码代理","任务管理","CLI","自动化","高效化","Git 集成","计划模式","上下文压缩","AI 工具"],"ja":["AIエージェント","タスク管理","CLI","自動化","効率化","Git統合","計画モード","コンテキスト圧縮","AIツール"],"ko":["AI 에이전트","태스크 관리","CLI","자동화","효율화","Git 통합","계획 모드","컨텍스트 압축","AI 도구"],"es":["Agentes de IA","gestión de tareas","integración de Git","CLI","determinismo","flujo de trabajo","pipeline","configuración de workflow-bridge"],"fr":["Outils d''IA","gestion de tâches","intégration Git","CLI","déterminisme","flux de travail","pipeline","configuration de workflow-bridge"],"de":["KI-Agenten","Aufgabenverwaltung","Git-Integration","CLI","Determinismus","Workflow","Pipeline","Einrichtung von workflow-bridge"],"pt":["workflow-bridge","Ferramentas de Inteligência Artificial","gestão de tarefas","Tick CLI","integração ao Git","modos de plano","context compaction"],"ru":["workflow-bridge","ИИ Агенты","управление задачами","Tick CLI","интеграция с Git","режимы плана","сжатие контекста"],"ar":["جسر_Workflow","عمليات الذكاء الاصطناعي","إدارة المهام","Tick واجهة سطر أوامر","التكامل مع Git","أوضاع التخطيط","ضغط السياق"]}},"owner":"leeovery","repo":"tick","repoPath":"leeovery/tick","stars":2,"forks":0,"updatedAt":"2026-02-28T10:43:01Z","topics":[],"category":"community","skillMd":{"name":"workflow-bridge","description":"","bodyPreview":"Enter plan mode with deterministic continuation instructions.\n\nThis skill is invoked by processing skills (technical-discussion, technical-specification, etc.) when a pipeline phase concludes. It discovers the next phase and creates a plan mode handoff that survives context compaction.\n\n> **ZERO OUTPUT RULE**: Do not narrate your processing. Produce no output until a step or reference file explicitly specifies display content. No \"proceeding with...\", no discovery summaries, no routing decisions","body":"Enter plan mode with deterministic continuation instructions.\n\nThis skill is invoked by processing skills (technical-discussion, technical-specification, etc.) when a pipeline phase concludes. It discovers the next phase and creates a plan mode handoff that survives context compaction.\n\n> **ZERO OUTPUT RULE**: Do not narrate your processing. Produce no output until a step or reference file explicitly specifies display content. No \"proceeding with...\", no discovery summaries, no routing decisions, no transition text. Your first output must be content explicitly called for by the instructions.\n\n## Instructions\n\nThis skill receives context from the calling processing skill:\n- **Topic**: The topic name\n- **Work type**: greenfield, feature, or bugfix\n- **Completed phase**: The phase that just concluded\n\n---\n\n## Step 1: Run Discovery\n\n!`.claude/skills/workflow-bridge/scripts/discovery.sh`\n\nIf the above shows a script invocation rather than YAML output, the dynamic content preprocessor did not run. Execute the script before continuing:\n\n```bash\n.claude/skills/workflow-bridge/scripts/discovery.sh\n```\n\nThe output contains three sections: `features:`, `bugfixes:`, and `greenfield:`. Use the known work type and topic from the calling context to extract the relevant data:\n\n#### If work type is \"feature\"\n\nFind the topic entry under `features: > topics:` and extract its `next_phase`.\n\n#### If work type is \"bugfix\"\n\nFind the topic entry under `bugfixes: > topics:` and extract its `next_phase`.\n\n#### If work type is \"greenfield\"\n\nParse the `greenfield:` section for phase-centric state:\n- `state`: Counts of artifacts across all phases\n- Phase-specific file lists with their statuses\n\n→ Proceed to **Step 2**.\n\n---\n\n## Step 2: Route to Continuation Reference\n\nBased on work type, load the appropriate continuation reference:\n\n#### If work type is \"feature\"\n\nLoad **[feature-continuation.md](references/feature-continuation.md)** and follow its instructions as written.\n\n#### If work type is \"bugfix\"\n\nLoad **[bugfix-continuation.md](references/bugfix-continuation.md)** and follow its instructions as written.\n\n#### If work type is \"greenfield\"\n\nLoad **[greenfield-continuation.md](references/greenfield-continuation.md)** and follow its instructions as written.\n\n---\n\n## Notes\n\n**Feature/bugfix** continuation references:\n1. Use discovery output to compute a single `next_phase`\n2. Call `EnterPlanMode` tool, write plan file with instructions to invoke `start-{next_phase}` with topic + work_type\n3. Call `ExitPlanMode` tool for user approval\n\nThe user will then clear context, and the fresh session will invoke the appropriate start-* skill with the topic and work_type provided, causing it to skip discovery and proceed directly to validation/processing.\n\n**Greenfield** continuation is interactive — greenfield is phase-centric with multiple actionable items, so there is no single next phase. The reference displays state, presents a menu of choices, waits for user selection, then enters plan mode with that specific choice. The plan mode content is deterministic (same as feature/bugfix) once the user has chosen.\n"},"lastSynced":"2026-03-06T07:07:32.870Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Coding Agents requiring streamlined pipeline management and deterministic task continuation.","zh":"适合需要流线型管道管理和确定性任务继续的AI编码代理。","ja":"AIコーディングエージェントがストリームライン化されたパイプライン管理と決定性タスク継続を必要とする場合に適しています。","ko":"스트림 라인화 된 파이프 라인 관리 및 결정적 작업 연속이 필요한 AI 코딩 에이전트에 적합합니다.","es":"Ideal para agentes de codificación de IA que requieren una gestión de pipeline optimizada y una continuación de tareas determinista.","fr":"Idéal pour les agents de codage de l''IA nécessitant une gestion de pipeline rationalisée et une continuation de tâches déterministe.","de":"Ideal für AI-Coding-Agents, die eine optimierte Pipeline-Verwaltung und eine deterministische Aufgabenfortführung erfordern.","pt":"Ideal para Agentes de Codificação de IA que exigem gerenciamento de pipeline simplificado e continuação de tarefas determinística.","ru":"Идеально для агентов кодирования ИИ, требующих упрощенного управления конвейером и детерминированного продолжения задач.","ar":"مثالي لعميل تشفير الذكاء الاصطناعي المتطلب لإدارة خط أنابيب مبسطة واستمرار مهمة محددة."},"recommendation":{"en":"Empowers agents to manage pipeline phases with simplicity, utilizing deterministic continuation instructions and context compaction, while supporting CLI-based task management and plan mode handoffs via technical skills like technical-discussion and technical-specification.","zh":"赋予代理管理管道阶段的能力，利用简单性、确定性继续指令和上下文压缩，同时支持基于CLI的任务管理和计划模式手loffs，通过技术技能如技术讨论和技术规格。","ja":"エージェントがパイプラインの段階を管理する能力を与え、シンプルさ、決定性継続命令、コンテキスト圧縮を活用し、CLIベースのタスク管理とプランモードハンドオフをサポートする、テクニカルスキルであるテクニカルディスカッションとテクニカルスペシフィケーションを使用します。","ko":"에이전트가 파이프 라인의 단계를 관리할 수 있는 능력을 부여하여 단순성, 결정적继續 지침 및 컨텍스트 압축을 사용하며, CLI 기반의 작업 관리 및 계획 모드 핸드 오버를 지원하며, 기술 스킬인 기술 토론 및 기술 사양을 사용합니다.","es":"Habilita a los agentes a gestionar fases de pipeline con simplicidad, utilizando instrucciones de continuación determinista y compactación de contexto, mientras que admite la gestión de tareas basada en CLI y la transferencia de planes en modo de mano mediante habilidades técnicas como technical-discussion y technical-specification.","fr":"Permet aux agents de gérer les phases de pipeline avec simplicité, en utilisant des instructions de continuation déterministe et une compactation de contexte, tout en prenant en charge la gestion des tâches basée sur CLI et les transferts de plans en mode main via des compétences techniques comme technical-discussion et technical-specification.","de":"Ermöglicht es den Agenten, Pipeline-Phasen mit Einfachheit zu verwalten, indem sie deterministische Fortführungsanweisungen und Kontextverdichtung verwenden, während sie gleichzeitig die CLI-basierte Aufgabenverwaltung und den Planmodus-Handover über technische Fähigkeiten wie technical-discussion und technical-specification unterstützen.","pt":"Habilita agentes a gerenciar fases de pipeline com simplicidade, utilizando instruções de continuação determinística e compactação de contexto, além de suportar gerenciamento de tarefas baseado em CLI e transferências de plano via habilidades técnicas como discussão técnica e especificação técnica.","ru":"Наделяет агентов возможностью управлять фазами конвейера с простотой, используя детерминированные инструкции продолжения и компактацию контекста, а также поддерживает управление задачами на основе CLI и передачи планов через технические навыки, такие как техническая дискуссия и техническая спецификация.","ar":"يمنح العميل القدرة على إدارة مراحل خط الأنابيب ببساطة، باستخدام تعليمات استمرار محددة وضغط السياق، بالإضافة إلى دعم إدارة المهام القائمة على CLI وعمليات نقل الخطة عبر المهارات الفنية مثل المناقشة الفنية والمواصفات الفنية."},"useCases":{"en":["Streamlining pipeline phases for AI coding tasks","Automating task handoffs between pipeline phases","Ensuring deterministic continuation of tasks"],"zh":["流线型AI编码任务的管道阶段","自动化管道阶段之间的任务手loffs","确保任务的确定性继续"],"ja":["AIコーディングタスクのパイプライン段階のストリームライン化","パイプライン段階間のタスクハンドオフの自動化","タスクの決定性継続の確保"],"ko":["AI 코딩 작업의 파이프 라인 단계의 스트림 라인화","파이프 라인 단계 간의 작업 핸드 오버의 자동화","작업의 결정적 연속의 보장"],"es":["Optimización de fases de pipeline para tareas de codificación de IA","Automatización de transferencias de tareas entre fases de pipeline","Garantía de continuación determinista de tareas"],"fr":["Rationalisation des phases de pipeline pour les tâches de codage de l''IA","Automatisation des transferts de tâches entre les phases de pipeline","Assurance d''une continuation déterministe des tâches"],"de":["Optimierung von Pipeline-Phasen für AI-Coding-Aufgaben","Automatisierung von Aufgabenübertragungen zwischen Pipeline-Phasen","Gewährleistung einer deterministischen Aufgabenfortführung"],"pt":["Simplificando fases de pipeline para tarefas de codificação de IA","Automatizando transferências de tarefas entre fases de pipeline","Garantindo continuação determinística de tarefas"],"ru":["Упрощение фаз конвейера для задач кодирования ИИ","Автоматизация передачи задач между фазами конвейера","Обеспечение детерминированного продолжения задач"],"ar":["تبسيط مراحل خط الأنابيب لمهام تشفير الذكاء الاصطناعي","تأتمة نقل المهام بين مراحل خط الأنابيب","ضمان استمرار محدد للمهام"]},"limitations":{"en":["Requires technical skills like technical-discussion and technical-specification for invocation","Must be used within a CLI environment","Survives context compaction but may require additional configuration"],"zh":["需要技术技能如技术讨论和技术规格来调用","必须在CLI环境中使用","可以承受上下文压缩，但可能需要额外配置"],"ja":["呼び出しにはテクニカルスキルであるテクニカルディスカッションとテクニカルスペシフィケーションが必要","CLI環境内で使用する必要がある","コンテキスト圧縮に耐えられるが、追加の設定が必要になる場合がある"],"ko":["호출에는 기술 스킬인 기술 토론 및 기술 사양이 필요","CLI 환경 내에서 사용해야 함","컨텍스트 압축에耐えられる 그러나 추가 설정이 필요한 경우가 있음"],"es":["Requiere habilidades técnicas como technical-discussion y technical-specification para la invocación","Debe usarse dentro de un entorno CLI","Sobrevive a la compactación de contexto, pero puede requerir configuración adicional"],"fr":["Nécessite des compétences techniques comme technical-discussion et technical-specification pour l''invocation","Doit être utilisé dans un environnement CLI","Survit à la compactation de contexte, mais peut nécessiter une configuration supplémentaire"],"de":["Erfordert technische Fähigkeiten wie technical-discussion und technical-specification für die Invocation","Muss in einer CLI-Umgebung verwendet werden","Überlebt die Kontextverdichtung, kann aber zusätzliche Konfiguration erfordern"],"pt":["Exige habilidades técnicas como discussão técnica e especificação técnica para invocação","Deve ser usado dentro de um ambiente CLI","Sobrevive à compactação de contexto, mas pode exigir configuração adicional"],"ru":["Требует технических навыков, таких как техническая дискуссия и техническая спецификация, для вызова","Должно использоваться внутри среды CLI","Выдерживает компактацию контекста, но может потребовать дополнительной конфигурации"],"ar":["يتطلب مهارات فنية مثل المناقشة الفنية والمواصفات الفنية للاستدعاء","يجب استخدامه داخل بيئة CLI","ينجو من ضغط السياق، ولكنه قد يحتاج إلى تكوين إضافي"]},"version":4},"contentHash":"5fd9f97d0e6e0353e0ba1bfb1b3773db89633be95b12c535ac0cba356c0a065a","qualityScore":57}');
