INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('leeovery/tick/workflow-bridge', 'workflow-bridge', 'leeovery', 'tick', 'community', 'workflow-bridge leeovery tick community workflow-bridge is a lightweight task management CLI designed for AI coding agents, prioritizing determinism and simplicity. It benefits AI developers by streamlining pipeline phases. workflow-bridge 是一个轻量级的任务管理 CLI，专为 AI 代码代理设计，实现任务管理的自动化和高效化 workflow-bridge は、AIエージェント用の軽量タスク管理 CLI で、タスク管理の自動化と効率化を実現します workflow-bridge는 AI 에이전트를 위한 가벼운 태스크 관리 CLI로 태스크 관리의 자동화와 효율화를 실현합니다 workflow-bridge es una herramienta de gestión de tareas ligera diseñada para Agentes de IA, que prioriza la determinismo y la simplicidad con integración de Git sin fricciones workflow-bridge est un outil de gestion de tâches léger conçu pour les Outils d''IA, qui privilégie la déterminisme et la simplicité avec une intégration Git sans friction workflow-bridge ist ein leichtes Task-Management-Tool, das für KI-Agenten entwickelt wurde, mit Priorität auf Determinismus und Einfachheit sowie einer reibungslosen Git-Integration O workflow-bridge é uma habilidade que permite a gestão de tarefas determinísticas e simples, com integração perfeita ao Git. Utiliza o Tick, uma CLI leve para gerenciamento de tarefas. Workflow-bridge — это навык, который позволяет управлять задачами детерминированным и простым способом, с идеальной интеграцией с Git. Использует Tick, легкий CLI для управления задачами. جسر_Workflow هو مهارة تمكنك من إدارة المهام بطريقة محددة و بسيطة، مع التكامل المثالي مع Git. يستخدم Tick، واجهة سطر أوامر خفيفة لإدارة المهام. how to use workflow-bridge workflow-bridge alternative workflow-bridge setup guide what is workflow-bridge workflow-bridge vs other CI tools install workflow-bridge workflow-bridge for AI coding agents git integration with workflow-bridge deterministic task management with workflow-bridge AI 代码代理 任务管理 CLI 自动化 高效化 Git 集成 计划模式 上下文压缩 AI 工具 Enters plan mode with deterministic continuation instructions Discovers next pipeline phase and creates plan mode handoff Survives context compaction for seamless workflow Invoked by processing skills like technical-discussion and technical-specification Adheres to zero output rule for efficient processing workflow-bridge is a lightweight CLI task management tool designed for AI coding agents, prioritizing determinism, simplicity, and zero-friction git integration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('colmarius/mobcrew/adapt', 'community', 'colmarius', 'mobcrew', 'colmarius/mobcrew', 'adapt', 2, 0, 57, '2026-02-04T10:25:17Z', '2026-03-06T07:09:11.337Z', 'ee3dd268e177051bdcedc5569ef6bc1569a15eb08915647ea75205a348b5856a', '{"id":"colmarius/mobcrew/adapt","name":"adapt","description":{"en":"The adapt skill is a native macOS timer designed for pair and mob programming sessions, helping developers analyze project structures and detect conventions. It benefits developers working on macOS platforms.","zh":"Adapt , macOS, ","ja":"Adapt AIエージェント, macOS, ","ko":"Adapt , macOS, ","es":"Adapt es una herramienta de programación en pareja para macOS que analiza proyectos y configura información específica. Soporta tecnologías como SwiftUI.","fr":"Adapt est un outil de programmation en binôme pour macOS qui analyse les projets et configure des informations spécifiques. Il prend en charge des technologies comme SwiftUI.","de":"Adapt ist ein Werkzeug für Paarprogrammierung auf macOS, das Projekte analysiert und projektspezifische Informationen konfiguriert. Es unterstützt Technologien wie SwiftUI.","pt":"O Adapt é um companheiro de programação em macOS que analisa o projeto e preenche o arquivo .agents/PROJECT.md com informações específicas do projeto.","ru":"ИИ Агент Adapt анализирует проект и заполняет файл .agents/PROJECT.md информацией, специфичной для проекта.","ar":"أدابت هو رفيق برمجة macOS يanalyzes المشروع و يملأ ملف .agents/PROJECT.md بمعلومات محددة للمشروع."},"seo":{"title":{"en":"adapt: Mob Programming Companion Setup Guide | AI Agent S...","zh":"Adapt Setup Guide: macOS ","ja":"Adapt AIエージェント: macOS ","ko":"Adapt : macOS ","es":"Guía de configuración de Adapt: Herramienta de programaci...","fr":"Guide de mise en place d''Adapt : Outil de programmation e...","de":"Adapt-Setup-Leitfaden: native macOS-Timer für Paar- und M...","pt":"Adapt: Guia de Configuração para Desenvolvedores","ru":"ИИ Агент Adapt: Руководство по Настройке","ar":"إعداد أدابت: دليل للمطورين"},"description":{"en":"Get started with adapt, the ultimate macOS timer for pair and mob programming sessions. Learn how to analyze project structures and detect conventions with t...","zh":"Adapt AI, macOS, ","ja":"Adapt AIエージェント, macOS, ","ko":"Adapt , macOS, ","es":"Descubre cómo Adapt analiza y configura proyectos para sesiones de programación en pareja y mob con tecnologías como SwiftUI","fr":"Découvrez comment Adapt analyse et configure les projets pour les séances de programmation en binôme et en mob avec des technologies comme SwiftUI","de":"Erfahren Sie, wie Adapt Projekte analysiert und konfiguriert für Paar- und Mob-Programmierungssitzungen mit Technologien wie SwiftUI","pt":"Aprenda a configurar o Adapt, um companheiro de programação em macOS para sessões de pair e mob programming","ru":"Узнайте, как настроить ИИ Агент Adapt, родной таймер macOS для сессий парного и мобильного программирования","ar":"تعلم كيفية إعداد أدابت، رفيق برمجة macOS للمحادثات البرمجية و mob"},"definition":{"en":"adapt is a macOS-based AI agent skill that analyzes project structures, detects conventions, and customizes configurations for pair and mob programming sessions.","zh":"Adapt : macOS, ","ja":"Adapt AIエージェント: macOS, ","ko":"Adapt : macOS, ","es":"Adapt es una herramienta de programación en pareja que analiza proyectos y configura información específica para sesiones de programación en pareja y mob","fr":"Adapt est un outil de programmation en binôme qui analyse les projets et configure des informations spécifiques pour les séances de programmation en binôme et en mob","de":"Adapt ist ein Werkzeug für Paarprogrammierung, das Projekte analysiert und projektspezifische Informationen konfiguriert für Paar- und Mob-Programmierungssitzungen","pt":"O Adapt é um agente de programação que analisa a estrutura do projeto e detecta convenções para personalizar a configuração.","ru":"ИИ Агент Adapt - это агент программирования, который анализирует структуру проекта и обнаруживает соглашения для настройки конфигурации.","ar":"أدابت هو وكيل برمجة يanalyzes هيكل المشروع و يكتشف الاتفاقيات لتخصيص الإعدادات."},"features":{"en":["Analyzes project structure by scanning configuration files like package.json and Cargo.toml","Detects frameworks, libraries, and tools in use, such as SwiftUI","Fills in .agents/PROJECT.md with project-specific information","Identifies existing scripts/commands in config files","Supports customization of configuration for mob programming sessions"],"zh":["macOS","SwiftUI","package.json","Cargo.toml","go.mod","pyproject.toml"],"ja":["macOS","SwiftUI","package.json","Cargo.toml","go.mod","pyproject.toml"],"ko":["macOS","SwiftUI","package.json","Cargo.toml","go.mod","pyproject.toml"],"es":["Análisis de estructura de proyecto","Detección de convenciones de configuración","Soporte para tecnologías como SwiftUI","Compatibilidad con macOS","Configuración de información de proyecto específica"],"fr":["Analyse de la structure de projet","Détection des conventions de configuration","Prise en charge des technologies comme SwiftUI","Compatibilité avec macOS","Configuration d''informations de projet spécifiques"],"de":["Analyse der Projekstruktur","Erkennung von Konfigurationskonventionen","Unterstützung von Technologien wie SwiftUI","Kompatibilität mit macOS","Konfiguration von projektspezifischen Informationen"],"pt":["Análise da estrutura do projeto","Detecção de convenções","Suporte a frameworks e bibliotecas","Integração com package.json, Cargo.toml, go.mod e pyproject.toml","Compatibilidade com macOS"],"ru":["Анализ структуры проекта","Обнаружение соглашений","Поддержка фреймворков и библиотек","Интеграция с package.json, Cargo.toml, go.mod и pyproject.toml","Совместимость с macOS"],"ar":["تحليل هيكل المشروع","اكتشاف الاتفاقيات","دعم الإطارات و المكتبات","التكامل مع package.json, Cargo.toml, go.mod و pyproject.toml","التوافق مع macOS"]},"keywords":{"en":["how to use adapt","adapt setup guide","macos mob programming timer","adapt alternative","adapt vs mob","what is adapt","adapt install","mob programming companion","adapt for SwiftUI developers","adapt for pair programming"],"zh":["Adapt AI","macOS","SwiftUI","AI","AI","mob","pair programming"],"ja":["Adapt AIエージェント","macOS","SwiftUI","AIエージェント","AIツール","mob","pair programming"],"ko":["Adapt ","macOS","SwiftUI","AI","AI","mob","pair programming"],"es":["herramientas de programación en pareja","Adapt macOS","programación en pareja","mob programming","SwiftUI","desarrollo de software","herramientas de desarrollo","programación en binôme"],"fr":["outils de programmation en binôme","Adapt macOS","programmation en binôme","programmation en mob","SwiftUI","développement de logiciels","outils de développement","programmation en équipe"],"de":["Werkzeuge für Paarprogrammierung","Adapt macOS","Paarprogrammierung","Mob-Programmierung","SwiftUI","Softwareentwicklung","Entwicklungstools","Teamprogrammierung"],"pt":["Adapt","programação em macOS","sessões de pair e mob programming","análise de estrutura de projeto","detecção de convenções","SwiftUI","desenvolvimento de software"],"ru":["ИИ Агент Adapt","программирование на macOS","сессии парного и мобильного программирования","анализ структуры проекта","обнаружение соглашений","SwiftUI","разработка программного обеспечения"],"ar":["أدابت","برمجة على macOS","جلسات برمجة زوجية و mob","تحليل هيكل المشروع","اكتشاف الاتفاقيات","SwiftUI","تطوير البرمجيات"]}},"owner":"colmarius","repo":"mobcrew","repoPath":"colmarius/mobcrew","stars":2,"forks":0,"updatedAt":"2026-02-04T10:25:17Z","topics":["macos","mob","programming","swiftui"],"category":"community","skillMd":{"name":"adapt","description":"Analyze project and fill in PROJECT.md. Use when adapting dot-agents to a new project, after initial installation.","bodyPreview":"# Adapt Skill\n\nAnalyze the current project and fill in `.agents/PROJECT.md` with project-specific information.\n\n## When to Use\n\nRun this skill after installing dot-agents into a new project to customize the configuration.\n\n## Workflow\n\n1. **Analyze project structure**\n   - Scan for configuration files (package.json, Cargo.toml, go.mod, pyproject.toml, etc.)\n   - Identify frameworks, libraries, and tools in use\n   - Find existing scripts/commands in config files\n\n2. **Detect conventions**\n   - Lo","body":"# Adapt Skill\n\nAnalyze the current project and fill in `.agents/PROJECT.md` with project-specific information.\n\n## When to Use\n\nRun this skill after installing dot-agents into a new project to customize the configuration.\n\n## Workflow\n\n1. **Analyze project structure**\n   - Scan for configuration files (package.json, Cargo.toml, go.mod, pyproject.toml, etc.)\n   - Identify frameworks, libraries, and tools in use\n   - Find existing scripts/commands in config files\n\n2. **Detect conventions**\n   - Look at code style (naming, formatting)\n   - Check for existing linter/formatter configs\n   - Identify testing patterns\n\n3. **Update PROJECT.md**\n   - Fill in project name from config\n   - List detected tech stack\n   - Extract commands from package.json scripts, Cargo.toml, Makefile, etc.\n   - Note any project-specific conventions observed\n\n4. **Suggest AGENTS.md updates**\n   - Recommend project-specific commands to add\n   - Suggest conventions to document\n\n## Example Output\n\nAfter running, PROJECT.md should look like:\n\n```markdown\n# Project Configuration\n\n## Project Name\n\nmy-awesome-app\n\n## Tech Stack\n\n- Language: TypeScript\n- Framework: Next.js 14\n- Database: PostgreSQL with Prisma\n- Testing: Jest, Playwright\n\n## Commands\n\n```bash\n# Install\npnpm install\n\n# Development\npnpm dev\n\n# Build\npnpm build\n\n# Test\npnpm test\npnpm test:e2e\n\n# Lint/Format\npnpm lint\npnpm format\n```\n\n## Conventions\n\n- Use kebab-case for file names\n- Components in src/components/\n- API routes in src/app/api/\n\n## Checklist\n\n- [ ] Read package.json/Cargo.toml/go.mod for project name and scripts\n- [ ] Identify main framework from dependencies\n- [ ] Find test commands and test file patterns\n- [ ] Check for Makefile, Justfile, or task runners\n- [ ] Look for .eslintrc, .prettierrc, rustfmt.toml for style configs\n- [ ] Update PROJECT.md with findings\n- [ ] Suggest any AGENTS.md additions\n"},"lastSynced":"2026-03-06T07:09:11.337Z","agentAnalysis":{"suitability":{"en":"Perfect for macOS-based Development Agents needing project structure analysis and convention detection for efficient pair and mob programming sessions.","zh":"适用于需要项目结构分析和约定检测以实现高效的配对和集体编程会话的macOS基础开发代理。","ja":"macOSベースの開発エージェントがプロジェクト構造分析と規約検出を必要とするペアプログラミングおよびモブプログラミングセッションに最適です。","ko":"프로젝트 구조 분석 및 규약 감지로 효율적인 페어 및 모브 프로그래밍 세션을 필요로 하는 macOS 기반 개발 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollo basados en macOS que necesitan análisis de estructura de proyecto y detección de convenciones para sesiones de programación en pareja y multitud eficientes.","fr":"Parfait pour les Agents de Développement basés sur macOS nécessitant une analyse de structure de projet et une détection de conventions pour des sessions de programmation en binôme et en groupe efficaces.","de":"Perfekt für macOS-basierte Entwicklungssagenten, die eine Projektstrukturanalyse und eine Konventionserkennung für effiziente Pair- und Mob-Programmiersitzungen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento baseados em macOS que necessitam de análise de estrutura de projeto e detecção de convenções para sessões de programação em par e em multidão eficientes.","ru":"Идеально подходит для агентов разработки на основе macOS, которым необходим анализ структуры проекта и обнаружение соглашений для эффективных парных и групповых сессий программирования.","ar":"مثالي للوكلاء النمطية على أساس macOS التي تحتاج إلى تحليل هيكل المشروع والكشف عن الاتفاقيات للجلسات البرمجية الكفيلة والجماعية الفعالة."},"recommendation":{"en":"Empowers agents to analyze project structures, detect conventions, and generate project-specific information in .agents/PROJECT.md files, leveraging configuration files like package.json, Cargo.toml, and pyproject.toml.","zh":"赋予代理分析项目结构、检测规约并在.agents/PROJECT.md文件中生成特定于项目的信息的能力，利用诸如package.json、Cargo.toml和pyproject.toml的配置文件。","ja":"エージェントがプロジェクト構造を分析し、規約を検出し、.agents/PROJECT.mdファイルにプロジェクト固有の情報を生成する機能を提供することで、package.json、Cargo.toml、pyproject.tomlなどの構成ファイルを活用します。","ko":"에이전트가 프로젝트 구조를 분석하고 규약을 검색하며 .agents/PROJECT.md 파일에 프로젝트 특정 정보를 생성할 수 있는 기능을 제공하여 package.json, Cargo.toml 및 pyproject.toml 등의 구성 파일을 활용합니다.","es":"Habilita a los agentes a analizar estructuras de proyecto, detectar convenciones y generar información específica del proyecto en archivos .agents/PROJECT.md, aprovechando archivos de configuración como package.json, Cargo.toml y pyproject.toml.","fr":"Permet aux agents d''analyser les structures de projet, de détecter les conventions et de générer des informations spécifiques au projet dans les fichiers .agents/PROJECT.md, en exploitant des fichiers de configuration tels que package.json, Cargo.toml et pyproject.toml.","de":"Ermächtigt die Agenten, Projektstrukturen zu analysieren, Konventionen zu erkennen und projektspezifische Informationen in .agents/PROJECT.md-Dateien zu generieren, indem Konfigurationsdateien wie package.json, Cargo.toml und pyproject.toml genutzt werden.","pt":"Habilita os agentes a analisar estruturas de projeto, detectar convenções e gerar informações específicas do projeto em arquivos .agents/PROJECT.md, aproveitando arquivos de configuração como package.json, Cargo.toml e pyproject.toml.","ru":"Наделяет агентов возможностью анализировать структуры проектов, обнаруживать соглашения и генерировать информацию, специфичную для проекта, в файлах .agents/PROJECT.md, используя файлы конфигурации, такие как package.json, Cargo.toml и pyproject.toml.","ar":"يمنح الوكلاء القدرة على تحليل هياكل المشروع والكشف عن الاتفاقيات وتوليد المعلومات الخاصة بالمشروع في ملفات .agents/PROJECT.md، مستفيدا من ملفات التكوين مثل package.json و Cargo.toml و pyproject.toml."},"useCases":{"en":["Analyzing project structures for framework and library detection","Automating project configuration for mob programming sessions","Generating project-specific documentation in .agents/PROJECT.md"],"zh":["分析项目结构以检测框架和库","自动化项目配置以用于集体编程会话","在.agents/PROJECT.md中生成特定于项目的文档"],"ja":["フレームワークとライブラリの検出のためのプロジェクト構造の分析","モブプログラミングセッションのためのプロジェクト構成の自動化",".agents/PROJECT.mdにプロジェクト固有のドキュメントを生成する"],"ko":["프레임워크 및 라이브러리 감지를 위한 프로젝트 구조 분석","모브 프로그래밍 세션을 위한 프로젝트 구성 자동화",".agents/PROJECT.md에 프로젝트 특정 문서 생성"],"es":["Análisis de estructuras de proyecto para la detección de frameworks y bibliotecas","Automatización de la configuración del proyecto para sesiones de programación en multitud","Generación de documentación específica del proyecto en .agents/PROJECT.md"],"fr":["Analyse des structures de projet pour la détection de frameworks et de bibliothèques","Automatisation de la configuration du projet pour des sessions de programmation en groupe","Génération de documentation spécifique au projet dans .agents/PROJECT.md"],"de":["Analyse von Projektstrukturen für die Erkennung von Frameworks und Bibliotheken","Automatisierung der Projekt-Konfiguration für Mob-Programmiersitzungen","Generierung von projektspezifischer Dokumentation in .agents/PROJECT.md"],"pt":["Analisar estruturas de projeto para detecção de estrutura e biblioteca","Automatizar a configuração do projeto para sessões de programação em multidão","Gerar documentação específica do projeto em .agents/PROJECT.md"],"ru":["Анализировать структуры проектов для обнаружения фреймворка и библиотеки","Автоматизировать настройку проекта для групповых сессий программирования","Генерировать документацию, специфичную для проекта, в .agents/PROJECT.md"],"ar":["تحليل هياكل المشروع للكشف عن الإطار والكتابخانه","أتمتة تكوين المشروع للجلسات البرمجية الجماعية","توليد توثيق خاص بالمشروع في .agents/PROJECT.md"]},"limitations":{"en":["Requires macOS platform","Limited to projects with supported configuration files"],"zh":["需要macOS平台","仅限支持的配置文件的项目"],"ja":["macOSプラットフォームが必要","サポートされている構成ファイルを持つプロジェクトのみ"],"ko":["macOS 플랫폼이 필요","지원되는 구성 파일을 갖는 프로젝트만"],"es":["Requiere plataforma macOS","Limitado a proyectos con archivos de configuración compatibles"],"fr":["Nécessite la plate-forme macOS","Limité aux projets avec des fichiers de configuration pris en charge"],"de":["Benötigt macOS-Plattform","Begrenzt auf Projekte mit unterstützten Konfigurationsdateien"],"pt":["Requer plataforma macOS","Limitado a projetos com arquivos de configuração suportados"],"ru":["Требует платформы macOS","Ограничен проектами с поддерживаемыми файлами конфигурации"],"ar":["يتطلب منصة macOS","محدود بالمشاريع ذات ملفات التكوين المعتمدة"]},"version":4},"contentHash":"ee3dd268e177051bdcedc5569ef6bc1569a15eb08915647ea75205a348b5856a","qualityScore":57}');
