INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('colmarius/mobcrew/adapt', 'adapt', 'colmarius', 'mobcrew', 'community', 'adapt colmarius mobcrew community macos mob programming swiftui The adapt skill is a native macOS timer designed for pair and mob programming sessions, helping developers analyze project structures and detect conventions. It benefits developers working on macOS platforms. Adapt , macOS, Adapt AIエージェント, macOS, Adapt , macOS, Adapt es una herramienta de programación en pareja para macOS que analiza proyectos y configura información específica. Soporta tecnologías como SwiftUI. Adapt est un outil de programmation en binôme pour macOS qui analyse les projets et configure des informations spécifiques. Il prend en charge des technologies comme SwiftUI. Adapt ist ein Werkzeug für Paarprogrammierung auf macOS, das Projekte analysiert und projektspezifische Informationen konfiguriert. Es unterstützt Technologien wie SwiftUI. O Adapt é um companheiro de programação em macOS que analisa o projeto e preenche o arquivo .agents/PROJECT.md com informações específicas do projeto. ИИ Агент Adapt анализирует проект и заполняет файл .agents/PROJECT.md информацией, специфичной для проекта. أدابت هو رفيق برمجة macOS يanalyzes المشروع و يملأ ملف .agents/PROJECT.md بمعلومات محددة للمشروع. how to use adapt adapt setup guide macos mob programming timer adapt alternative adapt vs mob what is adapt adapt install mob programming companion adapt for SwiftUI developers adapt for pair programming Adapt AI macOS SwiftUI AI AI mob pair programming Analyzes project structure by scanning configuration files like package.json and Cargo.toml Detects frameworks, libraries, and tools in use, such as SwiftUI Fills in .agents/PROJECT.md with project-specific information Identifies existing scripts/commands in config files Supports customization of configuration for mob programming sessions adapt is a macOS-based AI agent skill that analyzes project structures, detects conventions, and customizes configurations for pair and mob programming sessions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('djaiss/journalOS/action-writer', 'community', 'djaiss', 'journalOS', 'djaiss/journalOS', 'action-writer', 2, 0, 57, '2026-02-17T12:51:05Z', '2026-03-06T13:08:04.705Z', '2c9c627971540ac737a06babdeeed4dfa30c2f543202270a1426d939cf94c306', '{"id":"djaiss/journalOS/action-writer","name":"action-writer","description":{"en":"The action-writer skill helps developers manage actions in JournalOS, a self-hosted personal journaling system. It streamlines the process of creating and updating actions using modular daily tracking.","zh":"Action Writer Skill 是用于创建和更新 JournalOS 项目中的 Action 类的工具，支持实现 execute() 方法和添加单元测试。","ja":"Action Writer スキルは、JournalOS プロジェクトの Action クラスを作成および更新するためのツールであり、execute() メソッドの実装とユニットテストの追加をサポートします。","ko":"Action Writer 스킬은 JournalOS 프로젝트의 Action 클래스를 생성 및 업데이트하는 데 사용되는 도구로 execute() 메서드의 구현과 유닛 테스트의 추가를 지원합니다.","es":"Action Writer es una habilidad que ayuda a agregar o actualizar acciones en JournalOS utilizando convenciones de proyecto","fr":"Action Writer est une compétence qui aide à ajouter ou à mettre à jour des actions dans JournalOS en utilisant des conventions de projet","de":"Action Writer ist eine Fähigkeit, die hilft, Aktionen in JournalOS unter Verwendung von Projektconventionen hinzuzufügen oder zu aktualisieren","pt":"O Action Writer é uma habilidade que ajuda a adicionar ou atualizar ações no JournalOS, um sistema de diário pessoal com acompanhamento modular.","ru":"Action Writer - это навык, который помогает добавлять или обновлять действия в JournalOS, системе личного дневника с модульным отслеживанием.","ar":"كاتب الإجراءات هو مهارة تساعد على إضافة أو تحديث الإجراءات في منصة JournalOS، نظام اليوميات الشخصي مع التتبع المودي"},"seo":{"title":{"en":"action-writer: Modular Action Management Setup Guide | AI...","zh":"Action Writer_SETUP GUIDE","ja":"Action Writer_BEST PRACTICES","ko":"Action Writer_SETUP TUTORIAL","es":"Guía de configuración de Action Writer para JournalOS","fr":"Guide d''installation d''Action Writer pour JournalOS","de":"Einrichtungsanleitung für Action Writer in JournalOS","pt":"Guia de Configuração do Action Writer para Desenvolvedores","ru":"Настройка ИИ Агента Action Writer: Руководство для Разраб...","ar":"دليل إعداد كاتب الإجراءات لمنصة JournalOS"},"description":{"en":"Discover how to efficiently create and update actions in JournalOS using the action-writer skill. Get started with our step-by-step guide and optimize your w...","zh":"使用 Action Writer Skill 创建和更新 JournalOS 项目中的 Action 类，实现 execute() 方法，并添加单元测试。","ja":"Action Writer スキルを使用して JournalOS プロジェクトの Action クラスを作成および更新し、execute() メソッドを実装し、ユニットテストを追加します。","ko":"Action Writer 스킬을 사용하여 JournalOS 프로젝트의 Action 클래스를 생성 및 업데이트하고 execute() 메서드를 구현하며 유닛 테스트를 추가합니다.","es":"Aprende a utilizar Action Writer para agregar o actualizar acciones en JournalOS con AlpineJS y Laravel","fr":"Découvrez comment utiliser Action Writer pour ajouter ou mettre à jour des actions dans JournalOS avec AlpineJS et Laravel","de":"Erfahren Sie, wie Sie Action Writer verwenden, um Aktionen in JournalOS mit AlpineJS und Laravel hinzuzufügen oder zu aktualisieren","pt":"Aprenda a usar o Action Writer para criar e atualizar ações no JournalOS com AlpineJS e Laravel","ru":"Используйте ИИ Агент Action Writer для создания и обновления действий в JournalOS с AlpineJS и Laravel","ar":"استخدم كاتب الإجراءات لإنشاء وتحديث الإجراءات في منصة JournalOS مع AlpineJS و Laravel"},"definition":{"en":"action-writer is a skill that assists in adding or updating actions in the app/Actions directory of JournalOS, following project conventions and utilizing technologies like AlpineJS and Laravel.","zh":"Action Writer Skill 是一种用于创建和更新 JournalOS 项目中的 Action 类的工具，用于实现 execute() 方法和添加单元测试。","ja":"Action Writer スキルは、JournalOS プロジェクトの Action クラスを作成および更新するためのツールであり、AIエージェントの一種です。","ko":"Action Writer 스킬은 JournalOS 프로젝트의 Action 클래스를 생성 및 업데이트하는 데 사용되는 도구로 AI 툴の一種입니다。","es":"Action Writer es una herramienta de AI que ayuda a los desarrolladores a crear y actualizar acciones en JournalOS","fr":"Action Writer est un outil d''IA qui aide les développeurs à créer et à mettre à jour des actions dans JournalOS","de":"Action Writer ist ein AI-Tool, das Entwicklern hilft, Aktionen in JournalOS zu erstellen und zu aktualisieren","pt":"O Action Writer é uma ferramenta que facilita a criação e atualização de ações no JournalOS","ru":"Action Writer - это инструмент, который упрощает создание и обновление действий в JournalOS","ar":"كاتب الإجراءات هو أداة تسهل إنشاء وتحديث الإجراءات في منصة JournalOS"},"features":{"en":["Creates and updates Action classes with implementable execute() methods","Supports unit testing in tests/Unit/Actions with composer journalos:unit command","Utilizes modular daily tracking for sleep, mood, work, health, and more","Integrates with JournalOS, a privacy-first and self-hosted personal journaling system","Follows project conventions for action naming and input/output types","Enables quick start with step-by-step instructions for action implementation"],"zh":["支持创建和更新 Action 类","实现 execute() 方法","添加单元测试","兼容 Laravel 和 AlpineJS","支持自托管的 JournalOS 项目"],"ja":["Action クラスの作成および更新をサポート","execute() メソッドの実装","ユニットテストの追加","Laravel と AlpineJS との互換性","自托管の JournalOS プロジェクトをサポート"],"ko":["Action 클래스의 생성 및 업데이트를 지원","execute() 메서드의 구현","유닛 테스트의 추가","Laravel 및 AlpineJS 와의 호환성","자체 호스팅의 JournalOS 프로젝트를 지원"],"es":["Creación de acciones con convenciones de proyecto","Actualización de acciones existentes en JournalOS","Implementación de la función execute() en la clase de acción","Uso de AlpineJS y Laravel para el desarrollo de acciones","Pruebas unitarias en tests/Unit/Actions","Ejecución de pruebas con composer journalos:unit"],"fr":["Création d''actions avec des conventions de projet","Mise à jour d''actions existantes dans JournalOS","Implémentation de la fonction execute() dans la classe d''action","Utilisation d''AlpineJS et Laravel pour le développement d''actions","Tests unitaires dans tests/Unit/Actions","Exécution de tests avec composer journalos:unit"],"de":["Erstellung von Aktionen mit Projektconventionen","Aktualisierung von bestehenden Aktionen in JournalOS","Implementierung der Funktion execute() in der Aktionklasse","Verwendung von AlpineJS und Laravel für die Entwicklung von Aktionen","Einheitliche Tests in tests/Unit/Actions","Ausführung von Tests mit composer journalos:unit"],"pt":["Criação de ações com verbos como nome","Implementação do método execute()","Adição de testes unitários em tests/Unit/Actions","Compatibilidade com AlpineJS e Laravel","Suporte a acompanhamento modular de diário pessoal"],"ru":["Создание действий с глаголами как имя","Реализация метода execute()","Добавление юнит-тестов в tests/Unit/Actions","Совместимость с AlpineJS и Laravel","Поддержка модульного отслеживания личного дневника"],"ar":["إنشاء إجراءات باسم الفعل","تنفيذ طريقة execute()","إضافة اختبارات الوحدة في tests/Unit/Actions","التكامل مع AlpineJS و Laravel","دعم التتبع المودي لليوميات الشخصية"]},"keywords":{"en":["how to use action-writer","action-writer setup guide","journalos action management","alpinejs and laravel integration","modular daily tracking","action-writer vs journalos","installing action-writer","what is action-writer","action-writer alternative","action-writer tutorial"],"zh":["Action Writer Skill","JournalOS 项目","Laravel","AlpineJS","自托管","AI工具","execute() 方法","单元测试"],"ja":["Action Writer スキル","JournalOS プロジェクト","Laravel","AlpineJS","自托管","AIエージェント","execute() メソッド","ユニットテスト"],"ko":["Action Writer 스킬","JournalOS 프로젝트","Laravel","AlpineJS","자체 호스팅","AI 툴","execute() 메서드","유닛 테스트"],"es":["Action Writer","JournalOS","AlpineJS","Laravel","desarrollo de acciones","pruebas unitarias","composer journalos:unit","herramientas de AI para desarrolladores","creación de acciones en JournalOS"],"fr":["Action Writer","JournalOS","AlpineJS","Laravel","développement d''actions","tests unitaires","composer journalos:unit","outils d''IA pour les développeurs","création d''actions dans JournalOS"],"de":["Action Writer","JournalOS","AlpineJS","Laravel","Entwicklung von Aktionen","Einheitliche Tests","composer journalos:unit","AI-Tools für Entwickler","Erstellung von Aktionen in JournalOS"],"pt":["Action Writer","JournalOS","AlpineJS","Laravel","desenvolvimento de software","criação de ações","atualização de ações","testes unitários","diário pessoal"],"ru":["Action Writer","JournalOS","AlpineJS","Laravel","разработка программного обеспечения","создание действий","обновление действий","юнит-тесты","личный дневник"],"ar":["كاتب الإجراءات","منصة JournalOS","AlpineJS","Laravel","تطوير البرمجيات","إنشاء إجراءات","تحديث الإجراءات","اختبارات الوحدة","اليوميات الشخصية"]}},"owner":"djaiss","repo":"journalOS","repoPath":"djaiss/journalOS","stars":2,"forks":0,"updatedAt":"2026-02-17T12:51:05Z","topics":["alpinejs","diary","journal","laravel","self-hosted"],"category":"community","skillMd":{"name":"action-writer","description":"Create or update an Action in app/Actions following JournalOS conventions (validation, logging, queues, tests).","bodyPreview":"# Action Writer\n\nThis Skill helps you add or update an Action in `app/Actions` using the project conventions.\n\n## When to use this Skill\n\nUse this Skill when:\n- Creating a new Action\n- Updating an existing Action\n\n## Instructions\n\n## Quick start\n\n- Pick the action name (verb-first) and its input/output types.\n- Create the Action class and implement `execute()`.\n- Add or update unit tests in `tests/Unit/Actions`.\n- Run the smallest relevant test(s), then `composer journalos:unit`.\n\n### Step 1: Ch","body":"# Action Writer\n\nThis Skill helps you add or update an Action in `app/Actions` using the project conventions.\n\n## When to use this Skill\n\nUse this Skill when:\n- Creating a new Action\n- Updating an existing Action\n\n## Instructions\n\n## Quick start\n\n- Pick the action name (verb-first) and its input/output types.\n- Create the Action class and implement `execute()`.\n- Add or update unit tests in `tests/Unit/Actions`.\n- Run the smallest relevant test(s), then `composer journalos:unit`.\n\n### Step 1: Choose the action name and scope\n\n1. Actions represent a single user intent (example: `LogHealth`, `CreateBook`, `ResetWorkData`).\n1. Keep inputs minimal and explicit. Use descriptive parameter names.\n1. Decide whether the Action returns a model, a scalar, or nothing (`void`).\n\n### Step 2: Create the Action class\n\n1. Use Artisan to create the class:\n\n```bash\nphp artisan make:class Actions/ActionName --no-interaction\n```\n\n1. Use `declare(strict_types=1);` and the `App\\Actions` namespace.\n1. Default to `final readonly class` with constructor property promotion.\n1. If the Action must store a result (ex: `$this->book`), keep it `final` but not `readonly`, and declare a private property for the result.\n1. Always include explicit return types.\n\n### Step 3: Implement the action flow\n\n1. Typical flow:\n   - validate input\n   - perform data changes\n   - log user action\n   - update last activity date\n   - refresh content presence (when journal entry content changes)\n1. Validate ownership with `ModelNotFoundException` when a user does not own a journal or entry.\n1. Validate input with `ValidationException::withMessages([...])` when values are invalid.\n1. Sanitize user-provided text with `TextSanitizer::plainText()`.\n1. Use Eloquent models and relationships. Avoid `DB::`.\n1. Queue background work on the `low` queue:\n\n```php\nLogUserAction::dispatch(...)->onQueue(''low'');\nUpdateUserLastActivityDate::dispatch($user)->onQueue(''low'');\nCheckPresenceOfContentInJournalEntry::dispatch($entry)->onQueue(''low'');\n```\n\n1. If the Action mutates a journal entry module, reload the relationship before returning:\n\n```php\n$this->entry->load(''moduleHealth'');\n```\n\n### Step 4: Add tests\n\n1. Create `tests/Unit/Actions/ActionNameTest.php`.\n1. Use `RefreshDatabase` and `Queue::fake()`.\n1. Use factories with explicit foreign keys. Never use `for()` on factories.\n1. Cover:\n   - happy path\n   - invalid input (throws `ValidationException`)\n   - unauthorized access (throws `ModelNotFoundException`)\n   - queued jobs on `low` queue\n\n### Step 5: Run tests and lint\n\n1. Run the smallest relevant test file:\n\n```bash\nphp artisan test tests/Unit/Actions/ActionNameTest.php\n```\n\n1. Run `composer journalos:unit`.\n1. Run Pint:\n\n```bash\nvendor/bin/pint --dirty\n```\n"},"lastSynced":"2026-03-06T13:08:04.705Z","agentAnalysis":{"suitability":{"en":"Perfect for JournalOS Agents needing streamlined action management and modular daily tracking.","zh":"非常适合需要简化操作管理和模块化日常跟踪的 JournalOS Agents。","ja":"JournalOS エージェントがストリームライン化されたアクション管理とモジュール化された日常追跡を必要とする場合に最適です。","ko":"JournalOS 에이전트가 스트림라인된 액션 관리와 모듈러한 일일 추적을 필요로 할 때 완벽합니다.","es":"Perfecto para agentes de JournalOS que necesitan una gestión de acciones optimizada y un seguimiento diario modular.","fr":"Parfait pour les agents JournalOS qui ont besoin d''une gestion d''actions rationalisée et d''un suivi quotidien modulaire.","de":"Perfekt für JournalOS-Agents, die eine optimierte Aktionenverwaltung und ein modulares Tages-tracking benötigen.","pt":"Perfeito para Agentes do JournalOS que precisam de gerenciamento de ações simplificado e acompanhamento diário modular.","ru":"Идеально для агентов JournalOS, которым требуется упрощенное управление действиями и модульное ежедневное отслеживание.","ar":"مثالي لعميل JournalOS الذين يحتاجون إلى إدارة إجراءات مبسطة وتعقب يومي معماري."},"recommendation":{"en":"Empowers agents to efficiently create and update actions in JournalOS using modular daily tracking, following project conventions and implementing the execute() method, while ensuring unit test coverage in tests/Unit/Actions.","zh":"赋予代理人在 JournalOS 中使用模块化日常跟踪高效创建和更新操作的能力，遵循项目约定并实现 execute() 方法，同时确保 tests/Unit/Actions 中的单元测试覆盖。","ja":"JournalOS でモジュール化された日常追跡を使用してアクションを作成および更新するためのエージェントの能力を与え、プロジェクト規約に従い、execute() メソッドを実装し、tests/Unit/Actions のユニットテストカバーを確保します。","ko":"JournalOS 에서 모듈러한 일일 추적을 사용하여 액션을 생성하고 업데이트하는 에이전트의 능력을 부여하여 프로젝트 규약을 따르고 execute() 메서드를 구현하며 tests/Unit/Actions의 유닛 테스트 커버리를 보장합니다.","es":"Habilita a los agentes a crear y actualizar acciones en JournalOS de manera eficiente, utilizando un seguimiento diario modular, siguiendo las convenciones del proyecto e implementando el método execute(), mientras garantiza la cobertura de las pruebas unitarias en tests/Unit/Actions.","fr":"Permet aux agents de créer et de mettre à jour des actions dans JournalOS de manière efficace, en utilisant un suivi quotidien modulaire, en suivant les conventions de projet et en mettant en œuvre la méthode execute(), tout en assurant la couverture des tests unitaires dans tests/Unit/Actions.","de":"Ermöglicht es den Agenten, Aktionen in JournalOS effizient zu erstellen und zu aktualisieren, indem sie ein modulares Tages-Tracking verwenden, den Projektkonventionen folgen und die execute()-Methode implementieren, während sie die Testabdeckung in tests/Unit/Actions sicherstellen.","pt":"Habilita os agentes a criar e atualizar ações de forma eficiente no JournalOS usando o acompanhamento diário modular, seguindo as convenções do projeto e implementando o método execute(), garantindo a cobertura de teste unitário em tests/Unit/Actions.","ru":"Позволяет агентам эффективно создавать и обновлять действия в JournalOS с помощью модульного ежедневного отслеживания, соблюдая проектные конвенции и реализуя метод execute(), обеспечивая покрытие юнит-тестов в tests/Unit/Actions.","ar":"يمنح العميل القدرة على إنشاء وتحديث الإجراءات بفعالية في JournalOS باستخدام التعقب اليومي المعماري ، متبعًا اتفاقيات المشروع وتنفيذ طريقة execute() ، مع ضمان تغطية اختبار الوحدة في tests/Unit/Actions."},"useCases":{"en":["Creating new actions with verb-first naming convention","Updating existing actions with input/output type validation","Implementing unit tests for actions in tests/Unit/Actions"],"zh":["使用动词优先命名约定创建新操作","使用输入/输出类型验证更新现有操作","在 tests/Unit/Actions 中为操作实现单元测试"],"ja":["動詞優先命名規約を使用して新しいアクションを作成する","入力/出力タイプの検証を使用して既存のアクションを更新する","tests/Unit/Actions でアクションのユニットテストを実装する"],"ko":["동사優先命名規約을 사용하여 새로운 액션을 생성하는 것","입력/출력 유형 검증을 사용하여 기존 액션을 업데이트하는 것","tests/Unit/Actions 에서 액션의 유닛 테스트를 구현하는 것"],"es":["Crear nuevas acciones con la convención de nomenclatura de verbo en primer lugar","Actualizar acciones existentes con validación de tipos de entrada/salida","Implementar pruebas unitarias para acciones en tests/Unit/Actions"],"fr":["Créer de nouvelles actions avec la convention de nommage verbe-premier","Mettre à jour des actions existantes avec une validation des types d''entrée/sortie","Mettre en œuvre des tests unitaires pour les actions dans tests/Unit/Actions"],"de":["Erstellen neuer Aktionen mit der Benennungskonvention Verb-erstes","Aktualisieren bestehender Aktionen mit Eingabe/Ausgabtyp-Validierung","Implementieren von Einheitstests für Aktionen in tests/Unit/Actions"],"pt":["Criar novas ações com convenção de nomenclatura verb-first","Atualizar ações existentes com validação de tipo de entrada/saída","Implementar testes unitários para ações em tests/Unit/Actions"],"ru":["Создание новых действий с соглашением об именовании verb-first","Обновление существующих действий с валидацией типа входных/выходных данных","Реализация юнит-тестов для действий в tests/Unit/Actions"],"ar":["إنشاء إجراءات جديدة مع اتفاقية تسمية verb-first","تحديث الإجراءات الحالية مع التحقق من نوع الإدخال/الإخراج","تنفيذ اختبارات الوحدة للإجراءات في tests/Unit/Actions"]},"limitations":{"en":["Requires JournalOS project setup","Verb-first action naming convention","Composer and unit test setup for JournalOS"],"zh":["需要 JournalOS 项目设置","动词优先操作命名约定","JournalOS 的 Composer 和单元测试设置"],"ja":["JournalOS プロジェクト設定が必要","動詞優先アクション命名規約","JournalOS の Composer とユニットテスト設定"],"ko":["JournalOS 프로젝트 설정이 필요합니다","동사優先 액션命名規約","JournalOS의 컴포저 및 유닛 테스트 설정"],"es":["Requiere configuración de proyecto JournalOS","Convención de nomenclatura de acción con verbo en primer lugar","Configuración del compositor y de las pruebas unitarias para JournalOS"],"fr":["Nécessite une configuration de projet JournalOS","Convention de nommage d''action avec verbe en premier","Configuration du compositeur et des tests unitaires pour JournalOS"],"de":["Benötigt JournalOS-Projektsetup","Aktionsbenennungskonvention mit Verb-erstes","Composer- und Einheitstest-Setup für JournalOS"],"pt":["Requer configuração do projeto JournalOS","Convenção de nomenclatura de ação verb-first","Configuração do Composer e teste unitário para JournalOS"],"ru":["Требует настройки проекта JournalOS","Соглашение об именовании действий verb-first","Настройка Composer и юнит-теста для JournalOS"],"ar":["يتطلب إعداد مشروع JournalOS","اتفاقية تسمية الإجراء verb-first","إعداد Composer واختبار الوحدة ل JournalOS"]},"version":4},"contentHash":"2c9c627971540ac737a06babdeeed4dfa30c2f543202270a1426d939cf94c306","qualityScore":57}');
