INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('djaiss/journalOS/action-writer', 'action-writer', 'djaiss', 'journalOS', 'community', 'action-writer djaiss journalOS community alpinejs diary journal laravel self-hosted The action-writer skill helps developers manage actions in JournalOS, a self-hosted personal journaling system. It streamlines the process of creating and updating actions using modular daily tracking. Action Writer Skill 是用于创建和更新 JournalOS 项目中的 Action 类的工具，支持实现 execute() 方法和添加单元测试。 Action Writer スキルは、JournalOS プロジェクトの Action クラスを作成および更新するためのツールであり、execute() メソッドの実装とユニットテストの追加をサポートします。 Action Writer 스킬은 JournalOS 프로젝트의 Action 클래스를 생성 및 업데이트하는 데 사용되는 도구로 execute() 메서드의 구현과 유닛 테스트의 추가를 지원합니다. Action Writer es una habilidad que ayuda a agregar o actualizar acciones en JournalOS utilizando convenciones de proyecto Action Writer est une compétence qui aide à ajouter ou à mettre à jour des actions dans JournalOS en utilisant des conventions de projet Action Writer ist eine Fähigkeit, die hilft, Aktionen in JournalOS unter Verwendung von Projektconventionen hinzuzufügen oder zu aktualisieren O Action Writer é uma habilidade que ajuda a adicionar ou atualizar ações no JournalOS, um sistema de diário pessoal com acompanhamento modular. Action Writer - это навык, который помогает добавлять или обновлять действия в JournalOS, системе личного дневника с модульным отслеживанием. كاتب الإجراءات هو مهارة تساعد على إضافة أو تحديث الإجراءات في منصة JournalOS، نظام اليوميات الشخصي مع التتبع المودي how to use action-writer action-writer setup guide journalos action management alpinejs and laravel integration modular daily tracking action-writer vs journalos installing action-writer what is action-writer action-writer alternative action-writer tutorial Action Writer Skill JournalOS 项目 Laravel AlpineJS 自托管 AI工具 execute() 方法 单元测试 Creates and updates Action classes with implementable execute() methods Supports unit testing in tests/Unit/Actions with composer journalos:unit command Utilizes modular daily tracking for sleep, mood, work, health, and more Integrates with JournalOS, a privacy-first and self-hosted personal journaling system Follows project conventions for action naming and input/output types Enables quick start with step-by-step instructions for action implementation action-writer is a skill that assists in adding or updating actions in the app/Actions directory of JournalOS, following project conventions and utilizing technologies like AlpineJS and Laravel.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LopeWale/dev_ignition/pm-audit', 'community', 'LopeWale', 'dev_ignition', 'LopeWale/dev_ignition', 'pm-audit', 1, 0, 57, '2026-02-21T01:23:21Z', '2026-03-06T07:09:56.707Z', '3883ea326ea84d7af48327b174f2c4f819241a33cc67df75bb851ddcf6e85763', '{"id":"LopeWale/dev_ignition/pm-audit","name":"pm-audit","description":{"en":"The pm-audit skill provides a web-based interface for managing Ignition development environments, offering version control, automation, and device management. It benefits developers and DevOps teams.","zh":"pm-audit 是一个全栈应用程序，用于管理 Ignition 开发环境，提供版本控制、环境管理、自动化网关配置等功能","ja":"pm-audit は Ignition 開発環境を管理するためのフルスタックアプリケーションで、バージョン管理、環境管理、自動化ゲートウェイ構成などを提供","ko":"pm-audit는 Ignition 개발 환경을 관리하는 풀스택 애플리케이션으로 버전 관리, 환경 관리, 자동화 게이트웨이 구성 등을 제공","es":"pm-audit es una aplicación de pila completa para provisionar y gestionar entornos de desarrollo de Ignition, con funcionalidades como control de versiones y gestión de entornos","fr":"pm-audit est une application full-stack pour provisionner et gérer des environnements de développement Ignition, avec des fonctionnalités telles que le contrôle de version et la gestion d''environnement","de":"pm-audit ist eine Full-Stack-Anwendung zum Provisionieren und Verwalten von Ignition-Entwicklungsumgebungen, mit Funktionen wie Versionskontrolle und Umgebungsverwaltung","pt":"O pm-audit é uma ferramenta de auditoria de ambientes de desenvolvimento que fornece uma interface web para controle de versão, gerenciamento de ambientes e automação de gateway","ru":"pm-audit - это инструмент для аудита сред разработки, который обеспечивает веб-интерфейс для контроля версий, управления средами и автоматизации шлюза с помощью ИИ Агентов","ar":"pm-audit هو أداة لتدقيق بيئات التطوير توفر واجهة ويب للتحكم في الإصدار و إدارة البيئات و تautomatization البوابة بال代理ات الذكية"},"seo":{"title":{"en":"pm-audit: Full-Stack Environment Management Setup Guide |...","zh":"pm-audit Setup Guide: Ignition 开发环境管理","ja":"pm-audit セットアップガイド: Ignition 開発環境管理","ko":"pm-audit 설정 가이드: Ignition 개발 환경 관리","es":"Guía de configuración de pm-audit para entornos de desarr...","fr":"Guide de configuration de pm-audit pour les environnement...","de":"Konfigurationsleitfaden für pm-audit in Ignition-Entwickl...","pt":"Guia de Configuração pm-audit: Ferramenta de Auditoria de...","ru":"Настройка pm-audit: Инструмент для аудита сред разработки...","ar":"دليل إعداد pm-audit: أداة لتدقيق بيئات التطوير بال代理ات ال..."},"description":{"en":"Discover how pm-audit streamlines Ignition development environments with automated gateway configuration and real-time terminal access - get started now!","zh":"使用 pm-audit 管理 Ignition 开发环境，实现版本控制、环境管理、自动化网关配置等","ja":"pm-audit を使用して Ignition 開発環境を管理し、バージョン管理、環境管理、自動化ゲートウェイ構成などを実現","ko":"pm-audit를 사용하여 Ignition 개발 환경을 관리하고 버전 관리, 환경 관리, 자동화 게이트웨이 구성 등을 구현","es":"Descubre cómo configurar pm-audit para provisionar y gestionar entornos de desarrollo de Ignition con versiones de control, gestión de entornos y más","fr":"Découvrez comment configurer pm-audit pour provisionner et gérer des environnements de développement Ignition avec contrôle de version, gestion d''environneme...","de":"Erfahren Sie, wie Sie pm-audit konfigurieren, um Ignition-Entwicklungsumgebungen mit Versionskontrolle, Umgebungsverwaltung und mehr zu provisionieren und zu...","pt":"Aprenda a configurar o pm-audit, uma ferramenta de auditoria de ambientes de desenvolvimento para provisionar e gerenciar ambientes de desenvolvimento Ignition","ru":"Узнайте, как настроить pm-audit, инструмент для аудита сред разработки для обеспечения и управления средами разработки Ignition с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد pm-audit، أداة لتدقيق بيئات التطوير لتزويد و إدارة بيئات التطوير Ignition بال代理ات الذكية"},"definition":{"en":"pm-audit is a full-stack application for provisioning and managing Ignition development environments, providing features like environment management and automation gateway configuration.","zh":"pm-audit 是一种用于管理 Ignition 开发环境的 AI 工具","ja":"pm-audit は Ignition 開発環境を管理するための AI エージェント","ko":"pm-audit는 Ignition 개발 환경을 관리하는 AI 툴","es":"pm-audit es una herramienta de desarrollo que permite la gestión y provisionamiento de entornos de desarrollo de Ignition","fr":"pm-audit est un outil de développement qui permet la gestion et la provision de environnements de développement Ignition","de":"pm-audit ist ein Entwicklungstool, das die Verwaltung und Bereitstellung von Ignition-Entwicklungsumgebungen ermöglicht","pt":"O pm-audit é uma ferramenta de auditoria de ambientes de desenvolvimento que auxilia na configuração e gerenciamento de ambientes Ignition","ru":"pm-audit - это инструмент для аудита сред разработки, который помогает в настройке и управлении средами разработки Ignition с помощью ИИ Агентов","ar":"pm-audit هو أداة لتدقيق بيئات التطوير التي تساعد في إعداد و إدارة بيئات التطوير Ignition بال代理ات الذكية"},"features":{"en":["Provides web-based interface for version control and environment management","Supports automation gateway configuration and device management","Offers Vision client testing with QF-Test automation","Enables real-time terminal access to containers via WebSkt","Allows for runtime configuration and parsing of arguments for custom audits","Performs audits with options for checking orphans, links, schema, and registers"],"zh":["版本控制","环境管理","自动化网关配置","设备管理","Vision 客户端测试","实时终端访问"],"ja":["バージョン管理","環境管理","自動化ゲートウェイ構成","デバイス管理","Vision クライアントテスト","リアルタイムターミナルアクセス"],"ko":["버전 관리","환경 관리","자동화 게이트웨이 구성","디바이스 관리","Vision 클라이언트 테스트","실시간 터미널 액세스"],"es":["Control de versiones para entornos de desarrollo de Ignition","Gestión de entornos con funcionalidades de automatización","Configuración de puertas de enlace de automatización","Gestión de dispositivos y clientes de Vision","Pruebas de clientes de Vision con QF-Test","Monitoreo de la salud de la puerta de enlace en tiempo real"],"fr":["Contrôle de version pour les environnements de développement Ignition","Gestion d''environnement avec des fonctionnalités d''automatisation","Configuration des passerelles d''automatisation","Gestion des appareils et des clients Vision","Tests des clients Vision avec QF-Test","Surveillance de la santé de la passerelle en temps réel"],"de":["Versionskontrolle für Ignition-Entwicklungsumgebungen","Umgebungsverwaltung mit Automatisierungsfunktionen","Konfiguration von Automatisierungsgateways","Geräte- und Vision-Client-Verwaltung","Vision-Client-Tests mit QF-Test","Echtzeit-Überwachung der Gateway-Gesundheit"],"pt":["Interface web para controle de versão","Gerenciamento de ambientes de desenvolvimento","Automação de gateway de configuração","Monitoramento de saúde do gateway","Acesso a terminais em tempo real via WebSkt"],"ru":["Веб-интерфейс для контроля версий","Управление средами разработки","Автоматизация настройки шлюза","Мониторинг состояния шлюза","Доступ к терминалам в реальном времени через WebSkt с помощью ИИ Агентов"],"ar":["واجهة ويب للتحكم في الإصدار","إدارة بيئات التطوير","تأتمتية إعداد البوابة","مراقبة حالة البوابة","الدخول إلى المحطات في الوقت الفعلي عبر WebSkt بال代理ات الذكية"]},"keywords":{"en":["how to use pm-audit","pm-audit setup guide","Ignition development environment management","automation gateway configuration","pm-audit alternative","pm-audit vs competitors","pm-audit install","full-stack environment management","web-based interface for version control","QF-Test automation"],"zh":["Ignition 开发环境管理","AI 工具","版本控制","环境管理","自动化网关配置","设备管理","Vision 客户端测试","实时终端访问"],"ja":["Ignition 開発環境管理","AI エージェント","バージョン管理","環境管理","自動化ゲートウェイ構成","デバイス管理","Vision クライアントテスト","リアルタイムターミナルアクセス"],"ko":["Ignition 개발 환경 관리","AI 툴","버전 관리","환경 관리","자동화 게이트웨이 구성","디바이스 관리","Vision 클라이언트 테스트","실시간 터미널 액세스"],"es":["pm-audit","entornos de desarrollo de Ignition","control de versiones","gestión de entornos","automatización de puertas de enlace","pruebas de clientes de Vision","monitoreo de salud de puerta de enlace","herramientas de desarrollo de AI","agentes de IA para desarrollo"],"fr":["pm-audit","environnements de développement Ignition","contrôle de version","gestion d''environnement","automatisation de passerelles","tests de clients Vision","surveillance de la santé de la passerelle","outils de développement d''IA","agents d''IA pour le développement"],"de":["pm-audit","Ignition-Entwicklungsumgebungen","Versionskontrolle","Umgebungsverwaltung","Automatisierung von Gateways","Vision-Client-Tests","Überwachung der Gateway-Gesundheit","Entwicklungstools für KI","KI-Agents für die Entwicklung"],"pt":["pm-audit","ferramenta de auditoria","ambientes de desenvolvimento","Ignition","controle de versão","gerenciamento de ambientes","automação de gateway"],"ru":["pm-audit","инструмент для аудита","среды разработки","Ignition","контроль версий","управление средами","автоматизация настройки шлюза","ИИ Агенты"],"ar":["pm-audit","أداة لتدقيق","بيئات التطوير","Ignition","التحكم في الإصدار","إدارة البيئات","تأتمتية إعداد البوابة","ال代理ات الذكية"]}},"owner":"LopeWale","repo":"dev_ignition","repoPath":"LopeWale/dev_ignition","stars":1,"forks":0,"updatedAt":"2026-02-21T01:23:21Z","topics":[],"category":"community","skillMd":{"name":"pm-audit","description":"System-wide structural audit of the entire PM knowledge system. Checks orphans, broken links, register coverage, schema violations across all decisions, and vault health metrics. Slower and deeper than /pm-review. Triggers on /pm-audit, system audit, vault health, find orphans, check broken links.","bodyPreview":"## Runtime Configuration (Step 0)\n\nRead `ops/derivation-manifest.md` for vocabulary mapping.\nRead `ops/config.yaml` for all maintenance thresholds.\n\n---\n\n## EXECUTE NOW\n\n**Target: $ARGUMENTS**\n\nParse immediately:\n- If empty: run full audit (all checks)\n- If \"orphans\": find orphan decisions only\n- If \"links\": check broken wiki-links only\n- If \"schema\": validate schema compliance across all decisions\n- If \"registers\": audit decision register coverage and completeness\n\n**START NOW.**\n\n---\n\n## Philo","body":"## Runtime Configuration (Step 0)\n\nRead `ops/derivation-manifest.md` for vocabulary mapping.\nRead `ops/config.yaml` for all maintenance thresholds.\n\n---\n\n## EXECUTE NOW\n\n**Target: $ARGUMENTS**\n\nParse immediately:\n- If empty: run full audit (all checks)\n- If \"orphans\": find orphan decisions only\n- If \"links\": check broken wiki-links only\n- If \"schema\": validate schema compliance across all decisions\n- If \"registers\": audit decision register coverage and completeness\n\n**START NOW.**\n\n---\n\n## Philosophy\n\n**A knowledge system that cannot audit itself will rot.**\n\nIndividual /pm-review checks decisions for quality. /pm-audit checks the system for structural integrity. These are different problems. A system can contain individually high-quality decisions that are nevertheless disconnected, uncategorized, and inaccessible — effectively invisible to future coordination.\n\n/pm-audit is the health scan. It finds the issues that individual review misses: decisions no register points to, wiki-links to files that were deleted or renamed, registers that grew too large to navigate, schema drift where fields added in new templates haven''t been backfilled into old decisions.\n\nRun /pm-audit when the vault feels slow or when coordination starts feeling inefficient — that inefficiency often has a structural cause.\n\n---\n\n## Audit Checks\n\n### Check 1: Orphan Decisions\n\nA decision not referenced by any decision register is an orphan. Orphans exist in the vault but cannot be discovered through normal navigation.\n\n```bash\n# Get all decision filenames\nls decisions/*.md | grep -v \"index.md\" | grep -v \"-register.md\"\n\n# For each decision, check if it appears in any register\nfor f in decisions/*.md; do\n  basename=$(basename \"$f\" .md)\n  count=$(rg \"$basename\" decisions/*-register.md decisions/index.md --count 2>/dev/null | grep -v \":0\" | wc -l)\n  if [ \"$count\" -eq 0 ]; then\n    echo \"ORPHAN: $basename\"\n  fi\ndone\n```\n\n### Check 2: Broken Wiki-Links\n\nWiki-links pointing to non-existent files.\n\n```bash\n# Extract all [[links]] from decisions/\nrg \"\\[\\[([^\\]]+)\\]\\]\" decisions/ --include=\"*.md\" -o --no-filename | sort -u\n\n# Cross-reference against actual files\n# Flag any [[link]] where the target file doesn''t exist\n```\n\n### Check 3: Schema Violations\n\n```bash\n# Missing required fields\nrg \"^description: \\\"\\\"\" decisions/ --include=\"*.md\" -l\nrg \"last_reviewed: YYYY-MM-DD\" decisions/ --include=\"*.md\" -l\nrg \"^type: $\" decisions/ --include=\"*.md\" -l\n\n# Invalid enum values\nrg \"^type:\" decisions/ --include=\"*.md\" -h | sort | uniq -c | sort -rn\nrg \"^status:\" decisions/ --include=\"*.md\" -h | sort | uniq -c | sort -rn\nrg \"^meta_state:\" decisions/ --include=\"*.md\" -h | sort | uniq -c | sort -rn\n```\n\n### Check 4: Register Size and Coverage\n\n```bash\n# Count decisions in each register\nfor f in decisions/*-register.md; do\n  count=$(rg \"\\[\\[\" \"$f\" | wc -l)\n  echo \"$f: $count references\"\ndone\n\n# Check for registers approaching the split threshold (35 decisions)\n```\n\nRegisters approaching 35 decisions should be flagged for split consideration.\n\n### Check 5: Stale Decisions\n\n```bash\n# Find decisions by last_reviewed date\n# Flag any older than stale_issue_days from config.yaml\nrg \"^last_reviewed:\" decisions/ --include=\"*.md\" -h | sort | head -20\n```\n\n### Check 6: Pending Observations and Tensions Backlog\n\n```bash\n# Count pending observations\nrg \"^status: pending\" ops/observations/ --include=\"*.md\" -l | wc -l\n\n# Count pending tensions\nrg \"^status: pending\" ops/tensions/ --include=\"*.md\" -l | wc -l\n```\n\nIf pending observations > threshold (from config.yaml), flag for /pm-retrospect.\nIf pending tensions > threshold, flag for /pm-retrospect.\n\n### Check 7: Inbox Pressure\n\n```bash\nls inbox/ | wc -l\n```\n\nIf inbox has items, flag for /pm-document processing.\n\n---\n\n## Output Format\n\n```\n## Audit Complete — YYYY-MM-DD\n\n### System Metrics\n- Total decisions: N\n- Total decision registers: N\n- Total observations (pending/total): N/N\n- Total tensions (pending/total): N/N\n- Inbox items awaiting processing: N\n\n### Check 1: Orphan Decisions\n- Orphans found: N\n- [[decision-a]], [[decision-b]] — not referenced by any register\n\n### Check 2: Broken Wiki-Links\n- Broken links found: N\n- In [[decision-x]]: [[nonexistent-decision]] — target file missing\n\n### Check 3: Schema Violations\n- Violations found: N\n- [[decision-y]] — missing last_reviewed date\n- [[decision-z]] — description is empty\n\n### Check 4: Register Coverage\n- [[qftest-register]]: 12 decisions (healthy)\n- [[architecture-register]]: 28 decisions (approaching split threshold — flag)\n- [[sprint-register]]: 5 decisions (healthy)\n\n### Check 5: Stale Decisions\n- Stale decisions (>14 days): N\n- [[decision-a]] — last reviewed 21 days ago\n\n### Check 6: Pending Backlog\n- Pending observations: N [TRIGGER: /pm-retrospect] if > threshold\n- Pending tensions: N [TRIGGER: /pm-retrospect] if > threshold\n\n### Check 7: Inbox\n- Inbox items: N [TRIGGER: /pm-document] if > 0\n\n---\n\n### Priority Actions\n1. [CRITICAL] Fix N orphan decisions — assign to registers\n2. [HIGH] Process N pending observations — run /pm-retrospect\n3. [MEDIUM] Update N stale decisions\n4. [LOW] Review N schema violations\n\n### Vault Health Score: N/100\n[Breakdown: orphans -Xpts, schema violations -Xpts, stale decisions -Xpts, broken links -Xpts]\n```\n\n---\n\n## Vault Health Scoring\n\n| Issue | Penalty per instance |\n|-------|---------------------|\n| Orphan decision | -3 pts |\n| Broken wiki-link | -2 pts |\n| Schema violation | -2 pts |\n| Stale decision (>14 days) | -1 pt |\n| Pending observation >threshold | -5 pts flat |\n| Pending tension >threshold | -5 pts flat |\n\nStarting from 100. Report final score.\n"},"lastSynced":"2026-03-06T07:09:56.707Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing comprehensive content analysis and audit capabilities for Ignition development environments.","zh":"非常适合需要对 Ignition 开发环境进行全面内容分析和审计功能的开发代理。","ja":"Ignition 開発環境の包括的なコンテンツ分析および監査機能を必要とする開発エージェントに最適です。","ko":"Ignition 개발 환경에 대한 포괄적인 내용 분석 및 감사 기능이 필요한 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan un análisis y capacidades de auditoría de contenido integral para entornos de desarrollo de Ignition.","fr":"Parfait pour les agents de développement ayant besoin d''une analyse et de capacités d''audit de contenu complet pour les environnements de développement Ignition.","de":"Perfekt für Entwicklungsmittel, die eine umfassende Inhaltsanalyse und Auditfunktionen für Ignition-Entwicklungsumgebungen benötigen.","pt":"Perfeito para agentes de desenvolvimento que necessitam de análise e capacidades de auditoria abrangentes para ambientes de desenvolvimento Ignition.","ru":"Идеально подходит для агентов разработки, которым необходимы всесторонние возможности анализа контента и аудита для сред разработки Ignition.","ar":"مثالي لوسائل Entwicklung التي تحتاج إلى تحليل محتوى شامل وقدرات تدقيق لبيئات التطوير Ignition."},"recommendation":{"en":"Empowers agents to perform automated audits, validate schema compliance, and manage device configurations using version control and automation, leveraging configuration files like ''ops/config.yaml'' and ''ops/derivation-manifest.md''.","zh":"赋予代理执行自动化审计、验证模式合规性、并使用版本控制和自动化管理设备配置的能力，利用诸如 ''ops/config.yaml'' 和 ''ops/derivation-manifest.md'' 的配置文件。","ja":"エージェントが自動化された監査を実行し、スキーマの準拠を検証し、バージョン管理と自動化を使用してデバイス構成を管理する機能を提供することで、''ops/config.yaml'' や ''ops/derivation-manifest.md'' などの構成ファイルを活用します。","ko":"에이전트가 자동화된 감사를 수행하고 스키마 준수를 검증하며 버전 관리 및 자동화를 사용하여 디바이스 구성을 관리할 수 있는 기능을 제공하여 ''ops/config.yaml'' 및 ''ops/derivation-manifest.md''와 같은 구성 파일을 활용합니다.","es":"Habilita a los agentes a realizar auditorías automatizadas, validar la conformidad del esquema y gestionar configuraciones de dispositivos utilizando control de versiones y automatización, aprovechando archivos de configuración como ''ops/config.yaml'' y ''ops/derivation-manifest.md''.","fr":"Permet aux agents d''effectuer des audits automatisés, de valider la conformité du schéma et de gérer les configurations des appareils en utilisant le contrôle de version et l''automatisation, en exploitant des fichiers de configuration tels que ''ops/config.yaml'' et ''ops/derivation-manifest.md''.","de":"Ermächtigt Agenten, automatisierte Audits durchzuführen, die Schema-Konformität zu überprüfen und Gerätekonfigurationen mithilfe von Versionskontrolle und Automatisierung zu verwalten, indem Konfigurationsdateien wie ''ops/config.yaml'' und ''ops/derivation-manifest.md'' genutzt werden.","pt":"Habilita os agentes a realizar auditorias automatizadas, validar conformidade de esquema e gerenciar configurações de dispositivos usando controle de versão e automação, aproveitando arquivos de configuração como ''ops/config.yaml'' e ''ops/derivation-manifest.md''.","ru":"Наделяет агентов возможностью выполнять автоматические аудиты, проверять соответствие схемы и управлять конфигурациями устройств с помощью контроля версий и автоматизации, используя файлы конфигурации, такие как ''ops/config.yaml'' и ''ops/derivation-manifest.md''.","ar":"يمنح الوكلاء القدرة على إجراء عمليات تدقيق آلية، و التحقق من مطابقة مخطط و إدارة تكوينات الأجهزة باستخدام التحكم في الإصدار و الأتمتة، و باستخدام ملفات التكوين مثل ''ops/config.yaml'' و ''ops/derivation-manifest.md''."},"useCases":{"en":["Automating full audits for Ignition development environments","Identifying orphan decisions and broken wiki-links","Validating schema compliance across all decisions","Auditing decision register coverage and completeness"],"zh":["为 Ignition 开发环境自动化执行全面审计","识别孤立决定和破损 wiki 链接","验证所有决定的模式合规性","审计决定注册的覆盖范围和完整性"],"ja":["Ignition 開発環境の完全な監査を自動化する","孤立した決定と破損した Wiki リンクを特定する","すべての決定のスキーマの準拠を検証する","決定の登録範囲と完全性を監査する"],"ko":["Ignition 개발 환경에 대한 전체 감사를 자동화한다.","고아 결정 및 깨진 위키 링크를 식별한다.","모든 결정에 대한 스키마 준수를 검증한다.","결정 등록 범위 및 완전성을 감사한다."],"es":["Automatizar auditorías completas para entornos de desarrollo de Ignition","Identificar decisiones huérfanas y vínculos de wiki rotos","Validar la conformidad del esquema en todas las decisiones","Auditar la cobertura y la completitud del registro de decisiones"],"fr":["Automatiser les audits complets pour les environnements de développement Ignition","Identifier les décisions orphelines et les liens wiki cassés","Valider la conformité du schéma pour toutes les décisions","Auditer la couverture et l''exhaustivité de l''enregistrement des décisions"],"de":["Automatisieren von vollständigen Audits für Ignition-Entwicklungsumgebungen","Identifizieren von Waisenentscheidungen und gebrochenen Wiki-Links","Überprüfen der Schema-Konformität für alle Entscheidungen","Prüfen der Abdeckung und Vollständigkeit des Entscheidungsregisters"],"pt":["Automatizar auditorias completas para ambientes de desenvolvimento Ignition","Identificar decisões órfãs e links wiki quebrados","Validar conformidade de esquema em todas as decisões","Auditar cobertura e completude do registro de decisões"],"ru":["Автоматизировать полные аудиты для сред разработки Ignition","Определить сиротские решения и сломанные ссылки wiki","Проверить соответствие схемы во всех решениях","Провести аудит покрытия и полноты реестра решений"],"ar":["تأتمتة عمليات التدقيق الكاملة لبيئات التطوير Ignition","تحديد القرارات اليتمية و الروابط المنكوسة wiki","التحقق من مطابقة مخطط في جميع القرارات","تدقيق تغطية و اكتمال سجل القرارات"]},"limitations":{"en":["Requires access to ''ops/derivation-manifest.md'' and ''ops/config.yaml'' files","Specific to Ignition development environments"],"zh":["需要访问 ''ops/derivation-manifest.md'' 和 ''ops/config.yaml'' 文件","仅限于 Ignition 开发环境"],"ja":["''ops/derivation-manifest.md'' および ''ops/config.yaml'' ファイルにアクセスする必要がある","Ignition 開発環境に限定される"],"ko":["''ops/derivation-manifest.md'' 및 ''ops/config.yaml'' 파일에 액세스해야 한다.","Ignition 개발 환경으로 제한된다."],"es":["Requiere acceso a los archivos ''ops/derivation-manifest.md'' y ''ops/config.yaml''","Específico para entornos de desarrollo de Ignition"],"fr":["Nécessite l''accès aux fichiers ''ops/derivation-manifest.md'' et ''ops/config.yaml''","Spécifique aux environnements de développement Ignition"],"de":["Benötigt Zugriff auf die Dateien ''ops/derivation-manifest.md'' und ''ops/config.yaml''","Spezifisch für Ignition-Entwicklungsumgebungen"],"pt":["Requer acesso aos arquivos ''ops/derivation-manifest.md'' e ''ops/config.yaml''","Específico para ambientes de desenvolvimento Ignition"],"ru":["Требует доступа к файлам ''ops/derivation-manifest.md'' и ''ops/config.yaml''","Конкретно для сред разработки Ignition"],"ar":["يتطلب الوصول إلى الملفات ''ops/derivation-manifest.md'' و ''ops/config.yaml''","محدد لبيئات التطوير Ignition"]},"version":4},"contentHash":"3883ea326ea84d7af48327b174f2c4f819241a33cc67df75bb851ddcf6e85763","qualityScore":57}');
