INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('LopeWale/dev_ignition/pm-audit', 'pm-audit', 'LopeWale', 'dev_ignition', 'community', 'pm-audit LopeWale dev_ignition community The pm-audit skill provides a web-based interface for managing Ignition development environments, offering version control, automation, and device management. It benefits developers and DevOps teams. pm-audit 是一个全栈应用程序，用于管理 Ignition 开发环境，提供版本控制、环境管理、自动化网关配置等功能 pm-audit は Ignition 開発環境を管理するためのフルスタックアプリケーションで、バージョン管理、環境管理、自動化ゲートウェイ構成などを提供 pm-audit는 Ignition 개발 환경을 관리하는 풀스택 애플리케이션으로 버전 관리, 환경 관리, 자동화 게이트웨이 구성 등을 제공 pm-audit es una aplicación de pila completa para provisionar y gestionar entornos de desarrollo de Ignition, con funcionalidades como control de versiones y gestión de entornos pm-audit est une application full-stack pour provisionner et gérer des environnements de développement Ignition, avec des fonctionnalités telles que le contrôle de version et la gestion d''environnement pm-audit ist eine Full-Stack-Anwendung zum Provisionieren und Verwalten von Ignition-Entwicklungsumgebungen, mit Funktionen wie Versionskontrolle und Umgebungsverwaltung O pm-audit é uma ferramenta de auditoria de ambientes de desenvolvimento que fornece uma interface web para controle de versão, gerenciamento de ambientes e automação de gateway pm-audit - это инструмент для аудита сред разработки, который обеспечивает веб-интерфейс для контроля версий, управления средами и автоматизации шлюза с помощью ИИ Агентов pm-audit هو أداة لتدقيق بيئات التطوير توفر واجهة ويب للتحكم في الإصدار و إدارة البيئات و تautomatization البوابة بال代理ات الذكية how to use pm-audit pm-audit setup guide Ignition development environment management automation gateway configuration pm-audit alternative pm-audit vs competitors pm-audit install full-stack environment management web-based interface for version control QF-Test automation Ignition 开发环境管理 AI 工具 版本控制 环境管理 自动化网关配置 设备管理 Vision 客户端测试 实时终端访问 Provides web-based interface for version control and environment management Supports automation gateway configuration and device management Offers Vision client testing with QF-Test automation Enables real-time terminal access to containers via WebSkt Allows for runtime configuration and parsing of arguments for custom audits Performs audits with options for checking orphans, links, schema, and registers pm-audit is a full-stack application for provisioning and managing Ignition development environments, providing features like environment management and automation gateway configuration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DarkMonkDev/WitchCityRope/restart-dev-containers', 'community', 'DarkMonkDev', 'WitchCityRope', 'DarkMonkDev/WitchCityRope', 'restart-dev-containers', 1, 1, 57, '2026-02-24T06:06:45Z', '2026-03-06T07:11:30.988Z', '50316dd7e2dce79a472604e49dfed13b6948f61c19bb2a1caead9b681030a48e', '{"id":"DarkMonkDev/WitchCityRope/restart-dev-containers","name":"restart-dev-containers","description":{"en":"The restart-dev-containers skill restarts Docker development containers correctly, ideal for developers needing to rebuild containers after code changes or fix unhealthy containers.","zh":"restart-dev-containers AIエージェント用于重启Docker开发容器，解决代码更改和编译错误的问题","ja":"restart-dev-containers AIエージェントは、Docker開発コンテナの再起動とコンパイルエラーの解決を支援します","ko":"restart-dev-containers AI 에이전트는 Docker 개발 컨테이너의 재시작과 컴파일 에러 해결을 지원합니다","es":"El skill ''restart-dev-containers'' reinicia los contenedores de desarrollo de Docker de manera correcta, ideal para después de cambios de código o cuando los contenedores no están sanos","fr":"Le skill ''restart-dev-containers'' redémarre les conteneurs de développement Docker de manière correcte, idéal après des changements de code ou lorsque les conteneurs ne sont pas sains","de":"Der Skill ''restart-dev-containers'' startet Docker-Entwicklungscontainer auf die richtige Weise neu, ideal nach Codeänderungen oder wenn die Container nicht gesund sind","pt":"O agente restart-dev-containers é uma ferramenta de IA que ajuda a reiniciar contêineres de desenvolvimento de forma eficaz. Ele é projetado para ser usado após alterações de código que necessitam de reconstrução de contêineres","ru":"ИИ агент restart-dev-containers - это инструмент, который помогает перезапустить контейнеры разработки правильным образом. Он предназначен для использования после изменений кода, требующих пересборки контейнеров","ar":"وكيل الذكاء الاصطن