INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DarkMonkDev/WitchCityRope/restart-dev-containers', 'restart-dev-containers', 'DarkMonkDev', 'WitchCityRope', 'community', 'restart-dev-containers DarkMonkDev WitchCityRope community The restart-dev-containers skill restarts Docker development containers correctly, ideal for developers needing to rebuild containers after code changes or fix unhealthy containers. restart-dev-containers AIエージェント用于重启Docker开发容器，解决代码更改和编译错误的问题 restart-dev-containers AIエージェントは、Docker開発コンテナの再起動とコンパイルエラーの解決を支援します restart-dev-containers AI 에이전트는 Docker 개발 컨테이너의 재시작과 컴파일 에러 해결을 지원합니다 El skill ''restart-dev-containers'' reinicia los contenedores de desarrollo de Docker de manera correcta, ideal para después de cambios de código o cuando los contenedores no están sanos Le skill ''restart-dev-containers'' redémarre les conteneurs de développement Docker de manière correcte, idéal après des changements de code ou lorsque les conteneurs ne sont pas sains Der Skill ''restart-dev-containers'' startet Docker-Entwicklungscontainer auf die richtige Weise neu, ideal nach Codeänderungen oder wenn die Container nicht gesund sind O agente restart-dev-containers é uma ferramenta de IA que ajuda a reiniciar contêineres de desenvolvimento de forma eficaz. Ele é projetado para ser usado após alterações de código que necessitam de reconstrução de contêineres ИИ агент restart-dev-containers - это инструмент, который помогает перезапустить контейнеры разработки правильным образом. Он предназначен для использования после изменений кода, требующих пересборки контейнеров وكيل الذكاء الاصطناعي restart-dev-containers هو أداة تساعد على إعادة تشغيل حاويات التطوير بطريقة فعالة. تم تصميمه للاستخدام بعد تغييرات في الكود التي تحتاج إلى إعادة بناء الحاويات how to use restart-dev-containers restart-dev-containers setup guide docker development container restart restart-dev-containers vs restart-test-containers restart-dev-containers install docker container restart best practices restart-dev-containers AIエージェント Docker开发容器 代码更改 编译错误 Element not found错误 容器管理 开发环境 Restarts Docker development containers after code changes Resolves issues with unhealthy dev containers Fixes ''Element not found'' errors in dev testing Used in conjunction with ''restart-test-containers'' skill for test containers Rebuilds containers to reflect updated code restart-dev-containers is a skill that restarts Docker development containers, used for rebuilding containers after code changes or resolving issues with unhealthy containers');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('drsapaev/final/aif-improve', 'community', 'drsapaev', 'final', 'drsapaev/final', 'aif-improve', 1, 0, 57, '2026-02-23T19:41:09Z', '2026-03-06T07:13:14.743Z', '5a886d4edaad056a7a33839e503463dff4bf61291345f95819067cd28997e58d', '{"id":"drsapaev/final/aif-improve","name":"aif-improve","description":{"en":"aif-improve refines existing plans by re-analyzing them against the codebase, finding gaps and enhancing task quality. This skill benefits developers and project managers.","zh":"aif-improve 是一种 AI 工具，通过重新分析代码库来优化现有计划，找出缺陷和错误的依赖","ja":"aif-improve は、コードベースを再分析して既存のプランを最適化する AI ツールで、ギャップや誤った依存関係を発見する","ko":"aif-improve는 코드베이스를 재분석하여 기존 계획을 최적화하는 AI 도구로,ギャップ이나 잘못된 의존성을 찾습니다","es":"aif-improve es una herramienta de inteligencia artificial que refina planes existentes mediante un análisis más profundo del código y la retroalimentación del usuario","fr":"aif-improve est un outil d''intelligence artificielle qui affine les plans existants grâce à une analyse plus approfondie du code et à la rétroaction de l''utilisateur","de":"aif-improve ist ein KI-Tool, das bestehende Pläne durch eine tiefere Codeanalyse und Benutzerfeedback verfeinert","pt":"O aif-improve é uma ferramenta que refina planos de código existentes com análise de código e feedback do usuário, melhorando a qualidade das tarefas e identificando lacunas e dependências erradas","ru":"aif-improve - это инструмент, который усовершенствует существующие планы кодирования с помощью анализа кода и обратной связи пользователя, повышая качество задач и выявляя пробелы и неправильные зависимости","ar":"aif-improve هو أداة لتحسين خطط الكود الحالية من خلال تحليل الكود وآراء المستخدم، مما يحسن جودة المهام ويعرف الثغرات والاعتماديات الخاطئة"},"seo":{"title":{"en":"aif-improve: Plan Refinement Setup Guide | AI Agent Skill","zh":"AIエージェント aif-improve 优化指南","ja":"AIエージェント aif-improve セットアップガイド","ko":"AI 에이전트 aif-improve 최적화 설정","es":"Guía de configuración de aif-improve para refinar planes","fr":"Configurer aif-improve pour améliorer les plans","de":"Einrichtungsanleitung für aif-improve zur Planverfeinerung","pt":"Guia de Configuração do aif-improve - Otimização de Plano...","ru":"Настройка aif-improve - Улучшение Планов Кодирования с по...","ar":"دليل إعداد aif-improve - تحسين خطط الكود باستخدام أدوات ا..."},"description":{"en":"Discover how aif-improve refines existing plans through codebase analysis and user feedback. Learn to enhance task quality and dependencies today!","zh":"了解 aif-improve 的技术细节和优化方法，提高代码质量和任务精度","ja":"aif-improve の詳細と設定方法を学び、コード品質とタスク精度を向上させる","ko":"aif-improve의 기술 세부 정보와 최적화 방법을 알아보고 코드 품질과 작업 정확도를 향상시키세요","es":"Mejora tus planes con aif-improve, herramienta de inteligencia artificial para refinar y optimizar tareas","fr":"Améliorez vos plans avec aif-improve, outil d''intelligence artificielle pour affiner et optimiser les tâches","de":"Verbessern Sie Ihre Pläne mit aif-improve, einem KI-Tool zur Planverfeinerung und Optimierung","pt":"Aprenda a configurar o aif-improve para refinar planos de código existentes e melhorar a qualidade das tarefas com análise de código e feedback do usuário","ru":"Узнайте, как настроить aif-improve для усовершенствования существующих планов кодирования и повышения качества задач с помощью анализа кода и обратной связи ...","ar":"تعلم كيفية إعداد aif-improve لتحسين خطط الكود الحالية وتحسين جودة المهام من خلال تحليل الكود وآراء المستخدم"},"definition":{"en":"aif-improve is a skill that refines existing plans through deeper codebase analysis and optional user feedback to enhance task quality and correct dependencies.","zh":"aif-improve 是一种 AI 优化工具，用于提高代码质量和任务精度","ja":"aif-improve は、コード品質とタスク精度を向上させる AI 最適化ツールです","ko":"aif-improve는 코드 품질과 작업 정확도를 향상시키는 AI 최적화 도구입니다","es":"aif-improve es una herramienta de inteligencia artificial que permite la mejora de planes mediante la detección de brechas y la optimización de tareas","fr":"aif-improve est un outil d''intelligence artificielle qui permet d''améliorer les plans en détectant les lacunes et en optimisant les tâches","de":"aif-improve ist ein KI-Tool, das die Verbesserung von Plänen durch die Erkennung von Lücken und die Optimierung von Aufgaben ermöglicht","pt":"O aif-improve é uma ferramenta de otimização de planos de código que utiliza análise de código e feedback do usuário para melhorar a qualidade das tarefas","ru":"aif-improve - это инструмент оптимизации планов кодирования, который использует анализ кода и обратную связь пользователя для повышения качества задач","ar":"aif-improve هو أداة لتحسين خطط الكود التي تستخدم تحليل الكود وآراء المستخدم لتحسين جودة المهام"},"features":{"en":["Re-analyzes existing plans against the codebase to find gaps and missing tasks","Enhances task quality through deeper codebase analysis and user feedback","Corrects wrong dependencies and assumptions in existing plans","Locates the active plan file using a prioritized search","Supports optional user feedback for more accurate plan refinement"],"zh":["重新分析代码库以优化现有计划","找出缺陷和错误的依赖","增强任务质量和精度","支持用户反馈以改进计划","使用优先级定位活动计划文件"],"ja":["コードベースを再分析して既存のプランを最適化","ギャップや誤った依存関係を発見","タスク品質と精度を向上させる","ユーザーフィードバックをサポートしてプランを改善","優先順位を使用してアクティブなプランファイルを特定"],"ko":["코드베이스를 재분석하여 기존 계획을 최적화","ギャップ이나 잘못된 의존성을 찾습니다","작업 품질과 정확도를 향상시킵니다","사용자 피드백을 지원하여 계획을 개선","우선순위를 사용하여 활성 계획 파일을 위치"],"es":["Análisis de código para detectar brechas y errores","Incorporación de retroalimentación del usuario para mejorar la calidad de las tareas","Optimización de dependencias y tareas para mejorar la eficiencia","Refinamiento de planes existentes para mejorar la precisión","Detección de suposiciones incorrectas y casos de borde no considerados"],"fr":["Analyse de code pour détecter les lacunes et les erreurs","Intégration de la rétroaction de l''utilisateur pour améliorer la qualité des tâches","Optimisation des dépendances et des tâches pour améliorer l''efficacité","Affinement des plans existants pour améliorer la précision","Détection des hypothèses incorrectes et des cas de bord non pris en compte"],"de":["Codeanalyse zur Erkennung von Lücken und Fehlern","Einbindung von Benutzerfeedback zur Verbesserung der Aufgabenqualität","Optimierung von Abhängigkeiten und Aufgaben zur Verbesserung der Effizienz","Verfeinerung von bestehenden Plänen zur Verbesserung der Genauigkeit","Erkennung von falschen Annahmen und nicht berücksichtigten Randfällen"],"pt":["Refina planos de código existentes com análise de código","Identifica lacunas e dependências erradas","Melhora a qualidade das tarefas com feedback do usuário","Utiliza prioridade para localizar o arquivo de plano ativo","Análise de código para encontrar gaps e edge cases"],"ru":["Усовершенствует существующие планы кодирования с помощью анализа кода","Выявляет пробелы и неправильные зависимости","Повышает качество задач с помощью обратной связи пользователя","Использует приоритет для нахождения активного файла плана","Анализ кода для выявления пробелов и краевых случаев"],"ar":["يحسن خطط الكود الحالية من خلال تحليل الكود","يعرف الثغرات والاعتماديات الخاطئة","يحسن جودة المهام من خلال آراء المستخدم","يستخدم الأفضلية لتحديد موقع ملف الخطة النشط","تحليل الكود لتحديد الثغرات والحالات الحدية"]},"keywords":{"en":["how to use aif-improve","aif-improve alternative","aif-improve setup guide","what is aif-improve","aif-improve vs plan refinement tools","aif-improve install","plan refinement with aif-improve","aif-improve for developers","aif-improve for project managers"],"zh":["AI 优化工具","代码质量提高","任务精度提高","计划优化","代码库分析","缺陷发现","依存关系优化","用户反馈","计划改进"],"ja":["AI 最適化ツール","コード品質向上","タスク精度向上","プラン最適化","コードベース分析","ギャップ発見","依存関係最適化","ユーザーフィードバック","プラン改善"],"ko":["AI 최적화 도구","코드 품질 향상","작업 정확도 향상","계획 최적화","코드베이스 분석","ギャップ 찾기","의존성 최적화","사용자 피드백","계획 개선"],"es":["herramientas de inteligencia artificial para desarrollo","refinamiento de planes","análisis de código","optimización de tareas","detección de brechas","mejora de la calidad del código"],"fr":["outils d''intelligence artificielle pour le développement","affinement de plans","analyse de code","optimisation de tâches","détection de lacunes","amélioration de la qualité du code"],"de":["KI-Tools für die Entwicklung","Planverfeinerung","Codeanalyse","Optimierung von Aufgaben","Erkennung von Lücken","Verbesserung der Codequalität"],"pt":["aif-improve","otimização de planos de código","análise de código","feedback do usuário","refinamento de planos","qualidade de tarefas","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["aif-improve","оптимизация планов кодирования","анализ кода","обратная связь пользователя","усовершенствование планов","качество задач","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["aif-improve","تحسين خطط الكود","تحليل الكود","آراء المستخدم","تحسين خطط","جودة المهام","تطوير البرمجيات","أدوات التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"drsapaev","repo":"final","repoPath":"drsapaev/final","stars":1,"forks":0,"updatedAt":"2026-02-23T19:41:09Z","topics":[],"category":"community","skillMd":{"name":"aif-improve","description":"Refine and enhance an existing implementation plan with a second iteration. Re-analyzes the codebase, checks for gaps, missing tasks, wrong dependencies, and improves the plan quality. Use after $2 to polish the plan before implementation.","bodyPreview":"# Improve - Plan Refinement (Second Iteration)\n\nRefine an existing plan by re-analyzing it against the codebase. Finds gaps, missing tasks, wrong dependencies, and enhances task quality.\n\n## Core Idea\n\n```\nexisting plan + deeper codebase analysis + user feedback (optional)\n    ↓\nfind gaps, missing edge cases, wrong assumptions\n    ↓\nenhanced plan with better tasks, correct dependencies, more detail\n```\n\n## Workflow\n\n### Step 0: Find the Plan\n\n**Locate the active plan file using this priority:**","body":"# Improve - Plan Refinement (Second Iteration)\n\nRefine an existing plan by re-analyzing it against the codebase. Finds gaps, missing tasks, wrong dependencies, and enhances task quality.\n\n## Core Idea\n\n```\nexisting plan + deeper codebase analysis + user feedback (optional)\n    ↓\nfind gaps, missing edge cases, wrong assumptions\n    ↓\nenhanced plan with better tasks, correct dependencies, more detail\n```\n\n## Workflow\n\n### Step 0: Find the Plan\n\n**Locate the active plan file using this priority:**\n\n```\n1. .ai-factory/PLAN.md exists? → Use it (from $2 fast)\n2. No .ai-factory/PLAN.md → Check current git branch:\n   git branch --show-current\n   → Convert branch name to filename: replace \"/\" with \"-\", add \".md\"\n   → Look for .ai-factory/plans/<branch-name>.md\n   Example: feature/user-auth → .ai-factory/plans/feature-user-auth.md\n```\n\n**If NO plan file found at either location:**\n\n```\nNo active plan found.\n\nTo create a plan first, use:\n- $2 full <description>  — for a new feature (creates branch + plan)\n- $2 fast <description>  — for a quick task plan\n```\n\n→ **STOP here.** Do not proceed without a plan file.\n\n**If plan file found → read it and continue to Step 1.**\n\n### Step 1: Load Context\n\n**1.1: Read the plan file**\n\nRead the found plan file completely. Understand:\n- Feature scope and goals\n- Current tasks (subjects, descriptions, dependencies)\n- Settings (testing, logging preferences)\n- Commit checkpoints\n- Which tasks are already completed (checkboxes `- [x]`)\n\n**1.2: Read project context**\n\nRead `.ai-factory/DESCRIPTION.md` if it exists:\n- Tech stack\n- Architecture\n- Conventions\n- Non-functional requirements\n\n**1.3: Read patches (past mistakes)**\n\n```\nGlob: .ai-factory/patches/*.md\n```\n\nIf patches exist, read them to understand:\n- What mistakes were made before\n- What patterns to avoid\n- What the plan should account for\n\n**1.4: Load current task list**\n\n```\nTaskList → Get all tasks with statuses\n```\n\nUnderstand what''s already been created, what''s in progress, what''s completed.\n\n### Step 2: Deep Codebase Analysis\n\nNow do a **deeper** codebase exploration than what `$2` did initially:\n\n**2.1: Trace through existing code paths**\n\nFor each task in the plan, find the relevant files:\n```\nGlob + Grep: Find files mentioned in tasks\nRead: Understand current implementation\n```\n\nLook for:\n- Existing patterns the plan should follow\n- Code that already partially implements what a task describes\n- Hidden dependencies the plan missed\n- Shared utilities or services the plan should use instead of creating new ones\n\n**2.2: Check for integration points**\n\nLook for things the plan might have missed:\n- API routes that need updating\n- Database migrations needed\n- Config files that need changes\n- Import/export updates\n- Middleware or guards that apply\n- Existing validation patterns\n\n**2.3: Check for edge cases**\n\nBased on the tech stack and codebase:\n- Error handling patterns used in the project\n- Null/undefined safety patterns\n- Authentication/authorization checks needed\n- Rate limiting, caching considerations\n- Data validation at boundaries\n\n### Step 3: Identify Improvements\n\nCompare the plan against what you found. Categorize issues:\n\n**3.1: Missing tasks**\n- Tasks that should exist but don''t (e.g., migration, config update, index creation)\n- Tasks for edge cases not covered\n\n**3.2: Task quality issues**\n- Descriptions too vague (no file paths, no specific implementation details)\n- Missing logging requirements\n- Missing error handling details\n- Incorrect file paths\n\n**3.3: Dependency issues**\n- Wrong task order (task A depends on B but B comes after A)\n- Missing dependencies (task C needs task A''s output but isn''t blocked by it)\n- Unnecessary dependencies (tasks could run in parallel)\n\n**3.4: Redundant or duplicate tasks**\n- Two tasks doing the same thing\n- Task that''s unnecessary because the code already exists\n- Task that duplicates existing functionality\n\n**3.5: Scope issues**\n- Tasks too large (should be split)\n- Tasks too small (should be merged)\n- Tasks outside the feature scope (gold-plating)\n\n**3.6: User-prompted improvements (if $ARGUMENTS provided)**\n\nIf the user provided specific improvement instructions in `$ARGUMENTS`:\n- Apply the user''s feedback to the plan\n- Look for tasks that need modification based on the prompt\n- Add new tasks if the user''s prompt requires them\n\n### Step 4: Present Improvements\n\nShow the user what you found in a clear format:\n\n```\n## Plan Refinement Report\n\nPlan: [plan file path]\nTasks analyzed: N\n\n### Findings\n\n#### 🆕 Missing Tasks (N found)\n1. **[New task subject]**\n   Why: [reason this task is needed]\n   After: Task #X (dependency)\n\n2. **[New task subject]**\n   Why: [reason]\n\n#### 📝 Task Improvements (N found)\n1. **Task #X: [subject]**\n   Issue: [what''s wrong]\n   Fix: [what should change]\n\n2. **Task #Y: [subject]**\n   Issue: [what''s wrong]\n   Fix: [what should change]\n\n#### 🔗 Dependency Fixes (N found)\n1. Task #X should depend on Task #Y\n   Reason: [why]\n\n#### 🗑️ Removals (N found)\n1. **Task #X: [subject]**\n   Reason: [why it''s redundant/unnecessary]\n\n#### 📋 Summary\n- Missing tasks: N\n- Tasks to improve: N\n- Dependencies to fix: N\n- Tasks to remove: N\n\nApply these improvements?\n- [ ] Yes, apply all\n- [ ] Let me pick which ones\n- [ ] No, keep the plan as is\n```\n\n**If no improvements found:**\n\n```\n## Plan Review Complete\n\nThe plan looks solid! No significant gaps or issues found.\n\nPlan: [plan file path]\nTasks: N\n\nReady to implement:\n$2\n```\n\n### Step 5: Apply Approved Improvements\n\nBased on user''s choice:\n\n**5.1: Apply task improvements**\n\nFor existing tasks that need better descriptions:\n```\nTaskGet(taskId) → read current\nTaskUpdate(taskId, description: \"improved description\", subject: \"improved subject\")\n```\n\n**5.2: Add missing tasks**\n\nFor new tasks:\n```\nTaskCreate(subject, description, activeForm)\nTaskUpdate(taskId, addBlockedBy: [...]) → set dependencies\n```\n\n**5.3: Fix dependencies**\n\n```\nTaskUpdate(taskId, addBlockedBy: [...])\n```\n\n**5.4: Remove redundant tasks**\n\n```\nTaskUpdate(taskId, status: \"deleted\")\n```\n\n**5.5: Update the plan file**\n\n**CRITICAL:** After all changes, update the plan file to reflect the new state:\n\n- Add new tasks to the correct phase with `- [ ]` checkboxes\n- Update task descriptions if they changed\n- Fix task ordering if dependencies changed\n- Remove deleted tasks\n- Update commit checkpoints if task count changed significantly\n- Preserve any `- [x]` checkboxes for already completed tasks\n\nUse `Edit` to make surgical changes to the plan file, or `Write` to regenerate it if changes are extensive.\n\n**5.6: Confirm completion**\n\n```\n## Plan Refined\n\nChanges applied:\n- Added N new tasks\n- Improved N task descriptions\n- Fixed N dependencies\n- Removed N redundant tasks\n\nUpdated plan: [plan file path]\nTotal tasks: N\n\nReady to implement:\n$2\n```\n\n### Context Cleanup\n\nContext is heavy after deep codebase analysis. Plan is updated in file — suggest freeing space:\n\n```\nAskUserQuestion: Free up context before continuing?\n\nOptions:\n1. /clear — Full reset (recommended)\n2. /compact — Compress history\n3. Continue as is\n```\n\n## Important Rules\n\n1. **Don''t rewrite from scratch** — improve the existing plan, don''t replace it\n2. **Preserve completed work** — never modify or remove `- [x]` completed tasks\n3. **Traceable improvements** — every change must be justified by codebase analysis or user input\n4. **Respect settings** — if testing is \"no\", don''t add test tasks. If logging is \"minimal\", don''t add verbose logging tasks\n5. **No gold-plating** — don''t add tasks outside the feature scope unless critical\n6. **Minimal viable improvements** — suggest only what matters, not every possible enhancement\n7. **User approves first** — never apply changes without user confirmation\n8. **Keep plan file in sync** — the plan file MUST match the task list after improvements\n\n## Examples\n\n### Example 1: Auto-review (no arguments)\n\n```\nUser: $2\n\n→ Found plan: .ai-factory/plans/feature-user-auth.md\n→ 6 tasks in plan\n→ Deep codebase analysis...\n→ Found: project uses middleware pattern for auth, plan misses middleware task\n→ Found: Task #3 description doesn''t mention existing UserService\n→ Found: Task #5 depends on Task #3 but no dependency set\n\nReport:\n- 1 missing task (auth middleware)\n- 1 task to improve (reference UserService)\n- 1 dependency to fix\n\nApply? → Yes → Changes applied\n```\n\n### Example 2: With user prompt\n\n```\nUser: $2 добавь обработку ошибок и валидацию входных данных\n\n→ Found plan: .ai-factory/PLAN.md\n→ 4 tasks in plan\n→ User wants: error handling + input validation\n→ Analyzing each task for missing error handling...\n→ Found: none of the tasks mention input validation\n→ Found: error handling is inconsistent\n\nReport:\n- 2 tasks improved (added validation details to descriptions)\n- 1 new task (create shared validation utils)\n- Updated task descriptions with error handling patterns from codebase\n\nApply? → Yes → Changes applied\n```\n\n### Example 3: No plan found\n\n```\nUser: $2\n\n→ No .ai-factory/PLAN.md found\n→ Branch: main (no feature branch)\n→ No plan file found\n\n\"No active plan found. Create one first:\n- $2 full <description>\n- $2 fast <description>\"\n```\n\n### Example 4: Plan already looks good\n\n```\nUser: $2\n\n→ Found plan: .ai-factory/plans/feature-product-search.md\n→ 5 tasks in plan\n→ Deep analysis... all tasks well-defined, dependencies correct\n→ No significant improvements found\n\n\"Plan looks solid! Ready to implement:\n$2\"\n```\n"},"lastSynced":"2026-03-06T07:13:14.743Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced plan refinement and codebase analysis capabilities.","zh":"适用于需要高级计划细化和代码库分析能力的代码审查代理。","ja":"コードレビュー代理が高度なプランの改良とコードベースの分析機能を必要とする場合に最適です。","ko":"코드 리뷰 에이전트가 고급 계획 精緻化와 코드베이스 분석 기능을 필요로 할 때 적합합니다.","es":"Perfecto para Agentes de Revisión de Código que necesitan un refinamiento avanzado de planes y capacidades de análisis de código","fr":"Parfait pour les Agents de Révision de Code nécessitant un raffinement avancé de plans et des capacités d''analyse de codebase","de":"Perfekt für Code-Review-Agenten, die ein fortschrittliches Plan-Feinabstimmung und Codebase-Analysefunktionen benötigen","pt":"Perfeito para Agentes de Revisão de Código que necessitam de refino avançado de planos e capacidades de análise de codebase.","ru":"Идеально подходит для агентов проверки кода, которым необходимы продвинутые возможности уточнения планов и анализа кодовой базы.","ar":"مثالي لعميل مراجعة الكود الذي يحتاج إلى تعدين متقدم لخطة وملفات قاعدة بيانات الكود."},"recommendation":{"en":"Empowers agents to re-analyze existing plans against codebases, finding gaps and enhancing task quality through deeper analysis and optional user feedback, utilizing dependencies and task management protocols.","zh":"赋予代理重新分析现有计划与代码库的能力，发现差距并通过更深入的分析和可选的用户反馈提高任务质量，利用依赖关系和任务管理协议。","ja":"エージェントが既存のプランをコードベースに対して再分析し、ギャップを発見し、より深い分析とオプションのユーザーからのフィードバックを通じてタスクの品質を向上させ、依存関係とタスク管理プロトコルを利用することができます。","ko":"에이전트가 기존 계획을 코드베이스에 대해 재분석하여 격차를 발견하고 더 깊은 분석과 선택적인 사용자 피드백을 통해 작업 품질을 향상시키고 종속성 및 작업 관리 프로토콜을 활용할 수 있도록 합니다.","es":"Habilita a los agentes a reanalizar planes existentes frente a codebases, detectar brechas y mejorar la calidad de las tareas a través de un análisis más profundo y una retroalimentación opcional del usuario, utilizando dependencias y protocolos de gestión de tareas","fr":"Permet aux agents de réanalyser les plans existants par rapport aux codebases, de trouver les lacunes et d''améliorer la qualité des tâches grâce à une analyse plus approfondie et à une rétroaction facultative de l''utilisateur, en utilisant les dépendances et les protocoles de gestion des tâches","de":"Ermächtigt Agenten, bestehende Pläne gegen Codebases neu zu analysieren, Lücken zu finden und die Aufgabenqualität durch eine tiefere Analyse und optionalen Benutzer-Feedback zu verbessern, unter Nutzung von Abhängigkeiten und Aufgabenmanagement-Protokollen","pt":"Habilita os agentes a reanalisar planos existentes contra codebases, encontrando lacunas e aprimorando a qualidade das tarefas por meio de análise mais profunda e feedback opcional do usuário, utilizando dependências e protocolos de gerenciamento de tarefas.","ru":"Наделяет агентов возможностью переанализировать существующие планы в отношении кодовых баз, обнаруживая пробелы и повышая качество задач за счет более глубокого анализа и необязательной обратной связи пользователя, используя зависимости и протоколы управления задачами.","ar":"يمكّن الوكيل من إعادة تحليل الخطط الحالية مقابل قواعد بيانات الكود، وبذلك يجد الفجوات ويعزز جودة المهام من خلال تحليل أعمق ومراجعة مستخدم اختيارية، واستخدام التبعيات وبروتوكولات إدارة المهام."},"useCases":{"en":["Refining project plans for improved task quality","Identifying missing edge cases in codebase dependencies","Enhancing project management through gap analysis and corrective measures"],"zh":["改进任务质量的项目计划精化","识别代码库依赖关系中的缺失边界情况","通过缺口分析和纠正措施增强项目管理"],"ja":["タスクの品質を向上させるためのプロジェクト計画の改良","コードベースの依存関係における欠落したエッジケースの特定","ギャップ分析と是正措置を通じてのプロジェクト管理の強化"],"ko":["작업 품질을 개선하기 위한 프로젝트 계획의 세부화","코드베이스 종속성에서 누락된 에지 케이스를 식별","격차 분석 및 시정 조치를 통해 프로젝트 관리를 강화"],"es":["Perfeccionar los planes de proyecto para mejorar la calidad de las tareas","Identificar casos de borde faltantes en las dependencias de la codebase","Mejorar la gestión de proyectos a través del análisis de brechas y medidas correctivas"],"fr":["Affiner les plans de projet pour améliorer la qualité des tâches","Identifier les cas de bordure manquants dans les dépendances de la codebase","Améliorer la gestion de projet grâce à l''analyse des lacunes et aux mesures correctives"],"de":["Projektpläne verfeinern, um die Aufgabenqualität zu verbessern","Fehlende Randfälle in den Codebase-Abhängigkeiten identifizieren","Projektmanagement durch Lückenanalyse und Korrekturmaßnahmen verbessern"],"pt":["Aprimorar planos de projeto para melhorar a qualidade das tarefas","Identificar casos de bordo ausentes nas dependências da codebase","Melhorar a gestão de projetos por meio da análise de lacunas e medidas corretivas"],"ru":["Уточнение планов проекта для повышения качества задач","Обнаружение отсутствующих граничных случаев в зависимостях кодовой базы","Улучшение управления проектами за счет анализа пробелов и корректирующих мер"],"ar":["تحسين خطط المشروع لتحسين جودة المهام","تحديد الحالات الحدودية الناقصة في التبعيات لقاعدة بيانات الكود","تعزيز إدارة المشروع من خلال تحليل الفجوات والتدابير التصحيحية"]},"limitations":{"en":["Requires access to the codebase and existing plan files","May require user feedback for optimal results"],"zh":["需要访问代码库和现有计划文件","可能需要用户反馈以获得最佳结果"],"ja":["コードベースと既存のプランファイルへのアクセスが必要","最適な結果を得るためにユーザーからのフィードバックが必要になる場合がある"],"ko":["코드베이스 및 기존 계획 파일에 대한 액세스가 필요","최적의 결과를 얻기 위해 사용자 피드백이 필요할 수 있음"],"es":["Requiere acceso a la codebase y a los archivos de planes existentes","Puede requerir retroalimentación del usuario para resultados óptimos"],"fr":["Nécessite un accès à la codebase et aux fichiers de plans existants","Peut nécessiter une rétroaction de l''utilisateur pour des résultats optimaux"],"de":["Benötigt Zugriff auf die Codebase und bestehende Plan-Dateien","Kann Benutzer-Feedback für optimale Ergebnisse erfordern"],"pt":["Requer acesso à codebase e arquivos de planos existentes","Pode requerer feedback do usuário para resultados ótimos"],"ru":["Требует доступа к кодовой базе и существующим файлам планов","Может требовать обратной связи пользователя для оптимальных результатов"],"ar":["يتطلب الوصول إلى قاعدة بيانات الكود وملفات الخطة الحالية","يمكن أن يتطلب تقييم المستخدم لتحقيق نتائج مثالية"]},"version":4},"contentHash":"5a886d4edaad056a7a33839e503463dff4bf61291345f95819067cd28997e58d","qualityScore":57}');
