INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('drsapaev/final/aif-improve', 'aif-improve', 'drsapaev', 'final', 'community', 'aif-improve drsapaev final community aif-improve refines existing plans by re-analyzing them against the codebase, finding gaps and enhancing task quality. This skill benefits developers and project managers. aif-improve 是一种 AI 工具，通过重新分析代码库来优化现有计划，找出缺陷和错误的依赖 aif-improve は、コードベースを再分析して既存のプランを最適化する AI ツールで、ギャップや誤った依存関係を発見する aif-improve는 코드베이스를 재분석하여 기존 계획을 최적화하는 AI 도구로,ギャップ이나 잘못된 의존성을 찾습니다 aif-improve es una herramienta de inteligencia artificial que refina planes existentes mediante un análisis más profundo del código y la retroalimentación del usuario aif-improve est un outil d''intelligence artificielle qui affine les plans existants grâce à une analyse plus approfondie du code et à la rétroaction de l''utilisateur aif-improve ist ein KI-Tool, das bestehende Pläne durch eine tiefere Codeanalyse und Benutzerfeedback verfeinert O aif-improve é uma ferramenta que refina planos de código existentes com análise de código e feedback do usuário, melhorando a qualidade das tarefas e identificando lacunas e dependências erradas aif-improve - это инструмент, который усовершенствует существующие планы кодирования с помощью анализа кода и обратной связи пользователя, повышая качество задач и выявляя пробелы и неправильные зависимости aif-improve هو أداة لتحسين خطط الكود الحالية من خلال تحليل الكود وآراء المستخدم، مما يحسن جودة المهام ويعرف الثغرات والاعتماديات الخاطئة how to use aif-improve aif-improve alternative aif-improve setup guide what is aif-improve aif-improve vs plan refinement tools aif-improve install plan refinement with aif-improve aif-improve for developers aif-improve for project managers AI 优化工具 代码质量提高 任务精度提高 计划优化 代码库分析 缺陷发现 依存关系优化 用户反馈 计划改进 Re-analyzes existing plans against the codebase to find gaps and missing tasks Enhances task quality through deeper codebase analysis and user feedback Corrects wrong dependencies and assumptions in existing plans Locates the active plan file using a prioritized search Supports optional user feedback for more accurate plan refinement aif-improve is a skill that refines existing plans through deeper codebase analysis and optional user feedback to enhance task quality and correct dependencies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gaegulgaegul/gaegulzip/pdca', 'community', 'gaegulgaegul', 'gaegulzip', 'gaegulgaegul/gaegulzip', 'pdca', 0, 0, 57, '2026-03-06T05:14:23Z', '2026-03-07T03:39:19.104Z', '84bfbb16641b6218f998bd149a198c5d4c20166beb4951e1cb207e3bea6a26be', '{"id":"gaegulgaegul/gaegulzip/pdca","name":"pdca","description":{"en":"The pdca skill manages the PDCA cycle with an agent-integrated workflow, automating phases via bkit.config.json. It benefits developers by streamlining project workflows","zh":"PDCA技能提供了统一的工作流管理，通过agent-integrated workflow自动调用项目代理","ja":"PDCAスキルは統一されたワークフローマネジメントを提供し、AIエージェントワークフローを介してプロジェクトエージェントを自動的に呼び出します","ko":"PDCA 스킬은 통합 워크플로 관리를 제공하며 에이전트 통합 워크플로를 통해 프로젝트 에이전트를 자동으로 호출합니다","es":"El skill de PDCA ofrece un flujo de trabajo integrado de agentes para gestionar el ciclo de PDCA y personalizar la salida de documentos con bkit.config.json.","fr":"Le skill PDCA propose un flux de travail d''agents intégrés pour gérer le cycle PDCA et personnaliser la sortie de documents avec bkit.config.json.","de":"Das PDCA-Skill bietet einen integrierten Agenten-Workflow, um den PDCA-Zyklus zu verwalten und die Dokumentenausgabe mit bkit.config.json anzupassen.","pt":"O PDCA é uma habilidade que gerencia o ciclo de planejamento, desenvolvimento, checagem e ação com fluxo de trabalho integrado","ru":"PDCA - это навык, который управляет циклом планирования, разработки, проверки и действия с интегрированным рабочим процессом","ar":"PDCA هو مهارة لإدارة دورة التخطيط والتنمية والتحقق والعمل مع تدفق عمل متكامل"},"seo":{"title":{"en":"pdca: Unified PDCA Cycle Management for AI Agents | AI Ag...","zh":"PDCA技能集成指南 - AI智能代理工作流","ja":"PDCAスキル統合ガイド - AIエージェントワークフロー","ko":"PDCA 스킬 통합 가이드 - 에이전트 통합 워크플로","es":"Guía de configuración de PDCA para agentes de inteligenci...","fr":"Guide de configuration de PDCA pour les outils d''intellig...","de":"PDCA-Konfigurationsleitfaden für KI-Agents","pt":"Guia de Configuração PDCA: Implementação de Fluxo de Trab...","ru":"Настройка PDCA: Руководство по внедрению интегрированного...","ar":"دليل إعداد PDCA: تطبيق تدفق عمل متكامل لآلات الإجابة الذكية"},"description":{"en":"Discover how pdca simplifies agent-integrated workflow management. Learn to configure bkit.config.json for automated PDCA phases and optimize your AI agent s...","zh":"了解PDCA技能的技术细节，包括agent-integrated workflow和bkit.config.json配置","ja":"PDCAスキルの技術的詳細を学び、AIエージェントワークフローとbkit.config.jsonの設定について調べる","ko":"PDCA 스킬의 기술적 세부 사항을 살펴보고 에이전트 통합 워크플로 및 bkit.config.json 설정에 대해 학습하세요","es":"Aprende a configurar el ciclo de PDCA con un flujo de trabajo integrado de agentes y personaliza la salida de documentos con bkit.config.json","fr":"Découvrez comment configurer le cycle PDCA avec un flux de travail d''agents intégrés et personnalisez la sortie de documents avec bkit.config.json","de":"Erfahren Sie, wie Sie den PDCA-Zyklus mit einem integrierten Agenten-Workflow konfigurieren und die Dokumentenausgabe mit bkit.config.json anpassen","pt":"Aprenda a configurar o ciclo PDCA com fluxo de trabalho integrado e automatize as fases com agentes de projeto","ru":"Узнайте, как настроить цикл PDCA с интегрированным рабочим процессом и автоматизировать фазы с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد دورة PDCA مع تدفق عمل متكامل وتأتمة المراحل باستخدام وكلاء المشروع"},"definition":{"en":"pdca is a unified skill for managing the PDCA cycle, integrating project agents from bkit.config.json for automated workflow","zh":"PDCA技能是一种用于管理PDCA周期的统一技能，具有agent-integrated workflow","ja":"PDCAスキルは、AIエージェントワークフローを備えたPDCAサイクルを管理するための統一スキルです","ko":"PDCA 스킬은 에이전트 통합 워크플로를 갖춘 PDCA 사이클을 관리하기 위한 통합 스킬입니다","es":"PDCA es un skill que gestiona el ciclo de planificación, ejecución, verificación y actuación con un flujo de trabajo integrado de agentes","fr":"PDCA est un skill qui gère le cycle de planification, exécution, vérification et action avec un flux de travail d''agents intégrés","de":"PDCA ist ein Skill, der den Zyklus aus Planung, Ausführung, Überprüfung und Handlung mit einem integrierten Agenten-Workflow verwaltet","pt":"PDCA é uma habilidade que automatiza as fases do ciclo de gerenciamento de projetos","ru":"PDCA - это навык, который автоматизирует фазы цикла управления проектами","ar":"PDCA هو مهارة لتحسين المراحل في دورة إدارة المشاريع"},"features":{"en":["Automates PDCA phases with agent-integrated workflow","Configures context.defaultLanguage for output consistency","Supports customizable document output paths via pdca.planDocPaths and pdca.designDocPaths","Integrates with bkit.config.json for seamless project agent invocation","Enables phase-specific procedures via the phases/ directory"],"zh":["自动调用项目代理","支持bkit.config.json配置","输出文档路径自定义","状态消息和文档输出语言自定义","集成agent-integrated workflow"],"ja":["プロジェクトエージェントの自動呼び出し","bkit.config.jsonの設定をサポート","出力ドキュメントパスのカスタマイズ","ステータスメッセージとドキュメント出力言語のカスタマイズ","AIエージェントワークフローの統合"],"ko":["프로젝트 에이전트 자동 호출","bkit.config.json 설정 지원","출력 문서 경로 사용자 정의","상태 메시지 및 문서 출력 언어 사용자 정의","에이전트 통합 워크플로 통합"],"es":["Flujo de trabajo integrado de agentes","Personalización de la salida de documentos con bkit.config.json","Configuración de la ruta de salida de documentos con pdca.planDocPaths","Configuración de la ruta de salida de documentos con pdca.designDocPaths","Configuración de la ruta de salida de documentos con pdca.analyzeDocPaths","Soporte para múltiples idiomas con context.defaultLanguage"],"fr":["Flux de travail d''agents intégrés","Personnalisation de la sortie de documents avec bkit.config.json","Configuration du chemin de sortie de documents avec pdca.planDocPaths","Configuration du chemin de sortie de documents avec pdca.designDocPaths","Configuration du chemin de sortie de documents avec pdca.analyzeDocPaths","Prise en charge de plusieurs langues avec context.defaultLanguage"],"de":["Integrierter Agenten-Workflow","Anpassung der Dokumentenausgabe mit bkit.config.json","Konfiguration des Dokumentenausgabepfads mit pdca.planDocPaths","Konfiguration des Dokumentenausgabepfads mit pdca.designDocPaths","Konfiguration des Dokumentenausgabepfads mit pdca.analyzeDocPaths","Unterstützung für mehrere Sprachen mit context.defaultLanguage"],"pt":["Fluxo de trabalho integrado com agentes de projeto","Automatização das fases do ciclo PDCA","Leitura de configuração em `bkit.config.json`","Suporte a múltiplos caminhos de saída de documentos","Integração com tecnologias de desenvolvimento de software"],"ru":["Интегрированный рабочий процесс с ИИ Агентами","Автоматизация фаз цикла PDCA","Чтение конфигурации из `bkit.config.json`","Поддержка нескольких путей вывода документов","Интеграция с технологиями разработки программного обеспечения"],"ar":["تدفق عمل متكامل مع وكلاء المشروع","تأتمة المراحل في دورة PDCA","قراءة التكوين من `bkit.config.json`","دعم مسارات متعددة لإخراج الوثائق","التكامل مع تكنولوجيا تطوير البرمجيات"]},"keywords":{"en":["how to use pdca","pdca setup guide","pdca vs agile","what is pdca","pdca install","pdca alternative","pdca cycle management","bkit.config.json configuration","ai agent workflow automation"],"zh":["PDCA技能","AI智能代理","agent-integrated workflow","bkit.config.json","输出文档路径","状态消息","文档输出语言"],"ja":["PDCAスキル","AIエージェント","AIエージェントワークフロー","bkit.config.json","出力ドキュメントパス","ステータスメッセージ","ドキュメント出力言語"],"ko":["PDCA 스킬","에이전트 통합 워크플로","AI 에이전트","bkit.config.json","출력 문서 경로","상태 메시지","문서 출력 언어"],"es":["PDCA","agentes de inteligencia artificial","flujo de trabajo integrado","bkit.config.json","pdca.planDocPaths","pdca.designDocPaths","pdca.analyzeDocPaths","context.defaultLanguage","configuración de PDCA"],"fr":["PDCA","outils d''intelligence artificielle","flux de travail d''agents intégrés","bkit.config.json","pdca.planDocPaths","pdca.designDocPaths","pdca.analyzeDocPaths","context.defaultLanguage","configuration de PDCA"],"de":["PDCA","KI-Agents","integrierter Agenten-Workflow","bkit.config.json","pdca.planDocPaths","pdca.designDocPaths","pdca.analyzeDocPaths","context.defaultLanguage","PDCA-Konfiguration"],"pt":["pdca","fluxo de trabalho integrado","agentes de projeto","automatização de fases","bkit.config.json","desenvolvimento de software","gerenciamento de projetos","tecnologias de desenvolvimento","ferramentas de desenvolvimento"],"ru":["pdca","интегрированный рабочий процесс","ИИ Агенты","автоматизация фаз","bkit.config.json","разработка программного обеспечения","управление проектами","технологии разработки","инструменты разработки"],"ar":["pdca","تدفق عمل متكامل","وكلاء المشروع","تأتمة المراحل","bkit.config.json","تطوير البرمجيات","إدارة المشاريع","تكنولوجيا التطوير","أدوات التطوير"]}},"owner":"gaegulgaegul","repo":"gaegulzip","repoPath":"gaegulgaegul/gaegulzip","stars":0,"forks":0,"updatedAt":"2026-03-06T05:14:23Z","topics":[],"category":"community","skillMd":{"name":"pdca","description":"|","bodyPreview":"# PDCA Skill (gaegulzip Project Override)\n\n> Unified Skill for managing PDCA cycle with **agent-integrated workflow**.\n> Each PDCA phase automatically invokes the appropriate project agents from `bkit.config.json`.\n> Phase 상세 절차는 `phases/` 디렉토리의 개별 파일 참조.\n\n## Config Reference\n\nRead `bkit.config.json` to determine:\n- `context.defaultLanguage` → **모든 출력(문서, 상태 메시지, 에이전트 응답)에 이 언어 사용**\n- `pdca.planDocPaths` → document output paths\n- `pdca.designDocPaths` → document output paths\n- `pdca.analyzeDocPa","body":"# PDCA Skill (gaegulzip Project Override)\n\n> Unified Skill for managing PDCA cycle with **agent-integrated workflow**.\n> Each PDCA phase automatically invokes the appropriate project agents from `bkit.config.json`.\n> Phase 상세 절차는 `phases/` 디렉토리의 개별 파일 참조.\n\n## Config Reference\n\nRead `bkit.config.json` to determine:\n- `context.defaultLanguage` → **모든 출력(문서, 상태 메시지, 에이전트 응답)에 이 언어 사용**\n- `pdca.planDocPaths` → document output paths\n- `pdca.designDocPaths` → document output paths\n- `pdca.analyzeDocPaths` → analysis document output paths\n- `pdca.reportDocPaths` → report document output paths\n- `platforms.{platform}.agents` → agent mapping per phase\n- `pdca.statusFile` → `.pdca-status.json` path\n- `pdca.matchRateThreshold` → 90 (default)\n- `pdca.maxIterations` → 5 (default)\n\n## Language Rule\n\n**All output MUST be in the language specified by `bkit.config.json` → `context.defaultLanguage`.**\nWhen calling agents via Task tool, always append to the prompt:\n`\\nIMPORTANT: Respond and write all documents in {defaultLanguage}. Code, paths, and technical terms stay in English.`\n\n## ⚠️ Intent-Only Document Rule (Plan & Design 문서 필수 원칙)\n\n**Plan/Design 문서는 \"무엇을(WHAT)\"과 \"왜(WHY)\"만 작성한다. \"어떻게(HOW)\" 즉 구현은 절대 작성하지 않는다.**\n\n이 원칙을 위반하는 예시:\n- ❌ 파일명/경로 지정: `src/services/authService.ts에 구현`\n- ❌ 코드 구조 지시: `useEffect로 상태를 관리하고 Redux store에 저장`\n- ❌ 함수 시그니처: `async function validateToken(token: string): Promise<boolean>`\n- ❌ DB 쿼리 작성: `SELECT * FROM users WHERE email = ?`\n- ❌ 특정 라이브러리 사용법: `zod.object({ email: z.string().email() })로 검증`\n\n이 원칙을 지키는 예시:\n- ✅ 사용자 행동 정의: `사용자는 이메일과 비밀번호로 로그인할 수 있다`\n- ✅ 비즈니스 규칙: `비밀번호는 최소 8자, 영문+숫자+특수문자 포함`\n- ✅ 데이터 요구사항: `사용자 프로필에는 닉네임, 프로필 이미지, 가입일이 포함된다`\n- ✅ API 계약 (Design): `POST /auth/login → 요청: { email, password }, 응답: { token, user }`\n- ✅ 제약조건: `토큰 만료 시간은 24시간`\n\n**이유**: 구현은 Do 단계의 개발자 에이전트가 결정한다. 설계 문서에 구현을 쓰면 에이전트 자율성을 제한하고, 코드 변경 시 문서 부패를 유발한다.\n\n> **모든 Plan/Design phase 에이전트 프롬프트에 이 원칙을 포함시킬 것.**\n\n## Product Naming Convention\n\n`{product}`는 앱 이름을 그대로 사용합니다:\n- `wowa` — 메인 앱\n- `admin` — 어드민 대시보드\n- `talmosang` — 탈모상 AI 두피 분석\n\n경로 예: `docs/wowa/auth/user-story.md`, `docs/admin/dashboard/web-brief.md`\n\n## Fullstack frontendType 제약\n\n`frontendType`은 **단일 값**만 허용합니다 (`\"mobile\"` 또는 `\"web\"`).\nMobile + Web 동시 개발이 필요한 경우, **별도 PDCA 사이클**로 분리합니다:\n- 예: `wowa` feature = fullstack (frontendType: mobile), `admin` feature = fullstack (frontendType: web)\n\n## Status Tracking\n\n`.pdca-status.json` stores platform and phase per feature:\n\n```json\n{\n  \"features\": {\n    \"{feature}\": {\n      \"phase\": \"research | plan | design | do | analyze | iterate | completed | archived\",\n      \"platform\": \"server | mobile | web | fullstack\",\n      \"frontendType\": \"mobile | web\",\n      \"startedAt\": \"ISO timestamp\",\n      \"documents\": {}\n    }\n  }\n}\n```\n\n**IMPORTANT**:\n- `platform` is determined during Plan phase by CTO and reused in all subsequent phases.\n- `frontendType` is set when platform is `fullstack` to distinguish Mobile vs Web frontend agents.\n\n---\n\n## Arguments\n\n| Argument | Description | Example |\n|----------|-------------|---------|\n| `research [feature]` | clarify → research-director | `/pdca research user-auth` |\n| `plan [feature]` | PO → interactive-review → CTO routing | `/pdca plan user-auth` |\n| `design [feature]` | Design docs (per platform) | `/pdca design user-auth` |\n| `do [feature]` | CTO distribution → dev agents | `/pdca do user-auth` |\n| `analyze [feature]` | Gap analysis + CTO review | `/pdca analyze user-auth` |\n| `iterate [feature]` | Auto improvement | `/pdca iterate user-auth` |\n| `report [feature]` | Completion report | `/pdca report user-auth` |\n| `archive [feature]` | Archive documents | `/pdca archive user-auth` |\n| `cleanup [feature]` | Cleanup archived | `/pdca cleanup` |\n| `status` | Current status | `/pdca status` |\n| `next` | Next phase guide | `/pdca next` |\n\n---\n\n## Phase Details\n\n각 phase 실행 시 해당 파일을 Read하여 상세 절차를 따릅니다.\n\n| Phase | File | Summary |\n|-------|------|---------|\n| **research** | `phases/research.md` | clarify → research-director (Decision Points) → CTO 통합 평가 (아키텍처+복잡도, BLOCK↔clarify 재호출) |\n| **plan** | `phases/plan.md` | clarify → PO (Research Gate) ↔ CTO 타당성 스캔 (BLOCK→PO 재호출) → 사용자 승인 → CTO 라우팅 ↔ PO (Scope Mismatch→보완+재승인) |\n| **design** | `phases/design.md` | 플랫폼별 디스패치 + tech-lead ↔ designer Pushback 루프 + API Contract 양방향 검증 (Fullstack) |\n| **do** | `phases/do.md` | 선행조건 검증 → 설계 리뷰 → CTO work-plan → 사용자 승인 → 실행 모드 → 에이전트 구현 ↔ BLOCKED:QUESTIONS 프로토콜 |\n| **analyze** | `phases/analyze.md` | gap-detector → FINDINGS 구조화 → 코드 리뷰 → CTO 통합 리뷰 |\n| **iterate** | `phases/iterate.md` | FINDINGS severity 순 에이전트 디스패치 또는 Ralph Loop 자율 수정 |\n| **report** | `phases/report.md` | report-generator → 배포/유지보수/v2 가이드 → CHANGELOG |\n| **archive** | `phases/archive.md` | 문서 아카이브 → status 업데이트 |\n\n---\n\n### status (Status Check)\n\n1. Read `.pdca-status.json`\n2. Display: feature, phase, platform, matchRate, documents\n3. Visualize progress\n\n```\n📊 PDCA Status\n─────────────────────────────\nFeature: {feature}\nPlatform: {platform}\nPhase: {phase}\nMatch Rate: {matchRate}%\n─────────────────────────────\n[Research] ✅ → [Plan] ✅ → [Design] ✅ → [Do] 🔄 → [Check] ⏳ → [Act] ⏳\n```\n\n---\n\n### next (Next Phase)\n\n| Current | Next | Action |\n|---------|------|--------|\n| None | research (권장) 또는 plan | research는 선택적. 복잡한 기능은 research 권장, 단순 기능은 plan 직행 가능 |\n| research | plan | PO → interactive-review → CTO routing |\n| plan | design | Platform-based design agents |\n| design | do | CTO distribution → dev agents |\n| do | check | Gap analysis + CTO review |\n| check (<90%) | act | Auto-iterate |\n| check (>=90%) | report | Completion report |\n| report | archive | Archive documents |\n\n---\n\n## Agent Integration Summary (All Bidirectional)\n\n> `↔` = 양방향 (피드백 경로 있음), `──→` = 단방향 (최종 출력)\n> 참조: `.claude/guide/agent-communication-protocol.md` — 전 phase 양방향 통신 프로토콜\n\n```\nResearch: clarify (user) ──→ research-director (research.md + Decision Points)\n                                       │\n                                       ↓ CTO 통합 평가 (아키텍처 + 복잡도)\n                                       │\n                              BLOCK ↔ clarify 재호출 (max 2회)\n                              CONCERN → AskUserQuestion\n                                       │\n                                       ↓ Decision Points → PO에게 전달\nPlan:    PO (user-story.md) ↔ CTO (⓪-pre 타당성 스캔)\n              │                        │ BLOCK → PO 재호출 (max 2회)\n              │                        ↓ PASS/WARN\n         interactive-review (사용자 승인) ──→ CTO (⓪ 플랫폼 라우팅)\n                                                   │\n                                       Scope Mismatch ↔ PO 보완 + 사용자 재승인\n                                                   ↓ platform & frontendType stored\nDesign:  ┌── Server: tech-lead (server-brief)\n         ├── Mobile: ui-ux-designer ↔ tech-lead (Design Pushback 루프, max 2회)\n         │           └── frontend-design (Skill) 포함\n         └── Web:    ui-ux-designer ↔ tech-lead (Design Pushback 루프, max 2회)\n                     └── frontend-design (Skill) 포함\n              │      Fullstack = Server + frontend (by frontendType)\n              │      + API Contract 양방향 검증 (server tech-lead ↔ CTO ↔ frontend tech-lead)\n              │\nDo:      CTO (work-plan) ──→ developers (node/flutter/react)\n              │                    ↔ BLOCKED:QUESTIONS → CTO 라우팅 → 답변자 → 재개\n              │              OR: Ralph Loop (단일 에이전트 자율 반복)\n              │\nAnalyze: gap-detector ↔ CTO (review)\n              │\nIterate: pdca-iterator (if < 90%)  OR: Ralph Loop (FINDINGS 자율 수정)\n              │\nReport:  report-generator ──→ CHANGELOG\n              │\nVerify:  independent-reviewer (optional)\n```\n\n## Bidirectional Communication Reference\n\n전 phase의 양방향 통신 프로토콜 상세는 아래 문서를 참조합니다:\n- **통신 프로토콜**: `.claude/guide/agent-communication-protocol.md`\n- **phase별 상세**: `phases/{phase}.md`\n\n## CTO Involvement (5 Points)\n\n| Phase | CTO Role | Output | 양방향 |\n|-------|---------|--------|--------|\n| **Research** (after research-director) | 아키텍처+복잡도 통합 평가 | PASS/CONCERN/BLOCK + complexity 판정 | BLOCK → clarify 재호출 |\n| **Plan** (after PO, before user review) | ⓪-pre 타당성 스캔 | PASS/WARN/BLOCK 판정 | BLOCK → PO 재호출 |\n| **Plan** (after user review) | ⓪ 플랫폼 라우팅 + Scope Mismatch 감지 | `platform` in status | Mismatch → PO 보완 + 재승인 |\n| **Do** (before devs) | ② 작업 분배 + BLOCKED:QUESTIONS 라우팅 | work-plan.md (플랫폼별) | BLOCKED → 적절한 에이전트 라우팅 |\n| **Analyze** (after gap) | ③ 통합 리뷰 | cto-review.md (플랫폼별) | — |\n"},"lastSynced":"2026-03-07T03:39:19.104Z","agentAnalysis":{"suitability":{"en":"Perfect for Project Management Agents needing streamlined PDCA cycle automation with agent-integrated workflows.","zh":"非常适合需要简化PDCA周期自动化的项目管理代理，并且需要集成代理工作流程。","ja":"プロジェクト管理エージェントがストリームライン化されたPDCAサイクル自動化を必要とする場合に最適です。エージェント統合ワークフローを必要とする場合にも適しています。","ko":"프로젝트 관리 에이전트가 스트림라인化된 PDCA 사이클 자동화를 필요로 할 때 완벽합니다. 에이전트 통합 워크플로가 필요한 경우에도 적합합니다.","es":"Perfecto para Agentes de Gestión de Proyectos que necesitan una automatización del ciclo PDCA optimizada con flujos de trabajo integrados en el agente.","fr":"Parfait pour les agents de gestion de projet nécessitant une automatisation du cycle PDCA optimisée avec des flux de travail intégrés à l''agent.","de":"Perfekt für Projektmanagement-Agenten, die eine optimierte Automatisierung des PDCA-Zyklus mit in den Agenten integrierten Workflows benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Projetos que necessitam de automação de ciclo PDCA simplificado com fluxos de trabalho integrados ao agente.","ru":"Идеально для агентов по управлению проектами, которым требуется автоматизация цикла PDCA с упрощенными рабочими процессами, интегрированными с агентом.","ar":"مثالي لعمليات إدارة المشروع التي تحتاج إلى تلقيم دورة PDCA المبسطة مع سير عمل متكامل مع الوكيل."},"recommendation":{"en":"Empowers agents to automate PDCA phases via bkit.config.json, invoking project agents and managing document output paths with precision, leveraging JSON configuration for seamless integration.","zh":"赋予代理自动化PDCA阶段的能力，通过bkit.config.json调用项目代理，并精确地管理文档输出路径，利用JSON配置实现无缝集成。","ja":"エージェントがPDCA段階を自動化できるようにし、bkit.config.jsonを介してプロジェクトエージェントを呼び出し、文書の出力パスを精密に管理し、JSON設定を利用してシームレスな統合を実現します。","ko":"에이전트가 PDCA 단계를 자동화 할 수 있도록 하며, bkit.config.json을 통해 프로젝트 에이전트를 호출하고 문서 출력 경로를 정밀하게 관리하며, JSON 구성으로 무중단 통합을 구현합니다.","es":"Habilita a los agentes a automatizar las fases del PDCA a través de bkit.config.json, invocando a los agentes del proyecto y administrando los caminos de salida de los documentos con precisión, aprovechando la configuración JSON para una integración sin problemas.","fr":"Permet aux agents d''automatiser les phases du PDCA via bkit.config.json, en invoquant les agents de projet et en gérant les chemins de sortie des documents avec précision, en exploitant la configuration JSON pour une intégration sans problème.","de":"Ermächtigt die Agenten, die Phasen des PDCA über bkit.config.json zu automatisieren, indem sie Projektagenten aufrufen und die Ausgabepfade der Dokumente präzise verwalten, wobei die JSON-Konfiguration für eine nahtlose Integration genutzt wird.","pt":"Habilita os agentes a automatizar fases PDCA por meio do bkit.config.json, invocando agentes de projeto e gerenciando caminhos de saída de documentos com precisão, aproveitando a configuração JSON para integração perfeita.","ru":"Позволяет агентам автоматизировать фазы PDCA через bkit.config.json, вызывая агентов проекта и управляя путями вывода документов с точностью, используя конфигурацию JSON для бесшовной интеграции.","ar":"تمكّن الوكلاء من تلقيم مراحل PDCA من خلال bkit.config.json، واستدعاء وكلاء المشروع وتحديد مسارات إخراج الوثائق بدقة، واستغلال تكوين JSON من أجل التكامل السلس."},"useCases":{"en":["Automating PDCA cycle phases with agent integration","Generating document output paths for plan, design, and analysis documents","Invoking project agents from bkit.config.json for unified workflows"],"zh":["通过代理集成自动化PDCA周期阶段","为计划、设计和分析文档生成文档输出路径","从bkit.config.json调用项目代理以实现统一工作流程"],"ja":["エージェント統合を使用してPDCAサイクル段階を自動化する","計画、設計、分析文書の文書出力パスを生成する","bkit.config.jsonからプロジェクトエージェントを呼び出して統一されたワークフローを実現する"],"ko":["에이전트 통합을 사용하여 PDCA 사이클 단계를 자동화하는 것","계획, 설계 및 분석 문서를 위한 문서 출력 경로를 생성하는 것","bkit.config.json에서 프로젝트 에이전트를 호출하여 통일된 워크플로를 구현하는 것"],"es":["Automatizar las fases del ciclo PDCA con integración de agente","Generar caminos de salida de los documentos para los documentos de planificación, diseño y análisis","Invocar a los agentes del proyecto desde bkit.config.json para flujos de trabajo unificados"],"fr":["Automatiser les phases du cycle PDCA avec une intégration d''agent","Générer les chemins de sortie des documents pour les documents de planification, de conception et d''analyse","Invoquer les agents de projet à partir de bkit.config.json pour des flux de travail unifiés"],"de":["Automatisieren der Phasen des PDCA-Zyklus mit Agent-Integration","Erzeugen der Ausgabepfade für Plan-, Design- und Analyse-Dokumente","Aufrufen von Projektagenten aus bkit.config.json für einheitliche Workflows"],"pt":["Automatizar fases do ciclo PDCA com integração do agente","Gerar caminhos de saída de documentos para planos, design e documentos de análise","Invocar agentes de projeto a partir do bkit.config.json para fluxos de trabalho unificados"],"ru":["Автоматизация фаз цикла PDCA с интеграцией агента","Генерация путей вывода документов для планов, дизайна и документов анализа","Вызов агентов проекта из bkit.config.json для унифицированных рабочих процессов"],"ar":["تلقيم مراحل دورة PDCA مع إدماج الوكيل","توليد مسارات إخراج الوثائق لخطط وتصاميم ووثائق تحليل","استدعاء وكلاء المشروع من bkit.config.json من أجل سير عمل موحد"]},"limitations":{"en":["Requires bkit.config.json configuration","Dependent on agent-integrated workflow capabilities"],"zh":["需要bkit.config.json配置","依赖于代理集成工作流功能"],"ja":["bkit.config.jsonの設定が必要","エージェント統合ワークフロー機能に依存する"],"ko":["bkit.config.json 구성이 필요함","에이전트 통합 워크플로 기능에 의존함"],"es":["Requiere configuración de bkit.config.json","Dependiente de las capacidades de los flujos de trabajo integrados en el agente"],"fr":["Nécessite une configuration de bkit.config.json","Dépend des capacités des flux de travail intégrés à l''agent"],"de":["Benötigt bkit.config.json-Konfiguration","Abhängig von den Fähigkeiten der in den Agenten integrierten Workflows"],"pt":["Exige configuração do bkit.config.json","Dependente das capacidades de fluxo de trabalho integrado ao agente"],"ru":["Требует настройки bkit.config.json","Зависит от возможностей рабочего процесса, интегрированного с агентом"],"ar":["يتطلب تكوين bkit.config.json","يعتمد على إمكانيات سير العمل المتكامل مع الوكيل"]},"version":4},"contentHash":"84bfbb16641b6218f998bd149a198c5d4c20166beb4951e1cb207e3bea6a26be","qualityScore":57}');
