INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gaegulgaegul/gaegulzip/pdca', 'pdca', 'gaegulgaegul', 'gaegulzip', 'community', 'pdca gaegulgaegul gaegulzip community The pdca skill manages the PDCA cycle with an agent-integrated workflow, automating phases via bkit.config.json. It benefits developers by streamlining project workflows PDCA技能提供了统一的工作流管理，通过agent-integrated workflow自动调用项目代理 PDCAスキルは統一されたワークフローマネジメントを提供し、AIエージェントワークフローを介してプロジェクトエージェントを自動的に呼び出します PDCA 스킬은 통합 워크플로 관리를 제공하며 에이전트 통합 워크플로를 통해 프로젝트 에이전트를 자동으로 호출합니다 El skill de PDCA ofrece un flujo de trabajo integrado de agentes para gestionar el ciclo de PDCA y personalizar la salida de documentos con bkit.config.json. Le skill PDCA propose un flux de travail d''agents intégrés pour gérer le cycle PDCA et personnaliser la sortie de documents avec bkit.config.json. Das PDCA-Skill bietet einen integrierten Agenten-Workflow, um den PDCA-Zyklus zu verwalten und die Dokumentenausgabe mit bkit.config.json anzupassen. O PDCA é uma habilidade que gerencia o ciclo de planejamento, desenvolvimento, checagem e ação com fluxo de trabalho integrado PDCA - это навык, который управляет циклом планирования, разработки, проверки и действия с интегрированным рабочим процессом PDCA هو مهارة لإدارة دورة التخطيط والتنمية والتحقق والعمل مع تدفق عمل متكامل how to use pdca pdca setup guide pdca vs agile what is pdca pdca install pdca alternative pdca cycle management bkit.config.json configuration ai agent workflow automation PDCA技能 AI智能代理 agent-integrated workflow bkit.config.json 输出文档路径 状态消息 文档输出语言 Automates PDCA phases with agent-integrated workflow Configures context.defaultLanguage for output consistency Supports customizable document output paths via pdca.planDocPaths and pdca.designDocPaths Integrates with bkit.config.json for seamless project agent invocation Enables phase-specific procedures via the phases/ directory pdca is a unified skill for managing the PDCA cycle, integrating project agents from bkit.config.json for automated workflow');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('B4san/Calix-Pass/acfm-spec-workflow', 'community', 'B4san', 'Calix-Pass', 'B4san/Calix-Pass', 'acfm-spec-workflow', 0, 0, 57, '2026-02-21T18:31:39Z', '2026-03-07T13:06:58.316Z', '6660584e6e3ef12e67db496cc3b46e860ad160b90610379d153eb9e77e1660bd', '{"id":"B4san/Calix-Pass/acfm-spec-workflow","name":"acfm-spec-workflow","description":{"en":"The acfm-spec-workflow skill helps developers initialize and manage spec-driven development workflows using the AC Framework CLI. It benefits developers working on new or existing projects.","zh":"AC Framework Spec-Driven Workflow 是一个开源的密码管理器，使用 AC 框架构建","ja":"AC Framework Spec-Driven Workflow は、AC Framework CLI を使用して開発ワークフローを管理するためのオープンソースのパスワードマネージャーです","ko":"AC Framework Spec-Driven Workflow는 AC 프레임워크를 기반으로하는 오픈소스 패스워드 관리 도구입니다","es":"acfm-spec-workflow es una herramienta de gestión de contraseñas de código abierto construida con AC Framework, que facilita la configuración y gestión de flujos de trabajo de especificaciones","fr":"acfm-spec-workflow est un gestionnaire de mots de passe open-source construit avec AC Framework, qui facilite la configuration et la gestion des flux de travail de spécifications","de":"acfm-spec-workflow ist ein Open-Source-Passwort-Manager, der mit AC Framework erstellt wurde und die Konfiguration und Verwaltung von Spezifikations-Workflows erleichtert","pt":"O ACFM é um framework de código aberto para gerenciamento de senhas, que permite configurar e gerenciar fluxos de trabalho de desenvolvimento orientados a especificações.","ru":"ACFM - это открытый фреймворк для управления паролями, который позволяет настроить и управлять рабочими потоками разработки на основе спецификаций.","ar":"ACFM هو إطار عمل مفتوح المصدر لإدارة كلمات المرور، يسمح بضبط و إدارة تدفقات العمل الموجهة بالمواصفات."},"seo":{"title":{"en":"acfm-spec-workflow: Spec-Driven Workflow Setup Guide | AI...","zh":"AC Framework Spec-Driven Workflow 设置指南","ja":"AC Framework Spec-Driven Workflow のベストプラクティス - AIエージェント","ko":"AC Framework Spec-Driven Workflow 가이드 - AI 도구","es":"Guía de Configuración para acfm-spec-workflow con AC Fram...","fr":"Guide de Mise en Route pour acfm-spec-workflow avec AC Fr...","de":"Einrichtungsleitfaden für acfm-spec-workflow mit AC Frame...","pt":"Guia de Configuração do Fluxo de Trabalho ACFM","ru":"Настройка Рабочего Потока ACFM: Полное Руководство ИИ Аге...","ar":"دليل إعداد Fluxo de Trabalho ACFM باستخدام أدوات الذكاء ا..."},"description":{"en":"Learn how to initialize and manage spec-driven development workflows with acfm-spec-workflow. Get started with the AC Framework CLI today!","zh":"了解如何使用 AC Framework CLI 初始化和管理规格驱动的开发工作流","ja":"AC Framework Spec-Driven Workflow を使用して開発プロセスを効率化する - AIエージェントの活用","ko":"AC Framework CLI를 사용하여 규格 주도 개발 워크플로를 초기화하고 관리하는 방법","es":"Aprende a configurar y gestionar flujos de trabajo de especificaciones con acfm-spec-workflow y AC Framework para proyectos de desarrollo","fr":"Découvrez comment configurer et gérer les flux de travail de spécifications avec acfm-spec-workflow et AC Framework pour les projets de développement","de":"Erfahren Sie, wie Sie Spezifikations-Workflows mit acfm-spec-workflow und AC Framework für Entwicklungsprojekte konfigurieren und verwalten","pt":"Aprenda a configurar e gerenciar fluxos de trabalho de desenvolvimento orientados a especificações com o ACFM","ru":"Узнайте, как настроить и управлять рабочими потоками разработки на основе спецификаций с помощью ACFM и ИИ Агентов","ar":"تعلم كيفية ضبط و إدارة تدفقات العمل الموجهة بالمواصفات باستخدام ACFM و أدوات الذكاء الاصطناعي"},"definition":{"en":"acfm-spec-workflow is an open-source password manager built with the AC-framework, providing a spec-driven workflow guide for developers.","zh":"AC Framework Spec-Driven Workflow 是一种使用 AC 框架 CLI 管理规格驱动的开发工作流的方法","ja":"AC Framework Spec-Driven Workflow は、AC Framework CLI を使用して開発ワークフローを管理するための手法です","ko":"AC Framework Spec-Driven Workflow는 AC 프레임워크 CLI를 사용하여 규格 주도 개발 워크플로를 관리하는 방식입니다","es":"acfm-spec-workflow es una herramienta de código abierto que utiliza AC Framework para gestionar flujos de trabajo de especificaciones","fr":"acfm-spec-workflow est un outil open-source qui utilise AC Framework pour gérer les flux de travail de spécifications","de":"acfm-spec-workflow ist ein Open-Source-Tool, das AC Framework verwendet, um Spezifikations-Workflows zu verwalten","pt":"O que é ACFM? É um framework de código aberto para gerenciamento de senhas e fluxos de trabalho de desenvolvimento.","ru":"Что такое ACFM? Это открытый фреймворк для управления паролями и рабочими потоками разработки.","ar":"ما هو ACFM? هو إطار عمل مفتوح المصدر لإدارة كلمات المرور و تدفقات العمل."},"features":{"en":["Initializes spec workflow using the AC Framework CLI (acfm)","Checks if specs are initialized for existing projects","Creates new changes or features using the spec-driven workflow","Manages `.acfm/` and `openspec/` directories","Provides understanding of CLI commands for spec-driven development"],"zh":["使用 AC Framework CLI 初始化和管理规格驱动的开发工作流","支持创建新项目和检查现有项目的规格","提供 `.acfm/` 和 `openspec/` 目录的选择","集成了 AC 框架的 CLI 功能"],"ja":["AC Framework CLI を使用して開発ワークフローを初期化および管理","新しいプロジェクトの作成と既存のプロジェクトの仕様の確認をサポート","`.acfm/` と `openspec/` ディレクトリの選択を提供","AC Framework の CLI 機能と統合"],"ko":["AC 프레임워크 CLI를 사용하여 규格 주도 개발 워크플로를 초기화하고 관리","새 프로젝트 생성과 기존 프로젝트의 규格 확인을 지원","`.acfm/`와 `openspec/` 디렉토리의 선택을 제공","AC 프레임워크의 CLI 기능과 통합"],"es":["Inicialización de flujos de trabajo de especificaciones con AC Framework","Gestión de especficiaciones con el CLI de AC Framework (acfm)","Compatibilidad con directorios .acfm/ y openspec/","Integración con el flujo de trabajo de desarrollo de AC Framework","Soporte para la creación de nuevos cambios y características","Verificación de la inicialización de especficiaciones en proyectos existentes"],"fr":["Initialisation des flux de travail de spécifications avec AC Framework","Gestion des spécifications avec le CLI d''AC Framework (acfm)","Compatibilité avec les répertoires .acfm/ et openspec/","Intégration avec le flux de travail de développement d''AC Framework","Prise en charge de la création de nouveaux changements et fonctionnalités","Vérification de l''initialisation des spécifications dans les projets existants"],"de":["Initialisierung von Spezifikations-Workflows mit AC Framework","Verwaltung von Spezifikationen mit dem AC Framework-CLI (acfm)","Unterstützung für .acfm/- und openspec-Verzeichnisse","Integration mit dem Entwicklungs-Workflow von AC Framework","Unterstützung für die Erstellung neuer Änderungen und Funktionen","Überprüfung der Initialisierung von Spezifikationen in bestehenden Projekten"],"pt":["Inicialização do fluxo de trabalho de desenvolvimento orientado a especificações","Gerenciamento de specs com o ACFM","Criação de novas alterações/recursos usando o fluxo de trabalho de especificações","Utilização do CLI do ACFM para gerenciar o fluxo de trabalho","Escolha entre os diretórios `.acfm/` e `openspec/`"],"ru":["Инициализация рабочего потока разработки на основе спецификаций","Управление спецификациями с помощью ACFM","Создание новых изменений/функций с помощью рабочего потока спецификаций","Использование CLI ACFM для управления рабочим потоком","Выбор между директориями `.acfm/` и `openspec/`"],"ar":["_initializer التدفق العمل الموجه بالمواصفات","إدارة المواصفات مع ACFM","إنشاء التغييرات/الميزات الجديدة باستخدام تدفق العمل الموجه بالمواصفات","استخدام CLI ACFM لإدارة التدفق العمل","اختيار بين الدلائل `.acfm/` و `openspec/`"]},"keywords":{"en":["how to use acfm-spec-workflow","acfm-spec-workflow setup guide","acfm-spec-workflow alternative","acfm-spec-workflow vs AC-framework","spec-driven development workflow","AC Framework CLI tutorial"],"zh":["AC Framework Spec-Driven Workflow","规格驱动的开发工作流","AC 框架 CLI","密码管理器","开源工具","AI 工具","开发效率","规格管理"],"ja":["AC Framework Spec-Driven Workflow","開発ワークフロー","AC Framework CLI","パスワードマネージャー","オープンソースツール","AIエージェント","開発効率","仕様管理"],"ko":["AC Framework Spec-Driven Workflow","규格 주도 개발 워크플로","AC 프레임워크 CLI","패스워드 관리 도구","오픈소스 도구","AI 도구","개발 효율","규格 관리"],"es":["acfm-spec-workflow","AC Framework","gestión de contraseñas","flujos de trabajo de especificaciones","desarrollo de software","herramientas de desarrollo","CLI","especificaciones","código abierto"],"fr":["acfm-spec-workflow","AC Framework","gestion de mots de passe","flux de travail de spécifications","développement de logiciels","outils de développement","CLI","spécifications","code open-source"],"de":["acfm-spec-workflow","AC Framework","Passwort-Manager","Spezifikations-Workflows","Software-Entwicklung","Entwicklungs-Tools","CLI","Spezifikationen","Open-Source-Code"],"pt":["ACFM","fluxo de trabalho de desenvolvimento","especificações","gerenciamento de senhas","CLI","desenvolvimento de software","framework de código aberto","guia de configuração"],"ru":["ACFM","рабочий поток разработки","спецификации","управление паролями","CLI","разработка программного обеспечения","открытый фреймворк","руководство по настройке","ИИ Агенты"],"ar":["ACFM","تدفق العمل","المواصفات","إدارة كلمات المرور","CLI","تطوير البرمجيات","إطار العمل مفتوح المصدر","دليل الإعداد","أدوات الذكاء الاصطناعي"]}},"owner":"B4san","repo":"Calix-Pass","repoPath":"B4san/Calix-Pass","stars":0,"forks":0,"updatedAt":"2026-02-21T18:31:39Z","topics":[],"category":"community","skillMd":{"name":"acfm-spec-workflow","description":"Initialize and manage AC Framework spec-driven workflows using acfm CLI. Use when setting up spec workflows, checking project status, creating changes, or understanding the .acfm/ vs openspec/ directory structures. Essential first step before using any OpenSpec skills.","bodyPreview":"# AC Framework Spec-Driven Workflow\n\nGuide for initializing and managing spec-driven development workflows using the AC Framework CLI (`acfm`).\n\n## When to use this skill\n\nUse this skill when:\n- **Starting a new project** and need to initialize the spec workflow\n- **Working on an existing project** and need to check if specs are initialized\n- **Creating a new change/feature** using the spec-driven workflow\n- **Unsure whether to use `.acfm/` or `openspec/`** directories\n- **Need to understand CLI","body":"# AC Framework Spec-Driven Workflow\n\nGuide for initializing and managing spec-driven development workflows using the AC Framework CLI (`acfm`).\n\n## When to use this skill\n\nUse this skill when:\n- **Starting a new project** and need to initialize the spec workflow\n- **Working on an existing project** and need to check if specs are initialized\n- **Creating a new change/feature** using the spec-driven workflow\n- **Unsure whether to use `.acfm/` or `openspec/`** directories\n- **Need to understand CLI commands** for spec management\n- **Migrating from legacy openspec/ to new .acfm/ structure**\n\n## Quick start\n\n```bash\n# Check if project is initialized\nacfm spec status --json\n\n# Initialize new project (creates .acfm/)\nacfm spec init\n\n# Create a new change\nacfm spec new my-feature --json\n\n# Get instructions for next artifact\nacfm spec instructions proposal --change my-feature --json\n```\n\n## Directory Structure\n\n### NEW (Default): `.acfm/` directory\n\n```\nproject-root/\n├── .acfm/                    # NEW: Default spec directory\n│   ├── config.yaml           # Project configuration\n│   ├── specs/                # Shared specs\n│   └── changes/              # Active changes\n│       ├── archive/          # Archived changes\n│       └── my-feature/       # Individual change\n│           ├── .openspec.yaml\n│           ├── proposal.md\n│           ├── design.md\n│           ├── tasks.md\n│           └── specs/\n```\n\n### LEGACY: `openspec/` directory\n\n```\nproject-root/\n├── openspec/                 # LEGACY: Still fully supported\n│   ├── config.yaml\n│   ├── specs/\n│   └── changes/\n```\n\n**Priority**: CLI automatically uses `.acfm/` if it exists, otherwise falls back to `openspec/`.\n\n## Instructions\n\n### Step 1: Check initialization status\n\nAlways start by checking if the project is initialized:\n\n```bash\nacfm spec status --json\n```\n\n**If not initialized** (`\"initialized\": false`):\n- Proceed to Step 2 to initialize\n\n**If initialized** (`\"initialized\": true`):\n- Note the `dirName` field (either `.acfm` or `openspec`)\n- Proceed to Step 3 to create changes\n\n### Step 2: Initialize the project\n\nFor new projects:\n\n```bash\nacfm spec init\n```\n\nThis creates:\n- `.acfm/config.yaml` - Project configuration\n- `.acmf/specs/` - Shared specifications\n- `.acfm/changes/` - Active changes directory\n\n**Legacy support**: If the project already has `openspec/`, it will be detected automatically. No need to migrate unless desired.\n\n### Step 3: Create a change\n\n```bash\nacfm spec new <change-name> --json\n```\n\nExample:\n```bash\nacfm spec new user-authentication --json\n```\n\n**Output**:\n```json\n{\n  \"changeDir\": \"/project/.acfm/changes/user-authentication\",\n  \"schemaName\": \"spec-driven\",\n  \"artifacts\": [\"proposal\", \"specs\", \"design\", \"tasks\"]\n}\n```\n\n### Step 4: Get instructions for artifacts\n\nEach artifact has specific instructions:\n\n```bash\n# Get instructions for proposal\nacfm spec instructions proposal --change <name> --json\n\n# Get instructions for design\nacfm spec instructions design --change <name> --json\n\n# Get instructions for tasks\nacfm spec instructions tasks --change <name> --json\n\n# Get apply instructions (when ready to implement)\nacfm spec instructions apply --change <name> --json\n```\n\n### Step 5: Check status\n\nMonitor progress:\n\n```bash\n# Status of specific change\nacfm spec status --change <name> --json\n\n# List all changes\nacfm spec list --json\n```\n\n### Step 6: Archive completed changes\n\n```bash\nacfm spec archive <change-name>\n```\n\n## CLI Command Reference\n\n### Initialization\n- `acfm spec init [--json]` - Initialize spec directory\n- `acfm spec status [--json]` - Check initialization status\n\n### Change Management\n- `acfm spec new <name> [--json]` - Create new change\n- `acfm spec list [--json]` - List all changes\n- `acfm spec status --change <name> [--json]` - Check change status\n- `acfm spec archive <name> [--json]` - Archive completed change\n\n### Instructions\n- `acfm spec instructions <artifact> --change <name> [--json]` - Get artifact instructions\n- `acfm spec schemas [--json]` - List available schemas\n- `acfm spec validate <name> [--json]` - Validate change structure\n\n## Common scenarios\n\n### Scenario: New project setup\n\n```bash\n# 1. Check status\nacfm spec status --json\n\n# 2. Initialize\nacfm spec init\n\n# 3. Create first change\nacfm spec new initial-setup --json\n\n# 4. Get proposal instructions\nacfm spec instructions proposal --change initial-setup --json\n```\n\n### Scenario: Legacy project (openspec/)\n\n```bash\n# CLI automatically detects openspec/ directory\nacfm spec status --json\n# Output: { \"initialized\": true, \"dirName\": \"openspec\", ... }\n\n# Create change in openspec/\nacfm spec new legacy-feature --json\n# Creates: openspec/changes/legacy-feature/\n```\n\n### Scenario: Mixed directories\n\nIf both `.acfm/` and `openspec/` exist:\n- CLI uses `.acfm/` (higher priority)\n- Changes are created in `.acfm/changes/`\n\nTo use `openspec/` temporarily:\n```bash\nmv .acfm/ .acfm-backup/\n# Now CLI will use openspec/\n```\n\n## Best practices\n\n1. **Always use CLI commands** - Don''t manually create directories\n2. **Use `--json` flag** for programmatic parsing\n3. **Check initialization first** - Before creating changes\n4. **Let CLI handle paths** - Don''t hardcode `.acfm/` or `openspec/`\n5. **Archive completed changes** - Keeps active list clean\n\n## Troubleshooting\n\n### \"Spec system not initialized\"\n\n```bash\n# Solution\nacfm spec init\n```\n\n### Changes not appearing\n\n```bash\n# Check which directory is being used\nacfm spec status --json\n# Look at \"dirName\" field\n\n# List both directories\nls -la .acfm/changes/ 2>/dev/null || echo \"No .acfm/\"\nls -la openspec/changes/ 2>/dev/null || echo \"No openspec/\"\n```\n\n### Wrong directory detected\n\n```bash\n# Force use of openspec/ by renaming .acfm/\nmv .acfm/ .acfm-backup/\n\n# Or force use of .acfm/ by renaming openspec/\nmv openspec/ openspec-backup/\n```\n\n## Requirements\n\n- AC Framework CLI (`acfm`) must be installed\n- Node.js >= 18.0.0\n\n## Compatibility\n\n- ✅ Works with both `.acfm/` (new) and `openspec/` (legacy)\n- ✅ All existing OpenSpec skills continue to work\n- ✅ No migration required for legacy projects\n- ✅ Optional migration path available\n\n## See also\n\n- Use `openspec-new-change` skill after initialization to create structured changes\n- Use `openspec-continue-change` to work on existing changes\n- Use `openspec-apply-change` to implement tasks\n"},"lastSynced":"2026-03-07T13:06:58.316Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing to manage spec-driven workflows with the AC Framework CLI","zh":"非常适合需要使用 AC Framework CLI 管理基于规格的工作流的开发代理","ja":"AC Framework CLI を使用して規格ベースのワークフローを管理する必要がある開発エージェントに最適","ko":"AC Framework CLI를 사용하여 사양 기반 워크플로를 관리해야 하는 개발 에이전트에게 적합","es":"Perfecto para Agentes de Desarrollo que necesitan gestionar flujos de trabajo impulsados por especificaciones con la CLI del Marco AC","fr":"Parfait pour les agents de développement ayant besoin de gérer des flux de travail basés sur des spécifications avec la CLI du Framework AC","de":"Perfekt für Entwicklungsmittel, die spezifikationsgetriebene Workflows mit der AC-Framework-CLI verwalten müssen","pt":"Perfeito para Agentes de Desenvolvimento que precisam gerenciar fluxos de trabalho baseados em especificações com o CLI do Framework AC","ru":"Идеально подходит для агентов разработки, которым необходимо управлять рабочими процессами, основанными на спецификациях, с помощью CLI фреймворка AC","ar":"مثالي للوكلاء التطويريين الذين يحتاجون إلى إدارة تدفقات العمل القائمة على المواصفات مع CLI إطار العمل AC"},"recommendation":{"en":"Empowers agents to initialize and manage spec-driven development workflows using the AC Framework CLI, providing benefits such as spec initialization and management via `acfm` commands, and guiding decisions between `.acfm/` or `openspec/` directories","zh":"赋予代理初始化和管理基于规格的开发工作流的能力，使用 AC Framework CLI 提供诸如通过 `acfm` 命令进行规格初始化和管理等益处，并指导 `.acfm/` 或 `openspec/` 目录之间的决策","ja":"エージェントに規格ベースの開発ワークフローを初期化および管理する能力を与え、AC Framework CLI を使用して `acfm` コマンドによる規格の初期化および管理などの利点を提供し、`.acfm/` または `openspec/` ディレクトリ間の決定をガイドする","ko":"에이전트에게 사양 기반 개발 워크플로를 초기화하고 관리하는 능력을 부여하며, AC Framework CLI를 사용하여 `acfm` 명령을 통해 사양 초기화 및 관리와 같은 이점을 제공하고 `.acfm/` 또는 `openspec/` 디렉토리 사이의 결정에 대한 지침을 제공","es":"Habilita a los agentes a inicializar y gestionar flujos de trabajo de desarrollo basados en especificaciones utilizando la CLI del Marco AC, proporcionando beneficios como la inicialización y gestión de especificaciones a través de comandos `acfm`, y guiando decisiones entre directorios `.acfm/` o `openspec/`","fr":"Permet aux agents d''initialiser et de gérer des flux de travail de développement basés sur des spécifications en utilisant la CLI du Framework AC, offrant des avantages tels que l''initialisation et la gestion des spécifications via des commandes `acfm`, et guidant les décisions entre les répertoires `.acfm/` ou `openspec/`","de":"Ermächtigt die Agenten, spezifikationsgetriebene Entwicklungswerkflüsse mit der AC-Framework-CLI zu initialisieren und zu verwalten, und bietet Vorteile wie die Initialisierung und Verwaltung von Spezifikationen über `acfm`-Befehle sowie die Entscheidungsfindung zwischen `.acfm/`- oder `openspec/`-Verzeichnissen","pt":"Habilita os agentes a inicializar e gerenciar fluxos de trabalho de desenvolvimento baseados em especificações usando o CLI do Framework AC, fornecendo benefícios como inicialização e gerenciamento de especificações via comandos `acfm` e orientando decisões entre diretórios `.acfm/` ou `openspec/`","ru":"Наделяет агентов возможностью инициализировать и управлять рабочими процессами разработки, основанными на спецификациях, с помощью CLI фреймворка AC, обеспечивая такие преимущества, как инициализация и управление спецификациями через команды `acfm`, а также руководство при принятии решений между директориями `.acfm/` или `openspec/`","ar":"يتمكّن الوكلاء من 초기تها وإدارة تدفقات العمل التطويرية القائمة على المواصفات باستخدام CLI إطار العمل AC، وتوفير فوائد مثل 초기تها وإدارة المواصفات عبر أوامر `acfm`، وتوجيه القرارات بين المجلدات `.acfm/` أو `openspec/`"},"useCases":{"en":["Initializing spec workflows for new projects","Checking spec initialization for existing projects","Creating new changes or features using spec-driven workflows"],"zh":["为新项目初始化规格工作流","检查现有项目的规格初始化","使用规格驱动工作流创建新更改或功能"],"ja":["新規プロジェクトの規格ワークフローを初期化する","既存のプロジェクトの規格初期化を確認する","規格駆動のワークフローを使用して新しい変更または機能を作成する"],"ko":["새 프로젝트를 위한 사양 워크플로 초기화","기존 프로젝트의 사양 초기화를 확인","사양 기반 워크플로를 사용하여 새로운 변경 또는 기능을 생성"],"es":["Inicializar flujos de trabajo de especificaciones para nuevos proyectos","Comprobar la inicialización de especificaciones para proyectos existentes","Crear nuevos cambios o características utilizando flujos de trabajo impulsados por especificaciones"],"fr":["Initialiser des flux de travail de spécifications pour de nouveaux projets","Vérifier l''initialisation des spécifications pour les projets existants","Créer de nouvelles modifications ou fonctionnalités en utilisant des flux de travail basés sur des spécifications"],"de":["Initialisieren von Spezifikations-Workflows für neue Projekte","Überprüfen der Spezifikationsinitialisierung für bestehende Projekte","Erstellen neuer Änderungen oder Funktionen unter Verwendung von spezifikationsgetriebenen Workflows"],"pt":["Inicializar fluxos de trabalho de especificações para novos projetos","Verificar a inicialização de especificações para projetos existentes","Criar novas alterações ou recursos usando fluxos de trabalho baseados em especificações"],"ru":["Инициализация рабочих процессов спецификаций для новых проектов","Проверка инициализации спецификаций для существующих проектов","Создание новых изменений или функций с помощью рабочих процессов, основанных на спецификациях"],"ar":["ت初يته تدفقات العمل للمواصفات لمشاريع جديدة","تحقق من 초기تها للمواصفات لمشاريع موجودة","إنشاء تغييرات أو ميزات جديدة باستخدام تدفقات العمل القائمة على المواصفات"]},"limitations":{"en":["Requires AC Framework CLI (`acfm`) installation","Limited to spec-driven development workflows"],"zh":["需要 AC Framework CLI (`acfm`) 安装","仅限于规格驱动的开发工作流"],"ja":["AC Framework CLI (`acfm`) のインストールが必要","規格駆動の開発ワークフローに限定される"],"ko":["AC Framework CLI (`acfm`) 설치 필요","사양 기반 개발 워크플로에만 제한"],"es":["Requiere la instalación de la CLI del Marco AC (`acfm`)","Limitado a flujos de trabajo de desarrollo impulsados por especificaciones"],"fr":["Nécessite l''installation de la CLI du Framework AC (`acfm`)","Limité aux flux de travail de développement basés sur des spécifications"],"de":["Benötigt die Installation der AC-Framework-CLI (`acfm`)","Begrenzt auf spezifikationsgetriebene Entwicklungswerkflüsse"],"pt":["Exige a instalação do CLI do Framework AC (`acfm`)","Limitado a fluxos de trabalho de desenvolvimento baseados em especificações"],"ru":["Требует установки CLI фреймворка AC (`acfm`)","Ограничен рабочими процессами разработки, основанными на спецификациях"],"ar":["يتطلب تثبيت CLI إطار العمل AC (`acfm`)","محدود بتدفقات العمل التطويرية القائمة على المواصفات"]},"version":4},"contentHash":"6660584e6e3ef12e67db496cc3b46e860ad160b90610379d153eb9e77e1660bd","qualityScore":57}');
