INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('B4san/Calix-Pass/acfm-spec-workflow', 'acfm-spec-workflow', 'B4san', 'Calix-Pass', 'community', 'acfm-spec-workflow B4san Calix-Pass community The acfm-spec-workflow skill helps developers initialize and manage spec-driven development workflows using the AC Framework CLI. It benefits developers working on new or existing projects. AC Framework Spec-Driven Workflow 是一个开源的密码管理器，使用 AC 框架构建 AC Framework Spec-Driven Workflow は、AC Framework CLI を使用して開発ワークフローを管理するためのオープンソースのパスワードマネージャーです AC Framework Spec-Driven Workflow는 AC 프레임워크를 기반으로하는 오픈소스 패스워드 관리 도구입니다 acfm-spec-workflow es una herramienta de gestión de contraseñas de código abierto construida con AC Framework, que facilita la configuración y gestión de flujos de trabajo de especificaciones acfm-spec-workflow est un gestionnaire de mots de passe open-source construit avec AC Framework, qui facilite la configuration et la gestion des flux de travail de spécifications acfm-spec-workflow ist ein Open-Source-Passwort-Manager, der mit AC Framework erstellt wurde und die Konfiguration und Verwaltung von Spezifikations-Workflows erleichtert O ACFM é um framework de código aberto para gerenciamento de senhas, que permite configurar e gerenciar fluxos de trabalho de desenvolvimento orientados a especificações. ACFM - это открытый фреймворк для управления паролями, который позволяет настроить и управлять рабочими потоками разработки на основе спецификаций. ACFM هو إطار عمل مفتوح المصدر لإدارة كلمات المرور، يسمح بضبط و إدارة تدفقات العمل الموجهة بالمواصفات. how to use acfm-spec-workflow acfm-spec-workflow setup guide acfm-spec-workflow alternative acfm-spec-workflow vs AC-framework spec-driven development workflow AC Framework CLI tutorial AC Framework Spec-Driven Workflow 规格驱动的开发工作流 AC 框架 CLI 密码管理器 开源工具 AI 工具 开发效率 规格管理 Initializes spec workflow using the AC Framework CLI (acfm) Checks if specs are initialized for existing projects Creates new changes or features using the spec-driven workflow Manages `.acfm/` and `openspec/` directories Provides understanding of CLI commands for spec-driven development acfm-spec-workflow is an open-source password manager built with the AC-framework, providing a spec-driven workflow guide for developers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('corbanb/x4-mono/add-router', 'community', 'corbanb', 'x4-mono', 'corbanb/x4-mono', 'add-router', 0, 1, 57, '2026-02-23T23:48:22Z', '2026-03-07T03:53:22.078Z', 'cffaddc6a7fa419185c9fe7c8bd6af9c8bca11c8d721f961d67f942ce54c146d', '{"id":"corbanb/x4-mono/add-router","name":"add-router","description":{"en":"The add-router skill generates a new tRPC router with CRUD procedures for Next.js, React Native, Electron, and Hono.js. It benefits developers by streamlining API development.","zh":"add-router技能用于创建新的tRPC路由器，支持Next.js、React Native、Electron和Hono.js","ja":"add-routerスキルは、新しいtRPCルーターを作成するために使用され、Next.js、React Native、Electron、Hono.jsをサポートします","ko":"add-router 스킬은 새로운 tRPC 라우터를 생성하는 데 사용되며 Next.js, React Native, Electron, Hono.js를 지원합니다","es":"add-router es una herramienta para crear enrutadores tRPC con procedimientos CRUD y metadatos OpenAPI para proyectos x4-mono","fr":"add-router est un outil pour créer des routeurs tRPC avec des procédures CRUD et des métadonnées OpenAPI pour les projets x4-mono","de":"add-router ist ein Tool zum Erstellen von tRPC-Routern mit CRUD-Verfahren und OpenAPI-Metadaten für x4-mono-Projekte","pt":"O add-router é uma ferramenta para criar rotas personalizadas para Next.js, React Native e Electron, com suporte a tRPC e OpenAPI.","ru":"ИИ Агент Add Router позволяет создавать маршрутизаторы с поддержкой tRPC, OpenAPI и тестированием для x4-mono.","ar":"إضافة روتر هي أداة لإنشاء маршروتات مخصصة لتطبيقات Next.js و React Native و Electron مع دعم tRPC و OpenAPI."},"seo":{"title":{"en":"add-router: Setup Guide for Next.js and tRPC | AI Agent S...","zh":"添加路由器设置指南 - Next.js 和 React Native","ja":"ルーター追加設定ガイド - Next.js と React Native","ko":"라우터 추가 설정 가이드 - Next.js 및 React Native","es":"Guía de configuración de add-router para Next.js y React","fr":"Guide d''installation d''add-router pour Next.js et React","de":"Einrichtungsanleitung für add-router mit Next.js und React","pt":"Guia de Configuração do Add Router para Next.js e React","ru":"ИИ Агент Add Router: Настройка Маршрутизатора для tRPC","ar":"إضافة روتر للتنقل في تطبيقات Next.js و React Native"},"description":{"en":"Discover how to create a new tRPC router with CRUD procedures and OpenAPI meta using the add-router skill. Get started with our setup guide today!","zh":"使用add-router技能创建新的tRPC路由器，包括CRUD过程、OpenAPI元数据和测试文件","ja":"add-routerスキルを使用して、新しいtRPCルーターを作成します。CRUDプロセス、OpenAPIメタデータ、テストファイルを含みます","ko":"add-router 스킬을 사용하여 새로운 tRPC 라우터를 생성합니다. CRUD 프로세스, OpenAPI 메타데이터, 테스트 파일을 포함합니다","es":"Aprende a crear un enrutador tRPC con procedimientos CRUD y metadatos OpenAPI para tu proyecto x4-mono con add-router","fr":"Découvrez comment créer un routeur tRPC avec des procédures CRUD et des métadonnées OpenAPI pour votre projet x4-mono avec add-router","de":"Erfahren Sie, wie Sie einen tRPC-Router mit CRUD-Verfahren und OpenAPI-Metadaten für Ihr x4-mono-Projekt mit add-router erstellen","pt":"Aprenda a criar rotas personalizadas com o add-router para Next.js, React Native e Electron, com suporte a tRPC e OpenAPI","ru":"Используйте ИИ Агент Add Router для создания маршрутизаторов с поддержкой tRPC, OpenAPI и тестированием для x4-mono","ar":"استخدم إضافة روتر لإنشاء маршروتات مخصصة لتطبيقات Next.js و React Native و Electron مع دعم tRPC و OpenAPI"},"definition":{"en":"add-router is a mono repo skill for creating tRPC routers with CRUD procedures, OpenAPI meta, and test files for x4-mono applications.","zh":"add-router是一种用于创建新的tRPC路由器的技能，包括CRUD过程和OpenAPI元数据","ja":"add-routerは、新しいtRPCルーターを作成するスキルです。CRUDプロセスとOpenAPIメタデータを含みます","ko":"add-router는 새로운 tRPC 라우터를 생성하는 스킬입니다. CRUD 프로세스와 OpenAPI 메타데이터를 포함합니다","es":"add-router es una herramienta de desarrollo para crear enrutadores personalizados con procedimientos CRUD","fr":"add-router est un outil de développement pour créer des routeurs personnalisés avec des procédures CRUD","de":"add-router ist ein Entwicklungstool zum Erstellen von benutzerdefinierten Routern mit CRUD-Verfahren","pt":"O add-router é uma ferramenta de código aberto para criar rotas personalizadas para aplicações web e móveis","ru":"ИИ Агент Add Router - это инструмент для создания маршрутизаторов для веб- и мобильных приложений","ar":"إضافة روتر هي أداة مفتوحة المصدر لإنشاء маршروتات مخصصة لتطبيقات الويب وجوال"},"features":{"en":["Generates tRPC routers with CRUD procedures for Next.js, React Native, Electron, and Hono.js","Creates OpenAPI meta files for API documentation","Supports test file generation for x4-mono applications","Allows for customizable auth levels, including public, protected, and admin","Enables ownership checks for secure data management"],"zh":["支持Next.js、React Native、Electron和Hono.js","创建新的tRPC路由器","包含CRUD过程","包含OpenAPI元数据","生成测试文件","支持不同身份验证级别"],"ja":["Next.js、React Native、Electron、Hono.jsをサポート","新しいtRPCルーターを作成","CRUDプロセスを含む","OpenAPIメタデータを含む","テストファイルを生成","異なる認証レベルをサポート"],"ko":["Next.js, React Native, Electron, Hono.js 지원","新的 tRPC 라우터 생성","CRUD 프로세스 포함","OpenAPI 메타데이터 포함","테스트 파일 생성","다른 인증 레벨 지원"],"es":["Crea enrutadores tRPC con procedimientos CRUD","Genera metadatos OpenAPI para tu proyecto","Soporte para proyectos x4-mono con Next.js, React Native y Electron","Permite la creación de procedimientos personalizados para list, get, create, update y delete","Incorpora comprobaciones de propiedad para procedimientos protegidos"],"fr":["Crée des routeurs tRPC avec des procédures CRUD","Génère des métadonnées OpenAPI pour votre projet","Prise en charge des projets x4-mono avec Next.js, React Native et Electron","Permet la création de procédures personnalisées pour list, get, create, update et delete","Intègre des vérifications de propriété pour les procédures protégées"],"de":["Erstellt tRPC-Router mit CRUD-Verfahren","Generiert OpenAPI-Metadaten für Ihr Projekt","Unterstützt x4-mono-Projekte mit Next.js, React Native und Electron","Ermöglicht die Erstellung benutzerdefinierter Verfahren für list, get, create, update und delete","Integriert Eigentumsprüfungen für geschützte Verfahren"],"pt":["Criação de rotas personalizadas para Next.js e React Native","Suporte a tRPC para procedimentos CRUD","Geração de metadados OpenAPI","Testes automatizados para x4-mono","Integração com Electron para aplicações de desktop"],"ru":["Создание маршрутизаторов для Next.js и React Native","Поддержка tRPC для процедур CRUD","Генерация метаданных OpenAPI","Автоматическое тестирование для x4-mono","Интеграция с Electron для настольных приложений"],"ar":["إنشاء маршروتات مخصصة لتطبيقات Next.js و React Native","دعم tRPC لعمليات CRUD","توليد بيانات تعريف OpenAPI","اختبارات آلية لتطبيقات x4-mono","التكامل مع Electron لتطبيقات سطح المكتب"]},"keywords":{"en":["how to use add-router","add-router setup guide","tRPC router generation","Next.js API development","add-router vs tRPC","add-router install","what is add-router","add-router alternative","x4-mono application development"],"zh":["add-router","tRPC路由器","Next.js","React Native","Electron","Hono.js","CRUD过程","OpenAPI元数据","AI工具","AIエージェント"],"ja":["add-router","tRPCルーター","Next.js","React Native","Electron","Hono.js","CRUDプロセス","OpenAPIメタデータ","AIエージェント","ルーター追加"],"ko":["add-router","tRPC 라우터","Next.js","React Native","Electron","Hono.js","CRUD 프로세스","OpenAPI 메타데이터","AI 도구","라우터 추가"],"es":["add-router","tRPC","CRUD","OpenAPI","x4-mono","Next.js","React Native","Electron","enrutador personalizado","procedimientos CRUD"],"fr":["add-router","tRPC","CRUD","OpenAPI","x4-mono","Next.js","React Native","Electron","routeur personnalisé","procédures CRUD"],"de":["add-router","tRPC","CRUD","OpenAPI","x4-mono","Next.js","React Native","Electron","benutzerdefinierter Router","CRUD-Verfahren"],"pt":["add-router","Next.js","React Native","tRPC","OpenAPI","x4-mono","rotas personalizadas","criação de rotas","desenvolvimento web","desenvolvimento móvel"],"ru":["ИИ Агент Add Router","Next.js","React Native","tRPC","OpenAPI","x4-mono","создание маршрутизаторов","маршрутизация","веб-разработка","мобильная разработка"],"ar":["إضافة روتر","Next.js","React Native","tRPC","OpenAPI","x4-mono","إنشاء маршروتات","маршрутизация","تطوير ويب","تطوير تطبيقات جوال"]}},"owner":"corbanb","repo":"x4-mono","repoPath":"corbanb/x4-mono","stars":0,"forks":1,"updatedAt":"2026-02-23T23:48:22Z","topics":[],"category":"community","skillMd":{"name":"add-router","description":"Create a tRPC router with CRUD procedures, OpenAPI meta, and tests","bodyPreview":"# Add Router Skill\n\nCreate a new tRPC router with CRUD procedures, OpenAPI meta, and test file for x4-mono.\n\n## Arguments\n\nThe user describes the resource. If unclear, ask for:\n\n- Resource name (singular, camelCase for router, e.g., `comment`)\n- Which procedures: list, get, create, update, delete (default: all)\n- Auth level: public, protected, or admin\n- Whether it needs ownership checks\n\n## File Locations\n\n- **Router**: `apps/api/src/routers/{name}.ts`\n- **Registration**: `apps/api/src/routers/","body":"# Add Router Skill\n\nCreate a new tRPC router with CRUD procedures, OpenAPI meta, and test file for x4-mono.\n\n## Arguments\n\nThe user describes the resource. If unclear, ask for:\n\n- Resource name (singular, camelCase for router, e.g., `comment`)\n- Which procedures: list, get, create, update, delete (default: all)\n- Auth level: public, protected, or admin\n- Whether it needs ownership checks\n\n## File Locations\n\n- **Router**: `apps/api/src/routers/{name}.ts`\n- **Registration**: `apps/api/src/routers/index.ts`\n- **Tests**: `apps/api/src/__tests__/{name}.test.ts`\n- **Schemas**: `packages/shared/utils/validators.ts` (if not already there)\n\n## Router Template\n\nReference: `apps/api/src/routers/projects.ts`\n\n```typescript\nimport { eq, sql } from ''drizzle-orm'';\nimport { router, publicProcedure, protectedProcedure } from ''../trpc'';\nimport { Errors } from ''../lib/errors'';\nimport { tableName } from ''@x4/database'';\nimport {\n  CreateEntitySchema,\n  UpdateEntitySchema,\n  EntityResponseSchema,\n  EntityListResponseSchema,\n  IdParamSchema,\n  PaginationSchema,\n} from ''@x4/shared/utils'';\n\nexport const entityRouter = router({\n  list: publicProcedure\n    .meta({ openapi: { method: ''GET'', path: ''/entities'', tags: [''Entity''] } })\n    .input(PaginationSchema)\n    .output(EntityListResponseSchema)\n    .query(async ({ ctx, input }) => {\n      const items = await ctx.db.select().from(tableName).limit(input.limit).offset(input.offset);\n      return { items, total: items.length, limit: input.limit, offset: input.offset };\n    }),\n\n  get: publicProcedure\n    .meta({ openapi: { method: ''GET'', path: ''/entities/{id}'', tags: [''Entity''] } })\n    .input(IdParamSchema)\n    .output(EntityResponseSchema)\n    .query(async ({ ctx, input }) => {\n      const [record] = await ctx.db.select().from(tableName).where(eq(tableName.id, input.id));\n      if (!record) throw Errors.notFound(''Entity'').toTRPCError();\n      return record;\n    }),\n\n  create: protectedProcedure\n    .meta({ openapi: { method: ''POST'', path: ''/entities'', tags: [''Entity''], protect: true } })\n    .input(CreateEntitySchema)\n    .output(EntityResponseSchema)\n    .mutation(async ({ ctx, input }) => {\n      const [record] = await ctx.db\n        .insert(tableName)\n        .values({ ...input, ownerId: ctx.user.userId })\n        .returning();\n      return record;\n    }),\n\n  update: protectedProcedure\n    .meta({ openapi: { method: ''PATCH'', path: ''/entities/{id}'', tags: [''Entity''], protect: true } })\n    .input(UpdateEntitySchema)\n    .output(EntityResponseSchema)\n    .mutation(async ({ ctx, input }) => {\n      const { id, ...data } = input;\n      const [existing] = await ctx.db.select().from(tableName).where(eq(tableName.id, id));\n      if (!existing) throw Errors.notFound(''Entity'').toTRPCError();\n      if (existing.ownerId !== ctx.user.userId && ctx.user.role !== ''admin'') {\n        throw Errors.forbidden(''Not the owner'').toTRPCError();\n      }\n      const [updated] = await ctx.db\n        .update(tableName)\n        .set(data)\n        .where(eq(tableName.id, id))\n        .returning();\n      return updated;\n    }),\n\n  delete: protectedProcedure\n    .meta({\n      openapi: { method: ''DELETE'', path: ''/entities/{id}'', tags: [''Entity''], protect: true },\n    })\n    .input(IdParamSchema)\n    .output(z.object({ success: z.boolean() }))\n    .mutation(async ({ ctx, input }) => {\n      const [existing] = await ctx.db.select().from(tableName).where(eq(tableName.id, input.id));\n      if (!existing) throw Errors.notFound(''Entity'').toTRPCError();\n      if (existing.ownerId !== ctx.user.userId && ctx.user.role !== ''admin'') {\n        throw Errors.forbidden(''Not the owner'').toTRPCError();\n      }\n      await ctx.db.delete(tableName).where(eq(tableName.id, input.id));\n      return { success: true };\n    }),\n});\n```\n\n## Registration\n\nAdd to `apps/api/src/routers/index.ts`:\n\n```typescript\nimport { entityRouter } from ''./entity'';\n\nexport const appRouter = router({\n  // ... existing routers\n  entity: entityRouter,\n});\n```\n\n## Workflow\n\n1. Ensure Zod schemas exist (use `/add-schema` first if needed)\n2. Ensure database table exists (use `/add-table` first if needed)\n3. Create router file at `apps/api/src/routers/{name}.ts`\n4. Register in `apps/api/src/routers/index.ts`\n5. Run `bun turbo type-check` to verify AppRouter updates\n6. Create test file at `apps/api/src/__tests__/{name}.test.ts` (use `/add-test` or bun-test-gen)\n7. Run `bun test --cwd apps/api` to verify\n"},"lastSynced":"2026-03-07T03:53:22.078Z","agentAnalysis":{"suitability":{"en":"Ideal for Full Stack Agents needing streamlined API development with tRPC and Next.js","zh":"适合需要使用tRPC和Next.js进行流线API开发的全栈代理","ja":"tRPCとNext.jsを使ったストリームラインAPI開発が必要なフルスタックエージェントに適しています","ko":"tRPC와 Next.js를 사용한 스트림 라인 API 개발이 필요한 풀 스택 에이전트에 적합합니다","es":"Ideal para Agentes de Full Stack que necesitan un desarrollo de API optimizado con tRPC y Next.js","fr":"Idéal pour les agents Full Stack ayant besoin d''un développement d''API optimisé avec tRPC et Next.js","de":"Ideal für Full-Stack-Agents, die ein optimiertes API-Entwicklung mit tRPC und Next.js benötigen","pt":"Ideal para Agentes Full Stack que precisam de desenvolvimento de API simplificado com tRPC e Next.js","ru":"Идеально для полнофункциональных агентов, требующих упрощенного развития API с tRPC и Next.js","ar":"مثالي للوكلاء كامل الحزمة الذين يحتاجون إلى تطوير واجهة برمجة التطبيقات المبسطة مع tRPC و Next.js"},"recommendation":{"en":"Empowers agents to generate new tRPC routers with CRUD procedures, OpenAPI meta, and test files for frameworks like Next.js, React Native, Electron, and Hono.js, streamlining API development with features like ownership checks and customizable auth levels","zh":"赋予代理生成新的tRPC路由器，包括CRUD过程、OpenAPI元数据和测试文件，支持Next.js、React Native、Electron和Hono.js等框架，简化API开发，并具有所有权检查和可自定义的身份验证级别等功能","ja":"エージェントに、新しいtRPCルーターの生成を可能にし、CRUD手順、OpenAPIメタデータ、およびNext.js、React Native、Electron、Hono.jsなどのフレームワーク用のテストファイルを含み、API開発をストリームライン化し、所有権の確認やカスタマイズ可能な認証レベルなどの機能を提供する","ko":"에이전트가 새로운 tRPC 라우터를 생성하도록 허용하여 CRUD 절차, OpenAPI 메타데이터 및 Next.js, React Native, Electron 및 Hono.js와 같은 프레임워크용 테스트 파일을 포함하며, API 개발을 스트림 라인화하고, 소유권 확인 및 사용자 지정 가능한 인증 수준 등의 기능을 제공합니다","es":"Habilita a los agentes para generar nuevos enrutadores tRPC con procedimientos CRUD, metadatos OpenAPI y archivos de prueba para frameworks como Next.js, React Native, Electron y Hono.js, optimizando el desarrollo de API con características como controles de propiedad y niveles de autenticación personalizables","fr":"Permet aux agents de générer de nouveaux routeurs tRPC avec des procédures CRUD, des métadonnées OpenAPI et des fichiers de test pour des frameworks comme Next.js, React Native, Electron et Hono.js, optimisant le développement d''API avec des fonctionnalités comme les vérifications de propriété et les niveaux d''authentification personnalisables","de":"Ermöglicht es Agenten, neue tRPC-Router mit CRUD-Verfahren, OpenAPI-Metadaten und Testdateien für Frameworks wie Next.js, React Native, Electron und Hono.js zu generieren, optimiert die API-Entwicklung mit Funktionen wie Eigentümerprüfungen und anpassbaren Authentifizierungsebenen","pt":"Habilita os agentes a gerar novos roteadores tRPC com procedimentos CRUD, metadados OpenAPI e arquivos de teste para estruturas como Next.js, React Native, Electron e Hono.js, simplificando o desenvolvimento de API com recursos como verificações de propriedade e níveis de autenticação personalizáveis","ru":"Наделяет агентов возможностью генерировать новые маршрутизаторы tRPC с процедурами CRUD, метаданными OpenAPI и файлами тестирования для фреймворков như Next.js, React Native, Electron и Hono.js, упрощая разработку API с функциями такими как проверки владения и настраиваемые уровни аутентификации","ar":"تمكن الوكلاء من生成 روترات tRPC جديدة مع إجراءات CRUD وبيانات تعريف ميتا OpenAPI وملفات اختبار للعوامل مثل Next.js و React Native و Electron و Hono.js، وبذلك يُبسط تطوير واجهة برمجة التطبيقات مع الميزات مثل فحص الملكية ومستويات التحقق من الصلاحية القابلة للتعديل"},"useCases":{"en":["Generating CRUD APIs for Next.js applications","Creating protected routes with ownership checks for React Native","Automating tRPC router setup for Electron and Hono.js projects"],"zh":["为Next.js应用程序生成CRUD API","为React Native创建具有所有权检查的受保护路由","为Electron和Hono.js项目自动设置tRPC路由器"],"ja":["Next.jsアプリケーションのCRUD APIを生成する","React Native用に所有権の確認付きの保護ルートを作成する","ElectronとHono.jsプロジェクト用のtRPCルーターの自動設定"],"ko":["Next.js 애플리케이션용 CRUD API 생성","React Native용 소유권 확인이 있는 보호 경로 생성","Electron 및 Hono.js 프로젝트용 tRPC 라우터 자동 설정"],"es":["Generación de API CRUD para aplicaciones Next.js","Creación de rutas protegidas con controles de propiedad para React Native","Automatización de la configuración del enrutador tRPC para proyectos Electron y Hono.js"],"fr":["Génération d''API CRUD pour des applications Next.js","Création de routes protégées avec des vérifications de propriété pour React Native","Automatisation de la configuration du routeur tRPC pour des projets Electron et Hono.js"],"de":["Generierung von CRUD-APIs für Next.js-Anwendungen","Erstellung von geschützten Routen mit Eigentümerprüfungen für React Native","Automatisierung der tRPC-Router-Konfiguration für Electron- und Hono.js-Projekte"],"pt":["Geração de APIs CRUD para aplicações Next.js","Criação de rotas protegidas com verificações de propriedade para React Native","Automatização da configuração do roteador tRPC para projetos Electron e Hono.js"],"ru":["Генерация CRUD API для приложений Next.js","Создание защищенных маршрутов с проверками владения для React Native","Автоматизация настройки маршрутизатора tRPC для проектов Electron и Hono.js"],"ar":["إنشاء واجهات برمجة تطبيقات CRUD لتطبيقات Next.js","إنشاء مسارات محمية بفحوصات ملكية ل React Native","أتمتة إعداد روتر tRPC لمشاريع Electron و Hono.js"]},"limitations":{"en":["Requires knowledge of tRPC and supported frameworks","Limited to generating routers for specified frameworks"],"zh":["需要了解tRPC和支持的框架","仅限于为指定框架生成路由器"],"ja":["tRPCとサポートされているフレームワークの知識が必要","指定されたフレームワーク用のルーターの生成のみ"],"ko":["tRPC 및 지원 프레임워크에 대한 지식이 필요","지정된 프레임워크용 라우터 생성만"],"es":["Requiere conocimiento de tRPC y frameworks compatibles","Limitado a la generación de enrutadores para frameworks especificados"],"fr":["Nécessite des connaissances en tRPC et frameworks pris en charge","Limité à la génération de routeurs pour des frameworks spécifiés"],"de":["Benötigt Kenntnisse von tRPC und unterstützten Frameworks","Begrenzt auf die Generierung von Routern für spezifizierte Frameworks"],"pt":["Exige conhecimento de tRPC e estruturas suportadas","Limitado à geração de roteadores para estruturas especificadas"],"ru":["Требует знания tRPC и поддерживаемых фреймворков","Ограничен генерацией маршрутизаторов для указанных фреймворков"],"ar":["يتطلب معرفة tRPC والهياكل المدعومة","محدود بالتوجيه إلى روترات محددة"]},"version":4},"contentHash":"cffaddc6a7fa419185c9fe7c8bd6af9c8bca11c8d721f961d67f942ce54c146d","qualityScore":57}');
