INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('corbanb/x4-mono/add-router', 'add-router', 'corbanb', 'x4-mono', 'community', 'add-router corbanb x4-mono community The add-router skill generates a new tRPC router with CRUD procedures for Next.js, React Native, Electron, and Hono.js. It benefits developers by streamlining API development. add-router技能用于创建新的tRPC路由器，支持Next.js、React Native、Electron和Hono.js add-routerスキルは、新しいtRPCルーターを作成するために使用され、Next.js、React Native、Electron、Hono.jsをサポートします add-router 스킬은 새로운 tRPC 라우터를 생성하는 데 사용되며 Next.js, React Native, Electron, Hono.js를 지원합니다 add-router es una herramienta para crear enrutadores tRPC con procedimientos CRUD y metadatos OpenAPI para proyectos x4-mono add-router est un outil pour créer des routeurs tRPC avec des procédures CRUD et des métadonnées OpenAPI pour les projets x4-mono add-router ist ein Tool zum Erstellen von tRPC-Routern mit CRUD-Verfahren und OpenAPI-Metadaten für x4-mono-Projekte O add-router é uma ferramenta para criar rotas personalizadas para Next.js, React Native e Electron, com suporte a tRPC e OpenAPI. ИИ Агент Add Router позволяет создавать маршрутизаторы с поддержкой tRPC, OpenAPI и тестированием для x4-mono. إضافة روتر هي أداة لإنشاء маршروتات مخصصة لتطبيقات Next.js و React Native و Electron مع دعم tRPC و OpenAPI. how to use add-router add-router setup guide tRPC router generation Next.js API development add-router vs tRPC add-router install what is add-router add-router alternative x4-mono application development add-router tRPC路由器 Next.js React Native Electron Hono.js CRUD过程 OpenAPI元数据 AI工具 AIエージェント Generates tRPC routers with CRUD procedures for Next.js, React Native, Electron, and Hono.js Creates OpenAPI meta files for API documentation Supports test file generation for x4-mono applications Allows for customizable auth levels, including public, protected, and admin Enables ownership checks for secure data management add-router is a mono repo skill for creating tRPC routers with CRUD procedures, OpenAPI meta, and test files for x4-mono applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('loopstack-ai/sandbox-filesystem/sandbox-filesystem-tool', 'community', 'loopstack-ai', 'sandbox-filesystem', 'loopstack-ai/sandbox-filesystem', 'sandbox-filesystem-tool', 0, 0, 57, '2026-01-19T09:48:45Z', '2026-03-07T03:53:19.317Z', 'bf4f50d06360515649b12dd075dbcf1a18561c78645187c4b1f9224c36205217', '{"id":"loopstack-ai/sandbox-filesystem/sandbox-filesystem-tool","name":"sandbox-filesystem-tool","description":{"en":"The sandbox-filesystem-tool enables secure filesystem operations within Docker sandbox environments, allowing workflows to read, write, list, and manage files and directories in isolated containers, benefiting developers working with Loopstack tools.","zh":"Sandbox 文件系统工具提供了安全、受控的文件系统操作，用于 Docker 沙盒环境","ja":"サンドボックスファイルシステムツールは、Docker サンドボックス環境内で安全にファイルシステム操作を実行する","ko":"샌드박스 파일시스템 툴은 Docker 샌드박스 환경에서 안전한 파일시스템 작업을 제공합니다","es":"El sandbox-filesystem-tool es una herramienta de Loopstack que proporciona operaciones de sistema de archivos seguras en entornos de Docker","fr":"Le sandbox-filesystem-tool est un outil Loopstack qui offre des opérations de système de fichiers sécurisées dans les environnements Docker","de":"Das sandbox-filesystem-tool ist ein Loopstack-Tool, das sichere Dateisystemoperationen in Docker-Umgebungen ermöglicht","pt":"O sandbox-filesystem-tool é uma ferramenta do Loopstack que fornece operações de sistema de arquivos seguras em ambientes de sandbox do Docker","ru":"Sandbox-filesystem-tool - это инструмент Loopstack, обеспечивающий безопасные операции с файловой системой в среде Docker","ar":"أداة sandbox-filesystem-tool هي أداة من Loopstack توفر عمليات نظام الملفات الآمنة في بيئات Docker"},"seo":{"title":{"en":"sandbox-filesystem-tool: Secure Docker Sandbox Filesystem...","zh":"Sandbox 文件系统工具集成指南","ja":"AIエージェント：サンドボックスファイルシステムツールのセットアップガイド","ko":"샌드박스 파일시스템 툴 구현 가이드","es":"Guía de configuración de sandbox-filesystem-tool para ent...","fr":"Guide d''implémentation de sandbox-filesystem-tool pour le...","de":"Einrichtungsleitfaden für sandbox-filesystem-tool in Dock...","pt":"Guia de Configuração do sandbox-filesystem-tool para Dese...","ru":"Настройка ИИ Агентов: Руководство по sandbox-filesystem-tool","ar":"إعداد أداة sandbox-filesystem-tool: دليل المطورين"},"description":{"en":"Discover how to leverage sandbox-filesystem-tool for secure, controlled Docker sandbox environments. Learn to implement NestJS injectable tool classes for is...","zh":"了解如何使用 @loopstack/sandbox-filesystem 实现安全的沙盒文件系统操作","ja":"サンドボックス環境内で安全にファイルシステム操作を実行する方法を学ぶ","ko":"샌드박스 환경에서 안전한 파일시스템 작업을 수행하는 방법을 알아보세요","es":"Aprende a implementar sandbox-filesystem-tool para operaciones de sistema de archivos seguras en contenedores de Docker","fr":"Découvrez comment mettre en œuvre sandbox-filesystem-tool pour des opérations de système de fichiers sécurisées dans des conteneurs Docker","de":"Erfahren Sie, wie Sie sandbox-filesystem-tool für sichere Dateisystemoperationen in Docker-Containern implementieren","pt":"Aprenda a configurar o sandbox-filesystem-tool para operações de sistema de arquivos seguras em ambientes de sandbox do Docker","ru":"Узнайте, как настроить sandbox-filesystem-tool для безопасных операций с файловой системой в среде Docker","ar":"تعرف على كيفية إعداد أداة sandbox-filesystem-tool لعمليات نظام الملفات الآمنة في بيئات Docker"},"definition":{"en":"sandbox-filesystem-tool is a Loopstack tool providing secure, controlled filesystem operations within Docker sandbox environments, utilizing NestJS injectable tool classes.","zh":"Sandbox 文件系统工具是一种 Loopstack 工具，用于提供安全的文件系统操作","ja":"サンドボックスファイルシステムツールは、安全なファイルシステム操作を提供する Loopstack ツールです","ko":"샌드박스 파일시스템 툴은 안전한 파일시스템 작업을 제공하는 Loopstack 툴입니다","es":"Un sandbox-filesystem-tool es una herramienta que permite operaciones de sistema de archivos controladas en contenedores de Docker","fr":"Un sandbox-filesystem-tool est un outil qui permet des opérations de système de fichiers contrôlées dans des conteneurs Docker","de":"Ein sandbox-filesystem-tool ist ein Tool, das kontrollierte Dateisystemoperationen in Docker-Containern ermöglicht","pt":"O que é sandbox-filesystem-tool? É uma ferramenta do Loopstack para operações de sistema de arquivos seguras em ambientes de sandbox do Docker","ru":"Что такое sandbox-filesystem-tool? Это инструмент Loopstack для безопасных операций с файловой системой в среде Docker","ar":"ما هي أداة sandbox-filesystem-tool؟ هي أداة من Loopstack لعمليات نظام الملفات الآمنة في بيئات Docker"},"features":{"en":["Provides secure filesystem operations within Docker sandbox environments","Enables workflows to read, write, list, and manage files and directories in isolated containers","Utilizes NestJS injectable tool classes for implementation","Executes filesystem operations within sandbox containers using @loopstack/sandb","Extends ToolBase for integrated functionality","Supports isolated container management for enhanced security"],"zh":["支持 Docker 沙盒环境","提供安全、受控的文件系统操作","支持读、写、列出和管理文件和目录","使用 NestJS injectable 工具类","扩展 ToolBase 类","使用 @loopstack/sandb 库"],"ja":["Docker サンドボックス環境をサポート","安全なファイルシステム操作を提供","ファイルとディレクトリの読み取り、書き込み、列出、管理をサポート","NestJS injectable ツールクラスを使用","ToolBase クラスを拡張","@loopstack/sandb ライブラリを使用"],"ko":["Docker 샌드박스 환경을 지원","안전한 파일시스템 작업을 제공","파일과 디렉토리의 읽기, 쓰기, 열기, 관리를 지원","NestJS injectable 툴 클래스를 사용","ToolBase 클래스를 확장","@loopstack/sandb 라이브러리를 사용"],"es":["Proporciona operaciones de sistema de archivos seguras en contenedores de Docker","Permite la lectura, escritura, lista y gestión de archivos y directorios en contenedores aislados","Utiliza NestJS como framework de desarrollo","Extiende la clase ToolBase para proporcionar funcionalidades personalizadas","Ejecuta operaciones de sistema de archivos dentro de contenedores de sandbox utilizando @loopstack/sandb","Soporta entornos de Docker para una mayor flexibilidad y escalabilidad"],"fr":["Offre des opérations de système de fichiers sécurisées dans des conteneurs Docker","Permet la lecture, l''écriture, la liste et la gestion de fichiers et de répertoires dans des conteneurs isolés","Utilise NestJS comme framework de développement","Étend la classe ToolBase pour fournir des fonctionnalités personnalisées","Exécute des opérations de système de fichiers à l''intérieur de conteneurs de sandbox utilisant @loopstack/sandb","Prend en charge les environnements Docker pour une plus grande flexibilité et évolutivité"],"de":["Bietet sichere Dateisystemoperationen in Docker-Containern","Ermöglicht das Lesen, Schreiben, Auflisten und Verwalten von Dateien und Verzeichnissen in isolierten Containern","Verwendet NestJS als Entwicklungsfamework","Erweitert die ToolBase-Klasse, um benutzerdefinierte Funktionalitäten bereitzustellen","Führt Dateisystemoperationen innerhalb von Sandbox-Containern mit @loopstack/sandb aus","Unterstützt Docker-Umgebungen für eine größere Flexibilität und Skalierbarkeit"],"pt":["Fornece operações de sistema de arquivos seguras em ambientes de sandbox do Docker","Permite leitura, escrita, listagem e gerenciamento de arquivos e diretórios em contêineres isolados","Implementado como uma classe injectável do NestJS que estende ToolBase","Utiliza @loopstack/sandb para execução de operações em contêineres de sandbox","Suporta workflows para gerenciamento de arquivos e diretórios em ambientes de sandbox"],"ru":["Предоставляет безопасные операции с файловой системой в среде Docker","Позволяет читать, записывать, перечислять и управлять файлами и каталогами в изолированных контейнерах","Реализован как класс инъекта NestJS, расширяющий ToolBase","Использует @loopstack/sandb для выполнения операций в контейнерах sandbox","Поддерживает рабочие процессы для управления файлами и каталогами в среде sandbox"],"ar":["توفر عمليات نظام الملفات الآمنة في بيئات Docker","تمكن من قراءة وكتابة وlisting وإدارة الملفات والمجلدات في حاويات معزولة","مplemented كفئة قابلة للحقن من NestJS التي تمتد ToolBase","يستخدم @loopstack/sandb لتنفيذ العمليات في حاويات sandbox","يدعم سير العمل لإدارة الملفات والمجلدات في بيئات sandbox"]},"keywords":{"en":["how to use sandbox-filesystem-tool","sandbox-filesystem-tool setup guide","Docker sandbox environment security","NestJS injectable tool classes","isolated container filesystem operations","Loopstack tool implementation"],"zh":["Sandbox 文件系统工具","Docker 沙盒环境","安全文件系统操作","NestJS injectable","ToolBase 类","@loopstack/sandb","Loopstack 工具","文件系统管理","沙盒环境安全"],"ja":["AIエージェント","サンドボックスファイルシステムツール","Docker サンドボックス環境","安全なファイルシステム操作","NestJS injectable","ToolBase クラス","@loopstack/sandb","Loopstack ツール","ファイルシステム管理","サンドボックス環境のセキュリティ"],"ko":["AI 툴","샌드박스 파일시스템 툴","Docker 샌드박스 환경","안전한 파일시스템 작업","NestJS injectable","ToolBase 클래스","@loopstack/sandb","Loopstack 툴","파일시스템 관리","샌드박스 환경 보안"],"es":["sandbox-filesystem-tool","Docker","NestJS","sistema de archivos","operaciones de sistema de archivos","contenedores de Docker","entornos de sandbox","seguridad de sistema de archivos","Loopstack"],"fr":["sandbox-filesystem-tool","Docker","NestJS","système de fichiers","opérations de système de fichiers","conteneurs Docker","environnements de sandbox","sécurité de système de fichiers","Loopstack","outils de développement"],"de":["sandbox-filesystem-tool","Docker","NestJS","Dateisystem","Dateisystemoperationen","Docker-Container","Sandbox-Umgebungen","Dateisystem-Sicherheit","Loopstack","Entwicklungstools"],"pt":["sandbox-filesystem-tool","Loopstack","Docker","NestJS","operacoes de sistema de arquivos","seguranca em ambientes de sandbox","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["sandbox-filesystem-tool","Loopstack","Docker","NestJS","операции с файловой системой","безопасность в среде sandbox","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["أداة sandbox-filesystem-tool","Loopstack","Docker","NestJS","عمليات نظام الملفات","أمان في بيئات sandbox","تطوير البرمجيات","أدوات التطوير","وكلاء الذكاء الاصطناعي"]}},"owner":"loopstack-ai","repo":"sandbox-filesystem","repoPath":"loopstack-ai/sandbox-filesystem","stars":0,"forks":0,"updatedAt":"2026-01-19T09:48:45Z","topics":[],"category":"community","skillMd":{"name":"sandbox-filesystem-tool","description":"Build a secure filesystem operations tool for Docker sandbox environments using the Loopstack framework","bodyPreview":"# Sandbox Filesystem Tool Implementation Guide\n\n## Overview\n\nYou are building `@loopstack/sandbox-filesystem`, a Loopstack tool that provides secure, controlled filesystem operations within Docker sandbox environments. This tool enables workflows to read, write, list, and manage files and directories in isolated containers.\n\n## What to Build\n\nCreate a NestJS injectable tool class that extends `ToolBase` and provides filesystem operations executed within sandbox containers using `@loopstack/sandb","body":"# Sandbox Filesystem Tool Implementation Guide\n\n## Overview\n\nYou are building `@loopstack/sandbox-filesystem`, a Loopstack tool that provides secure, controlled filesystem operations within Docker sandbox environments. This tool enables workflows to read, write, list, and manage files and directories in isolated containers.\n\n## What to Build\n\nCreate a NestJS injectable tool class that extends `ToolBase` and provides filesystem operations executed within sandbox containers using `@loopstack/sandbox-tool`.\n\n### Core Operations Required\n\n1. **Read File** - Read complete file contents from a specified path\n2. **Write File** - Write content to a file, creating parent directories if needed\n3. **List Directory** - List files and subdirectories with metadata\n4. **Create Directory** - Create directories with recursive parent creation\n5. **Delete File/Directory** - Remove files or directories\n6. **Check Existence** - Verify if a file or directory exists\n7. **Get File Info** - Retrieve metadata (size, type, timestamps)\n\n## Tool Arguments Schema\n\nDefine a Zod schema with the following structure:\n\n```typescript\nconst sandboxFilesystemSchema = z.object({\n  operation: z.enum([''read'', ''write'', ''list'', ''createDir'', ''delete'', ''exists'', ''info'']),\n  path: z.string().describe(''Target filesystem path within sandbox''),\n  content: z.string().optional().describe(''Content to write (for write operation)''),\n  encoding: z.string().default(''utf-8'').optional().describe(''Character encoding''),\n  recursive: z.boolean().default(false).optional().describe(''Enable recursive operations''),\n  force: z.boolean().default(false).optional().describe(''Force overwrite or deletion''),\n});\n\ntype SandboxFilesystemArgs = z.infer<typeof sandboxFilesystemSchema>;\n```\n\n## Implementation Structure\n\n```typescript\nimport { Injectable } from ''@nestjs/common'';\nimport { z } from ''zod'';\nimport { ToolBase } from ''@loopstack/core'';\nimport { BlockConfig, ToolResult, WithArguments } from ''@loopstack/common'';\n\n@Injectable()\n@BlockConfig({\n  config: {\n    description: ''Secure filesystem operations within Docker sandbox environments'',\n  },\n})\n@WithArguments(sandboxFilesystemSchema)\nexport class SandboxFilesystemTool extends ToolBase<SandboxFilesystemArgs> {\n  \n  async execute(args: SandboxFilesystemArgs): Promise<ToolResult<any>> {\n    // 1. Validate path for security (no ../ traversal)\n    // 2. Normalize path\n    // 3. Execute operation based on args.operation\n    // 4. Return structured result with success, data, metadata\n  }\n}\n```\n\n## Tool Result Structure\n\nReturn a `ToolResult` with this structure:\n\n```typescript\n{\n  data: {\n    success: boolean,\n    data: any,              // Operation-specific payload\n    error?: string,         // Error message if failed\n    metadata?: {            // Additional context\n      bytesWritten?: number,\n      itemsCount?: number,\n      // etc.\n    }\n  }\n}\n```\n\n## Security Requirements\n\n### Path Validation\n- **CRITICAL**: Block path traversal attacks by rejecting paths containing `../`\n- Normalize all paths before execution\n- Restrict access to sandbox-designated directories only\n- Never allow access to system directories like `/etc`, `/sys`, `/proc`\n\n### Resource Limits\n- Enforce `maxFileSize` configuration (suggest default: 10MB)\n- Implement operation timeouts (suggest default: 5000ms)\n- Limit recursive depth to prevent infinite loops (suggest max: 10 levels)\n\n### Error Handling\n- Sanitize error messages to prevent information leakage\n- Provide generic errors to users, detailed logs internally\n- Fail safely on permission errors\n\n## Configuration Options\n\nSupport these configuration properties in the tool:\n\n```typescript\ninterface SandboxFilesystemConfig {\n  defaultEncoding?: string;      // Default: ''utf-8''\n  maxFileSize?: number;          // Default: 10485760 (10MB)\n  allowedPaths?: string[];       // Whitelist of accessible paths\n  timeoutMs?: number;            // Default: 5000\n}\n```\n\n## Usage Examples\n\n### Example 1: Read a Configuration File\n\n```yaml\ntransitions:\n  - id: read_config\n    from: start\n    to: process\n    call:\n      - tool: sandboxFilesystem\n        args:\n          operation: ''read''\n          path: ''/workspace/config.json''\n          encoding: ''utf-8''\n        assign:\n          configData: ${ result.data.data }\n```\n\n### Example 2: Write Generated Code\n\n```yaml\ntransitions:\n  - id: save_output\n    from: generate\n    to: end\n    call:\n      - tool: sandboxFilesystem\n        args:\n          operation: ''write''\n          path: ''/workspace/output/generated.ts''\n          content: ${ generatedCode }\n          recursive: true\n        assign:\n          writeResult: ${ result.data }\n```\n\n### Example 3: List Directory Contents\n\n```yaml\ntransitions:\n  - id: list_files\n    from: start\n    to: process\n    call:\n      - tool: sandboxFilesystem\n        args:\n          operation: ''list''\n          path: ''/workspace/data''\n          recursive: false\n        assign:\n          fileList: ${ result.data.data }\n```\n\n### Example 4: Check File Existence Before Processing\n\n```yaml\ntransitions:\n  - id: check_and_process\n    from: start\n    to: process\n    call:\n      - tool: sandboxFilesystem\n        args:\n          operation: ''exists''\n          path: ''/workspace/input.txt''\n        assign:\n          fileExists: ${ result.data.data }\n```\n\n## Dependencies\n\nEnsure these packages are installed:\n\n```json\n{\n  \"dependencies\": {\n    \"@loopstack/sandbox-tool\": \"latest\",\n    \"@loopstack/core\": \"latest\",\n    \"@loopstack/common\": \"latest\",\n    \"@nestjs/common\": \"^10.0.0\",\n    \"zod\": \"^3.22.0\"\n  }\n}\n```\n\n## Module Registration\n\nRegister the tool in your NestJS module:\n\n```typescript\nimport { Module } from ''@nestjs/common'';\nimport { SandboxFilesystemTool } from ''./sandbox-filesystem.tool'';\n\n@Module({\n  providers: [SandboxFilesystemTool],\n  exports: [SandboxFilesystemTool],\n})\nexport class SandboxFilesystemModule {}\n```\n\n## Troubleshooting\n\n### \"Path traversal detected\" Error\n- Ensure paths don''t contain `../` sequences\n- Use absolute paths starting with `/workspace/` or configured allowed paths\n- Normalize paths before validation\n\n### \"File size exceeds maximum\" Error\n- Check `maxFileSize` configuration\n- For large files, consider streaming or chunked operations\n- Increase limit if appropriate for your use case\n\n### \"Operation timeout\" Error\n- Verify sandbox container is running and accessible\n- Check network connectivity to Docker environment\n- Increase `timeoutMs` configuration for slow filesystems\n\n### Permission Denied Errors\n- Verify Docker volume mounts are configured correctly\n- Ensure sandbox container has appropriate user permissions\n- Check that target paths are within allowed sandbox boundaries\n\n### Binary vs Text File Handling\n- Use appropriate encoding: `''utf-8''` for text, `''binary''` or `''base64''` for binary files\n- Specify encoding explicitly in arguments to avoid corruption\n- Consider file type when reading/writing\n\n## Best Practices\n\n1. **Always validate paths** before executing operations\n2. **Use recursive: true** only when necessary to avoid performance issues\n3. **Set appropriate timeouts** based on expected file sizes\n4. **Handle errors gracefully** in workflows with fallback transitions\n5. **Log operations** for audit trails and debugging\n6. **Test in sandbox** before production deployment\n7. **Limit file sizes** to prevent resource exhaustion"},"lastSynced":"2026-03-07T03:53:19.317Z","agentAnalysis":{"suitability":{"en":"Ideal for Containerization Agents requiring secure filesystem operations within Docker sandbox environments","zh":"适用于需要在Docker沙盒环境中进行安全文件系统操作的容器化代理","ja":"Dockerサンドボックス環境内で安全なファイルシステム操作を必要とするコンテナ化エージェントに適しています","ko":"Docker 샌드박스 환경 내에서 보안 파일 시스템操作이 필요한 컨테이너화 에이전트에 적합합니다","es":"Ideal para Agentes de Contenerización que requieren operaciones de sistema de archivos seguras dentro de entornos de sandbox de Docker","fr":"Idéal pour les Agents de conteneurisation nécessitant des opérations de système de fichiers sécurisées dans des environnements de sandbox Docker","de":"Ideal für Containerisierungsagenten, die sichere Dateisystemoperationen in Docker-Sandbox-Umgebungen erfordern","pt":"Ideal para Agentes de Containerização que exigem operações de sistema de arquivos seguras em ambientes de sandbox do Docker","ru":"Идеально для агентов контейнеризации, требующих безопасных операций с файловой системой в средах sandbox Docker","ar":"مثالية لعمليات وكيل التخزين التي تتطلب عمليات نظام الملفات الآمنة في بيئات Docker المحمية"},"recommendation":{"en":"Empowers agents to execute secure, controlled filesystem operations within isolated containers using NestJS and @loopstack/sandbox-filesystem, enabling read, write, list, and management of files and directories","zh":"赋予代理在隔离的容器中使用NestJS和@loopstack/sandbox-filesystem执行安全的、受控的文件系统操作的能力，实现文件和目录的读取、写入、列出和管理","ja":"NestJSと@loopstack/sandbox-filesystemを使用して、隔離されたコンテナ内で安全で制御されたファイルシステム操作を実行するエージェントを可能にし、ファイルとディレクトリの読み取り、書き込み、リスト、管理を可能にします","ko":"NestJS와 @loopstack/sandbox-filesystem를 사용하여 격리된 컨테이너 내에서 보안이 보장된 제어된 파일 시스템操作을 실행할 수 있는 에이전트를 강화하여 파일과 디렉토리의 읽기, 쓰기, 목록, 관리를 가능하게 합니다","es":"Habilita a los agentes a ejecutar operaciones de sistema de archivos seguras y controladas dentro de contenedores aislados utilizando NestJS y @loopstack/sandbox-filesystem, lo que permite leer, escribir, listar y gestionar archivos y directorios","fr":"Permet aux agents d''exécuter des opérations de système de fichiers sécurisées et contrôlées dans des conteneurs isolés en utilisant NestJS et @loopstack/sandbox-filesystem, ce qui permet de lire, écrire, lister et gérer des fichiers et des répertoires","de":"Ermöglicht es Agenten, sichere, kontrollierte Dateisystemoperationen innerhalb isolierter Container mit NestJS und @loopstack/sandbox-filesystem auszuführen, wodurch Dateien und Verzeichnisse gelesen, geschrieben, aufgelistet und verwaltet werden können","pt":"Habilita os agentes a executar operações de sistema de arquivos seguras e controladas dentro de contêineres isolados, utilizando NestJS e @loopstack/sandbox-filesystem, permitindo leitura, gravação, listagem e gerenciamento de arquivos e diretórios","ru":"Наделяет агентов возможностью выполнять безопасные и контролируемые операции с файловой системой внутри изолированных контейнеров, используя NestJS и @loopstack/sandbox-filesystem, что позволяет читать, записывать, перечислять и управлять файлами и директориями","ar":"تمكّن الوكلاء من تشغيل عمليات نظام الملفات الآمنة والمنضبطة داخل حاويات معزولة باستخدام NestJS و @loopstack/sandbox-filesystem، وتمكين قراءة وكتابة وقائمة وإدارة الملفات والمجلدات"},"useCases":{"en":["Securing workflow file operations within Docker sandbox environments","Managing isolated container filesystems for Loopstack tools","Executing controlled filesystem operations for containerized applications"],"zh":["在Docker沙盒环境中保护工作流文件操作的安全","为Loopstack工具管理隔离的容器文件系统","为容器化应用程序执行受控的文件系统操作"],"ja":["Dockerサンドボックス環境内でワークフロー ファイル操作のセキュリティを保護する","Loopstackツールの分離されたコンテナファイルシステムを管理する","コンテナ化アプリケーション用の制御されたファイルシステム操作を実行する"],"ko":["Docker 샌드박스 환경 내에서 워크플로 파일 연산의 보안을 보호하는こと","Loopstack 툴의 격리된 컨테이너 파일 시스템을 관리하는 것","컨테이너화된 애플리케이션을 위한 제어된 파일 시스템 연산을 실행하는 것"],"es":["Seguridad de las operaciones de archivos de flujo de trabajo dentro de entornos de sandbox de Docker","Administración de sistemas de archivos de contenedores aislados para herramientas de Loopstack","Ejecución de operaciones de sistema de archivos controladas para aplicaciones contenerizadas"],"fr":["Sécurisation des opérations de fichiers de workflow dans des environnements de sandbox Docker","Gestion de systèmes de fichiers de conteneurs isolés pour les outils Loopstack","Exécution d''opérations de système de fichiers contrôlées pour des applications conteneurisées"],"de":["Sicherheit von Workflow-Dateioperationen innerhalb von Docker-Sandbox-Umgebungen","Verwaltung von isolierten Container-Dateisystemen für Loopstack-Tools","Ausführung von kontrollierten Dateisystemoperationen für containerisierte Anwendungen"],"pt":["Proteger operações de arquivo de fluxo de trabalho em ambientes de sandbox do Docker","Gerenciar sistemas de arquivos de contêiner isolados para ferramentas Loopstack","Executar operações de sistema de arquivos controladas para aplicativos contêinerizados"],"ru":["Защищать операции файлового потока рабочего процесса в средах sandbox Docker","Управлять изолированными файловыми системами контейнеров для инструментов Loopstack","Выполнять контролируемые операции с файловой системой для контейнеризированных приложений"],"ar":["حماية عمليات ملفات تدفق العمل في بيئات Docker المحمية","إدارة أنظمة الملفات المعزولة للحاويات لأدوات Loopstack","تشغيل عمليات نظام الملفات الخاضعة للرقابة للتطبيقات المحمولة"]},"limitations":{"en":["Requires Docker sandbox environment","Limited to Loopstack tools and NestJS framework"],"zh":["需要Docker沙盒环境","仅限于Loopstack工具和NestJS框架"],"ja":["Dockerサンドボックス環境が必要","LoopstackツールとNestJSフレームワークに限定される"],"ko":["Docker 샌드박스 환경이 필요","Loopstack 툴과 NestJS 프레임워크로 제한"],"es":["Requiere un entorno de sandbox de Docker","Limitado a herramientas de Loopstack y al framework NestJS"],"fr":["Nécessite un environnement de sandbox Docker","Limité aux outils Loopstack et au framework NestJS"],"de":["Benötigt eine Docker-Sandbox-Umgebung","Begrenzt auf Loopstack-Tools und das NestJS-Framework"],"pt":["Exige ambiente de sandbox do Docker","Limitado a ferramentas Loopstack e framework NestJS"],"ru":["Требует среды sandbox Docker","Ограничен инструментами Loopstack и фреймворком NestJS"],"ar":["يتطلب بيئة Docker المحمية","محدود بأدوات Loopstack و إطار العمل NestJS"]},"version":4},"contentHash":"bf4f50d06360515649b12dd075dbcf1a18561c78645187c4b1f9224c36205217","qualityScore":57}');
