INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('loopstack-ai/sandbox-filesystem/sandbox-filesystem-tool', 'sandbox-filesystem-tool', 'loopstack-ai', 'sandbox-filesystem', 'community', 'sandbox-filesystem-tool loopstack-ai sandbox-filesystem community The sandbox-filesystem-tool enables secure filesystem operations within Docker sandbox environments, allowing workflows to read, write, list, and manage files and directories in isolated containers, benefiting developers working with Loopstack tools. Sandbox 文件系统工具提供了安全、受控的文件系统操作，用于 Docker 沙盒环境 サンドボックスファイルシステムツールは、Docker サンドボックス環境内で安全にファイルシステム操作を実行する 샌드박스 파일시스템 툴은 Docker 샌드박스 환경에서 안전한 파일시스템 작업을 제공합니다 El sandbox-filesystem-tool es una herramienta de Loopstack que proporciona operaciones de sistema de archivos seguras en entornos de Docker Le sandbox-filesystem-tool est un outil Loopstack qui offre des opérations de système de fichiers sécurisées dans les environnements Docker Das sandbox-filesystem-tool ist ein Loopstack-Tool, das sichere Dateisystemoperationen in Docker-Umgebungen ermöglicht O sandbox-filesystem-tool é uma ferramenta do Loopstack que fornece operações de sistema de arquivos seguras em ambientes de sandbox do Docker Sandbox-filesystem-tool - это инструмент Loopstack, обеспечивающий безопасные операции с файловой системой в среде Docker أداة sandbox-filesystem-tool هي أداة من Loopstack توفر عمليات نظام الملفات الآمنة في بيئات Docker how to use sandbox-filesystem-tool sandbox-filesystem-tool setup guide Docker sandbox environment security NestJS injectable tool classes isolated container filesystem operations Loopstack tool implementation Sandbox 文件系统工具 Docker 沙盒环境 安全文件系统操作 NestJS injectable ToolBase 类 @loopstack/sandb Loopstack 工具 文件系统管理 沙盒环境安全 Provides secure filesystem operations within Docker sandbox environments Enables workflows to read, write, list, and manage files and directories in isolated containers Utilizes NestJS injectable tool classes for implementation Executes filesystem operations within sandbox containers using @loopstack/sandb Extends ToolBase for integrated functionality Supports isolated container management for enhanced security sandbox-filesystem-tool is a Loopstack tool providing secure, controlled filesystem operations within Docker sandbox environments, utilizing NestJS injectable tool classes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('leeovery/agntc/workflow-bridge', 'community', 'leeovery', 'agntc', 'leeovery/agntc', 'workflow-bridge', 0, 0, 57, '2026-03-03T16:07:51Z', '2026-03-07T03:55:55.983Z', '5fd9f97d0e6e0353e0ba1bfb1b3773db89633be95b12c535ac0cba356c0a065a', '{"id":"leeovery/agntc/workflow-bridge","name":"workflow-bridge","description":{"en":"The workflow-bridge skill automates pipeline phases for AI agents, creating plan mode handoffs that survive context compaction. It benefits developers working with technical skills like technical-discussion and technical-specification.","zh":"workflow-bridge技能用于管理pipeline阶段和上下文压缩，确保工作流程的顺畅执行","ja":"ワークフローブリッジは、パイプラインのフェーズを管理し、コンテキストの圧縮を実現するAIエージェントの重要なスキルです","ko":"워크플로우 브릿지는 파이프라인 단계와 컨텍스트 압축을 관리하여 작업 흐름을 효율적으로 진행시킵니다","es":"El workflow-bridge es una habilidad que permite la gestión eficiente de flujos de trabajo en proyectos de desarrollo con Agentes de IA. Permite la creación de un plan de continuidad determinista","fr":"Le workflow-bridge est une compétence qui permet la gestion efficace des flux de travail dans les projets de développement avec les Outils d''IA. Il permet la création d''un plan de continuité déterministe","de":"Das workflow-bridge ist eine Fähigkeit, die die effiziente Verwaltung von Arbeitsabläufen in Entwicklungsprojekten mit KI-Agents ermöglicht. Es ermöglicht die Erstellung eines deterministischen Kontinuitätsplans","pt":"O workflow-bridge é uma habilidade que permite a integração de fases de pipeline com instruções de continuação determinísticas, melhorando a eficiência do processo","ru":"Workflow-bridge - это навык, который позволяет интегрировать фазы потока работ с детерминированными инструкциями, повышая эффективность процесса","ar":"workflow-bridge هو مهارة يسمح بدمج مراحل خط الأنابيب مع تعليمات الاستمرار التي تحدد بشكل محدد، مما يحسن من كفاءة العملية"},"seo":{"title":{"en":"workflow-bridge: Pipeline Phase Automation for AI Agents","zh":"workflow-bridge 技术集成指南","ja":"ワークフローブリッジのセットアップガイド - AIエージェント","ko":"워크플로우 브릿지 개발자 설정 가이드","es":"Guía de configuración de workflow-bridge para Agentes de IA","fr":"Configurer le workflow-bridge pour les Outils d''IA","de":"Einrichtungsleitfaden für workflow-bridge in KI-Agents","pt":"Guia de Configuração do workflow-bridge: Integração de Fa...","ru":"Настройка workflow-bridge: ИИ Агенты для Оптимизации Пото...","ar":"دليل إعداد workflow-bridge: جسر العمل لتكامل مراحل أنابيب"},"description":{"en":"Discover how workflow-bridge automates pipeline phases and creates plan mode handoffs. Learn how to implement this skill in your AI agent workflow today!","zh":"了解workflow-bridge技能如何帮助您管理pipeline阶段和上下文压缩","ja":"ワークフローブリッジを使用してパイプラインのフェーズを管理し、コンテキストの圧縮を実現する","ko":"워크플로우 브릿지로 파이프라인 단계와 컨텍스트 압축을 효율적으로 관리하세요","es":"Aprende a utilizar workflow-bridge para mejorar la gestión de flujos de trabajo en tus proyectos de desarrollo con Agentes de IA","fr":"Découvrez comment configurer le workflow-bridge pour améliorer la gestion des flux de travail dans vos projets de développement avec les Outils d''IA","de":"Erfahren Sie, wie Sie workflow-bridge einrichten, um die Arbeitsabläufe in Ihren Entwicklungsprojekten mit KI-Agents zu optimieren","pt":"Aprenda a configurar o workflow-bridge para melhorar a eficiência do seu pipeline com instruções de continuação determinísticas","ru":"Узнайте, как настроить workflow-bridge для оптимизации вашего потока работ с помощью ИИ Агентов и детерминированных инструкций","ar":"تعرف على إعداد workflow-bridge لتحسين كفاءة خط أنابيبك باستخدام تعليمات الاستمرار التي تحدد بشكل محدد"},"definition":{"en":"workflow-bridge is a skill that automates pipeline phase transitions, creating deterministic continuation instructions for AI agents.","zh":"workflow-bridge是一种AI技能，用于连接和管理不同pipeline阶段","ja":"ワークフローブリッジは、パイプラインのフェーズを接続し管理するAIエージェントのスキルです","ko":"워크플로우 브릿지는 파이프라인 단계를 연결하고 관리하는 AI 에이전트의 기술입니다","es":"El workflow-bridge es una habilidad de Agentes de IA que permite la gestión de flujos de trabajo","fr":"Le workflow-bridge est une compétence des Outils d''IA qui permet la gestion des flux de travail","de":"Das workflow-bridge ist eine Fähigkeit von KI-Agents, die die Verwaltung von Arbeitsabläufen ermöglicht","pt":"O workflow-bridge é uma habilidade de software que atua como um ponte entre fases de pipeline","ru":"Workflow-bridge - это программный навык, который действует как мост между фазами потока работ","ar":"workflow-bridge هي مهارة برمجية تعمل كجسر بين مراحل خط الأنابيب"},"features":{"en":["Enters plan mode with deterministic continuation instructions","Discovers next pipeline phase and creates plan mode handoffs","Survives context compaction for seamless workflow transitions","Invoked by processing skills like technical-discussion and technical-specification","Adheres to ZERO OUTPUT RULE for efficient processing"],"zh":["支持确定性续行指令","自动发现下一个pipeline阶段","创建计划模式交接以应对上下文压缩","与技术讨论和技术规格等技能集成","遵循零输出规则以减少不必要的输出"],"ja":["決定性継続命令をサポート","次のパイプラインフェーズを自動で発見","コンテキスト圧縮に対応する計画モードハンドオフを作成","技術的な議論や技術的な仕様などのスキルと統合","不要な出力を減らすためのゼロ出力規則を遵守"],"ko":["결정적续行 지시를 지원","다음 파이프라인 단계를 자동으로 발견","컨텍스트 압축에 대응하는 계획 모드 핸드오버 생성","기술적인 토론과 기술적인 사양 등의 기술과 통합","불필요한 출력을 줄이기 위한 제로 출력 규칙을 따름"],"es":["Planificación de continuidad determinista","Creación de un plan de continuidad que sobrevive a la compactación de contexto","Invocación por habilidades de procesamiento como technical-discussion y technical-specification","Compatibilidad con fases de pipeline","Soporte para la gestión de flujos de trabajo en proyectos de desarrollo"],"fr":["Planification de continuité déterministe","Création d''un plan de continuité qui survive à la compaction de contexte","Invocation par des compétences de traitement comme technical-discussion et technical-specification","Compatibilité avec les phases de pipeline","Prise en charge de la gestion des flux de travail dans les projets de développement"],"de":["Planung von deterministischer Kontinuität","Erstellung eines Kontinuitätsplans, der die Kontextkomprimierung überlebt","Aufruf durch Verarbeitungsfähigkeiten wie technical-discussion und technical-specification","Kompatibilität mit Pipeline-Phasen","Unterstützung für die Verwaltung von Arbeitsabläufen in Entwicklungsprojekten"],"pt":["Integração de fases de pipeline com instruções de continuação determinísticas","Suporte a plan mode com handoff que sobrevive à compactação de contexto","ZERO OUTPUT RULE para evitar saídas desnecessárias","Invocação por habilidades de processamento como technical-discussion e technical-specification","Descoberta da próxima fase do pipeline"],"ru":["Интеграция фаз потока работ с детерминированными инструкциями","Поддержка режима планирования с передачей, которая выживает при компактации контекста","Правило ZERO OUTPUT для избежания ненужных выводов","Вызов навыками обработки, такими как technical-discussion и technical-specification","Обнаружение следующей фазы потока работ"],"ar":["دمج مراحل خط الأنابيب مع تعليمات الاستمرار التي تحدد بشكل محدد","دعم وضع تخطيط مع تسليم ينجو من ضغط السياق","قاعدة ZERO OUTPUT لمنع الإخراج غير الضروري","استدعاء مهارات المعالجة مثل مناقشة تقنية ومواصفات تقنية","اكتشاف المرحلة التالية لخط الأنابيب"]},"keywords":{"en":["how to use workflow-bridge","workflow-bridge skill for AI agents","pipeline phase automation","plan mode handoff creation","workflow-bridge setup guide","workflow-bridge vs technical-discussion","workflow-bridge install for AI workflows","what is workflow-bridge","workflow-bridge alternative for pipeline automation"],"zh":["workflow-bridge","AI技能","pipeline管理","上下文压缩","技术讨论","技术规格","确定性续行指令","计划模式交接"],"ja":["ワークフローブリッジ","AIエージェント","パイプライン管理","コンテキスト圧縮","技術的な議論","技術的な仕様","決定性継続命令","計画モードハンドオフ"],"ko":["워크플로우 브릿지","AI 에이전트","파이프라인 관리","컨텍스트 압축","기술적인 토론","기술적인 사양","결정적续行 지시","계획 모드 핸드오버"],"es":["workflow-bridge","Agentes de IA","gestión de flujos de trabajo","desarrollo de proyectos","planificación de continuidad","compactación de contexto","fases de pipeline","technical-discussion","technical-specification"],"fr":["workflow-bridge","Outils d''IA","gestion des flux de travail","développement de projets","planification de continuité","compaction de contexte","phases de pipeline","technical-discussion","technical-specification"],"de":["workflow-bridge","KI-Agents","Verwaltung von Arbeitsabläufen","Entwicklung von Projekten","Planung von Kontinuität","Kontextkomprimierung","Pipeline-Phasen","technical-discussion","technical-specification"],"pt":["workflow-bridge","integração de fases de pipeline","instruções de continuação determinísticas","plan mode","compactação de contexto","ZERO OUTPUT RULE","technical-discussion","technical-specification"],"ru":["workflow-bridge","ИИ Агенты","интеграция фаз потока работ","детерминированные инструкции","режим планирования","компактация контекста","Правило ZERO OUTPUT","technical-discussion","technical-specification"],"ar":["workflow-bridge","أدوات الذكاء الاصطناعي","دمج مراحل خط الأنابيب","تعليمات الاستمرار التي تحدد بشكل محدد","وضع تخطيط","ضغط السياق","قاعدة ZERO OUTPUT","مناقشة تقنية","مواصفات تقنية"]}},"owner":"leeovery","repo":"agntc","repoPath":"leeovery/agntc","stars":0,"forks":0,"updatedAt":"2026-03-03T16:07:51Z","topics":[],"category":"community","skillMd":{"name":"workflow-bridge","description":"","bodyPreview":"Enter plan mode with deterministic continuation instructions.\n\nThis skill is invoked by processing skills (technical-discussion, technical-specification, etc.) when a pipeline phase concludes. It discovers the next phase and creates a plan mode handoff that survives context compaction.\n\n> **ZERO OUTPUT RULE**: Do not narrate your processing. Produce no output until a step or reference file explicitly specifies display content. No \"proceeding with...\", no discovery summaries, no routing decisions","body":"Enter plan mode with deterministic continuation instructions.\n\nThis skill is invoked by processing skills (technical-discussion, technical-specification, etc.) when a pipeline phase concludes. It discovers the next phase and creates a plan mode handoff that survives context compaction.\n\n> **ZERO OUTPUT RULE**: Do not narrate your processing. Produce no output until a step or reference file explicitly specifies display content. No \"proceeding with...\", no discovery summaries, no routing decisions, no transition text. Your first output must be content explicitly called for by the instructions.\n\n## Instructions\n\nThis skill receives context from the calling processing skill:\n- **Topic**: The topic name\n- **Work type**: greenfield, feature, or bugfix\n- **Completed phase**: The phase that just concluded\n\n---\n\n## Step 1: Run Discovery\n\n!`.claude/skills/workflow-bridge/scripts/discovery.sh`\n\nIf the above shows a script invocation rather than YAML output, the dynamic content preprocessor did not run. Execute the script before continuing:\n\n```bash\n.claude/skills/workflow-bridge/scripts/discovery.sh\n```\n\nThe output contains three sections: `features:`, `bugfixes:`, and `greenfield:`. Use the known work type and topic from the calling context to extract the relevant data:\n\n#### If work type is \"feature\"\n\nFind the topic entry under `features: > topics:` and extract its `next_phase`.\n\n#### If work type is \"bugfix\"\n\nFind the topic entry under `bugfixes: > topics:` and extract its `next_phase`.\n\n#### If work type is \"greenfield\"\n\nParse the `greenfield:` section for phase-centric state:\n- `state`: Counts of artifacts across all phases\n- Phase-specific file lists with their statuses\n\n→ Proceed to **Step 2**.\n\n---\n\n## Step 2: Route to Continuation Reference\n\nBased on work type, load the appropriate continuation reference:\n\n#### If work type is \"feature\"\n\nLoad **[feature-continuation.md](references/feature-continuation.md)** and follow its instructions as written.\n\n#### If work type is \"bugfix\"\n\nLoad **[bugfix-continuation.md](references/bugfix-continuation.md)** and follow its instructions as written.\n\n#### If work type is \"greenfield\"\n\nLoad **[greenfield-continuation.md](references/greenfield-continuation.md)** and follow its instructions as written.\n\n---\n\n## Notes\n\n**Feature/bugfix** continuation references:\n1. Use discovery output to compute a single `next_phase`\n2. Call `EnterPlanMode` tool, write plan file with instructions to invoke `start-{next_phase}` with topic + work_type\n3. Call `ExitPlanMode` tool for user approval\n\nThe user will then clear context, and the fresh session will invoke the appropriate start-* skill with the topic and work_type provided, causing it to skip discovery and proceed directly to validation/processing.\n\n**Greenfield** continuation is interactive — greenfield is phase-centric with multiple actionable items, so there is no single next phase. The reference displays state, presents a menu of choices, waits for user selection, then enters plan mode with that specific choice. The plan mode content is deterministic (same as feature/bugfix) once the user has chosen.\n"},"lastSynced":"2026-03-07T03:55:55.983Z","agentAnalysis":{"suitability":{"en":"Perfect for Technical AI Agents needing automated pipeline phase management with context compaction survival","zh":"非常适合需要自动化流水线阶段管理和上下文压缩生存的技术AI代理","ja":"テクニカルAIエージェントが自動化されたパイプラインフェーズ管理とコンテキスト圧縮の生存を必要とする場合に最適","ko":"자동화된 파이프라인 단계 관리 및 컨텍스트 압축 생존이 필요한 기술 AI 에이전트에 적합","es":"Perfecto para Agentes de IA Técnicos que necesitan una gestión de fase de pipeline automatizada con supervivencia de compactación de contexto","fr":"Parfait pour les Agents d''IA Techniques ayant besoin d''une gestion de phase de pipeline automatisée avec une survie de compactage de contexte","de":"Perfekt für technische KI-Agents, die eine automatisierte Pipeline-Phasenverwaltung mit Kontextkompaktionsüberleben benötigen","pt":"Perfeito para Agentes de IA Técnicos que precisam de gerenciamento de fase de pipeline automatizado com sobrevivência de compactação de contexto","ru":"Идеально для Технических Агентов ИИ, которым необходим автоматизированный менеджмент фазы конвейера с выживанием при компактации контекста","ar":"مثالي لعميل الذكاء الاصطناعي الفني الذي يحتاج إلى إدارة阶段 أنابيب آلي مع البقاء على قيد الحياة في ضغط السياق"},"recommendation":{"en":"Empowers agents to create plan mode handoffs using deterministic continuation instructions, streamlining workflow automation with technical skills like technical-discussion and technical-specification, and ensuring seamless pipeline phase transitions","zh":"使代理能够使用确定性连续指令创建计划模式交接，简化具有技术讨论和技术规格等技术技能的工作流自动化，并确保流水线阶段的无缝过渡","ja":"エージェントが決定論的な継続指令を使用してプランモードハンドオフを作成できるようにし、技術的な議論と技術仕様などの技術スキルを備えたワークフローオートメーションを簡素化し、パイプラインフェーズの無縫な移行を保証する","ko":"에이전트가 결정론적 연속 지침을 사용하여 계획 모드 핸드오버를 생성할 수 있도록 하며, 기술적인 토론과 기술 사양 등의 기술 스킬을 갖춘 워크플로 자동화를 단순화하고, 파이프라인 단계의 무결점 전이를 보장","es":"Habilita a los agentes a crear entregas en modo de planificación utilizando instrucciones de continuación deterministas, simplificando la automatización del flujo de trabajo con habilidades técnicas como discusión técnica y especificación técnica, y garantizando transiciones de fase de pipeline sin problemas","fr":"Permet aux agents de créer des passes en mode de planification en utilisant des instructions de continuation déterministes, simplifiant l''automatisation du flux de travail avec des compétences techniques comme la discussion technique et la spécification technique, et assurant des transitions de phase de pipeline sans problème","de":"Ermöglicht es Agents, Planungsmodus-Übergaben mit deterministischen Fortsetzungsanweisungen zu erstellen, vereinfacht die Automatisierung des Arbeitsablaufs mit technischen Fähigkeiten wie technische Diskussion und technische Spezifikation und stellt einen reibungslosen Übergang zwischen den Pipeline-Phasen sicher","pt":"Habilita os agentes a criar transferências de modo de plano usando instruções de continuação determinísticas, simplificando a automação de fluxo de trabalho com habilidades técnicas como discussão técnica e especificação técnica, e garantindo transições de fase de pipeline sem interrupção","ru":"Наделяет агентов возможностью создавать передачи режима плана с помощью детерминированных инструкций продолжения, упрощая автоматизацию рабочего процесса с техническими навыками, такими как техническая дискуссия и техническая спецификация, и обеспечивая бесперебойные переходы фаз конвейера","ar":"يمكّن الوكيل من إنشاء عمليات نقل وضع الخطة باستخدام تعليمات استمرار محددة، وتبسيط آليّة عمل التيار مع مهارات تقنية مثل المناقشة الفنية والمواصفات الفنية، وضمان انتقالات سلسة لمرحلة الأنابيب"},"useCases":{"en":["Automating pipeline phase handoffs","Generating plan mode continuations","Surviving context compaction in workflow automation"],"zh":["自动化流水线阶段交接","生成计划模式连续体","在工作流自动化中生存上下文压缩"],"ja":["パイプラインフェーズハンドオフの自動化","プランモード連続体の生成","ワークフローオートメーションにおけるコンテキスト圧縮の生存"],"ko":["파이프라인 단계 핸드오버 자동화","계획 모드 연속체 생성","워크플로 자동화에서 컨텍스트 압축 생존"],"es":["Automatización de entregas de fase de pipeline","Generación de continuaciones en modo de planificación","Supervivencia de compactación de contexto en la automatización del flujo de trabajo"],"fr":["Automatisation des passes de phase de pipeline","Génération de continuations en mode de planification","Survie du compactage de contexte dans l''automatisation du flux de travail"],"de":["Automatisierung von Pipeline-Phasenübergaben","Erzeugung von Fortsetzungen im Planungsmodus","Überleben der Kontextkompaktierung in der Arbeitsablaufautomatisierung"],"pt":["Automatizar a transferência de fases de pipeline","Gerar continuidades de modo de plano","Sobreviver à compactação de contexto na automação de fluxo de trabalho"],"ru":["Автоматизировать передачу фаз конвейера","Генерировать продолжения режима плана","Выживать при компактации контекста в автоматизации рабочего процесса"],"ar":["أتمتة نقل مرحلة الأنابيب","генерировать استمرارية وضع الخطة","البقاء على قيد الحياة في ضغط السياق في آليّة عمل التيار"]},"limitations":{"en":["Requires processing skills like technical-discussion and technical-specification","ZERO OUTPUT RULE must be observed"],"zh":["需要具有技术讨论和技术规格等处理技能","必须遵守零输出规则"],"ja":["技術的な議論と技術仕様などの処理スキルを必要とする","ゼロアウトプットルールを遵守しなければならない"],"ko":["기술적인 토론과 기술 사양 등의 처리 스킬을 필요로 함","제로 출력 규칙을 준수해야 함"],"es":["Requiere habilidades de procesamiento como discusión técnica y especificación técnica","DEBE OBSERVARSE LA REGLA DE SALIDA CERO"],"fr":["Nécessite des compétences de traitement comme la discussion technique et la spécification technique","LA RÈGLE DE SORTIE ZÉRO DOIT ÊTRE OBSERVÉE"],"de":["Benötigt Verarbeitungsfähigkeiten wie technische Diskussion und technische Spezifikation","DIE NULL-AUSGABEREGEL MUSS EINGEHALTEN WERDEN"],"pt":["Requer habilidades de processamento como discussão técnica e especificação técnica","A REGRA DE SAÍDA ZERO deve ser observada"],"ru":["Требует навыков обработки, таких как техническая дискуссия и техническая спецификация","ПРАВИЛО НУЛЕВОГО ВЫХОДА должно быть соблюдено"],"ar":["يتطلب مهارات معالجة مثل المناقشة الفنية والمواصفات الفنية","يجب مراعاة قاعدة الإخراج الصفري"]},"version":4},"contentHash":"5fd9f97d0e6e0353e0ba1bfb1b3773db89633be95b12c535ac0cba356c0a065a","qualityScore":57}');
