INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('leeovery/agntc/workflow-bridge', 'workflow-bridge', 'leeovery', 'agntc', 'community', 'workflow-bridge leeovery agntc community The workflow-bridge skill automates pipeline phases for AI agents, creating plan mode handoffs that survive context compaction. It benefits developers working with technical skills like technical-discussion and technical-specification. workflow-bridge技能用于管理pipeline阶段和上下文压缩，确保工作流程的顺畅执行 ワークフローブリッジは、パイプラインのフェーズを管理し、コンテキストの圧縮を実現するAIエージェントの重要なスキルです 워크플로우 브릿지는 파이프라인 단계와 컨텍스트 압축을 관리하여 작업 흐름을 효율적으로 진행시킵니다 El workflow-bridge es una habilidad que permite la gestión eficiente de flujos de trabajo en proyectos de desarrollo con Agentes de IA. Permite la creación de un plan de continuidad determinista Le workflow-bridge est une compétence qui permet la gestion efficace des flux de travail dans les projets de développement avec les Outils d''IA. Il permet la création d''un plan de continuité déterministe Das workflow-bridge ist eine Fähigkeit, die die effiziente Verwaltung von Arbeitsabläufen in Entwicklungsprojekten mit KI-Agents ermöglicht. Es ermöglicht die Erstellung eines deterministischen Kontinuitätsplans O workflow-bridge é uma habilidade que permite a integração de fases de pipeline com instruções de continuação determinísticas, melhorando a eficiência do processo Workflow-bridge - это навык, который позволяет интегрировать фазы потока работ с детерминированными инструкциями, повышая эффективность процесса workflow-bridge هو مهارة يسمح بدمج مراحل خط الأنابيب مع تعليمات الاستمرار التي تحدد بشكل محدد، مما يحسن من كفاءة العملية how to use workflow-bridge workflow-bridge skill for AI agents pipeline phase automation plan mode handoff creation workflow-bridge setup guide workflow-bridge vs technical-discussion workflow-bridge install for AI workflows what is workflow-bridge workflow-bridge alternative for pipeline automation workflow-bridge AI技能 pipeline管理 上下文压缩 技术讨论 技术规格 确定性续行指令 计划模式交接 Enters plan mode with deterministic continuation instructions Discovers next pipeline phase and creates plan mode handoffs Survives context compaction for seamless workflow transitions Invoked by processing skills like technical-discussion and technical-specification Adheres to ZERO OUTPUT RULE for efficient processing workflow-bridge is a skill that automates pipeline phase transitions, creating deterministic continuation instructions for AI agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wesichain/wesichain/wesichain-core', 'community', 'wesichain', 'wesichain', 'wesichain/wesichain', 'wesichain-core', 0, 0, 57, '2026-02-19T09:35:05Z', '2026-03-07T03:59:02.820Z', '697cf0b2c7f3f5636ad0a5436d202950dea1342b1f8714cc89827e1ee6b9ac61', '{"id":"wesichain/wesichain/wesichain-core","name":"wesichain-core","description":{"en":"wesichain-core enables developers to build composable LLM pipelines with type-safe chaining and implement custom components in Rust. It benefits developers working with LLM agents and chains.","zh":"Wesichain-Core是一个Rust-native的LLM代理和链，支持可恢复的ReAct工作流","ja":"Wesichain-CoreはRustネイティブのLLMエージェントとチェーンで、再開可能なReActワークフローをサポート","ko":"Wesichain-Core는 러스트 네이티브 LLM 에이전트 및 체인으로 재개 가능한 ReAct 워크플ロー 지원","es":"wesichain-core es una biblioteca Rust para crear agentes de inteligencia artificial con pipelines de LLM y componentes personalizables","fr":"wesichain-core est une bibliothèque Rust pour créer des agents d''IA avec des pipelines de LLM et des composants personnalisables","de":"wesichain-core ist eine Rust-Bibliothek zur Erstellung von KI-Agents mit LLM-Pipelines und benutzerdefinierten Komponenten","pt":"O wesichain-core é uma biblioteca Rust que permite criar pipelines LLM compostas e personalizadas com type-safe chaining","ru":"Wesichain-core - это библиотека Rust, позволяющая создавать составные LLM-пipelines с type-safe chaining","ar":"وesichain-core هو مكتبة رست تعمل على إنشاء خطوط أنابيب LLM القابلة للتركيب والتعديل مع ربط آمن"},"seo":{"title":{"en":"wesichain-core: Composable LLM Pipelines Setup Guide | AI...","zh":"Wesichain-Core快速入门：构建可复用LLM管道","ja":"Wesichain-Coreセットアップガイド：AIエージェントのための型安全チェーン","ko":"Wesichain-Core 설정 가이드: 재사용 가능한 LLM 파이프라인 구축","es":"Guía de configuración de wesichain-core para agentes de i...","fr":"Mise en place de wesichain-core pour les agents d''IA","de":