INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wesichain/wesichain/wesichain-core', 'wesichain-core', 'wesichain', 'wesichain', 'community', 'wesichain-core wesichain wesichain community agents ai async langchain llm rust tokio wasm wesichain-core enables developers to build composable LLM pipelines with type-safe chaining and implement custom components in Rust. It benefits developers working with LLM agents and chains. Wesichain-Core是一个Rust-native的LLM代理和链，支持可恢复的ReAct工作流 Wesichain-CoreはRustネイティブのLLMエージェントとチェーンで、再開可能なReActワークフローをサポート Wesichain-Core는 러스트 네이티브 LLM 에이전트 및 체인으로 재개 가능한 ReAct 워크플ロー 지원 wesichain-core es una biblioteca Rust para crear agentes de inteligencia artificial con pipelines de LLM y componentes personalizables wesichain-core est une bibliothèque Rust pour créer des agents d''IA avec des pipelines de LLM et des composants personnalisables wesichain-core ist eine Rust-Bibliothek zur Erstellung von KI-Agents mit LLM-Pipelines und benutzerdefinierten Komponenten O wesichain-core é uma biblioteca Rust que permite criar pipelines LLM compostas e personalizadas com type-safe chaining Wesichain-core - это библиотека Rust, позволяющая создавать составные LLM-пipelines с type-safe chaining وesichain-core هو مكتبة رست تعمل على إنشاء خطوط أنابيب LLM القابلة للتركيب والتعديل مع ربط آمن how to use wesichain-core wesichain-core alternative wesichain-core install wesichain-core vs langchain what is wesichain-core wesichain-core setup guide wesichain-core rust example wesichain-core tokio integration wesichain-core wasm support Wesichain-Core LLM代理 Rust 异步工作流 类型安全 可重试 AIエージェント LLM管道 Build composable LLM pipelines with type-safe chaining Implement custom components that plug into the Runnable ecosystem Add retry logic, streaming, or error handling to your chains Create reusable, testable LLM components in Rust using async_trait Utilize Tokio for async operations and WASM for web assembly support Integrate with Langchain for large language model capabilities wesichain-core is a Rust-native framework for building LLM agents and chains with resumable ReAct workflows, supporting features like retry logic and streaming.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('steebchen/proof-of-war/dojo-indexer', 'community', 'steebchen', 'proof-of-war', 'steebchen/proof-of-war', 'dojo-indexer', 0, 0, 57, '2026-02-23T18:57:50Z', '2026-03-07T03:59:56.173Z', 'c6712331d16ddffd6952a19ef54a650ef23588e2ec297d24345ea7680a9130db', '{"id":"steebchen/proof-of-war/dojo-indexer","name":"dojo-indexer","description":{"en":"The dojo-indexer skill manages Torii indexer for efficient querying and real-time subscriptions to your world state, benefiting developers who need to optimize their data management.","zh":"Dojo Indexer（Torii）是一个用于高效查询和实时订阅的工具，帮助开发者优化世界状态访问","ja":"Dojo Indexer（Torii）は、効率的なクエリーとリアルタイムサブスクリプションを実現するツールで、開発者が世界状態へのアクセスを最適化するのに役立ちます","ko":"도조 인덱서（토리이）는 효율적인 쿼리와 실시간 구독을 제공하는 도구로, 개발자가 세계 상태 접근을 최적화하는 데 도움이 됩니다","es":"Dojo Indexer es una herramienta para gestionar Torii, permitiendo consultas eficientes y suscripciones en tiempo real","fr":"Dojo Indexer est un outil pour gérer Torii, permettant des requêtes efficaces et des abonnements en temps réel","de":"Dojo Indexer ist ein Tool zum Verwalten von Torii, ermöglicht effiziente Abfragen und Echtzeit-Abonnements","pt":"O Dojo Indexer é uma ferramenta para consultas eficientes e assinaturas em tempo real. Aprenda a configurá-lo com GraphQL e SQL.","ru":"Dojo Indexer - это инструмент для эффективных запросов и подписок в реальном времени. Узнайте, как его настроить с помощью GraphQL и SQL.","ar":"دوچو إنديكسر هو أداة للاستفسارات الفعالة والاشتراكات في الوقت الفعلي. تعرف على كيفية إعدادها مع جراف كيو إل و إس كيو إل"},"seo":{"title":{"en":"dojo-indexer: Setup Guide for Efficient Querying | AI Age...","zh":"Dojo Indexer 设置指南 - Torii 高效查询和实时订阅","ja":"Dojo Indexer の設定ガイド - Torii を使用した効率的なクエリーとリアルタイムサブスクリプション","ko":"도조 인덱서 설정 가이드 - 토리이를 사용한 효율적인 쿼리와 실시간 구독","es":"Guía de configuración de Dojo Indexer para consultas efic...","fr":"Guide de mise en place de Dojo Indexer pour des requêtes ...","de":"Einrichtungsleitfaden für Dojo Indexer zur effizienten Ab...","pt":"Guia de Configuração do Dojo Indexer para Consultas Efici...","ru":"Настройка Dojo Indexer: Руководство по эффективным запросам","ar":"دليل إعداد دوچو إنديكسر للاستفسارات الفعالة"},"description":{"en":"Unlock efficient querying and real-time subscriptions with dojo-indexer. Learn how to set up and use Torii for optimal world state management - get started now!","zh":"了解如何设置和使用 Dojo Indexer（Torii）进行高效的查询和实时订阅，优化世界状态访问","ja":"Dojo Indexer（Torii）を設定して使用する方法を学び、効率的なクエリーとリアルタイムサブスクリプションで世界状態へのアクセスを最適化する","ko":"도조 인덱서（토리이）를 설정하고 사용하여 효율적인 쿼리와 실시간 구독으로 세계 상태 접근을 최적화하는 방법을 알아보세요","es":"Aprende a configurar Torii, el indexador de Dojo, para consultas GraphQL y suscripciones en tiempo real","fr":"Découvrez comment configurer Torii, l''indexeur Dojo, pour des requêtes GraphQL et des abonnements en temps réel","de":"Erfahren Sie, wie Sie Torii, den Dojo-Indexer, für GraphQL-Abfragen und Echtzeit-Abonnements einrichten","pt":"Aprenda a configurar o Dojo Indexer para consultas eficientes e assinaturas em tempo real com GraphQL e SQL","ru":"Узнайте, как настроить Dojo Indexer для эффективных запросов и подписок в реальном времени с помощью GraphQL и SQL","ar":"تعرف على كيفية إعداد دوچو إنديكسر للاستفسارات الفعالة والاشتراكات في الوقت الفعلي باستخدام جراف كيو إل و إس كيو إل"},"definition":{"en":"dojo-indexer is a skill that sets up and uses Torii, the Dojo indexer, for efficient querying and real-time subscriptions to your world state.","zh":"Dojo Indexer（Torii）是一种用于管理和优化世界状态访问的索引工具","ja":"Dojo Indexer（Torii）は、世界状態へのアクセスを管理し最適化するためのインデックスツールです","ko":"도조 인덱서（토리이）は 세계 상태 접근을 관리하고 최적화하는 인덱스 도구입니다","es":"Dojo Indexer es un indexador que permite la gestión de Torii para consultas y suscripciones en tiempo real","fr":"Dojo Indexer est un indexeur qui permet la gestion de Torii pour des requêtes et des abonnements en temps réel","de":"Dojo Indexer ist ein Indexer, der die Verwaltung von Torii für Abfragen und Echtzeit-Abonnements ermöglicht","pt":"O Dojo Indexer é um índice de consulta eficiente para worlds state, permitindo consultas GraphQL e assinaturas em tempo real","ru":"Dojo Indexer - это эффективный индекс запросов для состояния мира, позволяющий выполнять запросы GraphQL и подписки в реальном времени","ar":"دوچو إنديكسر هو فهرس استفسار فعال لولاية العالم، يسمح بالاستفسارات جراف كيو إل والاشتراكات في الوقت الفعلي"},"features":{"en":["Starts and configures Torii indexer","Creates GraphQL queries for efficient data retrieval","Sets up real-time subscriptions for entity updates","Accesses SQL database directly for advanced querying","Manages world state efficiently using Torii"],"zh":["支持 GraphQL 查询","提供实时订阅功能","直接访问 SQL 数据库","高效的世界状态访问","支持 Torii 索引器配置"],"ja":["GraphQL クエリーをサポート","リアルタイムサブスクリプション機能を提供","SQL データベースへの直接アクセス","効率的な世界状態へのアクセス","Torii インデックスの設定をサポート"],"ko":["GraphQL 쿼리를 지원","실시간 구독 기능을 제공","SQL 데이터베이스에 직접 접근","효율적인 세계 상태 접근","토리이 인덱서 설정을 지원"],"es":["Configuración de Torii","Creación de consultas GraphQL","Suscripciones en tiempo real","Acceso directo a la base de datos SQL"],"fr":["Configuration de Torii","Création de requêtes GraphQL","Abonnements en temps réel","Accès direct à la base de données SQL"],"de":["Konfiguration von Torii","Erstellung von GraphQL-Abfragen","Echtzeit-Abonnements","Direkter Zugriff auf die SQL-Datenbank"],"pt":["Configuração do Torii","Criação de consultas GraphQL","Assinaturas em tempo real","Acesso direto ao banco de dados SQL"],"ru":["Настройка Torii","Создание запросов GraphQL","Подписки в реальном времени","Прямой доступ к базе данных SQL"],"ar":["إعداد تور二","إنشاء استفسارات جراف كيو إل","الاشتراكات في الوقت الفعلي","الدخول المباشر إلى قاعدة البيانات إس كيو إل"]},"keywords":{"en":["how to use dojo-indexer","what is dojo-indexer","dojo-indexer setup guide","dojo-indexer alternative","dojo-indexer vs GraphQL","dojo-indexer install","Torii indexer configuration","efficient querying with dojo-indexer","real-time subscriptions with dojo-indexer"],"zh":["Dojo Indexer","Torii","GraphQL","实时订阅","世界状态访问","索引工具","AIエージェント","设置指南"],"ja":["Dojo Indexer","Torii","GraphQL","リアルタイムサブスクリプション","世界状態へのアクセス","インデックスツール","AIエージェント","設定ガイド"],"ko":["도조 인덱서","토리이","GraphQL","실시간 구독","세계 상태 접근","인덱스 도구","AI 에이전트","설정 가이드"],"es":["Dojo Indexer","Torii","consultas GraphQL","suscripciones en tiempo real","base de datos SQL","herramientas de desarrollo","Guía de configuración de Dojo Indexer","optimización de consultas"],"fr":["Dojo Indexer","Torii","requêtes GraphQL","abonnements en temps réel","base de données SQL","outils de développement","Guide de mise en place de Dojo Indexer","optimisation de requêtes"],"de":["Dojo Indexer","Torii","GraphQL-Abfragen","Echtzeit-Abonnements","SQL-Datenbank","Entwicklungstools","Einrichtungsleitfaden für Dojo Indexer","Abfrageoptimierung"],"pt":["dojo indexer","torii","graphql","sql","consultas eficientes","assinaturas em tempo real","ferramentas de desenvolvimento","índice de consulta","world state"],"ru":["dojo indexer","тории","graphql","sql","эффективные запросы","подписки в реальном времени","инструменты разработки","индекс запросов","состояние мира"],"ar":["دوچو إنديكسر","تور二","جراف كيو إل","إس كيو إل","لاستفسارات الفعالة","الاشتراكات في الوقت الفعلي","أدوات التطوير","فهرس الاستفسار","حالة العالم"]}},"owner":"steebchen","repo":"proof-of-war","repoPath":"steebchen/proof-of-war","stars":0,"forks":0,"updatedAt":"2026-02-23T18:57:50Z","topics":[],"category":"community","skillMd":{"name":"dojo-indexer","description":"Set up and configure Torii indexer for GraphQL queries, gRPC subscriptions, and SQL access. Use when indexing your deployed world for client queries or real-time updates.","bodyPreview":"# Dojo Indexer (Torii)\n\nSet up and use Torii, the Dojo indexer, for efficient querying and real-time subscriptions to your world state.\n\n## When to Use This Skill\n\n- \"Set up Torii indexer\"\n- \"Configure GraphQL for my world\"\n- \"Create subscriptions for entity updates\"\n- \"Query world state efficiently\"\n\n## What This Skill Does\n\nManages Torii indexer:\n- Start and configure Torii\n- Create GraphQL queries\n- Set up real-time subscriptions\n- Access SQL database directly\n\n## Quick Start\n\n**Start Torii:*","body":"# Dojo Indexer (Torii)\n\nSet up and use Torii, the Dojo indexer, for efficient querying and real-time subscriptions to your world state.\n\n## When to Use This Skill\n\n- \"Set up Torii indexer\"\n- \"Configure GraphQL for my world\"\n- \"Create subscriptions for entity updates\"\n- \"Query world state efficiently\"\n\n## What This Skill Does\n\nManages Torii indexer:\n- Start and configure Torii\n- Create GraphQL queries\n- Set up real-time subscriptions\n- Access SQL database directly\n\n## Quick Start\n\n**Start Torii:**\n```bash\ntorii --world <WORLD_ADDRESS>\n```\n\nThis starts Torii with default settings:\n- GraphQL API at `http://localhost:8080/graphql`\n- gRPC API at `http://localhost:8080`\n- In-memory database (for development)\n\n**With Controller indexing (recommended):**\n```bash\ntorii --world <WORLD_ADDRESS> --indexing.controllers\n```\n\n**Production configuration:**\n```bash\ntorii --world <WORLD_ADDRESS> --db-dir ./torii-db --indexing.controllers\n```\n\n## What is Torii?\n\nTorii is the Dojo indexer that:\n- Watches blockchain for world events\n- Indexes model state changes\n- Provides GraphQL API for queries\n- Provides gRPC API for subscriptions\n- Offers SQL access for complex queries\n\n**Why use Torii:**\n- Faster than direct RPC queries\n- Complex queries (filters, pagination)\n- Real-time subscriptions\n- Type-safe GraphQL schema\n\n## GraphQL API\n\nTorii provides GraphQL endpoint at `http://localhost:8080/graphql`\n\nUse the GraphiQL IDE in your browser to explore the schema and test queries.\n\n### Schema Structure\n\nTorii generates two types of queries:\n\n**Generic Queries:**\n- `entities` - Access all entities with filtering\n- `models` - Retrieve model definitions\n- `transactions` - Query indexed transactions\n\n**Model-Specific Queries:**\n- `{modelName}Models` - Custom queries for each model\n- Example: `positionModels`, `movesModels`\n\n### Basic Queries\n\n**Get all entities of a model:**\n```graphql\nquery {\n    movesModels {\n        edges {\n            node {\n                player\n                remaining\n                last_direction\n            }\n        }\n    }\n}\n```\n\n**Get model metadata:**\n```graphql\nquery {\n    models {\n        edges {\n            node {\n                id\n                name\n                classHash\n                contractAddress\n            }\n        }\n        totalCount\n    }\n}\n```\n\n### Pagination\n\n**Cursor-based pagination:**\n```graphql\nquery {\n    entities(first: 10) {\n        edges {\n            cursor\n            node {\n                id\n            }\n        }\n        pageInfo {\n            hasNextPage\n            endCursor\n        }\n    }\n}\n```\n\n**Get next page:**\n```graphql\nquery {\n    entities(first: 10, after: \"cursor_value\") {\n        edges {\n            cursor\n            node { id }\n        }\n    }\n}\n```\n\n**Offset/limit pagination:**\n```graphql\nquery {\n    entities(offset: 20, limit: 10) {\n        edges {\n            node { id }\n        }\n        totalCount\n    }\n}\n```\n\n## Real-time Subscriptions\n\nSubscribe to world state changes via WebSocket.\n\n### Entity Updates\n\n```graphql\nsubscription {\n    entityUpdated(id: \"0x54f58...\") {\n        id\n        updatedAt\n        models {\n            __typename\n            ... on Position {\n                vec {\n                    x\n                    y\n                }\n            }\n            ... on Moves {\n                remaining\n            }\n        }\n    }\n}\n```\n\n### Event Stream\n\nMonitor all world events:\n\n```graphql\nsubscription {\n    eventEmitted {\n        id\n        keys\n        data\n        transactionHash\n    }\n}\n```\n\n### Model Registration\n\nListen for new model registrations:\n\n```graphql\nsubscription {\n    modelRegistered {\n        id\n        name\n        namespace\n    }\n}\n```\n\n## SQL Access\n\nTorii stores data in SQLite, accessible for complex queries.\n\n**Connect to database:**\n```bash\nsqlite3 torii.db\n```\n\n**Example queries:**\n```sql\n-- Count entities\nSELECT COUNT(*) FROM entities;\n\n-- Custom aggregations\nSELECT AVG(value) FROM model_data WHERE model_name = ''Health'';\n```\n\n## Client Integration\n\n### JavaScript/TypeScript\n\n```typescript\nimport { createClient } from ''@dojoengine/torii-client'';\n\nconst client = await createClient({\n    rpcUrl: \"http://localhost:5050\",\n    toriiUrl: \"http://localhost:8080\",\n    worldAddress: WORLD_ADDRESS,\n});\n\n// Query entities\nconst positions = await client.getEntities({\n    model: \"Position\",\n    limit: 10\n});\n\n// Subscribe to updates\nawait client.onEntityUpdated(\n    [{ model: \"Position\", keys: [playerId] }],\n    (entity) => console.log(\"Position updated:\", entity)\n);\n```\n\n### Apollo Client (GraphQL)\n\n```typescript\nimport { ApolloClient, InMemoryCache, gql } from ''@apollo/client'';\n\nconst client = new ApolloClient({\n    uri: ''http://localhost:8080/graphql'',\n    cache: new InMemoryCache(),\n});\n\nconst { data } = await client.query({\n    query: gql`\n        query GetMoves {\n            movesModels {\n                edges {\n                    node {\n                        player\n                        remaining\n                    }\n                }\n            }\n        }\n    `\n});\n```\n\n## Configuration Options\n\n| Option | Description | Default |\n|--------|-------------|---------|\n| `--world` | World contract address | Optional (since Torii 1.6.0) |\n| `--rpc` | RPC endpoint URL | `http://localhost:5050` |\n| `--db-dir` | Database directory | In-memory |\n| `--config` | Path to TOML configuration file | None |\n| `--http.cors_origins` | CORS origins | `*` |\n\n## Slot Deployment (Remote)\n\n[Slot](https://docs.cartridge.gg/slot) provides hosted Torii instances. Slot requires a TOML configuration file.\n\n### Create Configuration\n\n```toml\n# torii.toml\nworld_address = \"<WORLD_ADDRESS>\"\nrpc = \"<RPC_URL>\"\n\n[indexing]\ncontrollers = true\n```\n\nSee the [Torii configuration guide](/toolchain/torii/configuration) for all TOML options (indexing, polling, namespaces, etc.).\n\n### Deploy\n\n```bash\nslot auth login\n\nslot deployments create <PROJECT_NAME> torii --config torii.toml --version <DOJO_VERSION>\n```\n\n### Manage\n\n```bash\n# Stream logs\nslot deployments logs <PROJECT_NAME> torii -f\n\n# Delete and recreate (safe — all data is on-chain)\nslot deployments delete <PROJECT_NAME> torii\n```\n\n## Development Workflow\n\n**Terminal 1: Start Katana**\n```bash\nkatana --dev --dev.no-fee\n```\n\n**Terminal 2: Deploy world**\n```bash\nsozo build && sozo migrate\n```\n\n**Terminal 3: Start Torii**\n```bash\ntorii --world <WORLD_ADDRESS> --http.cors_origins \"*\"\n```\n\n## Troubleshooting\n\n### \"Connection refused\"\n- Check Torii is running\n- Verify port (default 8080)\n- Check firewall rules\n\n### \"World not found\"\n- Verify world address is correct\n- Check RPC URL is accessible\n- Ensure world is deployed\n\n### \"Slow queries\"\n- Use model-specific queries instead of generic `entities`\n- Use pagination\n- Request only needed fields\n\n## Next Steps\n\nAfter Torii setup:\n1. Integrate with client (`dojo-client` skill)\n2. Create optimized queries\n3. Set up subscriptions\n4. Monitor performance\n\n## Related Skills\n\n- **dojo-deploy**: Deploy world first\n- **dojo-client**: Use Torii in clients\n- **dojo-world**: Configure what Torii indexes\n- **dojo-migrate**: Restart Torii after migrations\n"},"lastSynced":"2026-03-07T03:59:56.173Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing efficient data management and real-time subscriptions to their world state via Torii indexer and GraphQL.","zh":"适合需要高效数据管理和通过Torii indexer和GraphQL实时订阅其世界状态的AI代理。","ja":"Torii indexerとGraphQLを介した効率的なデータ管理とリアルタイムのワールド状態へのサブスクリプションが必要なAIエージェントに最適です。","ko":"Torii indexer와 GraphQL을 통해 효율적인 데이터 관리와 실시간 세계 상태 구독이 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan una gestión de datos eficiente y suscripciones en tiempo real a su estado del mundo a través de Torii indexer y GraphQL.","fr":"Parfait pour les agents IA nécessitant une gestion de données efficace et des abonnements en temps réel à leur état du monde via Torii indexer et GraphQL.","de":"Perfekt für KI-Agents, die eine effiziente Datenverwaltung und Echtzeit-Abonnements für ihren Weltzustand über Torii indexer und GraphQL benötigen.","pt":"Perfeito para Agentes de IA que necessitam de gerenciamento de dados eficiente e assinaturas em tempo real para o seu estado de mundo via Torii indexer e GraphQL.","ru":"Идеально подходит для агентов ИИ, которым необходим эффективный менеджмент данных и подписки в реальном времени на их состояние мира через Torii indexer и GraphQL.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى إدارة بيانات فعالة وتسجيلات في وقت حقيقي في حالة عالمهم عبرTorii indexer و GraphQL."},"recommendation":{"en":"Empowers agents to manage Torii indexer for efficient querying and real-time subscriptions, leveraging GraphQL for optimized data access and SQL database direct access for comprehensive world state management.","zh":"赋予代理管理Torii indexer以进行高效查询和实时订阅的能力，利用GraphQL进行优化的数据访问，并直接访问SQL数据库以实现全面世界状态管理。","ja":"エージェントがTorii indexerを管理して効率的なクエリとリアルタイムのサブスクリプションを行い、GraphQLを使用して最適化されたデータアクセスを行い、SQLデータベースに直接アクセスして包括的なワールド状態管理を行うことができます。","ko":"에이전트가 Torii indexer를 관리하여 효율적인 쿼리와 실시간 구독을 수행하고 GraphQL을 사용하여 최적화된 데이터 액세스를 수행하며 SQL 데이터베이스에 직접 액세스하여 포괄적인 세계 상태 관리를 수행할 수 있습니다.","es":"Habilita a los agentes a gestionar Torii indexer para consultas eficientes y suscripciones en tiempo real, aprovechando GraphQL para un acceso a datos optimizado y acceso directo a bases de datos SQL para una gestión integral del estado del mundo.","fr":"Permet aux agents de gérer Torii indexer pour des requêtes efficaces et des abonnements en temps réel, en exploitant GraphQL pour un accès aux données optimisé et un accès direct aux bases de données SQL pour une gestion complète de l''état du monde.","de":"Ermöglicht es Agents, Torii indexer für effiziente Abfragen und Echtzeit-Abonnements zu verwalten, indem GraphQL für optimierten Datenzugriff und direkten Zugriff auf SQL-Datenbanken für umfassende Weltzustandsverwaltung genutzt wird.","pt":"Habilita os agentes a gerenciar o Torii indexer para consultas eficientes e assinaturas em tempo real, aproveitando o GraphQL para acesso a dados otimizado e acesso direto ao banco de dados SQL para gerenciamento abrangente do estado do mundo.","ru":"Наделяет агентов возможностью управлять Torii indexer для эффективных запросов и подписок в реальном времени, используя GraphQL для оптимизированного доступа к данным и прямого доступа к базе данных SQL для комплексного управления состоянием мира.","ar":"يمنح الوكلاء القدرة على إدارة Torii indexer من أجل استفسارات فعالة وتسجيلات في وقت حقيقي، مستفيداً من GraphQL للوصول الأمثل إلى البيانات والوصول المباشر إلى قاعدة بيانات SQL لإدارة شاملة لحالة العالم."},"useCases":{"en":["Configuring Torii indexer for real-time entity updates","Creating efficient GraphQL queries for world state data","Setting up subscriptions for automated data synchronization","Accessing SQL databases directly for advanced data analysis"],"zh":["配置Torii indexer以进行实时实体更新","创建高效的GraphQL查询以获取世界状态数据","设置订阅以实现自动数据同步","直接访问SQL数据库以进行高级数据分析"],"ja":["リアルタイムのエンティティ更新のためにTorii indexerを設定する","ワールド状態データを取得するための効率的なGraphQLクエリを作成する","自動データ同期のためにサブスクリプションを設定する","高級なデータ分析のためにSQLデータベースに直接アクセスする"],"ko":["실시간 엔티티 업데이트를 위한 Torii indexer 설정","세계 상태 데이터를 가져오기 위한 효율적인 GraphQL 쿼리 생성","자동 데이터 동기화를 위한 구독 설정","고급 데이터 분석을 위한 SQL 데이터베이스 직접 액세스"],"es":["Configuración de Torii indexer para actualizaciones de entidades en tiempo real","Creación de consultas GraphQL eficientes para datos del estado del mundo","Configuración de suscripciones para la sincronización de datos automatizada","Acceso directo a bases de datos SQL para análisis de datos avanzados"],"fr":["Configuration de Torii indexer pour des mises à jour d''entités en temps réel","Création de requêtes GraphQL efficaces pour les données de l''état du monde","Configuration des abonnements pour la synchronisation des données automatisée","Accès direct aux bases de données SQL pour une analyse de données avancée"],"de":["Konfiguration von Torii indexer für Echtzeit-Entitätsaktualisierungen","Erstellung effizienter GraphQL-Abfragen für Weltzustandsdaten","Einrichtung von Abonnements für automatisierte Datensynchronisation","Direkter Zugriff auf SQL-Datenbanken für erweiterte Datenanalyse"],"pt":["Configurando o Torii indexer para atualizações de entidades em tempo real","Criando consultas GraphQL eficientes para dados do estado do mundo","Configurando assinaturas para sincronização de dados automatizada","Acessando bancos de dados SQL diretamente para análise de dados avançada"],"ru":["Настройка Torii indexer для обновлений сущностей в реальном времени","Создание эффективных запросов GraphQL для данных состояния мира","Настройка подписок для автоматической синхронизации данных","Доступ к базам данных SQL напрямую для продвинутого анализа данных"],"ar":["تكوين Torii indexer لتحديثات الكيانات في الوقت الحقيقي","إنشاء استفسارات GraphQL فعالة لبيانات حالة العالم","تكوين التسجيلات لتزامن البيانات التلقائي","الوصول إلى قواعد بيانات SQL مباشرة للتحليل المتقدم للبيانات"]},"limitations":{"en":["Requires Torii indexer setup and configuration","GraphQL knowledge necessary for query optimization","SQL database access required for direct data manipulation"],"zh":["需要Torii indexer的设置和配置","需要GraphQL知识来优化查询","需要SQL数据库访问来直接操作数据"],"ja":["Torii indexerの設定と構成が必要","クエリの最適化のためにGraphQLの知識が必要","データの直接操作のた