INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yeohj0710/wellnessbox/capacitor-ci-cd', 'capacitor-ci-cd', 'yeohj0710', 'wellnessbox', 'community', 'capacitor-ci-cd yeohj0710 wellnessbox community The capacitor-ci-cd skill automates building, testing, and deploying Capacitor apps, benefiting developers who need CI/CD pipeline automation and app signing. Capacitor CI/CD自动化构建、测试和部署应用，支持GitHub Actions和自动签名 Capacitor CI/CDは、アプリのビルド、テスト、デプロイを自動化し、GitHub Actionsと自動署名をサポートします Capacitor CI/CD는 애플리케이션의 자동화된 빌드、테스트 및 배포를 지원하며 GitHub Actions 및 자동 서명 기능을 제공합니다 El skill capacitor-ci-cd permite automatizar la compilación, prueba y despliegue de aplicaciones Capacitor. Le skill capacitor-ci-cd permet d''automatiser la construction, les tests et le déploiement d''applications Capacitor. Das Skill capacitor-ci-cd ermöglicht die Automatisierung von Build, Test und Deployment von Capacitor-Anwendungen. O Capacitor CI/CD é uma ferramenta para automatizar a construção, teste e implantação de aplicações móveis Capacitor CI/CD - это инструмент для автоматизации xây dựng, тестирования и развертывания мобильных приложений Capacitor CI/CD هو أداة لتوفير وقت وعمالة في بناء وتجربة وتشغيل التطبيقات المتنقلة how to use capacitor-ci-cd capacitor-ci-cd setup guide automated CI/CD pipeline for Capacitor GitHub Actions for Capacitor capacitor-ci-cd vs manual deployment install capacitor-ci-cd capacitor-ci-cd tutorial Capacitor app signing automation CI/CD pipeline automation for mobile apps Capacitor CI/CD GitHub Actions 自动化构建 自动化部署 AIエージェント Capacitor应用 Automates building and testing of Capacitor apps using GitHub Actions Supports automated deployment to main and develop branches Utilizes YAML workflows for customized CI/CD pipelines Enables app signing automation for secure releases Integrates with GitHub Actions for streamlined workflow management capacitor-ci-cd is a skill that automates the build, test, and deployment process for Capacitor applications using GitHub Actions and YAML workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('citywalki/ams-ai/frontend-development', 'community', 'citywalki', 'ams-ai', 'citywalki/ams-ai', 'frontend-development', 0, 0, 57, '2026-03-01T12:48:04Z', '2026-03-07T04:04:21.237Z', 'db0a9740c25c15bca4fee41432b4f16e4ce3020588b3dbe55dbfdac7a6430fe2', '{"id":"citywalki/ams-ai/frontend-development","name":"frontend-development","description":{"en":"The frontend-development skill enables developers to build efficient UI components using Ant Design v6, React 18, and TypeScript, benefiting developers and teams working on complex web applications.","zh":"使用 Ant Design v6、React 18 和 TypeScript 进行前端开发，构建高性能和可维护的应用","ja":"Ant Design v6、React 18、TypeScript を使用したフロントエンド開発で、高パフォーマンスとメンテナンス性の高いアプリケーションを構築する","ko":"Ant Design v6, React 18, TypeScript를 사용하여 프론트엔드 개발을 진행하고, 고성능과 유지 보수 가능한 애플리케이션을 구축합니다","es":"Desarrollo frontend con React, TypeScript y Ant Design v6 para crear aplicaciones web robustas","fr":"Développement frontend avec React, TypeScript et Ant Design v6 pour créer des applications web robustes","de":"Frontend-Entwicklung mit React, TypeScript und Ant Design v6 für robuste Webanwendungen","pt":"Desenvolvimento frontend com Ant Design v6, React 18 e TypeScript para criar aplicações web escaláveis","ru":"Фронтенд-разработка с Ant Design v6, React 18 и TypeScript для создания масштабируемых веб-приложений","ar":"تطوير الواجهة الأمامية باستخدام Ant Design v6 و React 18 و TypeScript لتطوير تطبيقات الويب القابلة للتوسيع"},"seo":{"title":{"en":"Frontend-Development: Setup Guide for AI Agents | AI Agen...","zh":"AIエージェント Frontend 开发最佳实践","ja":"AIエージェント フロントエンド開発ガイド","ko":"AI 에이전트 프론트엔드 개발 설정 가이드","es":"Guía de configuración de desarrollo frontend con React y ...","fr":"Guide de mise en place du développement frontend avec Rea...","de":"Einrichtungsleitfaden für Frontend-Entwicklung mit React ...","pt":"Desenvolvimento Frontend: Guia de Configuração com React ...","ru":"Фронтенд-разработка: Настройка с React и TypeScript для И...","ar":"تطوير الواجهة الأمامية: دليل الإعداد مع React و TypeScrip..."},"description":{"en":"Unlock efficient frontend development with Ant Design v6, React 18, and TypeScript. Learn how to implement standard CRUD pages and server-side pagination.","zh":"了解如何使用 Ant Design v6、React 18 和 TypeScript 构建高性能的前端应用","ja":"Ant Design v6、React 18、TypeScript を使用した高パフォーマンス フロントエンド アプリケーションの構築方法を学ぶ","ko":"Ant Design v6, React 18, TypeScript를 사용하여 고성능 프론트엔드 애플리케이션을 구축하는 방법 알아보기","es":"Aprende a utilizar Ant Design v6, React 18 y TypeScript para crear aplicaciones frontend escalables y mantenibles","fr":"Découvrez comment utiliser Ant Design v6, React 18 et TypeScript pour créer des applications frontend évolutives et maintenables","de":"Erfahren Sie, wie Sie Ant Design v6, React 18 und TypeScript verwenden, um skalierbare und wartbare Frontend-Anwendungen zu erstellen","pt":"Aprenda a configurar um projeto de frontend com Ant Design v6, React 18 e TypeScript para desenvolver aplicações web escaláveis","ru":"Узнайте, как настроить проект фронтенда с Ant Design v6, React 18 и TypeScript для создания масштабируемых веб-приложений для ИИ Агентов","ar":"تعرف على كيفية تهيئة مشروع الواجهة الأمامية باستخدام Ant Design v6 و React 18 و TypeScript لتطوير تطبيقات الويب القابلة للتوسيع لأدوات الذكاء الاصطناعي"},"definition":{"en":"Frontend-development is the practice of building user interface components using UI frameworks like Ant Design, React, and TypeScript, following specific development conventions and workflows.","zh":"前端开发是使用 Ant Design v6、React 18 和 TypeScript 构建用户界面和交互式 Web 应用的过程","ja":"フロントエンド開発とは、Ant Design v6、React 18、TypeScript を使用してユーザー インターフェイスとインタラクティブな Web アプリケーションを構築するプロセスです","ko":"프론트엔드 개발은 Ant Design v6, React 18, TypeScript를 사용하여 사용자 인터페이스와 상호 작용형 웹 애플리케이션을 구축하는 과정입니다","es":"Desarrollo frontend es la creación de interfaces de usuario web con tecnologías como React y TypeScript","fr":"Le développement frontend est la création d''interfaces utilisateur web avec des technologies comme React et TypeScript","de":"Frontend-Entwicklung ist die Erstellung von Benutzeroberflächen für Webanwendungen mit Technologien wie React und TypeScript","pt":"Desenvolvimento frontend é a prática de criar interfaces de usuário web com tecnologias como React e TypeScript","ru":"Фронтенд-разработка - это практика создания веб-интерфейсов пользователя с помощью технологий seperti React и TypeScript для ИИ Агентов","ar":"تطوير الواجهة الأمامية هو ممارسة إنشاء واجهات المستخدم الويب باستخدام เทคโนโลยيات مثل React و TypeScript لأدوات الذكاء الاصطناعي"},"features":{"en":["Utilizes Ant Design v6 for UI component development","Leverages React 18 for building reusable and efficient components","Supports server-side pagination using page, size, and x-total-count parameters","Implements standard CRUD page features with separate search input state and query state","Employs Dialog-based create/edit functionality with relationship selection","Follows a defined development workflow with TypeScript and i18n support"],"zh":["使用 Ant Design v6 进行 UI 组件化","基于 React 18 的高性能渲染","使用 TypeScript 进行类型安全检查","服务器端分页和查询优化","对话框式创建和编辑功能"],"ja":["Ant Design v6 を使用した UI コンポーネント化","React 18 ベースの高パフォーマンス レンダリング","TypeScript を使用した型安全性のチェック","サーバー側のページングとクエリの最適化","ダイアログボックス形式の作成と編集機能"],"ko":["Ant Design v6를 사용한 UI 컴포넌트화","React 18 기반의 고성능 렌더링","TypeScript를 사용한 타입 안전성 체크","서버 측 페이지네이션과 쿼리 최적화","대화 상자 형식의 생성과 편집 기능"],"es":["Utiliza Ant Design v6 para crear interfaces de usuario personalizadas","Desarrollo con React 18 para aplicaciones web dinámicas","Tipo de datos seguro con TypeScript","Paginación del lado del servidor con parámetros de página y tamaño","Diálogos basados en la creación y edición de relaciones"],"fr":["Utilisez Ant Design v6 pour créer des interfaces utilisateur personnalisées","Développement avec React 18 pour des applications web dynamiques","Typage sécurisé avec TypeScript","Pagination côté serveur avec des paramètres de page et de taille","Dialogues basés sur la création et l''édition de relations"],"de":["Verwenden Sie Ant Design v6, um benutzerdefinierte Benutzeroberflächen zu erstellen","Entwicklung mit React 18 für dynamische Webanwendungen","Sichere Typisierung mit TypeScript","Serverseitige Paginierung mit Seiten- und Größenparametern","Dialoge für die Erstellung und Bearbeitung von Beziehungen"],"pt":["Utilização de Ant Design v6 para componentes de interface de usuário","Desenvolvimento com React 18 para criar aplicações web escaláveis","Tipagem com TypeScript para melhorar a manutenção do código","Paginação no lado do servidor com parâmetros page, size e x-total-count","Criação de diálogos para edição e criação de registros com seleção de relacionamentos"],"ru":["Использование Ant Design v6 для компонентов интерфейса пользователя","Разработка с React 18 для создания масштабируемых веб-приложений","Типизация с помощью TypeScript для улучшения поддержки кода","Пагинация на стороне сервера с параметрами page, size и x-total-count","Создание диалогов для редактирования и создания записей с выбором связей"],"ar":["استخدام Ant Design v6 لمركبات واجهة المستخدم","التطوير مع React 18 لإنشاء تطبيقات الويب القابلة للتوسيع","التنميط مع TypeScript لتحسين صيانة الكود","التنقليزية في جانب الخادم مع معاملات page و size و x-total-count","إنشاء حوارات للتعديل وإنشاء السجلات مع اختيار العلاقات"]},"keywords":{"en":["how to use frontend-development","frontend-development setup guide","what is frontend-development","frontend-development vs React","frontend-development alternative to Angular","frontend-development install with TypeScript","frontend-development tutorial for AI agents","Ant Design v6 frontend-development","React 18 frontend-development best practices","frontend-development with server-side pagination"],"zh":["AIエージェント","前端开发","Ant Design v6","React 18","TypeScript","服务器端分页","对话框式创建"],"ja":["AIエージェント","フロントエンド開発","Ant Design v6","React 18","TypeScript","サーバー側のページング","ダイアログボックス形式の作成"],"ko":["AI 에이전트","프론트엔드 개발","Ant Design v6","React 18","TypeScript","서버 측 페이지네이션","대화 상자 형식의 생성"],"es":["desarrollo frontend","React 18","TypeScript","Ant Design v6","paginación del lado del servidor","diálogos basados en la creación","tipo de datos seguro","interfaces de usuario web","aplicaciones web robustas"],"fr":["développement frontend","React 18","TypeScript","Ant Design v6","pagination côté serveur","dialogues basés sur la création","typage sécurisé","interfaces utilisateur web","applications web robustes"],"de":["Frontend-Entwicklung","React 18","TypeScript","Ant Design v6","Serverseitige Paginierung","Dialoge für die Erstellung","sichere Typisierung","Benutzeroberflächen für Webanwendungen","robuste Webanwendungen"],"pt":["desenvolvimento frontend","React 18","TypeScript","Ant Design v6","paginação no lado do servidor","diálogos para edição e criação de registros","ferramentas de desenvolvimento web","aplicações web escaláveis"],"ru":["фронтенд-разработка","React 18","TypeScript","Ant Design v6","пагинация на стороне сервера","диалоги для редактирования и создания записей","инструменты разработки веб-приложений","масштабируемые веб-приложения","ИИ Агенты"],"ar":["تطوير الواجهة الأمامية","React 18","TypeScript","Ant Design v6","التنقليزية في جانب الخادم","حوارات للتعديل وإنشاء السجلات","أدوات تطوير تطبيقات الويب","تطبيقات الويب القابلة للتوسيع","أدوات الذكاء الاصطناعي"]}},"owner":"citywalki","repo":"ams-ai","repoPath":"citywalki/ams-ai","stars":0,"forks":0,"updatedAt":"2026-03-01T12:48:04Z","topics":[],"category":"community","skillMd":{"name":"frontend-development","description":"Frontend development conventions - Use when creating or modifying AMS-AI React pages/components, including form development, page structure, i18n, and API integration","bodyPreview":"# AMS-AI Frontend Development Conventions\n\n## Overview\n\n**UI Framework**: Ant Design v6 + React 18 + TypeScript\n\nReference implementation: `app-web/src/pages/admin/RoleManagementPage.tsx`\n\nStandard CRUD page features:\n- Separate search input state from query state\n- Server-side pagination (`page`, `size`, `x-total-count`)\n- Dialog-based create/edit with relationship selection\n\n## Development Workflow\n\n1. Define Types → `lib/types.ts` or `features/*/types.ts`\n2. Add i18n → `i18n/locales/zh-CN.jso","body":"# AMS-AI Frontend Development Conventions\n\n## Overview\n\n**UI Framework**: Ant Design v6 + React 18 + TypeScript\n\nReference implementation: `app-web/src/pages/admin/RoleManagementPage.tsx`\n\nStandard CRUD page features:\n- Separate search input state from query state\n- Server-side pagination (`page`, `size`, `x-total-count`)\n- Dialog-based create/edit with relationship selection\n\n## Development Workflow\n\n1. Define Types → `lib/types.ts` or `features/*/types.ts`\n2. Add i18n → `i18n/locales/zh-CN.json` and `en-US.json`\n3. Add API → `features/*/queries.ts` (GraphQL) or `mutations.ts` (REST)\n4. Build Page → `pages/*/XManagementPage.tsx`\n5. Configure Routes → `Router.tsx`\n6. Browser Verification → Use `frontend-ui-verification` skill\n\n## Internationalization (i18n)\n\n**All user-visible text must use i18n**\n\n### Language Files\n\n- `app-web/src/i18n/locales/zh-CN.json`\n- `app-web/src/i18n/locales/en-US.json`\n\n### Naming Conventions\n\n| Pattern | Example | Description |\n|---------|---------|-------------|\n| `pages.{pageName}.title` | `pages.roleManagement.title` | Page title |\n| `pages.{pageName}.columns.{field}` | `pages.roleManagement.columns.name` | Table columns |\n| `pages.{pageName}.form.{field}` | `pages.roleManagement.form.name` | Form labels |\n| `pages.{pageName}.dialog.{action}` | `pages.roleManagement.dialog.createTitle` | Dialog titles |\n| `pages.{pageName}.messages.{type}` | `pages.roleManagement.messages.createSuccess` | Toast messages |\n\n### Usage\n\n```tsx\nimport { useTranslation } from ''react-i18next'';\n\nconst { t } = useTranslation();\n\n// Page title\n<CardTitle>{t(''pages.xManagement.title'')}</CardTitle>\n\n// Input placeholder\n<Input placeholder={t(''pages.xManagement.searchPlaceholder'')} />\n\n// Toast message\nmessage.success(t(''pages.xManagement.messages.createSuccess''));\n```\n\n### Predefined Common Keys\n\n- `common.loading`, `common.submit`, `common.cancel`, `common.confirm`\n- `common.save`, `common.delete`, `common.edit`, `common.add`, `common.search`\n- `common.loadFailed`, `common.retry`\n\n## API Architecture\n\n### Directory Structure\n\n```\nlib/\n├── apiClient.ts      # Axios REST client\n├── graphqlClient.ts  # Graffle GraphQL client\n├── queryClient.ts    # React Query config\n├── queryKeys.ts      # Query key definitions\n├── types.ts          # Shared types (UserItem, RoleItem, etc.)\n└── utils.ts\n\nfeatures/admin/*/\n├── mutations.ts      # REST commands + useMutation\n├── queries.ts        # GraphQL queries\n├── types.ts          # Feature-specific types\n└── components/       # Dialog components\n```\n\n### Query (GraphQL)\n\n```typescript\n// features/admin/roles/queries.ts\nimport { graphqlClient } from ''@/lib/graphqlClient'';\nimport { useQuery } from ''@tanstack/react-query'';\nimport { queryKeys } from ''@/lib/queryKeys'';\n\nexport const ROLES_QUERY = `\n  query Roles($page: Int, $size: Int, $keyword: String) {\n    roles(page: $page, size: $size, keyword: $keyword) {\n      content { id name code description }\n      totalElements\n    }\n  }\n`;\n\nexport function useRoles(page: number, size: number, keyword?: string) {\n  return useQuery({\n    queryKey: queryKeys.roles.list(page, size, keyword),\n    queryFn: () => graphqlClient.request(ROLES_QUERY, { page, size, keyword }),\n  });\n}\n```\n\n### Mutation (REST)\n\n```typescript\n// features/admin/roles/mutations.ts\nimport { useMutation, useQueryClient } from ''@tanstack/react-query'';\nimport { apiClient } from ''@/lib/apiClient'';\nimport { queryKeys } from ''@/lib/queryKeys'';\n\nexport function useCreateRole() {\n  const queryClient = useQueryClient();\n  return useMutation({\n    mutationFn: (data: RolePayload) => apiClient.post(''/api/system/roles'', data),\n    onSuccess: () => queryClient.invalidateQueries({ queryKey: queryKeys.roles.all() }),\n  });\n}\n```\n\n### Type Definitions\n\n```typescript\n// lib/types.ts\nexport type Id = number | string;\n\nexport interface PageResponse<T> {\n  content?: T[];\n  items?: T[];\n  totalElements?: number;\n  totalCount?: number;\n}\n\n// features/admin/roles/types.ts\nexport interface RoleItem {\n  id: Id;\n  name: string;\n  code: string;\n  description?: string;\n}\n\nexport interface RolePayload {\n  name: string;\n  code: string;\n  description?: string;\n}\n```\n\n## Ant Design Form Development\n\n### Form Layout\n\n**All forms must use horizontal layout** (labels left, inputs right):\n\n```tsx\n<Form form={form} layout=\"horizontal\" onFinish={handleSubmit}>\n  <Form.Item label={t(''pages.xxx.form.name'')} name=\"name\" rules={[{ required: true }]}>\n    <Input />\n  </Form.Item>\n</Form>\n```\n\n### Dialog with Form\n\n```tsx\nimport { Form, Modal, Input } from ''antd'';\nimport { useTranslation } from ''react-i18next'';\n\ninterface Props {\n  open: boolean;\n  mode: ''create'' | ''edit'';\n  initialValues?: RoleItem;\n  onClose: () => void;\n  onSubmit: (values: RolePayload) => Promise<void>;\n}\n\nexport function RoleFormDialog({ open, mode, initialValues, onClose, onSubmit }: Props) {\n  const { t } = useTranslation();\n  const [form] = Form.useForm();\n  const [loading, setLoading] = useState(false);\n\n  useEffect(() => {\n    if (open) {\n      form.resetFields();\n      if (initialValues) form.setFieldsValue(initialValues);\n    }\n  }, [open, initialValues, form]);\n\n  const handleOk = async () => {\n    const values = await form.validateFields();\n    setLoading(true);\n    try {\n      await onSubmit(values);\n      onClose();\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  return (\n    <Modal\n      open={open}\n      title={mode === ''create'' ? t(''pages.roleManagement.dialog.createTitle'') : t(''pages.roleManagement.dialog.editTitle'')}\n      onOk={handleOk}\n      onCancel={onClose}\n      confirmLoading={loading}\n    >\n      <Form form={form} layout=\"horizontal\" labelCol={{ span: 6 }} wrapperCol={{ span: 18 }}>\n        <Form.Item label={t(''pages.roleManagement.form.name'')} name=\"name\" rules={[{ required: true }]}>\n          <Input />\n        </Form.Item>\n        <Form.Item label={t(''pages.roleManagement.form.code'')} name=\"code\" rules={[{ required: true }]}>\n          <Input />\n        </Form.Item>\n      </Form>\n    </Modal>\n  );\n}\n```\n\n### Required Field Markers\n\nAnt Design automatically shows red asterisk `*` when `rules={[{ required: true }]}` is set.\n\n```tsx\n// ✅ Correct - Use rules for required\n<Form.Item name=\"name\" rules={[{ required: true, message: t(''common.required'') }]}>\n  <Input />\n</Form.Item>\n\n// ❌ Wrong - Don''t add asterisk manually\n<Form.Item label=\"Name*\">\n  <Input />\n</Form.Item>\n```\n\n## Page Component Construction\n\n### State Patterns\n\n```typescript\nconst [items, setItems] = useState<XItem[]>([]);\nconst [loading, setLoading] = useState(false);\nconst [error, setError] = useState<Error | null>(null);\n\n// Search: Separate input state from query state\nconst [searchKeyword, setSearchKeyword] = useState('''');\nconst [queryKeyword, setQueryKeyword] = useState('''');\n\n// Pagination: UI uses 1-based\nconst [currentPage, setCurrentPage] = useState(1);\nconst [pageSize, setPageSize] = useState(20);\nconst [total, setTotal] = useState(0);\n\n// Dialog\nconst [dialogOpen, setDialogOpen] = useState(false);\nconst [dialogMode, setDialogMode] = useState<''create'' | ''edit''>(''create'');\nconst [editingItem, setEditingItem] = useState<XItem | null>(null);\n```\n\n### Loading Pattern\n\n```typescript\nconst loadItems = useCallback(async () => {\n  setLoading(true);\n  setError(null);\n  try {\n    const params = {\n      page: Math.max(currentPage - 1, 0),  // Convert to zero-based\n      size: pageSize,\n      keyword: queryKeyword || undefined,\n    };\n    const res = await xApi.getList(params);\n    const list = res.data.content ?? res.data.items ?? [];\n    const totalHeader = res.headers?.[''x-total-count''];\n    const totalCount = Number(totalHeader) || res.data.totalElements || list.length;\n    \n    setItems(list);\n    setTotal(totalCount);\n  } catch (err) {\n    setError(err instanceof Error ? err : new Error(''Load failed''));\n  } finally {\n    setLoading(false);\n  }\n}, [currentPage, pageSize, queryKeyword]);\n```\n\n### Table with Actions\n\n```tsx\nconst columns: ColumnsType<XItem> = [\n  { title: t(''pages.xxx.columns.code''), dataIndex: ''code'', key: ''code'' },\n  { title: t(''pages.xxx.columns.name''), dataIndex: ''name'', key: ''name'' },\n  {\n    title: t(''pages.xxx.columns.actions''),\n    key: ''actions'',\n    render: (_, record) => (\n      <Space>\n        <Button type=\"link\" onClick={() => handleEdit(record)}>{t(''common.edit'')}</Button>\n        <Popconfirm title={t(''common.deleteConfirm'')} onConfirm={() => handleDelete(record.id)}>\n          <Button type=\"link\" danger>{t(''common.delete'')}</Button>\n        </Popconfirm>\n      </Space>\n    ),\n  },\n];\n\n<Table\n  columns={columns}\n  dataSource={items}\n  rowKey=\"id\"\n  loading={loading}\n  pagination={{\n    current: currentPage,\n    pageSize,\n    total,\n    showSizeChanger: true,\n    showTotal: (total) => t(''common.totalItems'', { total }),\n    onChange: (page, size) => {\n      setCurrentPage(page);\n      setPageSize(size);\n    },\n  }}\n/>\n```\n\n## Common Mistakes\n\n| Mistake | Correction |\n|---------|------------|\n| Hardcoded text in components | Use `t(''pages.xxx.key'')` for all user text |\n| Adding i18n key to only one language file | Must add to both `zh-CN.json` and `en-US.json` |\n| Using `searchKeyword` directly when loading | Keep `queryKeyword` separate from input state |\n| Sending 1-based `page` to backend | Use `Math.max(currentPage - 1, 0)` to convert |\n| Ignoring `x-total-count` header | Prefer response header, then fallback to body |\n| JS long integer precision issues | Use `string` or `number \\| string` for ID fields |\n| Not handling empty page after delete | Go back one page when current page becomes empty |\n\n## Verification\n\n```bash\ncd app-web && pnpm lint\ncd app-web && pnpm build\n```\n\nAfter completion, use the `frontend-ui-verification` skill for browser verification.\n\n## Ant Design Reference\n\n### Documentation URLs\n\n| URL | Purpose |\n|-----|---------|\n| https://ant.design/llms.txt | **Index** - Navigation to all docs |\n| https://ant.design/llms-full.txt | **Full API** - All 73 components (EN) |\n| https://ant.design/llms-full-cn.txt | **Full API** - All 73 components (CN) |\n| https://ant.design/llms-semantic.md | **Semantic DOM** - Styling guide (EN) |\n\n### Key Design Docs\n\n- [Form Design](https://ant.design/docs/spec/research-form.md) - Form UX patterns\n- [Data Display](https://ant.design/docs/spec/data-display.md) - Table/List patterns\n- [Navigation](https://ant.design/docs/spec/navigation.md) - Menu/breadcrumb patterns\n- [Feedback](https://ant.design/docs/spec/feedback.md) - Message/notification patterns\n\n### Key Components\n\n| Component | Use Case | Key Props |\n|-----------|----------|-----------|\n| `Form` | Data entry forms | `layout=\"horizontal\"`, `Form.Item`, `name`, `rules` |\n| `Table` | Data display with pagination | `columns`, `dataSource`, `pagination`, `rowKey` |\n| `Modal` | Dialogs | `open`, `onCancel`, `onOk`, `title`, `confirmLoading` |\n| `Select` | Dropdown selection | `options`, `value`, `onChange`, `mode=\"multiple\"` |\n| `Input` | Text input | `placeholder`, `value`, `onChange` |\n| `Button` | Actions | `type`, `loading`, `disabled`, `icon` |\n| `Card` | Content container | `title`, `extra` |\n| `Space` | Layout spacing | `direction`, `size` |\n| `message` | Toast notifications | `success()`, `error()`, `warning()` |\n| `Popconfirm` | Delete confirmation | `title`, `onConfirm`, `okText` |\n\n### Type Utilities (v5+)\n\n```tsx\nimport type { GetProps, GetRef, GetProp } from ''antd'';\n\ntype SelectProps = GetProps<typeof Select>;\ntype SelectRef = GetRef<typeof Select>;\ntype OptionType = GetProp<typeof Select, ''options''>[number];\n```\n"},"lastSynced":"2026-03-07T04:04:21.237Z","agentAnalysis":{"suitability":{"en":"Perfect for UI-focused Agents needing efficient frontend development capabilities with Ant Design v6, React 18, and TypeScript.","zh":"适合需要高效前端开发能力的UI焦点代理，具有Ant Design v6，React 18和TypeScript。","ja":"UIに焦点を当てたエージェントが効率的なフロントエンド開発機能を必要とする場合に適しています。Ant Design v6、React 18、TypeScriptを使用します。","ko":"UI에 중점을 둔 에이전트가 효율적인 프론트엔드 개발 능력을 필요로 할 때 적합합니다. Ant Design v6, React 18, TypeScript를 사용합니다.","es":"Perfecto para Agentes centrados en la interfaz de usuario que necesitan capacidades de desarrollo de frontend eficientes con Ant Design v6, React 18 y TypeScript.","fr":"Parfait pour les agents axés sur l''interface utilisateur nécessitant des capacités de développement de frontend efficaces avec Ant Design v6, React 18 et TypeScript.","de":"Perfekt für benutzeroberflächenorientierte Agenten, die effiziente Frontend-Entwicklungsfähigkeiten mit Ant Design v6, React 18 und TypeScript benötigen.","pt":"Perfeito para Agentes focados em UI que necessitam de capacidades de desenvolvimento de frontend eficientes com Ant Design v6, React 18 e TypeScript.","ru":"Идеально подходит для агентов, ориентированных на UI, которым необходимы эффективные возможности разработки frontend с помощью Ant Design v6, React 18 и TypeScript.","ar":"مثالي للوكلاء الذين يركزون على واجهة المستخدم وهم في حاجة إلى قدرات تطوير واجهة المستخدم الأمامية فعالة مع Ant Design v6 و React 18 و TypeScript."},"recommendation":{"en":"Empowers agents to build efficient UI components using Ant Design v6, React 18, and TypeScript, enabling the creation of complex web applications with features like server-side pagination and dialog-based create/edit functionality.","zh":"赋予代理构建高效UI组件的能力，使用Ant Design v6，React 18和TypeScript，实现复杂的Web应用程序，具有服务器端分页和基于对话框的创建/编辑功能。","ja":"エージェントがAnt Design v6、React 18、TypeScriptを使用して効率的なUIコンポーネントを構築できるようにし、サーバーサイドのページングやダイアログベースの作成/編集機能など、複雑なWebアプリケーションを作成できるようにします。","ko":"에이전트가 Ant Design v6, React 18, TypeScript를 사용하여 효율적인 UI 컴포넌트를 구축할 수 있도록 하여 서버 측 페이징 및 대화 상자 기반 생성/편집 기능과 같은 복잡한 웹 애플리케이션을 생성할 수 있도록 합니다.","es":"Habilita a los agentes a crear componentes de interfaz de usuario eficientes utilizando Ant Design v6, React 18 y TypeScript, lo que permite la creación de aplicaciones web complejas con características como paginación del lado del servidor y funcionalidad de creación/edición basada en diálogos.","fr":"Permet aux agents de créer des composants d''interface utilisateur efficaces en utilisant Ant Design v6, React 18 et TypeScript, permettant ainsi la création d''applications web complexes avec des fonctionnalités comme la pagination côté serveur et la fonctionnalité de création/édition basée sur les dialogues.","de":"Ermöglich es den Agenten, effiziente Benutzeroberflächenkomponenten mit Ant Design v6, React 18 und TypeScript zu erstellen, wodurch die Erstellung komplexer Webanwendungen mit Funktionen wie Server-seitige Paginierung und Dialog-basierte Erstellung/Bearbeitungsfunktion möglich wird.","pt":"Habilita os agentes a construir componentes de UI eficientes usando Ant Design v6, React 18 e TypeScript, permitindo a criação de aplicações web complexas com recursos como paginação no lado do servidor e funcionalidade de criação/edição baseada em diálogo.","ru":"Наделяет агентов возможностью создавать эффективные компоненты UI с помощью Ant Design v6, React 18 и TypeScript, что позволяет создавать сложные веб-приложения с функциями, такими как серверная пагинация и диалоговая функциональность создания/редактирования.","ar":"يمكن للوكلاء بناء مكونات واجهة المستخدم فعالة باستخدام Ant Design v6 و React 18 و TypeScript، مما يتيح إنشاء تطبيقات ويب معقدة مع ميزات مثل الترقيم الجانبي للخادم وتحرير وظيفة إنشاء الحوار."},"useCases":{"en":["Building standard CRUD pages with separate search input state and query state","Implementing server-side pagination using page, size, and x-total-count parameters","Creating dialog-based create/edit interfaces with relationship selection"],"zh":["构建具有独立搜索输入状态和查询状态的标准CRUD页面","使用页面、大小和x-total-count参数实现服务器端分页","创建具有关系选择的对话框式创建/编辑接口"],"ja":["個別の検索入力状態とクエリ状態を備えた標準のCRUDページを構築する","ページ、サイズ、x-total-countパラメータを使用したサーバーサイドのページングの実装","関係選択を備えたダイアログベースの作成/編集インターフェイスの作成"],"ko":["개별 검색 입력 상태 및 쿼리 상태가 있는 표준 CRUD 페이지 구축","페이지, 크기, x-total-count 매개 변수를 사용한 서버 측 페이징 구현","관계 선택을 갖춘 대화 상자 기반 생성/편집 인터페이스 생성"],"es":["Creación de páginas CRUD estándar con estado de búsqueda de entrada y estado de consulta separados","Implementación de paginación del lado del servidor utilizando los parámetros de página, tamaño y x-total-count","Creación de interfaces de creación/edición basadas en diálogos con selección de relaciones"],"fr":["Création de pages CRUD standard avec état de recherche d''entrée et état de requête séparés","Mise en œuvre de la pagination côté serveur en utilisant les paramètres de page, de taille et de x-total-count","Création d''interfaces de création/édition basées sur les dialogues avec sélection de relations"],"de":["Erstellung von Standard-CRUD-Seiten mit getrenntem Sucheingabe- und Abfragezustand","Implementierung von Server-seitiger Paginierung unter Verwendung der Parameter Seite, Größe und x-total-count","Erstellung von Dialog-basierten Erstellungs-/Bearbeitungsschnittstellen mit Beziehungsselektion"],"pt":["Construir páginas CRUD padrão com estado de entrada de pesquisa separado e estado de consulta","Implementar paginação no lado do servidor usando parâmetros de página, tamanho e x-total-count","Criar interfaces de criação/edição baseadas em diálogo com seleção de relacionamento"],"ru":["Построение стандартных страниц CRUD с отдельным состоянием поискового ввода и состоянием запроса","Реализация серверной пагинации с помощью параметров страницы, размера и x-total-count","Создание диалоговых интерфейсов создания/редактирования с выбором отношений"],"ar":["بناء صفحات CRUD القياسية مع حالة إدخال بحث منفصلة وحالة استعلام","تنفيذ ترقيم جانبي للخادم باستخدام معلمات الصفحة والحجم والعدد الإجمالي","إنشاء واجهات حوار لإنشاء/تحرير مع تحديد العلاقات"]},"limitations":{"en":["Requires knowledge of Ant Design v6, React 18, and TypeScript","Limited to web application development","Dependent on specific implementation conventions, such as those outlined in the AMS-AI Frontend Development Conventions"],"zh":["需要Ant Design v6、React 18和TypeScript的知识","仅限Web应用程序开发","依赖于特定的实现约定，例如AMS-AI前端开发约定中概述的那些"],"ja":["Ant Design v6、React 18、TypeScriptの知識が必要","Webアプリケーションの開発のみ","特定の実装規約、たとえばAMS-AIフロントエンド開発規約に概説されているようなものに依存"],"ko":["Ant Design v6, React 18, TypeScript에 대한 지식이 필요합니다.","웹 애플리케이션 개발만 해당합니다.","특정 구현 규칙, 즉 AMS-AI 프론트엔드 개발 규칙에概述된 것과 같은 것에 의존합니다."],"es":["Requiere conocimiento de Ant Design v6, React 18 y TypeScript","Limitado al desarrollo de aplicaciones web","Dependiente de convenciones de implementación específicas, como las que se describen en las Convenciones de desarrollo de frontend de AMS-AI"],"fr":["Nécessite des connaissances en Ant Design v6, React 18 et TypeScript","Limité au développement d''applications web","Dépendant de conventions d''implémentation spécifiques, telles que celles décrites dans les Conventions de développement de frontend d''AMS-AI"],"de":["Benötigt Kenntnisse von Ant Design v6, React 18 und TypeScript","Begrenzt auf die Entwicklung von Webanwendungen","Abhängig von spezifischen Implementierungskonventionen, wie z.B. den im AMS-AI-Frontend-Entwicklungs-Konventionen beschriebenen"],"pt":["Exige conhecimento de Ant Design v6, React 18 e TypeScript","Limitado ao desenvolvimento de aplicações web","Dependente de convenções de implementação específicas, como aquelas delineadas nas Convenções de Desenvolvimento de Frontend da AMS-AI"],"ru":["Требует знания Ant Design v6, React 18 и TypeScript","Ограничен разработкой веб-приложений","Зависит от конкретных конвенций реализации, таких как те, которые изложены в Конвенциях разработки frontend AMS-AI"],"ar":["يتطلب معرفة Ant Design v6 و React 18 و TypeScript","محدود بتطوير تطبيقات الويب","يعتمد على اتفاقيات تنفيذ محددة، مثل تلك المحددة في اتفاقيات تطوير واجهة المستخدم الأمامية لشركة AMS-AI"]},"version":4},"contentHash":"db0a9740c25c15bca4fee41432b4f16e4ce3020588b3dbe55dbfdac7a6430fe2","qualityScore":57}');
