INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('citywalki/ams-ai/frontend-development', 'frontend-development', 'citywalki', 'ams-ai', 'community', 'frontend-development citywalki ams-ai community The frontend-development skill enables developers to build efficient UI components using Ant Design v6, React 18, and TypeScript, benefiting developers and teams working on complex web applications. 使用 Ant Design v6、React 18 和 TypeScript 进行前端开发，构建高性能和可维护的应用 Ant Design v6、React 18、TypeScript を使用したフロントエンド開発で、高パフォーマンスとメンテナンス性の高いアプリケーションを構築する Ant Design v6, React 18, TypeScript를 사용하여 프론트엔드 개발을 진행하고, 고성능과 유지 보수 가능한 애플리케이션을 구축합니다 Desarrollo frontend con React, TypeScript y Ant Design v6 para crear aplicaciones web robustas Développement frontend avec React, TypeScript et Ant Design v6 pour créer des applications web robustes Frontend-Entwicklung mit React, TypeScript und Ant Design v6 für robuste Webanwendungen Desenvolvimento frontend com Ant Design v6, React 18 e TypeScript para criar aplicações web escaláveis Фронтенд-разработка с Ant Design v6, React 18 и TypeScript для создания масштабируемых веб-приложений تطوير الواجهة الأمامية باستخدام Ant Design v6 و React 18 و TypeScript لتطوير تطبيقات الويب القابلة للتوسيع how to use frontend-development frontend-development setup guide what is frontend-development frontend-development vs React frontend-development alternative to Angular frontend-development install with TypeScript frontend-development tutorial for AI agents Ant Design v6 frontend-development React 18 frontend-development best practices frontend-development with server-side pagination AIエージェント 前端开发 Ant Design v6 React 18 TypeScript 服务器端分页 对话框式创建 Utilizes Ant Design v6 for UI component development Leverages React 18 for building reusable and efficient components Supports server-side pagination using page, size, and x-total-count parameters Implements standard CRUD page features with separate search input state and query state Employs Dialog-based create/edit functionality with relationship selection Follows a defined development workflow with TypeScript and i18n support Frontend-development is the practice of building user interface components using UI frameworks like Ant Design, React, and TypeScript, following specific development conventions and workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LNSD/agentsync/code-test', 'community', 'LNSD', 'agentsync', 'LNSD/agentsync', 'code-test', 0, 0, 57, '2026-03-01T18:37:31Z', '2026-03-07T04:05:00.655Z', '69d83d2f7eead55f4f77aebcfa9a63e7a2cd2d6cdd1e2af88ed468e3596dcbbb', '{"id":"LNSD/agentsync/code-test","name":"code-test","description":{"en":"The code-test skill provides testing operations for project codebases using cargo-nextest. It benefits developers by automating test commands.","zh":"代码测试技能提供项目代码库的测试操作，使用cargo-nextest进行测试","ja":"コードテストスキルは、プロジェクトのコードベースのテスト操作を提供し、cargo-nextestを使用してテストを行います","ko":"코드 테스트 스킬은 프로젝트 코드베이스의 테스트 운영을 제공하며 cargo-nextest를 사용하여 테스트를 수행합니다","es":"El skill de pruebas de código proporciona operaciones de prueba para la base de código del proyecto. Utiliza exclusivamente cargo-nextest para ejecutar comandos de prueba","fr":"Le skill de tests de code fournit des opérations de test pour la base de code du projet. Il utilise exclusivement cargo-nextest pour exécuter des commandes de test","de":"Das Code-Test-Skill bietet Testoperationen für die Codebasis des Projekts. Es verwendet ausschließlich cargo-nextest, um Testkommandos auszuführen","pt":"O code-test é uma habilidade que fornece operações de teste para a base de código do projeto. Ele usa exclusivamente o cargo-nextest.","ru":"Код-тест - это навык, который предоставляет операции тестирования для базы кода проекта. Он использует исключительно cargo-nextest, популярный инструмент среди ИИ Агентов.","ar":"اختبار الكود هو مهارة توفر عمليات اختبار للكود الأساسي للمشروع. يستخدم حزمة cargo-nextest بشكل حصري"},"seo":{"title":{"en":"code-test: Automated Testing Setup Guide | AI Agent Skill","zh":"代码测试设置指南 - Code Test","ja":"コードテストベストプラクティス - Code Test","ko":"코드 테스트 설정 가이드 - Code Test","es":"Guía de configuración de pruebas de código con cargo-nextest","fr":"Guide de configuration des tests de code avec cargo-nextest","de":"Konfigurationsleitfaden für Code-Tests mit cargo-nextest","pt":"Guia de Configuração do Code-Test: Melhores Práticas para...","ru":"Настройка ИИ Агента Code-Test: Руководство по тестировани...","ar":"دليل إعداد اختبار الكود: أفضل الممارسات لاختبار الكود"},"description":{"en":"Discover how to streamline your testing workflow with code-test, featuring cargo-nextest. Learn how to install and run tests efficiently.","zh":"了解代码测试技能的功能和特点，包括cargo-nextest测试命令和测试范围选择","ja":"コードテストスキルの機能と特徴を紹介します。cargo-nextestテストコマンドやテスト範囲選択など","ko":"코드 테스트 스킬의 기능과 특징을 알아보세요. cargo-nextest 테스트 명령과 테스트 범위 선택 등","es":"Aprende a configurar y ejecutar pruebas de código con cargo-nextest. Descubre cómo seleccionar el alcance de las pruebas y ejecutar comandos de prueba","fr":"Découvrez comment configurer et exécuter des tests de code avec cargo-nextest. Apprenez à sélectionner la portée des tests et à exécuter des commandes de test","de":"Erfahren Sie, wie Sie Code-Tests mit cargo-nextest konfigurieren und ausführen. Entdecken Sie, wie Sie den Umfang der Tests auswählen und Testkommandos ausfü...","pt":"Aprenda a configurar o code-test para melhorar a qualidade do seu código. Descubra como usar o cargo-nextest para testar seu projeto.","ru":"Узнайте, как настроить код-тест для улучшения качества вашего кода. Откройте для себя, как использовать cargo-nextest для тестирования вашего проекта с помощ...","ar":"تعلم كيفية إعداد اختبار الكود لتحسين جودة كودك. اكتشف كيفية استخدام cargo-nextest لاختبار مشروعك"},"definition":{"en":"code-test is a skill that offers automated testing capabilities for project codebases, utilizing cargo-nextest for efficient test operations.","zh":"代码测试技能是一种使用cargo-nextest进行代码测试的技术","ja":"コードテストスキルは、cargo-nextestを使用してコードをテストする技術です","ko":"코드 테스트 스킬은 cargo-nextest를 사용하여 코드를 테스트하는 기술입니다","es":"Un skill de pruebas de código es una herramienta que permite probar y validar el código de un proyecto utilizando cargo-nextest","fr":"Un skill de tests de code est un outil qui permet de tester et de valider le code d''un projet en utilisant cargo-nextest","de":"Ein Code-Test-Skill ist ein Tool, das es ermöglicht, den Code eines Projekts mit cargo-nextest zu testen und zu validieren","pt":"O que é code-test? É uma habilidade de teste de código que usa cargo-nextest para garantir a qualidade do código.","ru":"Что такое код-тест? Это навык тестирования кода, который использует cargo-nextest для обеспечения качества кода с помощью ИИ Агентов.","ar":"ما هو اختبار الكود? هو مهارة لاختبار الكود التي تستخدم حزمة cargo-nextest لضمان جودة الكود"},"features":{"en":["Utilizes cargo-nextest exclusively for testing operations","Runs all tests, including unit tests, using specific commands","Requires installation via the `just install-cargo-nextest` task if not available","Supports test scope selection for customized testing","Enables running unit tests on specific parts of the codebase"],"zh":["使用cargo-nextest进行代码测试","支持测试范围选择","提供运行所有测试和单元测试的命令","支持外部依赖项","需要安装cargo-nextest"],"ja":["cargo-nextestを使用してコードをテストする","テスト範囲選択をサポートする","すべてのテストとユニットテストを実行するコマンドを提供する","外部依存関係をサポートする","cargo-nextestのインストールが必要"],"ko":["cargo-nextest를 사용하여 코드를 테스트한다","테스트 범위 선택을 지원한다","모든 테스트와 유닛 테스트를 실행하는 명령을 제공한다","외부 의존关系을 지원한다","cargo-nextest 설치가 필요하다"],"es":["Ejecución de pruebas de código con cargo-nextest","Selección del alcance de las pruebas","Ejecución de comandos de prueba como ''Run All Tests'' y ''Run Unit Tests''","Instalación automática de cargo-nextest con ''just install-cargo-nextest''","Compatibilidad con proyectos que requieren dependencias externas"],"fr":["Exécution de tests de code avec cargo-nextest","Sélection de la portée des tests","Exécution de commandes de test comme ''Run All Tests'' et ''Run Unit Tests''","Installation automatique de cargo-nextest avec ''just install-cargo-nextest''","Compatibilité avec des projets qui requièrent des dépendances externes"],"de":["Ausführung von Code-Tests mit cargo-nextest","Auswahl des Umfangs der Tests","Ausführung von Testkommandos wie ''Run All Tests'' und ''Run Unit Tests''","Automatische Installation von cargo-nextest mit ''just install-cargo-nextest''","Kompatibilität mit Projekten, die externe Abhängigkeiten erfordern"],"pt":["Suporte ao cargo-nextest","Testes unitários e de integração","Seleção de escopo de teste","Comandos de teste personalizados"],"ru":["Поддержка cargo-nextest","Юнит-тесты и интеграционные тесты","Выбор области тестирования","Пользовательские команды тестирования с помощью ИИ Агентов"],"ar":["دعم حزمة cargo-nextest","اختبارات الوحدة واختبارات التكامل","اختيار نطاق الاختبار","أوامر اختبار مخصصة"]},"keywords":{"en":["how to use code-test","code-test setup guide","cargo-nextest installation","automated testing with code-test","code-test vs traditional testing methods","what is code-test","code-test install","code-test alternative"],"zh":["代码测试","cargo-nextest","测试范围选择","代码测试工具","AI代码测试","代码质量保证"],"ja":["コードテスト","cargo-nextest","テスト範囲選択","コードテストツール","AIコードテスト","コード品質保証"],"ko":["코드 테스트","cargo-nextest","테스트 범위 선택","코드 테스트 도구","AI 코드 테스트","코드 품질 보증"],"es":["pruebas de código","cargo-nextest","skill de pruebas de código","herramientas de desarrollo","testing de código","desarrollo de software","pruebas automatizadas","instalación de cargo-nextest"],"fr":["tests de code","cargo-nextest","skill de tests de code","outils de développement","testing de code","développement de logiciels","tests automatisés","installation de cargo-nextest"],"de":["Code-Tests","cargo-nextest","Code-Test-Skill","Entwicklungstools","Code-Testing","Software-Entwicklung","automatisierte Tests","Installation von cargo-nextest"],"pt":["code-test","cargo-nextest","testes de código","qualidade de código","desenvolvimento de software","ferramentas de teste","melhores práticas de teste"],"ru":["код-тест","cargo-nextest","тестирование кода","качество кода","разработка программного обеспечения","инструменты тестирования","лучшие практики тестирования с помощью ИИ Агентов"],"ar":["اختبار الكود","حزمة cargo-nextest","اختبارات الكود","جودة الكود","تطوير البرمجيات","أدوات الاختبار","أفضل الممارسات لاختبار الكود"]}},"owner":"LNSD","repo":"agentsync","repoPath":"LNSD/agentsync","stars":0,"forks":0,"updatedAt":"2026-03-01T18:37:31Z","topics":[],"category":"community","skillMd":{"name":"code-test","description":"Run targeted tests to validate changes. Prefer the smallest relevant scope; broaden only when necessary.","bodyPreview":"# Code Testing Skill\n\nThis skill provides testing operations for the project codebase. \n\nAll test commands use cargo-nextest exclusively. If not available ask the user to run the `just install-cargo-nextest` task to install it.\n\n## Table of Contents\n\n- [When to Use This Skill](#when-to-use-this-skill)\n- [Test Scope Selection](#test-scope-selection-default-minimal)\n- [Available Commands](#available-commands)\n  - [Run All Tests](#run-all-tests-requires-external-dependencies)\n  - [Run Unit Tests On","body":"# Code Testing Skill\n\nThis skill provides testing operations for the project codebase. \n\nAll test commands use cargo-nextest exclusively. If not available ask the user to run the `just install-cargo-nextest` task to install it.\n\n## Table of Contents\n\n- [When to Use This Skill](#when-to-use-this-skill)\n- [Test Scope Selection](#test-scope-selection-default-minimal)\n- [Available Commands](#available-commands)\n  - [Run All Tests](#run-all-tests-requires-external-dependencies)\n  - [Run Unit Tests Only](#run-unit-tests-only)\n  - [Run Integration Tests](#run-integration-tests-requires-external-dependencies)\n  - [Run E2E Tests](#run-e2e-tests-requires-external-dependencies)\n  - [Per-Crate Targeted Testing](#per-crate-targeted-testing)\n- [Important Guidelines](#important-guidelines)\n  - [Cargo Nextest](#cargo-nextest)\n  - [Pre-approved Commands](#pre-approved-commands)\n  - [Test Workflow Recommendations](#test-workflow-recommendations)\n  - [External Dependencies](#external-dependencies-required-by-non-local-tests)\n  - [Common Test Flags](#common-test-flags)\n- [Common Mistakes to Avoid](#common-mistakes-to-avoid)\n- [Validation Loop Pattern](#validation-loop-pattern)\n- [Debugging](#debugging)\n  - [Using Logs](#using-logs)\n- [Next Steps](#next-steps)\n- [Project Context](#project-context)\n\n## When to Use This Skill\n\nUse this skill when you need to run tests and have decided testing is warranted:\n- Validate behavior changes or bug fixes\n- Confirm localized changes with targeted test suites (unit, integration)\n- Test specific packages or areas\n- Respond to a user request to run tests\n\n## Test Scope Selection (Default: Minimal)\n\nStart with the smallest scope that covers the change. Only broaden if you need more confidence.\n\n- Docs/comments-only changes: skip tests and state why\n- Localized code change in 1-2 crates: run unit tests or targeted package tests\n- End-to-end/external dependency changes: run `just test-integration`, `just test-e2e`, or `just test` in CI\n- If unsure, ask the user which scope they want\n\n## Available Commands\n\n### Run All Tests (REQUIRES EXTERNAL DEPENDENCIES)\n```bash\njust test [EXTRA_FLAGS]\n```\nRuns all tests (unit and integration) in the workspace. Uses `cargo nextest run --workspace`.\n\n**⚠️ WARNING**: This command requires external dependencies (PostgreSQL, Firehose services, etc.) that may not be available locally.\n\n**Use this when**: Running in CI.\n\nExamples:\n- `just test` - run all tests\n- `just test -- --nocapture` - run with output capture disabled\n- `just test my_test_name` - run specific test by name\n\n### Run Unit Tests Only\n```bash\njust test-unit [EXTRA_FLAGS]\n```\nRuns only unit tests using the `unit` nextest profile. Excludes integration tests (`it_*`) and the top-level `tests` package.\n\n**Use this when**: You want fast feedback on pure logic changes. Unit tests have no external dependencies.\n\nExamples:\n- `just test-unit` - run all unit tests\n- `just test-unit -p metadata-db` - run unit tests for metadata-db crate\n\n### Run Integration Tests (REQUIRES EXTERNAL DEPENDENCIES)\n```bash\njust test-integration [EXTRA_FLAGS]\n```\nRuns integration tests (`it_*` tests across all crates) using the `integration` nextest profile. Excludes the top-level `tests` package.\n\n**⚠️ WARNING**: Integration tests require external dependencies (databases, Firehose endpoints, etc.).\n\n**Use this when**: Running in CI or when you have external services available locally.\n\nExamples:\n- `just test-integration` - run all integration tests\n- `just test-integration -p metadata-db` - run integration tests for a specific crate\n\n### Run E2E Tests (REQUIRES EXTERNAL DEPENDENCIES)\n```bash\njust test-e2e [EXTRA_FLAGS]\n```\nRuns end-to-end tests from the top-level `tests/` workspace package using the `e2e` nextest profile.\n\n**⚠️ WARNING**: E2E tests require external dependencies (databases, Firehose endpoints, etc.).\n\n**Use this when**: Running in CI for end-to-end validation.\n\nExamples:\n- `just test-e2e` - run all e2e tests\n- `just test-e2e test_name` - run specific e2e test\n\n### Per-Crate Targeted Testing\n\nFor targeted testing within a single crate, use `cargo nextest run` directly:\n\n```bash\n# Unit tests for a specific crate (skip in-tree integration tests)\ncargo nextest run -p metadata-db -E ''not test(/::it_/)''\n\n# Specific module''s unit tests\ncargo nextest run -p metadata-db -E ''test(/workers::tests::/)''\n\n# In-tree integration tests for a crate\ncargo nextest run -p metadata-db -E ''test(/::it_/)''\n\n# Specific in-tree integration test suite\ncargo nextest run -p metadata-db -E ''test(/::it_workers/)''\n\n# Public API integration tests for a crate\ncargo nextest run -p metadata-db -E ''kind(test)''\n\n# Specific public API integration test file\ncargo nextest run -p metadata-db -E ''test(it_api_workers)''\n\n# Run a single test by name\ncargo nextest run -p metadata-db -E ''test(=my_exact_test_name)''\n```\n\n## Important Guidelines\n\n### Cargo Nextest\n\nThis project uses **cargo-nextest exclusively** for all test execution:\n- Faster parallel test execution\n- Better output formatting and filtering\n- Filter expressions (`-E`) for precise test selection\n- Install with: `just install-cargo-nextest`\n\n### Pre-approved Commands\nThese test commands are pre-approved and can be run without user permission:\n- `just test` - Run all tests\n- `just test-unit` - Run unit tests\n- `just test-integration` - Run integration tests\n- `just test-e2e` - Run e2e tests\n- `cargo nextest run` with targeted filters - Per-crate targeted testing\n\n### Test Workflow Recommendations\n\n1. **During local development**: Prefer targeted unit tests first; broaden only if the change is risky or cross-cutting\n2. **Before commits (local)**: Run the smallest relevant test scope; broaden only if the change is risky or cross-cutting\n3. **In CI environments**: The CI system will run `just test`, `just test-integration`, `just test-e2e`\n4. **Local development**: Never run `just test`, `just test-integration`, or `just test-e2e` locally — those require external dependencies\n\n### External Dependencies Required by Non-Local Tests\n\nThe following tests require external services that are typically not available in local development:\n- **PostgreSQL database**: Required for metadata-db tests\n- **Firehose endpoints**: Required for Firehose dataset tests\n- **EVM RPC endpoints**: Required for EVM RPC dataset tests\n- **Other services**: As configured in docker-compose or CI environment\n\n**Use `just test-unit` or per-crate targeted testing to avoid these dependencies during local development.**\n\n### Common Test Flags\n\nYou can pass extra flags through the EXTRA_FLAGS parameter:\n- `-p <package>` or `--package <package>` - test specific package\n- `-E ''<filter>''` - nextest filter expression for precise test selection\n- `test_name` - run tests matching name\n- `-- --show-output` - show output from passing tests\n\n## Common Mistakes to Avoid\n\n### ❌ Anti-patterns\n- **Never use `cargo test`** - Always use `cargo nextest run` or justfile tasks (which use nextest profiles). See [Per-Crate Targeted Testing](#per-crate-targeted-testing)\n- **Never run `just test` locally** - It requires external dependencies\n- **Never skip tests when behavior changes** - Skipping is OK for docs/comments-only changes, but not for runtime changes\n- **Never ignore failing tests** - Fix them or document why they fail\n- **Never run integration/e2e tests locally** - Use `just test-unit` or target unit tests instead\n\n### ✅ Best Practices\n- Prefer the smallest relevant test scope\n- Run tests for behavior changes or bug fixes\n- Fix failing tests immediately\n- If nextest not installed, install it for better performance\n- Run broader tests only when necessary\n\n## Validation Loop Pattern\n\n```\nCode Change → Format → Check → Clippy → Targeted Tests (when needed)\n                ↑                          ↓\n                ←── Fix failures ──────────┘\n```\n\nIf tests fail:\n1. Read error messages carefully\n2. Fix the issue\n3. Format the fix (`just fmt-file`)\n4. Check compilation (`just check-crate`)\n5. Re-run the relevant tests (same scope as before)\n6. Repeat until all pass\n\n## Debugging\n\n### Using Logs\n\nTests use the `monitoring` crate''s logging system. Enable structured logs via the `AGENTFLOW_LOG` environment variable to diagnose failures.\n\n**Environment variables:**\n\n| Variable | Default | Values | Purpose |\n|---|---|---|---|\n| `AGENTFLOW_LOG` | `info` | `error`, `warn`, `info`, `debug`, `trace` | Log level for all agentflow workspace crates |\n| `AGENTFLOW_LOG_SPAN_EVENT` | *(none)* | `close`, `full` | Log tracing span lifecycle events |\n| `RUST_LOG` | *(none)* | Standard `tracing` directives | Fine-grained per-crate overrides (takes precedence over `AGENTFLOW_LOG`) |\n\n**Examples with nextest:**\n\n```bash\n# Debug logging for a failing test\nAGENTFLOW_LOG=debug cargo nextest run -p metadata-db -E ''test(my_failing_test)''\n\n# Trace logging (very verbose)\nAGENTFLOW_LOG=trace cargo nextest run -p worker -E ''test(my_test)''\n\n# Debug a specific crate while keeping others quiet\nRUST_LOG=\"metadata_db=trace,sqlx=warn\" cargo nextest run -p metadata-db\n\n# Include span open/close events for async debugging\nAGENTFLOW_LOG=debug AGENTFLOW_LOG_SPAN_EVENT=full cargo nextest run -E ''test(my_test)''\n```\n\n**How it works:**\n- `AGENTFLOW_LOG` sets the log level for all agentflow workspace crates; external dependencies default to `error`\n- `RUST_LOG` directives override `AGENTFLOW_LOG` for specific crates (useful for noisy dependencies)\n- Logging is initialized via `monitoring::logging::init()`, which is idempotent and already called by the test context builder\n- Output goes to stderr, which nextest captures by default — use `-- --show-output` to see logs from passing tests\n\n**See also:** [docs/code/logging.md](../../../docs/code/logging.md) for full logging configuration details.\n\n## Next Steps\n\nAfter required tests pass:\n1. **Review changes** → Ensure quality before commits\n2. **Commit** → All checks and tests must be green\n\n## Project Context\n\n- This is a Rust workspace with multiple crates\n- E2E tests are in the top-level `tests/` package\n- Some tests require external dependencies (databases, services)\n- Test configurations are defined in `.config/nextest.toml`\n- Nextest profiles: `default`, `unit`, `integration`, `e2e`\n"},"lastSynced":"2026-03-07T04:05:00.655Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring automated testing capabilities for project codebases using cargo-nextest.","zh":"适用于需要为使用 cargo-nextest 的项目代码库自动化测试的开发代理。","ja":"cargo-nextest を使用するプロジェクトコードベースの自動テスト機能を必要とする開発エージェントに適しています。","ko":"cargo-nextest 를 사용하는 프로젝트 코드베이스에 대한 자동화 테스트 기능이 필요한 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren capacidades de prueba automatizada para bases de código de proyectos que utilizan cargo-nextest.","fr":"Idéal pour les agents de développement nécessitant des capacités de test automatisé pour les bases de code de projet utilisant cargo-nextest.","de":"Ideal für Entwicklungsmittel, die automatisierte Testfunktionen für Projektcodesammlungen mit cargo-nextest erfordern.","pt":"Ideal para Agentes de Desenvolvimento que exigem capacidades de teste automatizado para repositórios de código do projeto usando cargo-nextest.","ru":"Идеально подходит для агентов разработки, требующих автоматизированных возможностей тестирования для кодовых баз проекта, использующих cargo-nextest.","ar":"مثالي لعميل التطوير الذي يتطلب القدرات الاختبارية الآلية لمشاريع قاعدة الكود باستخدام cargo-nextest."},"recommendation":{"en":"Empowers agents to automate test commands using cargo-nextest, streamlining the development process with features like test scope selection and support for running unit tests, integrating seamlessly with existing project workflows through the use of cargo-nextest exclusively.","zh":"赋予代理自动化测试命令的能力，使用 cargo-nextest 流线型开发流程，具有测试范围选择和运行单元测试的功能，并通过 cargo-nextest 的独家使用与现有的项目工作流无缝集成。","ja":"エージェントにテストコマンドの自動化機能を提供し、cargo-nextest を使用して開発プロセスを最適化することで、テスト範囲の選択やユニットテストの実行などの機能を提供し、既存のプロジェクトワークフローとシームレスに統合します。","ko":"에이전트에게 테스트 명령의 자동화 기능을 제공하여 cargo-nextest 를 사용하여 개발 프로세스를 최적화하고 테스트 범위 선택 및 유닛 테스트 실행 등의 기능을 제공하며 기존 프로젝트 워크플로와 무縫으로 통합합니다.","es":"Habilita a los agentes a automatizar comandos de prueba mediante cargo-nextest, racionalizando el proceso de desarrollo con características como la selección del alcance de la prueba y el soporte para la ejecución de pruebas unitarias, integrándose de forma transparente con los flujos de trabajo de proyectos existentes mediante el uso exclusivo de cargo-nextest.","fr":"Permet aux agents d''automatiser les commandes de test à l''aide de cargo-nextest, rationalisant le processus de développement avec des fonctionnalités telles que la sélection de la portée des tests et le support de l''exécution de tests unitaires, s''intégrant de manière transparente aux flux de travail de projet existants grâce à l''utilisation exclusive de cargo-nextest.","de":"Ermächtigt Agenten, Testbefehle mithilfe von cargo-nextest zu automatisieren, strafft den Entwicklungsprozess mit Funktionen wie Testbereichsauswahl und Unterstützung für die Ausführung von Einheitstests, integriert sich nahtlos in bestehende Projektworkflows durch den exklusiven Einsatz von cargo-nextest.","pt":"Habilita os agentes a automatizar comandos de teste usando cargo-nextest, otimizando o processo de desenvolvimento com recursos como seleção de escopo de teste e suporte à execução de testes unitários, integrando-se perfeitamente com os fluxos de trabalho de projeto existentes por meio do uso exclusivo do cargo-nextest.","ru":"Наделяет агентов возможностью автоматизировать тестовые команды с помощью cargo-nextest, оптимизируя процесс разработки функциями, такими как выбор области тестирования и поддержка запуска юнит-тестов, интегрируясь без проблем с существующими рабочими процессами проекта посредством исключительного использования cargo-nextest.","ar":"يمنح الوكيل القدرة على تشغيل أوامر الاختبار آليًا باستخدام cargo-nextest، ويعزز من عملية التطوير بمزايا مثل تحديد نطاق الاختبار ودعم تشغيل الاختبارات الوحدوية، ويتكامل بشكل متوافق مع سير عمل المشروع الحالي من خلال استخدام cargo-nextest حصريًا."},"useCases":{"en":["Automating test operations for project codebases","Running unit tests on specific modules","Debugging test failures with detailed output from cargo-nextest"],"zh":["为项目代码库自动化测试操作","在特定模块上运行单元测试","使用 cargo-nextest 的详细输出调试测试失败"],"ja":["プロジェクトコードベースのテスト操作の自動化","特定のモジュールでユニットテストを実行","cargo-nextest の詳細な出力でテスト失敗をデバッグ"],"ko":["프로젝트 코드베이스의 테스트 동작 자동화","특정 모듈에서 유닛 테스트 실행","cargo-nextest 의 상세한 출력으로 테스트 실패 디버깅"],"es":["Automatización de operaciones de prueba para bases de código de proyectos","Ejecución de pruebas unitarias en módulos específicos","Depuración de fallos de prueba con salida detallada de cargo-nextest"],"fr":["Automatisation des opérations de test pour les bases de code de projet","Exécution de tests unitaires sur des modules spécifiques","Débogage des échecs de test avec une sortie détaillée de cargo-nextest"],"de":["Automatisierung von Testvorgängen für Projektcodesammlungen","Ausführung von Einheitstests in bestimmten Modulen","Fehlerbehebung von Testfehlern mit detaillierter Ausgabe von cargo-nextest"],"pt":["Automatizar operações de teste para repositórios de código do projeto","Executar testes unitários em módulos específicos","Depurar falhas de teste com saída detalhada do cargo-nextest"],"ru":["Автоматизация тестовых операций для кодовых баз проекта","Запуск юнит-тестов на конкретных модулях","Отладка неудач тестирования с подробным выводом cargo-nextest"],"ar":["التشغيل الآلي لعمليات الاختبار لمشاريع قاعدة الكود","تشغيل الاختبارات الوحدوية على وحدات محددة","تصحيح الأخطاء في الاختبار باستخدام الإخراج المفصل من cargo-nextest"]},"limitations":{"en":["Requires cargo-nextest installation via ''just install-cargo-nextest'' task if not already available","Exclusive use of cargo-nextest for test commands"],"zh":["需要通过 ''just install-cargo-nextest'' 任务安装 cargo-nextest 如果尚未可用","测试命令需要专门使用 cargo-nextest"],"ja":["cargo-nextest が利用可能でない場合は ''just install-cargo-nextest'' タスクを介してインストールする必要がある","テストコマンドは cargo-nextest 専用でなければならない"],"ko":["cargo-nextest が 사용 가능하지 않은 경우 ''just install-cargo-nextest'' 태스크를 통해 설치해야 함","테스트 명령은 cargo-nextest 전용으로 사용해야 함"],"es":["Requiere la instalación de cargo-nextest a través de la tarea ''just install-cargo-nextest'' si no está disponible","Uso exclusivo de cargo-nextest para comandos de prueba"],"fr":["Nécessite l''installation de cargo-nextest via la tâche ''just install-cargo-nextest'' si elle n''est pas déjà disponible","Utilisation exclusive de cargo-nextest pour les commandes de test"],"de":["Erfordert die Installation von cargo-nextest über die Aufgabe ''just install-cargo-nextest'', wenn diese noch nicht verfügbar ist","Exklusiver Einsatz von cargo-nextest für Testbefehle"],"pt":["Exige a instalação do cargo-nextest via tarefa ''just install-cargo-nextest'' se não estiver já disponível","Uso exclusivo do cargo-nextest para comandos de teste"],"ru":["Требует установки cargo-nextest через задачу ''just install-cargo-nextest'', если она еще не доступна","Использование исключительно cargo-nextest для тестовых команд"],"ar":["يتطلب تثبيت cargo-nextest من خلال مهمة ''just install-cargo-nextest'' إذا لم يكن متاحًا،","استخدام حصري لبرنامج cargo-nextest لأوامر الاختبار"]},"version":4},"contentHash":"69d83d2f7eead55f4f77aebcfa9a63e7a2cd2d6cdd1e2af88ed468e3596dcbbb","qualityScore":57}');
