INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('LNSD/agentsync/code-test', 'code-test', 'LNSD', 'agentsync', 'community', 'code-test LNSD agentsync community The code-test skill provides testing operations for project codebases using cargo-nextest. It benefits developers by automating test commands. 代码测试技能提供项目代码库的测试操作，使用cargo-nextest进行测试 コードテストスキルは、プロジェクトのコードベースのテスト操作を提供し、cargo-nextestを使用してテストを行います 코드 테스트 스킬은 프로젝트 코드베이스의 테스트 운영을 제공하며 cargo-nextest를 사용하여 테스트를 수행합니다 El skill de pruebas de código proporciona operaciones de prueba para la base de código del proyecto. Utiliza exclusivamente cargo-nextest para ejecutar comandos de prueba Le skill de tests de code fournit des opérations de test pour la base de code du projet. Il utilise exclusivement cargo-nextest pour exécuter des commandes de test Das Code-Test-Skill bietet Testoperationen für die Codebasis des Projekts. Es verwendet ausschließlich cargo-nextest, um Testkommandos auszuführen O code-test é uma habilidade que fornece operações de teste para a base de código do projeto. Ele usa exclusivamente o cargo-nextest. Код-тест - это навык, который предоставляет операции тестирования для базы кода проекта. Он использует исключительно cargo-nextest, популярный инструмент среди ИИ Агентов. اختبار الكود هو مهارة توفر عمليات اختبار للكود الأساسي للمشروع. يستخدم حزمة cargo-nextest بشكل حصري how to use code-test code-test setup guide cargo-nextest installation automated testing with code-test code-test vs traditional testing methods what is code-test code-test install code-test alternative 代码测试 cargo-nextest 测试范围选择 代码测试工具 AI代码测试 代码质量保证 Utilizes cargo-nextest exclusively for testing operations Runs all tests, including unit tests, using specific commands Requires installation via the `just install-cargo-nextest` task if not available Supports test scope selection for customized testing Enables running unit tests on specific parts of the codebase code-test is a skill that offers automated testing capabilities for project codebases, utilizing cargo-nextest for efficient test operations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Kaakati/managing-director/Scenario Planning', 'community', 'Kaakati', 'managing-director', 'Kaakati/managing-director', 'Scenario Planning', 0, 0, 57, '2026-03-01T21:28:29Z', '2026-03-07T04:06:20.028Z', 'bc8ffbeeb800654c8b4dc0ce0a3a8e4cd807580808c64a38a93f8134481885e2', '{"id":"Kaakati/managing-director/Scenario Planning","name":"Scenario Planning","description":{"en":"Scenario Planning is an AI-powered consultancy system that delivers board-room-quality scenario modeling for strategic decision-making. It benefits managing directors and practice-area partners by providing rigorous base/bull/bear scenarios.","zh":"场景规划是一种使用AI工具构建强大的决策模型的方法，通过构建基础、看好和看坏场景，实现业务成功","ja":"シナリオプランニングは、AIエージェントを使用して強力な意思決定モデルを構築する方法で、基礎、ブル、ベアシナリオを構築してビジネスを成功させる","ko":"시나리오 계획은 AI 도구를 사용하여 강력한 의사 결정 모델을 구축하는 방법으로, 기본, 중립, 부정적 시나리오를 구축하여 사업을 성공시키는 것을 목표로 합니다","es":"La planificación de escenarios es una tecnología de IA que replica la amplitud y profundidad de las empresas Big 4 para entregar resultados de calidad.","fr":"La planification de scénarios est une technologie d''IA qui reproduit l''amplitude et la profondeur des entreprises Big 4 pour livrer des résultats de qualité.","de":"Die Szenario-Planung ist eine KI-Technologie, die die Breite und Tiefe der Big-4-Unternehmen nachahmt, um hochwertige Ergebnisse zu liefern.","pt":"O Planejamento de Cenários é uma habilidade de consulta empresarial que replica a amplitude e profundidade das principais firmas de consultoria, utilizando a estrutura de agentes e habilidades da Claude Code.","ru":"Планирование сценариев - это консалтинговая система, которая воспроизводит широту и глубину крупных консалтинговых фирм, используя фреймворк агентов и навыков от Claude Code.","ar":"التخطيط السيناريو هو نظام استشاري مدعوم بالذكاء الاصطناعي الذي ي复ي عرض وعمق الشركات الاستشارية الكبرى باستخدام إطار العمل للوكلاء والمهارات من كلود كود"},"seo":{"title":{"en":"Scenario Planning: Rigorous Scenario Modeling for AI Agen...","zh":"场景规划设置指南 - 使用AI工具构建强大的决策模型","ja":"シナリオプランニングのベストプラクティス - AIエージェントを活用した意思決定","ko":"시나리오 계획 설정 가이드 - AI 도구를 사용하여 강력한 의사 결정 모델 구축","es":"Guía de configuración de Planificación de Escenarios con ...","fr":"Guide de mise en place de la planification de scénarios a...","de":"Einrichtungsleitfaden für Szenario-Planung mit KI-Agenten","pt":"Guia de Configuração de Planejamento de Cenários com Ferr...","ru":"Руководство по настройке планирования сценариев с помощью...","ar":"دليل إعداد التخطيط السيناريو باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to build robust scenarios with probability-weighted expected values. Learn to set up Scenario Planning and drive informed decision-making with A...","zh":"了解如何使用AI工具进行场景规划，构建强大的决策模型，实现业务成功","ja":"AIエージェントを使用してシナリオプランニングを行い、ビジネスを成功させるための強力な意思決定モデルを構築する方法を学びましょう","ko":"AI 도구를 사용하여 시나리오 계획을 수행하고 사업을 성공시키기 위한 강력한 의사 결정 모델을 구축하는 방법을 알아보세요","es":"Aprende a implementar la planificación de escenarios con agentes de IA para tomar decisiones informadas. Descubre cómo funciona esta tecnología avanzada.","fr":"Découvrez comment mettre en place la planification de scénarios avec les agents d''IA pour prendre des décisions éclairées. Comprenez cette technologie de poi...","de":"Erfahren Sie, wie Sie die Szenario-Planung mit KI-Agenten implementieren, um informierte Entscheidungen zu treffen. Entdecken Sie diese fortschrittliche Tech...","pt":"Aprenda a configurar o Planejamento de Cenários com nossa guia passo a passo e melhore sua tomada de decisões com Ferramentas de IA","ru":"Узнайте, как настроить планирование сценариев с нашей пошаговой инструкцией и улучшите свое решение с помощью ИИ Агентов","ar":"تعلم كيفية إعداد التخطيط السيناريو باستخدام دليلنا خطوة بخطوة و تحسين اتخاذ القرارات باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"Scenario Planning is a systematic approach to building and analyzing scenarios with probability-weighted expected values, trigger identification, and financial impact quantification.","zh":"场景规划是一种使用AI工具构建决策模型的方法，通过构建不同场景和概率加权预期值","ja":"シナリオプランニングは、AIエージェントを使用して意思決定モデルを構築する方法で、さまざまなシナリオと確率付き予期値を構築する","ko":"시나리오 계획은 AI 도구를 사용하여 의사 결정 모델을 구축하는 방법으로, 다양한 시나리오와 확률 가중 기대 값을 구축하는 것을 의미합니다","es":"La planificación de escenarios es un sistema de consultoría impulsado por IA que crea escenarios rigurosos con valores esperados ponderados por probabilidad.","fr":"La planification de scénarios est un système de conseil propulsé par l''IA qui crée des scénarios rigoureux avec des valeurs attendues pondérées par probabilité.","de":"Die Szenario-Planung ist ein von KI angetriebenes Beratungssystem, das strenge Szenarien mit wahrscheinlichkeitsgewichteten Erwartungswerten erstellt.","pt":"O Planejamento de Cenários é uma técnica de modelagem que cria cenários base, otimista e pessimista com valores esperados ponderados por probabilidade.","ru":"Планирование сценариев - это метод моделирования, который создает базовые, оптимистические и пессимистические сценарии с ожидаемыми значениями, взвешенными по вероятности.","ar":"التخطيط السيناريو هو تقنية نمذجة تخلق سيناريوهات أساسية ومثالية وسيئة مع قيم متوقعة موزونة بالاحتمالية"},"features":{"en":["Builds rigorous base/bull/bear scenarios with probability-weighted expected values","Identifies triggers and quantifies financial impact","Delivers strategic response planning per scenario","Requires business/project description and key decision as inputs","Supports time horizon projection periods (e.g., 1-year, 3-year, 5-year)"],"zh":["构建基础、看好和看坏场景","概率加权预期值和触发器识别","财务影响量化和战略响应规划","使用Claude Code的代理和技能框架","支持多个业务领域和决策模型"],"ja":["基礎、ブル、ベアシナリオの構築","確率付き予期値とトリガーの識別","財務影響の量化と戦略的対応計画","Claude Codeのエージェントとスキルフレームワークの使用","複数のビジネス領域と意思決定モデルのサポート"],"ko":["기본, 중립, 부정적 시나리오 구축","확률 가중 기대 값과 트리거 식별","재무 영향량화와 전략적 대응 계획","Claude Code의 에이전트와 스킬 프레임워크 사용","여러 사업 분야와 의사 결정 모델 지원"],"es":["Creación de escenarios base, bull y bear con valores esperados ponderados por probabilidad","Identificación de desencadenantes y cuantificación del impacto financiero","Planificación de respuestas estratégicas para cada escenario","Análisis de sensibilidad para evaluar la robustez de los escenarios","Integración con la estructura de habilidades y agentes de Claude Code"],"fr":["Création de scénarios de base, de hausse et de baisse avec des valeurs attendues pondérées par probabilité","Identification des déclencheurs et quantification de l''impact financier","Planification de réponses stratégiques pour chaque scénario","Analyse de sensibilité pour évaluer la robustesse des scénarios","Intégration avec la structure de compétences et d''agents de Claude Code"],"de":["Erstellung von Basis-, Bull- und Bärenszenarien mit wahrscheinlichkeitsgewichteten Erwartungswerten","Identifizierung von Auslösern und Quantifizierung des finanziellen Einflusses","Planung strategischer Antworten für jedes Szenario","Sensitivitätsanalyse zur Bewertung der Robustheit der Szenarien","Integration mit der Fähigkeits- und Agentenstruktur von Claude Code"],"pt":["Criação de cenários base, otimista e pessimista com valores esperados ponderados por probabilidade","Identificação de gatilhos e quantificação do impacto financeiro","Planejamento de respostas estratégicas para cada cenário","Utilização da estrutura de agentes e habilidades da Claude Code","Integração com práticas de consultoria de alta qualidade"],"ru":["Создание базовых, оптимистических и пессимистических сценариев с ожидаемыми значениями, взвешенными по вероятности","Идентификация триггеров и количественная оценка финансового воздействия","Планирование стратегических ответов для каждого сценария","Использование фреймворка агентов и навыков от Claude Code","Интеграция с высококачественными консалтинговыми практиками"],"ar":["إنشاء سيناريوهات أساسية ومثالية وسيئة مع قيم متوقعة موزونة بالاحتمالية","تحديد الزنادات وتقدير التأثير المالي","تخطيط الاستجابات الاستراتيجية لكل سيناريو","استخدام إطار العمل للوكلاء والمهارات من كلود كود","التكامل مع ممارسات استشارية عالية الجودة"]},"keywords":{"en":["how to use Scenario Planning","what is Scenario Planning","Scenario Planning alternative","Scenario Planning vs Deloitte","Scenario Planning install guide","Scenario Planning setup for AI agents","probability-weighted expected values","scenario modeling for strategic decision-making"],"zh":["AI工具","场景规划","决策模型","概率加权预期值","触发器识别","财务影响量化","战略响应规划","Claude Code","代理和技能框架"],"ja":["AIエージェント","シナリオプランニング","意思決定モデル","確率付き予期値","トリガーの識別","財務影響の量化","戦略的対応計画","Claude Code","エージェントとスキルフレームワーク"],"ko":["AI 도구","시나리오 계획","의사 결정 모델","확률 가중 기대 값","트리거 식별","재무 영향량화","전략적 대응 계획","Claude Code","에이전트와 스킬 프레임워크"],"es":["planificación de escenarios","agentes de IA","análisis de sensibilidad","escenarios de negocio","tomar decisiones informadas","tecnología de IA","Big 4","Claude Code"],"fr":["planification de scénarios","agents d''IA","analyse de sensibilité","scénarios d''entreprise","prendre des décisions éclairées","technologie d''IA","Big 4","Claude Code"],"de":["Szenario-Planung","KI-Agenten","Sensitivitätsanalyse","Geschäftsszenarien","informierte Entscheidungen treffen","KI-Technologie","Big 4","Claude Code"],"pt":["Planejamento de Cenários","Ferramentas de IA","Consultoria Empresarial","Modelagem de Cenários","Análise de Sensibilidade","Tomada de Decisões","Estratégia de Negócios","Claude Code","Agentes de IA"],"ru":["Планирование сценариев","ИИ Агенты","Консалтинговые услуги","Моделирование сценариев","Анализ чувствительности","Принятие решений","Бизнес-стратегия","Claude Code","ИИ инструменты"],"ar":["التخطيط السيناريو","أدوات الذكاء الاصطناعي","استشارات أعمال","نمذجة السيناريوهات","تحليل الحساسية","اتخاذ القرارات","استراتيجية الأعمال","كلود كود","وكلاء الذكاء الاصطناعي"]}},"owner":"Kaakati","repo":"managing-director","repoPath":"Kaakati/managing-director","stars":0,"forks":0,"updatedAt":"2026-03-01T21:28:29Z","topics":[],"category":"community","skillMd":{"name":"Scenario Planning","description":">","bodyPreview":"# Scenario Planning & Sensitivity Analysis\n\nBuild rigorous base/bull/bear scenarios with probability-weighted expected values, trigger identification, financial impact quantification, and strategic response planning per scenario.\n\n---\n\n## Required Inputs\n\n| Input | Description | Required? |\n|---|---|---|\n| Business/project description | What is being modeled | Yes |\n| Key decision | The strategic decision these scenarios inform | Yes |\n| Time horizon | Projection period (e.g., 1-year, 3-year, 5-","body":"# Scenario Planning & Sensitivity Analysis\n\nBuild rigorous base/bull/bear scenarios with probability-weighted expected values, trigger identification, financial impact quantification, and strategic response planning per scenario.\n\n---\n\n## Required Inputs\n\n| Input | Description | Required? |\n|---|---|---|\n| Business/project description | What is being modeled | Yes |\n| Key decision | The strategic decision these scenarios inform | Yes |\n| Time horizon | Projection period (e.g., 1-year, 3-year, 5-year) | Yes |\n| Key variables | Revenue drivers, cost drivers, market factors | Yes |\n| Base case assumptions | Current best estimates | Yes |\n| Historical data | Past performance data for calibration | Recommended |\n| Industry benchmarks | Peer/industry performance ranges | Recommended |\n| Risk factors | Known threats and uncertainties | Recommended |\n| Financial model | Existing P&L, cash flow, or valuation model | If available |\n\n---\n\n## Execution Steps\n\n### Step 1: Identify Key Variables\n\nDetermine the 5-8 variables that most influence outcomes:\n\n1. **Revenue drivers**: Market size, market share, pricing, volume, win rate, churn\n2. **Cost drivers**: COGS, headcount, CAC, variable costs, CapEx\n3. **Market factors**: Growth rate, competitive intensity, regulatory changes\n4. **Operational factors**: Capacity, efficiency, time-to-market\n5. **External factors**: Macroeconomic conditions, FX rates, commodity prices\n\n**Variable prioritization matrix**:\n\n| Variable | Impact on Outcome (1-5) | Uncertainty Level (1-5) | Impact × Uncertainty | Include in Scenarios? |\n|---|---|---|---|---|\n| [Variable 1] | [X] | [X] | [X] | [Yes/No] |\n| [Variable 2] | [X] | [X] | [X] | [Yes/No] |\n| [Variable 3] | [X] | [X] | [X] | [Yes/No] |\n| [Variable 4] | [X] | [X] | [X] | [Yes/No] |\n| [Variable 5] | [X] | [X] | [X] | [Yes/No] |\n| [Variable 6] | [X] | [X] | [X] | [Yes/No] |\n\n**Rule**: Include variables scoring >=12 on Impact x Uncertainty. Typically 4-6 variables drive 80%+ of outcome variance.\n\n### Step 2: Define Scenario Framework\n\nBuild three core scenarios plus optional stress test:\n\n| Scenario | Definition | Probability Guidance |\n|---|---|---|\n| **Bull case** | Favorable conditions across key variables; things go right | 15-25% probability |\n| **Base case** | Most likely outcome; balanced assumptions | 40-60% probability |\n| **Bear case** | Unfavorable conditions; key risks materialize | 15-25% probability |\n| **Stress test** (optional) | Extreme downside; multiple risks compound | 5-10% probability |\n\n**Probability constraint**: All scenario probabilities must sum to 100%.\n\n**Scenario construction rules**:\n1. Each scenario must be internally consistent (a world where all assumptions fit together)\n2. Scenarios should differ on the KEY drivers, not every variable\n3. Bear case is not \"everything goes wrong\" — it is the most likely bad outcome\n4. Bull case is not \"fantasy\" — it is the most likely good outcome\n5. Base case is the median expectation, not the optimistic plan relabeled\n\n### Step 3: Build Scenario Assumptions\n\nFor each key variable, define the value under each scenario:\n\n| Variable | Unit | Bear Case | Base Case | Bull Case | Stress Test |\n|---|---|---|---|---|---|\n| [Market growth] | % | [X]% | [X]% | [X]% | [X]% |\n| [Market share] | % | [X]% | [X]% | [X]% | [X]% |\n| [Average price] | $ | $[X] | $[X] | $[X] | $[X] |\n| [Volume/units] | # | [X] | [X] | [X] | [X] |\n| [Churn rate] | % | [X]% | [X]% | [X]% | [X]% |\n| [Gross margin] | % | [X]% | [X]% | [X]% | [X]% |\n| [CAC] | $ | $[X] | $[X] | $[X] | $[X] |\n| [Headcount] | # | [X] | [X] | [X] | [X] |\n\n**Calibration check**: Are the ranges supported by historical data, industry benchmarks, or analogues? If bear case has never happened in the industry''s history, it may be too extreme (or not extreme enough if tail risks are real).\n\n### Step 4: Financial Impact Quantification\n\nBuild the P&L (or relevant financial model) for each scenario:\n\n| Financial Metric | Bear Case | Base Case | Bull Case | Stress Test |\n|---|---|---|---|---|\n| **Revenue** | $[X] | $[X] | $[X] | $[X] |\n| Revenue growth YoY | [X]% | [X]% | [X]% | [X]% |\n| **Gross profit** | $[X] | $[X] | $[X] | $[X] |\n| Gross margin | [X]% | [X]% | [X]% | [X]% |\n| **Operating expenses** | $[X] | $[X] | $[X] | $[X] |\n| **EBITDA** | $[X] | $[X] | $[X] | $[X] |\n| EBITDA margin | [X]% | [X]% | [X]% | [X]% |\n| **Free cash flow** | $[X] | $[X] | $[X] | $[X] |\n| **Cash runway** (if pre-profit) | [X] months | [X] months | [X] months | [X] months |\n\n**Multi-year projection** (repeat for each year of time horizon):\n\n| Year | Bear Revenue | Base Revenue | Bull Revenue | Bear EBITDA | Base EBITDA | Bull EBITDA |\n|---|---|---|---|---|---|---|\n| Year 1 | $[X] | $[X] | $[X] | $[X] | $[X] | $[X] |\n| Year 2 | $[X] | $[X] | $[X] | $[X] | $[X] | $[X] |\n| Year 3 | $[X] | $[X] | $[X] | $[X] | $[X] | $[X] |\n\n### Step 5: Probability-Weighted Expected Value\n\nCalculate the expected value across scenarios:\n\n| Scenario | Probability | Revenue | EBITDA | Prob-Weighted Revenue | Prob-Weighted EBITDA |\n|---|---|---|---|---|---|\n| Bull | [X]% | $[X] | $[X] | $[X] | $[X] |\n| Base | [X]% | $[X] | $[X] | $[X] | $[X] |\n| Bear | [X]% | $[X] | $[X] | $[X] | $[X] |\n| Stress | [X]% | $[X] | $[X] | $[X] | $[X] |\n| **Expected Value** | **100%** | | | **$[X]** | **$[X]** |\n\n**Key insight**: How does the expected value compare to the base case? If expected value is significantly below base case, the risk profile is skewed to the downside.\n\n### Step 6: Trigger Identification\n\nFor each scenario, identify what would cause it to materialize:\n\n| Scenario | Trigger Event | Leading Indicator | Detection Signal | Timeline |\n|---|---|---|---|---|\n| **Bull** | [Event that causes upside] | [Metric to watch] | [Specific threshold] | [When visible] |\n| **Bull** | [Second trigger] | [Metric] | [Threshold] | [Timeline] |\n| **Bear** | [Event that causes downside] | [Metric to watch] | [Specific threshold] | [When visible] |\n| **Bear** | [Second trigger] | [Metric] | [Threshold] | [Timeline] |\n| **Stress** | [Extreme event] | [Metric to watch] | [Specific threshold] | [When visible] |\n\n**Monitoring cadence**: [Weekly/Monthly/Quarterly] review of leading indicators against trigger thresholds.\n\n### Step 7: Scenario Tree (Decision Mapping)\n\nMap key decision points and branching outcomes:\n\n```\n                            [Initial Decision]\n                           /         |         \\\n                    [Path A]     [Path B]     [Path C]\n                    /    \\        /    \\        /    \\\n              [Bull]  [Bear]  [Bull]  [Bear]  [Bull]  [Bear]\n              p=[X]%  p=[X]%  p=[X]%  p=[X]%  p=[X]%  p=[X]%\n              EV=$X   EV=$X   EV=$X   EV=$X   EV=$X   EV=$X\n```\n\n**Decision rule**: Choose the path with the highest expected value, subject to:\n- Acceptable downside (bear case is survivable)\n- Acceptable regret (if bull case materializes on unchosen path)\n- Strategic optionality (path preserves future flexibility)\n\n### Step 8: Monte Carlo Considerations\n\nFor key variables with continuous distributions, consider Monte Carlo simulation:\n\n1. **Define probability distributions** for each key variable:\n   - Normal: For variables with symmetric uncertainty (e.g., market growth)\n   - Log-normal: For variables that are bounded at zero (e.g., revenue)\n   - Triangular: When you know min, most likely, and max\n   - Uniform: When all values in a range are equally likely\n\n2. **Correlation matrix**: Identify which variables move together (e.g., market growth and pricing power are often correlated)\n\n3. **Simulation outputs** (if running Monte Carlo):\n   - Mean and median outcome\n   - Standard deviation\n   - 10th percentile (downside) and 90th percentile (upside)\n   - Probability of achieving target (e.g., P(revenue > $X) = Y%)\n   - Value at Risk (VaR): What is the worst outcome at 95% confidence?\n\n4. **Simplified distribution table** (when full Monte Carlo is not feasible):\n\n   | Outcome Metric | P10 (Downside) | P25 | P50 (Median) | P75 | P90 (Upside) |\n   |---|---|---|---|---|---|\n   | Revenue | $[X] | $[X] | $[X] | $[X] | $[X] |\n   | EBITDA | $[X] | $[X] | $[X] | $[X] | $[X] |\n   | Cash flow | $[X] | $[X] | $[X] | $[X] | $[X] |\n\n### Step 9: Strategic Response per Scenario\n\nDefine what actions to take under each scenario:\n\n| Scenario | Strategic Response | Resource Reallocation | Trigger to Activate |\n|---|---|---|---|\n| **Bull** | [Accelerate: increase investment, hire faster, expand] | [Where to deploy resources] | [Signal that bull case is materializing] |\n| **Base** | [Execute: stay the course, optimize] | [Standard plan] | [Default operating mode] |\n| **Bear** | [Defend: cut costs, focus on core, conserve cash] | [Where to reduce] | [Signal that bear case is materializing] |\n| **Stress** | [Survive: emergency measures, pivot consideration] | [Dramatic restructuring] | [Signal that stress case is materializing] |\n\n**Pre-committed actions**: For each scenario, define 2-3 actions that are pre-approved and can be executed immediately when triggers are hit, without additional deliberation.\n\n---\n\n## Output Template\n\n### Scenario Analysis: [Business/Project] — [Decision Context]\n\n**Date**: [Date] | **Prepared for**: [Client/Project] | **Time Horizon**: [X] years\n\n#### 1. Key Variables & Ranges\n\n| Variable | Bear | Base | Bull | Primary Data Source |\n|---|---|---|---|---|\n| [Var 1] | [X] | [X] | [X] | [Source] |\n| [Var 2] | [X] | [X] | [X] | [Source] |\n| [Var 3] | [X] | [X] | [X] | [Source] |\n| [Var 4] | [X] | [X] | [X] | [Source] |\n\n#### 2. Scenario Narratives\n\n**Bull case ([X]% probability)**: [2-3 sentence narrative of what this world looks like]\n\n**Base case ([X]% probability)**: [2-3 sentence narrative]\n\n**Bear case ([X]% probability)**: [2-3 sentence narrative]\n\n**Stress test ([X]% probability)**: [2-3 sentence narrative]\n\n#### 3. Financial Impact Summary\n\n*(Include tables from Steps 4 and 5)*\n\n#### 4. Probability-Weighted Expected Value\n\n*(Include table from Step 5)*\n\n#### 5. Sensitivity Tornado\n\n| Variable | -20% Impact on EBITDA | +20% Impact on EBITDA | Range |\n|---|---|---|---|\n| [Var 1 — highest impact] | $[X] | $[X] | $[X] |\n| [Var 2] | $[X] | $[X] | $[X] |\n| [Var 3] | $[X] | $[X] | $[X] |\n| [Var 4 — lowest impact] | $[X] | $[X] | $[X] |\n\n#### 6. Trigger Dashboard\n\n*(Include table from Step 6)*\n\n#### 7. Strategic Response Plan\n\n*(Include table from Step 9)*\n\n#### 8. Decision Recommendation\n\n**Recommended path**: [Decision recommendation]\n**Expected value**: $[X]\n**Key risk**: [Primary risk with mitigation]\n**Decision reversibility**: [Reversible / Partially reversible / Irreversible]\n\n---\n\n## Quality Checks\n\n- [ ] All scenario probabilities sum to exactly 100%\n- [ ] Variable ranges are calibrated against historical data or industry benchmarks\n- [ ] Each scenario tells a coherent, internally consistent narrative (not random variable combinations)\n- [ ] Bear case is genuinely unfavorable, not just \"slightly below base case\"\n- [ ] Financial impact is quantified in dollar terms, not just directional\n- [ ] Probability-weighted expected value is calculated and compared to base case\n- [ ] Triggers are specific, measurable, and time-bound (not vague)\n- [ ] Leading indicators are identified for each trigger with monitoring cadence\n- [ ] Strategic response for each scenario includes specific pre-committed actions\n- [ ] Sensitivity tornado ranks variables by actual impact magnitude\n- [ ] Stress test addresses existential risk (can the business survive?)\n- [ ] Decision recommendation addresses reversibility and optionality\n- [ ] Monte Carlo considerations address variable correlations, not just independent ranges\n"},"lastSynced":"2026-03-07T04:06:20.028Z","agentAnalysis":{"suitability":{"en":"Ideal for Strategic Decision Support Agents requiring advanced scenario modeling and sensitivity analysis capabilities.","zh":"适用于需要高级场景建模和敏感性分析能力的战略决策支持代理。","ja":"高度なシナリオモデリングと感度分析機能を必要とする戦略的意思決定サポートエージェントに最適。","ko":"고급 시나리오 모델링 및 민감도 분석 기능을 필요로 하는 전략적 의사 결정 지원 에이전트에 적합합니다.","es":"Ideal para Agentes de Soporte de Decisión Estratégica que requieren modelado de escenarios avanzado y capacidades de análisis de sensibilidad.","fr":"Idéal pour les Agents de Support de Décision Stratégique nécessitant un modelage de scénarios avancé et des capacités d''analyse de sensibilité.","de":"Ideal für Strategische Entscheidungsunterstützungsagenten, die erweiterte Szenariomodellierung und Sensitivitätsanalysefunktionen erfordern.","pt":"Ideal para Agentes de Suporte à Decisão Estratégica que exigem modelagem de cenário avançada e capacidades de análise de sensibilidade.","ru":"Идеально для Стратегических Агентов Поддержки Принятия Решений, требующих продвинутой моделирования сценариев и возможностей анализа чувствительности.","ar":"مثالي لعمليات دعم اتخاذ القرارات الاستراتيجية التي تتطلب نماذج سيناريوهات متقدمة وقدرات تحليل الحساسية."},"recommendation":{"en":"Empowers agents to build rigorous base/bull/bear scenarios with probability-weighted expected values, trigger identification, and financial impact quantification using trigger identification and strategic response planning protocols.","zh":"赋予代理构建严格的基础/看涨/看跌场景的能力，具有概率加权的预期值、触发器识别和财务影响量化，使用触发器识别和战略响应规划协议。","ja":"エージェントが厳密なベース/ブル/ベアシナリオを構築できるようにし、確率加重された期待値、トリガー識別、財務影響の量化を実行することができ、トリガー識別と戦略的対応計画プロトコルを使用します。","ko":"에이전트가 엄격한 기본/불/방어 시나리오를 구축할 수 있도록 하여 확률 가중 기대값, 트리거 식별 및 재무 영향 정량화를 수행하고 트리거 식별 및 전략적 대응 계획 프로토콜을 사용합니다.","es":"Permite a los agentes crear escenarios base/bull/bear rigurosos con valores esperados con ponderación de probabilidad, identificación de desencadenantes y cuantificación del impacto financiero utilizando protocolos de identificación de desencadenantes y planificación de respuestas estratégicas.","fr":"Permet aux agents de créer des scénarios base/bull/bear rigoureux avec des valeurs attendues pondérées par probabilité, une identification de déclencheurs et une quantification de l''impact financier en utilisant des protocoles d''identification de déclencheurs et de planification de réponses stratégiques.","de":"Ermöglicht es den Agenten, strenge Basis-/Bullen-/Bären-Szenarien mit wahrscheinlichkeitsgewichteten Erwartungswerten, Auslöseridentifizierung und finanzieller Auswirkungsquantifizierung unter Verwendung von Auslöseridentifizierungs- und strategischer Reaktionsplanungsprotokollen zu erstellen.","pt":"Habilita os agentes a construir cenários rigorosos base/bull/bear com valores esperados com pesos de probabilidade, identificação de gatilhos e quantificação do impacto financeiro usando protocolos de identificação de gatilhos e planejamento de respostas estratégicas.","ru":"Наделяет агентов возможностью создавать строгие базовые/бычьи/медвежьи сценарии с вероятностно-взвешенными ожидаемыми значениями, выявлением триггеров и количественной оценкой финансового воздействия с использованием протоколов выявления триггеров и стратегического планирования реакций.","ar":"تمكن الوكلاء من بناء سيناريوهات قاسية لأساس/دب/دب مع قيم متوقعة ذات أوزان احتمالية، وتحديد الزنادات وتقدير التأثير المالي باستخدام بروتوكولات تحديد الزنادات وتخطيط الاستجابة الاستراتيجية."},"useCases":{"en":["Automating scenario planning for strategic decision-making","Generating probability-weighted expected values for financial impact quantification","Creating comprehensive sensitivity analyses for business/project descriptions"],"zh":["为战略决策自动化场景规划","为财务影响量化生成概率加权预期值","为业务/项目描述创建全面的敏感性分析"],"ja":["戦略的意思決定のためのシナリオプランニングの自動化","財務影響の量化のための確率加重された期待値の生成","ビジネス/プロジェクトの説明のための包括的な感度分析の作成"],"ko":["전략적 의사 결정의ための 시나리오 계획 자동화","재무 영향의 정량화를 위한 확률 가중 기대값 생성","사업/프로젝트 설명을 위한 포괄적인 민감도 분석 생성"],"es":["Automatizar la planificación de escenarios para la toma de decisiones estratégicas","Generar valores esperados con ponderación de probabilidad para la cuantificación del impacto financiero","Crear análisis de sensibilidad comprehensivos para descripciones de empresas/proyectos"],"fr":["Automatiser la planification de scénarios pour la prise de décision stratégique","Générer des valeurs attendues pondérées par probabilité pour la quantification de l''impact financier","Créer des analyses de sensibilité complètes pour les descriptions d''entreprises/projets"],"de":["Automatisierung der Szenarienplanung für strategische Entscheidungsfindung","Erzeugen von wahrscheinlichkeitsgewichteten Erwartungswerten für die Quantifizierung der finanziellen Auswirkungen","Erstellen umfassender Sensitivitätsanalysen für Unternehmens-/Projektbeschreibungen"],"pt":["Automatizar a planejamento de cenários para a tomada de decisões estratégicas","Gerar valores esperados com pesos de probabilidade para a quantificação do impacto financeiro","Criar análises de sensibilidade abrangentes para descrições de negócios/projetos"],"ru":["Автоматизировать планирование сценариев для стратегического принятия решений","Генерировать вероятностно-взвешенные ожидаемые значения для количественной оценки финансового воздействия","Создавать комплексные анализы чувствительности для описаний бизнеса/проектов"],"ar":["تحويل التخطيط السيناريو إلى تطبيق آلي لاتخاذ القرارات الاستراتيجية","توليد القيم المتوقعة ذات الأوزان الاحتمالية لتقدير التأثير المالي","إنشاء تحليلات شاملة للحساسية لوصف الأعمال/المشاريع"]},"limitations":{"en":["Requires business/project description and key decision inputs","Needs time horizon specification for projection periods","Limited to board-room-quality scenario modeling for managing directors and practice-area partners"],"zh":["需要业务/项目描述和关键决策输入","需要时间范围规范以进行投影期","仅限于董事会质量的场景建模，用于管理董事和执业领域合伙人"],"ja":["ビジネス/プロジェクトの説明と重要な意思決定入力を必要とする","投影期間のための時間範囲の指定が必要","取締役会の質のシナリオモデリングに限定され、管理取締役と実践エリアパートナーを管理するために使用"],"ko":["사업/프로젝트 설명 및 주요 의사 결정 입력이 필요합니다.","예측 기간을 위한 시간 범위 규정 필요","이사회 품질의 시나리오 모델링으로 제한되며, 관리 이사 및 실무 분야 파트너를 관리하는 데 사용"],"es":["Requiere descripción de empresa/proyecto y entradas de decisión clave","Necesita especificación del horizonte temporal para períodos de proyección","Limitado a la modelización de escenarios de calidad de salas de juntas para directores generales y socios de práctica"],"fr":["Nécessite une description d''entreprise/projet et des entrées de décision clés","A besoin de la spécification de l''horizon temporel pour les périodes de projection","Limité à la modélisation de scénarios de qualité de salle de réunion pour les directeurs généraux et les associés de pratique"],"de":["Benötigt Unternehmens-/Projektbeschreibung und Schlüsselentscheidungseingaben","Benötigt Zeithorizontspezifikation für Prognoseperioden","Begrenzt auf Szenarienmodellierung in Raumqualität für Geschäftsführer und Praxispartner"],"pt":["Exige descrição de negócios/projetos e entradas de decisão-chave","Necessita de especificação do horizonte de tempo para períodos de projeção","Limitado à modelagem de cenários de qualidade de sala de reuniões para diretores e sócios de área de prática"],"ru":["Требует описания бизнеса/проекта и ключевых входных данных для принятия решений","Требует указания временного горизонта для периодов прогнозирования","Ограничен моделированием сценариев высокого качества для руководителей и партнеров практической области"],"ar":["يتطلب وصفًا للأعمال/المشاريع ومعلومات مدخلة رئيسية للقرار","يحتاج إلى تحديد الأفق الزمني لفترات التوقع","محدود بالنمذجة السيناريو عالية الجودة لإدارة المديرين والشركاء في مجال الممارسة"]},"version":4},"contentHash":"bc8ffbeeb800654c8b4dc0ce0a3a8e4cd807580808c64a38a93f8134481885e2","qualityScore":57}');
DELETE FROM skills_fts WHERE id = 'Kaakati/managing-director/Scenario Planning';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Kaakati/managing-director/Scenario Planning', 'Scenario Planning', 'Kaakati', 'managing-director', 'community', 'Scenario Planning Kaakati managing-director community Scenario Planning is an AI-powered consultancy system that delivers board-room-quality scenario modeling for strategic decision-making. It benefits managing directors and practice-area partners by providing rigorous base/bull/bear scenarios. 场景规划是一种使用AI工具构建强大的决策模型的方法，通过构建基础、看好和看坏场景，实现业务成功 シナリオプランニングは、AIエージェントを使用して強力な意思決定モデルを構築する方法で、基礎、ブル、ベアシナリオを構築してビジネスを成功させる 시나리오 계획은 AI 도구를 사용하여 강력한 의사 결정 모델을 구축하는 방법으로, 기본, 중립, 부정적 시나리오를 구축하여 사업을 성공시키는 것을 목표로 합니다 La planificación de escenarios es una tecnología de IA que replica la amplitud y profundidad de las empresas Big 4 para entregar resultados de calidad. La planification de scénarios est une technologie d''IA qui reproduit l''amplitude et la profondeur des entreprises Big 4 pour livrer des résultats de qualité. Die Szenario-Planung ist eine KI-Technologie, die die Breite und Tiefe der Big-4-Unternehmen nachahmt, um hochwertige Ergebnisse zu liefern. O Planejamento de Cenários é uma habilidade de consulta empresarial que replica a amplitude e profundidade das principais firmas de consultoria, utilizando a estrutura de agentes e habilidades da Claude Code. Планирование сценариев - это консалтинговая система, которая воспроизводит широту и глубину крупных консалтинговых фирм, используя фреймворк агентов и навыков от Claude Code. التخطيط السيناريو هو نظام استشاري مدعوم بالذكاء الاصطناعي الذي ي复ي عرض وعمق الشركات الاستشارية الكبرى باستخدام إطار العمل للوكلاء والمهارات من كلود كود how to use Scenario Planning what is Scenario Planning Scenario Planning alternative Scenario Planning vs Deloitte Scenario Planning install guide Scenario Planning setup for AI agents probability-weighted expected values scenario modeling for strategic decision-making AI工具 场景规划 决策模型 概率加权预期值 触发器识别 财务影响量化 战略响应规划 Claude Code 代理和技能框架 Builds rigorous base/bull/bear scenarios with probability-weighted expected values Identifies triggers and quantifies financial impact Delivers strategic response planning per scenario Requires business/project description and key decision as inputs Supports time horizon projection periods (e.g., 1-year, 3-year, 5-year) Scenario Planning is a systematic approach to building and analyzing scenarios with probability-weighted expected values, trigger identification, and financial impact quantification.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lildibbb/tele-crm-frontend/zustand', 'community', 'lildibbb', 'tele-crm-frontend', 'lildibbb/tele-crm-frontend', 'zustand', 0, 0, 57, '2026-02-24T13:15:39Z', '2026-03-07T04:06:13.694Z', 'f14495ff461cc8bf3c69e46edf63fda621f71b8bdaaebcada97c595c4561a2a4', '{"id":"lildibbb/tele-crm-frontend/zustand","name":"zustand","description":{"en":"zustand is a state management solution that provides a hierarchical structure for actions, benefiting developers who need to manage complex UI component interactions. It enables efficient parameter validation, flow orchestration, and optimistic updates.","zh":"zustand是一种状态管理工具，提供公共操作、内部操作和派发方法来优化应用程序性能","ja":"zustandはステート管理ツールで、パブリックアクション、内部アクション、ディスパッチメソッドを提供してアプリケーションのパフォーマンスを最適化します","ko":"zustand는 상태 관리 도구로公開 동작, 내부 동작 및 디스패치 방법을 제공하여 애플리케이션 성능을 최적화합니다","es":"Zustand es una biblioteca de manejo de estado que proporciona una forma sencilla de gestionar el estado de tus aplicaciones. Con su jerarquía de acciones, puede administrar el flujo de datos de manera eficiente.","fr":"Zustand est une bibliothèque de gestion d''état qui offre une façon simple de gérer l''état de vos applications. Avec sa hiérarchie d''actions, vous pouvez gérer le flux de données de manière efficace.","de":"Zustand ist eine Bibliothek für das State Management, die eine einfache Möglichkeit bietet, den Zustand Ihrer Anwendungen zu verwalten. Mit seiner Aktionshierarchie können Sie den Datenfluss effizient steuern.","pt":"O Zustand é uma biblioteca de gerenciamento de estado que fornece uma abordagem simples e escalável para gerenciar o estado da aplicação.","ru":"Zustand - это библиотека управления состоянием, которая предоставляет простой и масштабируемый подход к управлению состоянием приложения.","ar":"Zustand هي مكتبة لإدارة الحالة توفر نهجًا بسيطًا وقابلًا للتوسيع لإدارة حالة التطبيق."},"seo":{"title":{"en":"zustand: State Management Setup Guide | AI Agent Skill","zh":"zustand 状态管理设置指南","ja":"zustand ステート管理のベストプラクティス","ko":"zustand 상태 관리 설정 가이드","es":"Guía de configuración de Zustand para el manejo de estado","fr":"Configurer Zustand pour la gestion d''état : meilleures pr...","de":"Zustand Einrichtungsleitfaden für State Management","pt":"Guia de Configuração do Zustand para Gerenciamento de Estado","ru":"Настройка Zustand для управления состоянием: лучшие практики","ar":"إعداد Zustand لإدارة الحالة: دليل المطور"},"description":{"en":"Discover how to implement zustand''s Action Type Hierarchy for efficient state management. Learn to optimize your UI components with public actions and intern...","zh":"了解zustand的状态管理功能，包括公共操作、内部操作和派发方法，优化您的应用程序性能","ja":"zustandのステート管理機能を紹介します。パブリックアクション、内部アクション、ディスパッチメソッドなどを活用して、アプリケーションのパフォーマンスを最適化する方法を学びましょう","ko":"zustand의 상태 관리 기능을 살펴보세요. 공개 동작, 내부 동작 및 디스패치 방법을 사용하여 애플리케이션 성능을 최적화하는 방법을学习하세요","es":"Aprende a configurar Zustand para el manejo de estado en tus aplicaciones con nuestra guía detallada y mejores prácticas.","fr":"Découvrez comment configurer Zustand pour la gestion d''état dans vos applications avec notre guide détaillé et les meilleures pratiques.","de":"Erfahren Sie, wie Sie Zustand für das State Management in Ihren Anwendungen mit unserem detaillierten Leitfaden und Best Practices einrichten.","pt":"Aprenda a configurar o Zustand para gerenciamento de estado eficaz em suas aplicações. Descubra as melhores práticas e recursos técnicos.","ru":"Узнайте, как настроить Zustand для эффективного управления состоянием в ваших приложениях. Обзор лучших практик и технических возможностей.","ar":"تعلم كيفية إعداد Zustand لإدارة الحالة الفعالة في تطبيقاتك. اكتشف أفضل الممارسات والميزات الفنية."},"definition":{"en":"zustand is a state management system that utilizes an Action Type Hierarchy, comprising public actions, internal actions, and dispatch methods to manage application state.","zh":"zustand是一种JavaScript状态管理库，提供简单的状态管理解决方案","ja":"zustandはJavaScriptのステート管理ライブラリで、シンプルなステート管理ソリューションを提供します","ko":"zustand는 JavaScript 상태 관리 라이브러리로서 단순한 상태 관리 솔루션을 제공합니다","es":"Zustand es una biblioteca de manejo de estado que utiliza una jerarquía de acciones para administrar el estado de las aplicaciones.","fr":"Zustand est une bibliothèque de gestion d''état qui utilise une hiérarchie d''actions pour gérer l''état des applications.","de":"Zustand ist eine Bibliothek für das State Management, die eine Aktionshierarchie zur Verwaltung des Zustands von Anwendungen verwendet.","pt":"O Zustand é uma biblioteca JavaScript para gerenciamento de estado que utiliza uma hierarquia de ações para gerenciar o estado da aplicação.","ru":"Zustand - это библиотека JavaScript для управления состоянием, которая использует иерархию действий для управления состоянием приложения.","ar":"Zustand هي مكتبة جافاسكريبت لإدارة الحالة التي تستخدم هرمية الإجراءات لإدارة حالة التطبيق."},"features":{"en":["Utilizes a hierarchical Action Type structure for organized state management","Supports public actions for UI component interactions with verb form naming conventions","Employs internal actions with an `internal_` prefix for core business logic implementation","Enables optimistic updates and service calls through internal actions","Provides dispatch methods for efficient state updates"],"zh":["公共操作（Public Actions）","内部操作（Internal Actions）","派发方法（Dispatch Methods）","参数验证","流程编排","乐观更新"],"ja":["パブリックアクション（Public Actions）","内部アクション（Internal Actions）","ディスパッチメソッド（Dispatch Methods）","パラメータ検証","フロー制御","楽観的な更新"],"ko":["공개 동작（Public Actions）","내부 동작（Internal Actions）","디스패치 방법（Dispatch Methods）","매개 변수 검증","흐름 조율","낙관적인 업데이트"],"es":["Jerarquía de acciones para el manejo de estado","Acciones públicas para la interfaz de usuario","Acciones internas para la lógica de negocio","Métodos de despacho para la actualización del estado","Validación de parámetros y orquestación de flujo","Actualizaciones optimistas y manejo de errores"],"fr":["Hiérarchie d''actions pour la gestion d''état","Actions publiques pour l''interface utilisateur","Actions internes pour la logique métier","Méthodes de dispatch pour la mise à jour de l''état","Validation des paramètres et orchestration du flux","Mises à jour optimistes et gestion des erreurs"],"de":["Aktionshierarchie für das State Management","Öffentliche Aktionen für die Benutzeroberfläche","Interne Aktionen für die Geschäftlogik","Dispatch-Methoden für die Aktualisierung des Zustands","Parametervalidierung und Flussorchestrierung","Optimistische Aktualisierungen und Fehlernhandling"],"pt":["Hierarquia de ações para gerenciamento de estado","Ações públicas para interfaces de usuário","Ações internas para lógica de negócios","Métodos de dispatch para atualizações otimistas","Validação de parâmetros e orquestração de fluxo","Tratamento de erros e atualizações de serviço"],"ru":["Иерархия действий для управления состоянием","Публичные действия для интерфейсов пользователя","Внутренние действия для бизнес-логики","Методы диспетчеризации для оптимистических обновлений","Валидация параметров и оркестрация потока","Обработка ошибок и обновления сервиса"],"ar":["هرمية الإجراءات لإدارة الحالة","الإجراءات العامة لواجهات المستخدم","الإجراءات الداخلية لل逻辑 التجارية","طرق الإرسال للتحديثات المتفائلة","تحقق من المعاملات وتنسيق التدفق","معالجة الأخطاء والتحديثات الخدمية"]},"keywords":{"en":["how to use zustand","zustand state management","zustand vs mobx","zustand install guide","what is zustand","zustand alternative","zustand setup tutorial","zustand action type hierarchy","zustand public actions","zustand internal actions"],"zh":["zustand","状态管理","JavaScript状态管理","公共操作","内部操作","派发方法","AIエージェント","前端开发"],"ja":["zustand","ステート管理","JavaScriptステート管理","パブリックアクション","内部アクション","ディスパッチメソッド","AIエージェント","フロントエンド開発"],"ko":["zustand","상태 관리","JavaScript 상태 관리","공개 동작","내부 동작","디스패치 방법","인공지능 에이전트","프론트엔드 개발"],"es":["zustand","manejo de estado","jerarquía de acciones","acciones públicas","acciones internas","métodos de despacho","validación de parámetros","orquestación de flujo","actualizaciones optimistas","manejo de errores"],"fr":["zustand","gestion d''état","hiérarchie d''actions","actions publiques","actions internes","méthodes de dispatch","validation des paramètres","orchestration du flux","mises à jour optimistes","gestion des erreurs"],"de":["zustand","state management","aktionshierarchie","öffentliche aktionen","interne aktionen","dispatch-methoden","parametervalidierung","flussorchestrierung","optimistische aktualisierungen","fehlernhandling"],"pt":["zustand","gerenciamento de estado","biblioteca javascript","hierarquia de ações","ações públicas","ações internas","métodos de dispatch","validação de parâmetros","orquestração de fluxo","tratamento de erros"],"ru":["zustand","управление состоянием","библиотека javascript","иерархия действий","публичные действия","внутренние действия","методы диспетчеризации","валидация параметров","оркестрация потока","обработка ошибок"],"ar":["zustand","إدارة الحالة","مكتبة جافاسكريبت","هرمية الإجراءات","الإجراءات العامة","الإجراءات الداخلية","طرق الإرسال","تحقق من المعاملات","تنسيق التدفق","معالجة الأخطاء"]}},"owner":"lildibbb","repo":"tele-crm-frontend","repoPath":"lildibbb/tele-crm-frontend","stars":0,"forks":0,"updatedAt":"2026-02-24T13:15:39Z","topics":[],"category":"community","skillMd":{"name":"zustand","description":"Zustand state management guide. Use when working with store code (src/store/**), implementing actions, managing state, or creating slices. Triggers on Zustand store development, state management questions, or action implementation.","bodyPreview":"# LobeHub Zustand State Management\n\n## Action Type Hierarchy\n\n### 1. Public Actions\n\nMain interfaces for UI components:\n\n- Naming: Verb form (`createTopic`, `sendMessage`)\n- Responsibilities: Parameter validation, flow orchestration\n\n### 2. Internal Actions (`internal_*`)\n\nCore business logic implementation:\n\n- Naming: `internal_` prefix (`internal_createTopic`)\n- Responsibilities: Optimistic updates, service calls, error handling\n- Should not be called directly by UI\n\n### 3. Dispatch Methods (`","body":"# LobeHub Zustand State Management\n\n## Action Type Hierarchy\n\n### 1. Public Actions\n\nMain interfaces for UI components:\n\n- Naming: Verb form (`createTopic`, `sendMessage`)\n- Responsibilities: Parameter validation, flow orchestration\n\n### 2. Internal Actions (`internal_*`)\n\nCore business logic implementation:\n\n- Naming: `internal_` prefix (`internal_createTopic`)\n- Responsibilities: Optimistic updates, service calls, error handling\n- Should not be called directly by UI\n\n### 3. Dispatch Methods (`internal_dispatch*`)\n\nState update handlers:\n\n- Naming: `internal_dispatch` + entity (`internal_dispatchTopic`)\n- Responsibilities: Calling reducers, updating store\n\n## When to Use Reducer vs Simple `set`\n\n**Use Reducer Pattern:**\n\n- Managing object lists/maps (`messagesMap`, `topicMaps`)\n- Optimistic updates\n- Complex state transitions\n\n**Use Simple `set`:**\n\n- Toggling booleans\n- Updating simple values\n- Setting single state fields\n\n## Optimistic Update Pattern\n\n```typescript\ninternal_createTopic: async (params) => {\n  const tmpId = Date.now().toString();\n\n  // 1. Immediately update frontend (optimistic)\n  get().internal_dispatchTopic(\n    { type: ''addTopic'', value: { ...params, id: tmpId } },\n    ''internal_createTopic''\n  );\n\n  // 2. Call backend service\n  const topicId = await topicService.createTopic(params);\n\n  // 3. Refresh for consistency\n  await get().refreshTopic();\n  return topicId;\n},\n```\n\n**Delete operations**: Don''t use optimistic updates (destructive, complex recovery)\n\n## Naming Conventions\n\n**Actions:**\n\n- Public: `createTopic`, `sendMessage`\n- Internal: `internal_createTopic`, `internal_updateMessageContent`\n- Dispatch: `internal_dispatchTopic`\n- Toggle: `internal_toggleMessageLoading`\n\n**State:**\n\n- ID arrays: `messageLoadingIds`, `topicEditingIds`\n- Maps: `topicMaps`, `messagesMap`\n- Active: `activeTopicId`\n- Init flags: `topicsInit`\n\n## Detailed Guides\n\n- Action patterns: `references/action-patterns.md`\n- Slice organization: `references/slice-organization.md`\n\n## Class-Based Action Implementation\n\nWe are migrating slices from plain `StateCreator` objects to **class-based actions**.\n\n### Pattern\n\n- Define a class that encapsulates actions and receives `(set, get, api)` in the constructor.\n- Use `#private` fields (e.g., `#set`, `#get`) to avoid leaking internals.\n- Prefer shared typing helpers:\n  - `StoreSetter<T>` from `@/store/types` for `set`.\n  - `Pick<ActionImpl, keyof ActionImpl>` to expose only public methods.\n- Export a `create*Slice` helper that returns a class instance.\n\n```ts\ntype Setter = StoreSetter<HomeStore>;\nexport const createRecentSlice = (set: Setter, get: () => HomeStore, _api?: unknown) =>\n  new RecentActionImpl(set, get, _api);\n\nexport class RecentActionImpl {\n  readonly #get: () => HomeStore;\n  readonly #set: Setter;\n\n  constructor(set: Setter, get: () => HomeStore, _api?: unknown) {\n    void _api;\n    this.#set = set;\n    this.#get = get;\n  }\n\n  useFetchRecentTopics = () => {\n    // ...\n  };\n}\n\nexport type RecentAction = Pick<RecentActionImpl, keyof RecentActionImpl>;\n```\n\n### Composition\n\n- In store files, merge class instances with `flattenActions` (do not spread class instances).\n- `flattenActions` binds methods to the original class instance and supports prototype methods and class fields.\n\n```ts\nconst createStore: StateCreator<HomeStore, [[''zustand/devtools'', never]]> = (...params) => ({\n  ...initialState,\n  ...flattenActions<HomeStoreAction>([\n    createRecentSlice(...params),\n    createHomeInputSlice(...params),\n  ]),\n});\n```\n\n### Multi-Class Slices\n\n- For large slices that need multiple action classes, compose them in the slice entry using `flattenActions`.\n- Use a local `PublicActions<T>` helper if you need to combine multiple classes and hide private fields.\n\n```ts\ntype PublicActions<T> = { [K in keyof T]: T[K] };\n\nexport type ChatGroupAction = PublicActions<\n  ChatGroupInternalAction & ChatGroupLifecycleAction & ChatGroupMemberAction & ChatGroupCurdAction\n>;\n\nexport const chatGroupAction: StateCreator<\n  ChatGroupStore,\n  [[''zustand/devtools'', never]],\n  [],\n  ChatGroupAction\n> = (...params) =>\n  flattenActions<ChatGroupAction>([\n    new ChatGroupInternalAction(...params),\n    new ChatGroupLifecycleAction(...params),\n    new ChatGroupMemberAction(...params),\n    new ChatGroupCurdAction(...params),\n  ]);\n```\n\n### Store-Access Types\n\n- For class methods that depend on actions in other classes, define explicit store augmentations:\n  - `ChatGroupStoreWithSwitchTopic` for lifecycle `switchTopic`\n  - `ChatGroupStoreWithRefresh` for member refresh\n  - `ChatGroupStoreWithInternal` for curd `internal_dispatchChatGroup`\n\n### Do / Don''t\n\n- **Do**: keep constructor signature aligned with `StateCreator` params `(set, get, api)`.\n- **Do**: use `#private` to avoid `set/get` being exposed.\n- **Do**: use `flattenActions` instead of spreading class instances.\n- **Don''t**: keep both old slice objects and class actions active at the same time.\n"},"lastSynced":"2026-03-07T04:06:13.694Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring efficient state management for complex UI component interactions.","zh":"适用于需要高效状态管理的复杂UI组件交互的前端代理。","ja":"複雑なUIコンポーネントの相互作用に対して効率的な状態管理が必要なフロントエンドエージェントに適しています。","ko":"복잡한 UI 컴포넌트 상호 작용에 효율적인 상태 관리가 필요한 프론트엔드 에이전트에 적합합니다.","es":"Ideal para Agentes Frontend que requieren un manejo de estado eficiente para interacciones de componentes de UI complejos.","fr":"Idéal pour les agents Frontend nécessitant une gestion d''état efficace pour les interactions de composants d''interface utilisateur complexes.","de":"Ideal für Frontend-Agents, die ein effizientes Zustandsmanagement für komplexe UI-Komponenten-Interaktionen benötigen.","pt":"Ideal para Agentes de Frontend que requerem gerenciamento de estado eficiente para interações complexas de componentes de interface do usuário.","ru":"Идеально подходит для агентов Frontend, требующих эффективного управления состоянием для сложных взаимодействий компонентов пользовательского интерфейса.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يتطلب إدارة حالة فعالة لتفاعلات مكونات واجهة المستخدم المعقدة."},"recommendation":{"en":"Empowers agents to manage hierarchical state structures with optimistic updates, parameter validation, and flow orchestration using Zustand''s action type hierarchy, including public actions, internal actions, and dispatch methods.","zh":"赋予代理管理分层状态结构的能力，包括乐观更新、参数验证和工作流编排，使用Zustand的操作类型层次结构，包括公共操作、内部操作和调度方法。","ja":"Zustandのアクションタイプ階層構造を使用して、階層的な状態構造を管理するエージェントを可能にします。パブリックアクション、内部アクション、Dispatchメソッドを使用した楽観的な更新、パラメーターの検証、ワークフローオーケストレーションが含まれます。","ko":"Zustand의 액션 타입 계층 구조를 사용하여 계층적 상태 구조를 관리하는 에이전트를 가능하게 합니다. 공개 액션, 내부 액션 및 디스패치 메서드를 사용한 낙관적 업데이트와 매개변수 유효성 검사, 워크플로 오케스트레이션이 포함됩니다.","es":"Habilita a los agentes a gestionar estructuras de estado jerárquicas con actualizaciones optimistas, validación de parámetros y orquestación de flujo utilizando la jerarquía de tipos de acción de Zustand, incluyendo acciones públicas, acciones internas y métodos de despacho.","fr":"Permet aux agents de gérer des structures d''état hiérarchiques avec des mises à jour optimistes, une validation de paramètres et une orchestration de flux en utilisant la hiérarchie de types d''action de Zustand, y compris les actions publiques, les actions internes et les méthodes de dispatch.","de":"Ermächtigt Agenten, hierarchische Zustandsstrukturen mit optimistischen Updates, Parametervalidierung und Flussorchestrierung mithilfe von Zustands Aktionstyp-Hierarchie zu verwalten, einschließlich öffentlicher Aktionen, interner Aktionen und Dispatch-Methoden.","pt":"Habilita os agentes a gerenciarem estruturas de estado hierárquicas com atualizações otimistas, validação de parâmetros e orquestração de fluxo usando a hierarquia de tipo de ação do Zustand, incluindo ações públicas, ações internas e métodos de dispatch.","ru":"Наделяет агентов возможностью управлять иерархическими структурами состояния с оптимистичными обновлениями, валидацией параметров и оркестровкой потока с использованием иерархии типа действия Zustand, включая публичные действия, внутренние действия и методы диспетчеризации.","ar":"تمكّن العميل من إدارة هياكل الحالة الهيكلية مع تحديثات متفائلة وتصديق للمعاملات وتنسيق التدفق باستخدام هرمية نوع الإجراء من Zustand، بما في ذلك الإجراءات العامة والإجراءات الداخلية وأساليب الإرسال."},"useCases":{"en":["Orchestrating UI component interactions with public actions like createTopic and sendMessage","Implementing core business logic with internal actions like internal_createTopic","Dispatching actions with optimistic updates and error handling"],"zh":["使用公共操作（如createTopic和sendMessage）编排UI组件交互","使用内部操作（如internal_createTopic）实现核心业务逻辑","使用乐观更新和错误处理调度操作"],"ja":["createTopicやsendMessageなどのパブリックアクションを使用してUIコンポーネントの相互作用をオーケストレーションする","internal_createTopicなどの内部アクションを使用してコアビジネスロジックを実装する","楽観的な更新とエラーハンドリングを使用してアクションをDispatchする"],"ko":["createTopic 및 sendMessage와 같은 공개 액션을 사용하여 UI 컴포넌트 상호 작용을 오케스트레이션","internal_createTopic과 같은 내부 액션을 사용하여 핵심 비즈니스 로직을 구현","낙관적 업데이트와 오류 처리를 사용하여 액션을 디스패치"],"es":["Orquestar interacciones de componentes de UI con acciones públicas como createTopic y sendMessage","Implementar lógica de negocio principal con acciones internas como internal_createTopic","Dispatchar acciones con actualizaciones optimistas y control de errores"],"fr":["Orchestrer les interactions de composants d''interface utilisateur avec des actions publiques comme createTopic et sendMessage","Mettre en œuvre la logique métier principale avec des actions internes comme internal_createTopic","Dispatch des actions avec des mises à jour optimistes et une gestion des erreurs"],"de":["Orchestrieren von UI-Komponenten-Interaktionen mit öffentlichen Aktionen wie createTopic und sendMessage","Implementieren der Kerngeschäftslogik mit internen Aktionen wie internal_createTopic","Dispatchen von Aktionen mit optimistischen Updates und Fehlerbehandlung"],"pt":["Orquestração de interações de componentes de interface do usuário com ações públicas como createTopic e sendMessage","Implementação da lógica de negócios core com ações internas como internal_createTopic","Dispatch de ações com atualizações otimistas e tratamento de erros"],"ru":["Оркестровка взаимодействий компонентов пользовательского интерфейса с публичными действиями, такими как createTopic и sendMessage","Реализация основной логики бизнеса с внутренними действиями, такими как internal_createTopic","Диспетчеризация действий с оптимистичными обновлениями и обработкой ошибок"],"ar":["تنسيق تفاعلات مكونات واجهة المستخدم مع الإجراءات العامة مثل createTopic و sendMessage","تنفيذ المنطق التجاري الأساسي بالإجراءات الداخلية مثل internal_createTopic","إرسال الإجراءات مع تحديثات متفائلة ومعالجة الأخطاء"]},"limitations":{"en":["Requires understanding of Zustand''s action type hierarchy","Limited to state management use cases","May require additional setup for complex UI component interactions"],"zh":["需要理解Zustand的操作类型层次结构","仅限于状态管理用例","可能需要为复杂UI组件交互添加额外的设置"],"ja":["Zustandのアクションタイプ階層構造の理解が必要","状態管理用途に限定される","複雑なUIコンポーネントの相互作用には追加の設定が必要になる可能性がある"],"ko":["Zustand의 액션 타입 계층 구조를 이해해야 함","상태 관리 용도에만 제한됨","복잡한 UI 컴포넌트 상호 작용에는 추가 설정이 필요할 수 있음"],"es":["Requiere comprensión de la jerarquía de tipos de acción de Zustand","Limitado a casos de uso de gestión de estado","Puede requerir una configuración adicional para interacciones de componentes de UI complejos"],"fr":["Nécessite une compréhension de la hiérarchie de types d''action de Zustand","Limité aux cas d''utilisation de gestion d''état","Peut nécessiter une configuration supplémentaire pour les interactions de composants d''interface utilisateur complexes"],"de":["Benötigt Verständnis für Zustands Aktionstyp-Hierarchie","Begrenzt auf Zustandsmanagement-Anwendungsfälle","Kann eine zusätzliche Einrichtung für komplexe UI-Komponenten-Interaktionen erfordern"],"pt":["Requer entendimento da hierarquia de tipo de ação do Zustand","Limitado a casos de uso de gerenciamento de estado","Pode requerer configuração adicional para interações complexas de componentes de interface do usuário"],"ru":["Требует понимания иерархии типа действия Zustand","Ограничен случаи использования управления состоянием","Может потребовать дополнительной настройки для сложных взаимодействий компонентов пользовательского интерфейса"],"ar":["يتطلب فهم هرمية نوع الإجراء من Zustand","محدود لحالات استخدام إدارة الحالة","يمكن أن يتطلب إعدادًا إضافيًا لتفاعلات مكونات واجهة المستخدم المعقدة"]},"version":4},"contentHash":"f14495ff461cc8bf3c69e46edf63fda621f71b8bdaaebcada97c595c4561a2a4","qualityScore":57}');
